  function getActiveStaffPortalKey() {
    const page = getPage();

    if (page === "user-settings" || page === "staff-settings") {
      return "settings";
    }

    if (STAFF_PORTAL_PAGE_CONFIG[page]) {
      return STAFF_PORTAL_PAGE_CONFIG[page].key;
    }

    if (page !== "portal") {
      return "";
    }

    return "dashboard";
  }

  function updateStaffPortalSidebarActive(nav) {
    if (!nav) {
      return;
    }

    const activeKey = getActiveStaffPortalKey();
    nav.querySelectorAll("[data-staff-nav-key]").forEach((link) => {
      link.classList.toggle("is-active", link.dataset.staffNavKey === activeKey);
    });
  }

  function renderStaffPortalSidebar(nav) {
    nav.dataset.navRole = "staff";
    nav.setAttribute("aria-label", "Staff portal");
    nav.innerHTML = STAFF_PORTAL_LINKS.map(
      (item) => `
        <a
          class="admin-sidebar-link"
          href="${escapeHtml(item.href)}"
          title="${escapeHtml(`${item.label} - ${item.description}`)}"
          data-staff-nav-key="${escapeHtml(item.key)}"
          data-permission-key="${escapeHtml(item.permissionKey)}"
        >
          ${getStaffPortalIcon(item.key)}
          <span>${escapeHtml(item.label)}</span>
        </a>
      `,
    ).join("");
    updateStaffPortalSidebarActive(nav);
  }

  function getActiveStudentPortalKey() {
    if (getPage() === "user-settings") {
      return "profile";
    }

    if (getPage() !== "portal") {
      return "";
    }

    const requested = String(window.location.hash || "")
      .replace(/^#/, "")
      .trim()
      .toLowerCase();
    return STUDENT_PORTAL_LINKS.some((item) => item.key === requested && item.key !== "profile")
      ? requested
      : "dashboard";
  }

  function updateStudentPortalSidebarActive(nav) {
    if (!nav) {
      return;
    }

    const activeKey = getActiveStudentPortalKey();
    nav.querySelectorAll("[data-student-nav-key]").forEach((link) => {
      link.classList.toggle("is-active", link.dataset.studentNavKey === activeKey);
    });
  }

  function renderStudentPortalSidebar(nav) {
    nav.dataset.navRole = "student";
    nav.setAttribute("aria-label", "Student portal");
    nav.innerHTML = STUDENT_PORTAL_LINKS.map(
      (item) => `
        <a
          class="admin-sidebar-link"
          href="${escapeHtml(item.href)}"
          title="${escapeHtml(`${item.label} - ${item.description}`)}"
          data-student-nav-key="${escapeHtml(item.key)}"
          data-permission-key="${escapeHtml(item.permissionKey)}"
        >
          ${getStaffPortalIcon(item.key === "reports" ? "results" : item.key)}
          <span>${escapeHtml(item.label)}</span>
        </a>
      `,
    ).join("");
    updateStudentPortalSidebarActive(nav);
  }

  function getPageIdFromHref(href) {
    if (!href) {
      return "";
    }

    try {
      const url = new URL(href, window.location.href);
      const fileName = url.pathname.split("/").filter(Boolean).pop() || "portal.html";
      return fileName.replace(/\.html$/i, "") || "portal";
    } catch (error) {
      return String(href)
        .replace(/^\.?\//, "")
        .replace(/\.html(?:[#?].*)?$/i, "");
    }
  }

  function getSidebarPermissionKey(link) {
    if (!link) {
      return null;
    }

    if (link.dataset.permissionKey) {
      return link.dataset.permissionKey;
    }

    const pageId = getPageIdFromHref(link.getAttribute("href") || "");
    return PARENT_PAGE_PERMISSION_KEYS[pageId] || PAGE_PERMISSION_KEYS[pageId] || null;
  }

  function applyRolePermissionSidebarVisibility(nav, roleLabel) {
    if (!nav) {
      return;
    }

    const normalizedRole = normalizeRoleLabel(roleLabel || DEFAULT_AUTH_ROLE);
    const isAdminRole = /admin/i.test(normalizedRole);

    nav.querySelectorAll(".admin-sidebar-link").forEach((link) => {
      const permissionKey = getSidebarPermissionKey(link);
      const isAllowed = isAdminRole || !permissionKey || canAccessPermission(normalizedRole, permissionKey);

      link.hidden = !isAllowed;
      link.classList.toggle("is-permission-hidden", !isAllowed);

      if (isAllowed) {
        link.removeAttribute("aria-hidden");
        link.removeAttribute("tabindex");
      } else {
        link.setAttribute("aria-hidden", "true");
        link.setAttribute("tabindex", "-1");
      }
    });
  }

  function getFeatureModuleManager() {
    return window.SchoolSphereFeatureModules || null;
  }

  function getRolePermissionManager() {
    return window.SchoolSphereRolePermissions || null;
  }

  function getRolePermissionSnapshot(roleLabel) {
    const manager = getRolePermissionManager();

    if (!manager || typeof manager.getPermissions !== "function") {
      return null;
    }

    const normalizedRole = normalizeRoleLabel(roleLabel || DEFAULT_AUTH_ROLE);
    if (/admin/i.test(normalizedRole)) {
      return null;
    }

    const permissions = manager.getPermissions();
    return permissions[normalizedRole] || null;
  }

  function canAccessPermission(roleLabel, permissionKey) {
    if (!permissionKey) {
      return true;
    }

    const normalizedRole = normalizeRoleLabel(roleLabel || DEFAULT_AUTH_ROLE);

    if (/admin/i.test(normalizedRole)) {
      return true;
    }

    const permissionSnapshot = getRolePermissionSnapshot(normalizedRole);

    if (!permissionSnapshot) {
      return false;
    }

    if (
      normalizedRole === "Student" &&
      permissionKey === "student_messages_view" &&
      typeof permissionSnapshot[permissionKey] !== "boolean"
    ) {
      return true;
    }

    return Boolean(permissionSnapshot[permissionKey]);
  }

  function getSchoolSettingsManager() {
    return window.SchoolSphereSiteSettings || null;
  }

  function getAcademicCycleManager() {
    return window.SchoolSphereAcademicCycles || null;
  }

  function getAcademicCalendarManager() {
    return window.SchoolSphereAcademicCalendar || null;
  }

  function getAdmissionConfigManager() {
    return window.SchoolSphereAdmissionConfig || null;
  }

  function getTimetableManager() {
    return window.SchoolSphereTimetable || null;
  }

  function getFeeItemManager() {
    return window.SchoolSphereFeeItems || null;
  }

  function normalizeFeeCategoryKey(value) {
    const normalized = String(value || "")
      .trim()
      .toLowerCase()
      .replace(/&/g, "and")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");

    if (["fee", "fees", "tuition", "school-fees", "school-fee", "levy", "levies"].includes(normalized)) {
      return "fees";
    }

    if (["uniform", "uniforms", "school-uniform"].includes(normalized)) {
      return "uniform";
    }

    if (["book", "books", "textbook", "textbooks"].includes(normalized)) {
      return "books";
    }

    if (["transport", "transportation", "bus", "bus-fee"].includes(normalized)) {
      return "transport";
    }

    if (["exam", "exams", "examination", "examination-fee"].includes(normalized)) {
      return "exam";
    }

    if (["boarding", "hostel", "accommodation"].includes(normalized)) {
      return "boarding";
    }

    return normalized || FEE_CATEGORY_FALLBACK;
  }

  function getFeeCategoryOption(value) {
    const category = normalizeFeeCategoryKey(value);
    const option = FEE_CATEGORY_OPTIONS.find((item) => item.value === category);
    if (option) {
      return option;
    }

    const label = category
      .split("-")
      .filter(Boolean)
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
      .join(" ");

    return {
      value: category,
      label: label || "Fees",
      copy: "Custom school billing category.",
    };
  }

  function getFeeCategoryLabel(value) {
    return getFeeCategoryOption(value).label;
  }

  function getFeeCategoryOptionsForItems(items = []) {
    const known = new Map(FEE_CATEGORY_OPTIONS.map((option) => [option.value, option]));
    (Array.isArray(items) ? items : []).forEach((item) => {
      const category = normalizeFeeCategoryKey(item?.category || FEE_CATEGORY_FALLBACK);
      if (!known.has(category)) {
        known.set(category, getFeeCategoryOption(category));
      }
    });
    return Array.from(known.values());
  }

