  function getTermLabelFromCycle(cycleState, termId) {
    const target = (cycleState?.terms || []).find((term) => term.id === termId);
    if (!target) {
      return "Unmapped period";
    }
    const periodLabel = target.periodType === "semester" ? "Semester" : "Term";
    return `${periodLabel}: ${target.name}`;
  }

  function getSessionLabelFromCycle(cycleState, sessionId) {
    const target = (cycleState?.sessions || []).find((session) => session.id === sessionId);
    return target ? target.name : "Unmapped session";
  }

  function getPortalTimetableSlotKey(record = {}) {
    return [
      String(record.name || "").trim().toLowerCase(),
      String(record.startTime || "").trim(),
      String(record.endTime || "").trim(),
    ].join("|");
  }

  function portalTimetableWeekTypesOverlap(left, right) {
    const normalizedLeft = String(left || "all").trim() || "all";
    const normalizedRight = String(right || "all").trim() || "all";
    return normalizedLeft === "all" || normalizedRight === "all" || normalizedLeft === normalizedRight;
  }

  function getPortalTimetableSlotRows(activePeriods = [], days = []) {
    return Array.from(
      activePeriods
        .filter((period) => days.includes(period.day))
        .reduce((rows, period) => {
          const key = getPortalTimetableSlotKey(period);
          if (!rows.has(key)) {
            rows.set(key, {
              key,
              name: period.name,
              startTime: period.startTime,
              endTime: period.endTime,
              sortOrder: period.sortOrder,
              byDay: new Map(),
            });
          }
          rows.get(key).byDay.set(period.day, period);
          return rows;
        }, new Map())
        .values(),
    ).sort((left, right) => {
      if (left.sortOrder !== right.sortOrder) return left.sortOrder - right.sortOrder;
      return left.startTime.localeCompare(right.startTime);
    });
  }

  function getPortalTimetableClassGroups(entries = [], criteria = {}) {
    const selectedSessionId = String(criteria.sessionId || "").trim();
    const selectedTermId = String(criteria.termId || "").trim();
    const selectedWeekType = String(criteria.weekType || "all").trim() || "all";
    const groups = new Map();

    entries
      .filter((entry) => {
        const sessionMatches = !selectedSessionId || entry.sessionId === selectedSessionId;
        const termMatches = !selectedTermId || entry.termId === selectedTermId;
        const weekMatches = portalTimetableWeekTypesOverlap(entry.weekType, selectedWeekType);
        return entry.status !== "archived" && sessionMatches && termMatches && weekMatches;
      })
      .forEach((entry) => {
        const key = [
          entry.sessionId || "",
          entry.termId || "",
          String(entry.classId || "").trim() || String(entry.classLevel || "").trim().toLowerCase(),
        ].join("|");
        if (!groups.has(key)) {
          groups.set(key, {
            key,
            classId: entry.classId || "",
            classLevel: entry.classLevel,
            sessionId: entry.sessionId,
            termId: entry.termId,
            rows: [],
          });
        }
        groups.get(key).rows.push(entry);
      });

    return Array.from(groups.values())
      .map((group) => ({
        ...group,
        weekType:
          Array.from(new Set(group.rows.map((row) => String(row.weekType || "all").trim() || "all"))).length === 1
            ? String(group.rows[0]?.weekType || "all").trim() || "all"
            : "all",
        rows: group.rows.sort((left, right) => {
          const dayComparison = String(left.day || "").localeCompare(String(right.day || ""));
          if (dayComparison !== 0) return dayComparison;
          return String(left.startTime || "").localeCompare(String(right.startTime || ""));
        }),
        isPublished: group.rows.length > 0 && group.rows.every((row) => row.status === "published"),
      }))
      .sort((left, right) => left.classLevel.localeCompare(right.classLevel, undefined, { numeric: true }));
  }

  function renderPortalTimetablePrintSheet({
    schoolName = "School",
    classLevel = "Class",
    sessionName = "",
    termName = "",
    weekType = "all",
    days = [],
    slotRows = [],
    entries = [],
  } = {}) {
    const entryByPeriod = new Map(entries.map((entry) => [entry.periodId, entry]));
    const periodLabel = [sessionName, termName, weekType === "all" ? "Every week" : `Week ${weekType}`]
      .filter(Boolean)
      .join(" - ");

    return `
      <section class="portal-timetable-print-sheet">
        <header class="portal-timetable-print-head">
          <h1>${escapeHtml(schoolName)}</h1>
          <h2>${escapeHtml(classLevel)} Timetable</h2>
          <p>${escapeHtml(periodLabel || "Academic timetable")}</p>
        </header>
        <div class="portal-timetable-print-wrap">
          <table class="portal-timetable-print-grid">
            <thead>
              <tr>
                <th>Period</th>
                ${days.map((day) => `<th>${escapeHtml(day)}</th>`).join("")}
              </tr>
            </thead>
            <tbody>
              ${
                slotRows.length
                  ? slotRows
                      .map(
                        (slot) => `
                          <tr>
                            <th>
                              <strong>${escapeHtml(slot.name)}</strong>
                              <span>${escapeHtml(slot.startTime)}-${escapeHtml(slot.endTime)}</span>
                            </th>
                            ${days
                              .map((day) => {
                                const period = slot.byDay.get(day);
                                const entry = period ? entryByPeriod.get(period.id) : null;
                                return `
                                  <td>
                                    ${
                                      entry
                                        ? `<strong>${escapeHtml(entry.subject)}</strong>
                                           <span>${escapeHtml(entry.teacher || "Teacher not assigned")}</span>`
                                        : `<span class="portal-timetable-print-empty">Free</span>`
                                    }
                                  </td>
                                `;
                              })
                              .join("")}
                          </tr>
                        `,
                      )
                      .join("")
                  : `<tr><td colspan="${days.length + 1}">No periods configured yet.</td></tr>`
              }
            </tbody>
          </table>
        </div>
      </section>
    `;
  }

  function renderTimetableSection({ isAdmin, manager, summaryTarget, listTarget, context = {} }) {
    if (!summaryTarget || !listTarget) {
      return;
    }

    if (!manager) {
      summaryTarget.innerHTML = `
        <article class="portal-class-stat">
          <span>Timetable unavailable</span>
          <strong>0</strong>
          <p>The timetable manager could not be loaded on this page.</p>
        </article>
      `;
      listTarget.innerHTML = "";
      return;
    }

    const {
      entries,
      publishedCount,
      draftCount,
      archivedCount,
      classCount,
      teacherCount,
      activePeriods,
      substitutions,
    } = manager.summarize();
    const cycleManager = getAcademicCycleManager();
    const cycleState = cycleManager && typeof cycleManager.getState === "function"
      ? cycleManager.getState()
      : { sessions: [], terms: [] };
    const days = manager.schoolDays || ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"];
    const viewMode = context.viewMode === "teacher" ? "teacher" : "class";
    const selectedClass = context.classRecord || null;
    const selectedTeacher = context.teacherRecord || null;
    const selectedSessionId = String(context.sessionId || "").trim();
    const selectedTermId = String(context.termId || "").trim();
    const selectedWeekType = String(context.weekType || "all").trim() || "all";
    const selectedSessionName = getSessionLabelFromCycle(cycleState, selectedSessionId);
    const selectedTermName = getTermLabelFromCycle(cycleState, selectedTermId);
    const teacherLoad = selectedTeacher && typeof manager.getTeacherLoad === "function"
      ? manager.getTeacherLoad({
          teacherId: selectedTeacher.id,
          teacher: selectedTeacher.name,
          termId: selectedTermId,
          weekType: selectedWeekType,
        })
      : { count: 0, entries: [] };
    const teacherMax = selectedTeacher?.maxPeriodsPerWeek || 24;
    const selectedClassLabel = selectedClass ? getClassDisplayName(selectedClass) : "";
    const visibleEntries = entries.filter((entry) => {
      const termMatches = !selectedTermId || entry.termId === selectedTermId;
      const weekMatches =
        selectedWeekType === "all" ||
        entry.weekType === "all" ||
        entry.weekType === selectedWeekType;
      const scopeMatches =
        viewMode === "teacher"
          ? selectedTeacher && (entry.teacherId === selectedTeacher.id || entry.teacher === selectedTeacher.name)
          : selectedClass &&
            (entry.classId
              ? entry.classId === selectedClass.id
              : String(entry.classLevel || "").trim().toLowerCase() === selectedClassLabel.toLowerCase());
      return entry.status !== "archived" && termMatches && weekMatches && scopeMatches;
    });
    const entryByPeriod = new Map(visibleEntries.map((entry) => [entry.periodId, entry]));
    const slotRows = getPortalTimetableSlotRows(activePeriods, days);
    const classTimetableGroups = getPortalTimetableClassGroups(entries, {
      weekType: "all",
    });
    const setupMessages = [];
    const canAssignSlots = Boolean(isAdmin && selectedSessionId && selectedTermId && selectedClass);
    const classTimetableListHtml = classTimetableGroups.length
      ? classTimetableGroups
          .map(
            (group) => `
              <div class="portal-timetable-entry-row portal-timetable-class-row">
                <span>
                  <strong>${escapeHtml(group.classLevel)}</strong>
                  ${group.isPublished ? "Saved timetable" : "Draft timetable"}
                </span>
                <span>${group.rows.length} lesson${group.rows.length === 1 ? "" : "s"}</span>
                <span>${escapeHtml(getSessionLabelFromCycle(cycleState, group.sessionId))} • ${escapeHtml(
                  getTermLabelFromCycle(cycleState, group.termId),
                )}</span>
                <span class="portal-timetable-row-actions">
                  <button class="portal-class-button" type="button" data-timetable-class-action="view" data-timetable-session-id="${escapeHtml(group.sessionId)}" data-timetable-term-id="${escapeHtml(group.termId)}" data-timetable-class-id="${escapeHtml(group.classId || "")}" data-timetable-class="${escapeHtml(group.classLevel)}" data-timetable-week-type="${escapeHtml(group.weekType)}">View</button>
                  <button class="portal-class-button" type="button" data-timetable-class-action="edit" data-timetable-session-id="${escapeHtml(group.sessionId)}" data-timetable-term-id="${escapeHtml(group.termId)}" data-timetable-class-id="${escapeHtml(group.classId || "")}" data-timetable-class="${escapeHtml(group.classLevel)}" data-timetable-week-type="${escapeHtml(group.weekType)}">Edit</button>
                  <button class="portal-class-button" type="button" data-timetable-class-action="print" data-timetable-session-id="${escapeHtml(group.sessionId)}" data-timetable-term-id="${escapeHtml(group.termId)}" data-timetable-class-id="${escapeHtml(group.classId || "")}" data-timetable-class="${escapeHtml(group.classLevel)}" data-timetable-week-type="${escapeHtml(group.weekType)}">Print</button>
                </span>
              </div>
            `,
          )
          .join("")
      : `<p>No class timetables have been recorded yet.</p>`;

    if (!selectedSessionId) setupMessages.push(`Create or select a session from <a href="./admin-settings-academic.html">Sessions and Terms</a>.`);
    if (!selectedTermId) setupMessages.push(`Create or select a term or semester before assigning timetable slots.`);
    if (!selectedClass) setupMessages.push(`Select a class before adding lessons to the timetable grid.`);
    if (!context.teachers?.length) setupMessages.push(`Create teacher accounts before assigning lessons.`);

    summaryTarget.innerHTML = `
      <article class="portal-class-stat portal-class-stat-blue">
        <span>Lessons</span>
        <strong>${entries.filter((entry) => entry.status !== "archived").length}</strong>
        <p>Active timetable lessons across all views.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-violet">
        <span>Published</span>
        <strong>${publishedCount}</strong>
        <p>Lessons visible to staff, students, and parents.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-amber">
        <span>Draft</span>
        <strong>${draftCount}</strong>
        <p>Rows awaiting publish action.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-green">
        <span>Classes covered</span>
        <strong>${classCount}</strong>
        <p>Unique classes with timetable rows.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-slate">
        <span>Teachers</span>
        <strong>${teacherCount}</strong>
        <p>Teachers with at least one active lesson.</p>
      </article>
      <article class="portal-class-stat">
        <span>Periods</span>
        <strong>${activePeriods.length}</strong>
        <p>Editable time slots available across school days.</p>
      </article>
    `;

    listTarget.innerHTML = `
      ${setupMessages.length ? `<div class="auth-status auth-status--info portal-timetable-setup">${setupMessages.join(" ")}</div>` : ""}
      <section class="portal-timetable-context">
        <div>
          <strong>${viewMode === "teacher" ? escapeHtml(selectedTeacher?.name || "Teacher grid") : escapeHtml(selectedClassLabel || "Select a class")}</strong>
          <span>${escapeHtml(selectedSessionName)} - ${escapeHtml(selectedTermName)} - ${selectedWeekType === "all" ? "Every week" : `Week ${escapeHtml(selectedWeekType)}`}</span>
        </div>
        <div>
          <strong>${viewMode === "teacher" ? `${teacherLoad.count}/${teacherMax}` : visibleEntries.length}</strong>
          <span>${viewMode === "teacher" && selectedTeacher ? "teacher workload" : "lessons in this class grid"}</span>
        </div>
      </section>
      <section class="portal-class-card portal-timetable-panel portal-timetable-saved-panel">
        <div class="portal-class-card-head">
          <div class="portal-class-title">
            <strong>Class timetables</strong>
            <span>${classTimetableGroups.length} saved timetable${classTimetableGroups.length === 1 ? "" : "s"} available for view, print, or edit</span>
          </div>
        </div>
        <div class="portal-timetable-entry-list">
          ${classTimetableListHtml}
        </div>
      </section>
      <div class="portal-timetable-grid" style="--timetable-day-count:${days.length}">
        <div class="portal-timetable-grid-corner">Period</div>
        ${days.map((day) => `<div class="portal-timetable-day-head">${escapeHtml(day.slice(0, 3))}</div>`).join("")}
        ${
          slotRows.length
            ? slotRows
                .map(
                  (slot) => `
                    <div class="portal-timetable-period-label">
                      <div>
                        <strong>${escapeHtml(slot.name)}</strong>
                        <span>${escapeHtml(slot.startTime)}-${escapeHtml(slot.endTime)}</span>
                      </div>
                      <button class="portal-timetable-period-edit" type="button" data-timetable-period-edit data-timetable-period-ids="${escapeHtml(Array.from(slot.byDay.values()).map((period) => period.id).join(","))}" data-timetable-period-name="${escapeHtml(slot.name)}" data-timetable-period-start="${escapeHtml(slot.startTime)}" data-timetable-period-end="${escapeHtml(slot.endTime)}" data-timetable-period-sort="${escapeHtml(String(slot.sortOrder || ""))}" ${isAdmin ? "" : "disabled"}>Edit</button>
                    </div>
                    ${days
                      .map((day) => {
                        const period = slot.byDay.get(day);
                        const entry = period ? entryByPeriod.get(period.id) : null;
                        return `
                          <button class="portal-timetable-slot ${entry ? "has-entry" : ""}" type="button" data-timetable-slot data-timetable-period-id="${escapeHtml(period?.id || "")}" data-timetable-entry-id="${escapeHtml(entry?.id || "")}" ${!period || !canAssignSlots ? "disabled" : ""}>
                            ${
                              entry
                                ? `<span class="portal-timetable-entry-subject">${escapeHtml(entry.subject)}</span>
                                   <span>${escapeHtml(viewMode === "teacher" ? entry.classLevel : entry.teacher)}</span>
                                   <span>${entry.weekType === "all" ? "Every week" : `Week ${escapeHtml(entry.weekType)}`}</span>
                                   <span class="portal-class-status ${entry.status === "published" ? "is-active" : "is-archived"}">${escapeHtml(entry.status)}</span>`
                                : `<span class="portal-timetable-empty-slot">${selectedClass ? "Add lesson" : "Select class first"}</span>`
                            }
                          </button>
                        `;
                      })
                      .join("")}
                  `,
                )
                .join("")
            : `<div class="portal-timetable-grid-empty">No periods configured yet.</div>`
        }
      </div>
      <section class="portal-timetable-grid-actions" aria-label="Timetable actions">
        <div id="portal-timetable-inline-status" class="auth-status portal-timetable-inline-status" role="alert" aria-live="polite" hidden></div>
        <div class="utility-actions portal-timetable-actions portal-timetable-actions-inline">
          <button class="button button-outline" type="button" data-timetable-inline-action="copy" ${isAdmin ? "" : "disabled"}>Copy previous period</button>
          <button class="button button-outline" type="button" data-timetable-inline-action="period" ${isAdmin ? "" : "disabled"}>Add period</button>
          <button class="button button-primary" type="button" data-timetable-inline-action="save" ${isAdmin ? "" : "disabled"}>Save class timetable</button>
          <button class="button button-outline" type="button" data-timetable-inline-action="print" ${isAdmin ? "" : "disabled"}>Print selected class</button>
        </div>
      </section>
      <section class="portal-timetable-footer-panels">
        <article class="portal-class-card portal-timetable-panel">
          <div class="portal-class-title">
            <strong>Substitution log</strong>
            <span>${substitutions.length} recent replacement${substitutions.length === 1 ? "" : "s"}</span>
          </div>
          <div class="portal-timetable-entry-list">
            ${
              substitutions.length
                ? substitutions
                    .slice(0, 6)
                    .map(
                      (entry) => `
                        <div class="portal-timetable-entry-row">
                          <span>${escapeHtml(entry.substitutionDate || "Today")}</span>
                          <span>${escapeHtml(entry.classLevel)} - ${escapeHtml(entry.subject)}</span>
                          <span>${escapeHtml(entry.originalTeacher || "Original")} -> ${escapeHtml(entry.replacementTeacher)}</span>
                        </div>
                      `,
                    )
                    .join("")
                : `<p>No substitutions logged yet.</p>`
            }
          </div>
        </article>
      </section>
      ${archivedCount ? `<p class="auth-helper-text">${archivedCount} archived timetable lesson${archivedCount === 1 ? "" : "s"} retained for audit history.</p>` : ""}
    `;
  }

  function renderFeeManagementSection({ isAdmin, manager, summaryTarget, listTarget, selectedCategory = FEE_CATEGORY_FALLBACK }) {
    if (!summaryTarget || !listTarget) {
      return;
    }

    if (!manager) {
      summaryTarget.innerHTML = `
        <article class="portal-class-stat">
          <span>Fee tools unavailable</span>
          <strong>0</strong>
          <p>The fee item manager could not be loaded on this page.</p>
        </article>
      `;
      listTarget.innerHTML = "";
      return;
    }

    const { items, activeCount, archivedCount, classCount, activeAmount, categoryCount } = manager.summarize();
    const activeItems = items.filter((item) => item.status !== "archived");
    const category = normalizeFeeCategoryKey(selectedCategory);
    const categoryLabel = getFeeCategoryLabel(category);
    const selectedItems = items.filter((item) => normalizeFeeCategoryKey(item.category || FEE_CATEGORY_FALLBACK) === category);
    const activeSelectedItems = selectedItems.filter((item) => item.status !== "archived");
    const selectedAmount = activeSelectedItems.reduce((sum, item) => sum + Number(item.amount || 0), 0);
    const activeCategoryCount =
      categoryCount || new Set(activeItems.map((item) => normalizeFeeCategoryKey(item.category || FEE_CATEGORY_FALLBACK))).size;
    const cycleManager = getAcademicCycleManager();
    const cycleState = cycleManager && typeof cycleManager.getState === "function"
      ? cycleManager.getState()
      : { sessions: [], terms: [] };

    summaryTarget.innerHTML = `
      <article class="portal-class-stat portal-class-stat-blue">
        <span>Active fee items</span>
        <strong>${activeCount}</strong>
        <p>Fee lines currently available to billing operations.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-violet">
        <span>Fee categories</span>
        <strong>${activeCategoryCount}</strong>
        <p>Active billing categories currently in use.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-green">
        <span>Classes covered</span>
        <strong>${classCount}</strong>
        <p>Unique class levels with configured fees.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-amber">
        <span>${escapeHtml(categoryLabel)} value</span>
        <strong>${escapeHtml(formatCurrencyAmount(selectedAmount))}</strong>
        <p>${archivedCount} archived item${archivedCount === 1 ? "" : "s"} retained. Total active value: ${escapeHtml(
          formatCurrencyAmount(activeAmount),
        )}.</p>
      </article>
    `;

    if (!items.length) {
      listTarget.innerHTML = `
        <article class="portal-class-empty">
          <strong>No fee items yet</strong>
          <p>Create fee items and map each to class, session, and term.</p>
        </article>
      `;
      return;
    }

    const groupedFees = items.reduce((sessions, item) => {
      const sessionLabel = getSessionLabelFromCycle(cycleState, item.sessionId);
      const termLabel = getTermLabelFromCycle(cycleState, item.termId);
      const sessionKey = item.sessionId || sessionLabel;
      const classKey = item.classLevel || "Unassigned";
      const itemCategory = normalizeFeeCategoryKey(item.category || FEE_CATEGORY_FALLBACK);
      const itemCategoryLabel = getFeeCategoryLabel(itemCategory);

      if (!sessions.has(sessionKey)) {
        sessions.set(sessionKey, {
          label: sessionLabel,
          classes: new Map(),
          items: [],
        });
      }

      const sessionGroup = sessions.get(sessionKey);
      sessionGroup.items.push(item);

      if (!sessionGroup.classes.has(classKey)) {
        sessionGroup.classes.set(classKey, {
          label: classKey,
          categories: new Map(),
          items: [],
        });
      }

      const classGroup = sessionGroup.classes.get(classKey);
      classGroup.items.push(item);

      if (!classGroup.categories.has(itemCategory)) {
        classGroup.categories.set(itemCategory, {
          key: itemCategory,
          label: itemCategoryLabel,
          terms: new Set(),
          items: [],
        });
      }

      const categoryGroup = classGroup.categories.get(itemCategory);
      categoryGroup.terms.add(termLabel);
      categoryGroup.items.push(item);
      return sessions;
    }, new Map());

    listTarget.innerHTML = Array.from(groupedFees.values())
      .map((sessionGroup) => {
        const sessionActiveTotal = sessionGroup.items
          .filter((item) => item.status !== "archived")
          .reduce((sum, item) => sum + item.amount, 0);

        return `
          <section class="portal-class-group portal-fee-session-group">
            <div class="portal-class-group-head">
              <div>
                <span>Academic year</span>
                <strong>${escapeHtml(sessionGroup.label)}</strong>
              </div>
              <small>${sessionGroup.items.length} fee item${sessionGroup.items.length === 1 ? "" : "s"} • ${escapeHtml(
                formatCurrencyAmount(sessionActiveTotal),
              )}</small>
            </div>
            <div class="portal-class-level-stack">
              ${Array.from(sessionGroup.classes.values())
                .sort((left, right) => left.label.localeCompare(right.label, undefined, { numeric: true }))
                .map((classGroup) => {
                  const classItems = classGroup.items;
                  const classTotal = classItems
                    .filter((item) => item.status !== "archived")
                    .reduce((sum, item) => sum + item.amount, 0);
                  return `
                  <details class="portal-class-level-group portal-fee-class-details">
                    <summary>
                      <div>
                        <strong>${escapeHtml(classGroup.label)}</strong>
                        <span>${classGroup.categories.size} fee categor${classGroup.categories.size === 1 ? "y" : "ies"} • ${
                          classGroup.items.length
                        } item${classGroup.items.length === 1 ? "" : "s"}</span>
                      </div>
                      <small>${escapeHtml(formatCurrencyAmount(classTotal))}</small>
                    </summary>
                    <div class="portal-fee-class-stack-inner">
                      <div class="portal-fee-category-stack">
                        ${Array.from(classGroup.categories.values())
                          .sort((left, right) => left.label.localeCompare(right.label, undefined, { numeric: true }))
                          .map((classCategory) => {
                            const categoryItems = classCategory.items.sort((left, right) => {
                              const termComparison = getTermLabelFromCycle(cycleState, left.termId).localeCompare(
                                getTermLabelFromCycle(cycleState, right.termId),
                                undefined,
                                { numeric: true },
                              );
                              if (termComparison !== 0) return termComparison;
                              return left.name.localeCompare(right.name, undefined, { numeric: true });
                            });
                            const categoryTotal = categoryItems
                              .filter((item) => item.status !== "archived")
                              .reduce((sum, item) => sum + item.amount, 0);
                            return `
                              <section class="portal-fee-class-category-group">
                                <header class="portal-fee-class-category-head">
                                  <div>
                                    <span>Category</span>
                                    <strong>${escapeHtml(classCategory.label)}</strong>
                                  </div>
                                  <small>${categoryItems.length} item${categoryItems.length === 1 ? "" : "s"} • ${escapeHtml(
                                    formatCurrencyAmount(categoryTotal),
                                  )}</small>
                                </header>
                                <div class="portal-fee-item-grid">
                                  ${categoryItems
                                    .map((item) => {
                                      const itemTermLabel = getTermLabelFromCycle(cycleState, item.termId);
                                      return `
                                        <article class="portal-class-card portal-fee-item-card ${item.status === "archived" ? "is-archived" : ""}" data-fee-action="edit" data-fee-id="${
                                        escapeHtml(item.id)
                                      }" role="button" tabindex="${isAdmin ? "0" : "-1"}" aria-label="Edit ${escapeHtml(item.name)}">
                                          <div class="portal-class-card-head">
                                            <div class="portal-class-title">
                                              <strong>${escapeHtml(item.name)}</strong>
                                              <span>${escapeHtml(item.description || `${classCategory.label} item for ${classGroup.label}`)}</span>
                                            </div>
                                            <span class="portal-class-status ${item.status === "archived" ? "is-archived" : "is-active"}">
                                              ${item.status === "archived" ? "Archived" : "Active"}
                                            </span>
                                          </div>
                                          <div class="portal-class-meta">
                                            <div class="portal-class-meta-item"><span>Amount</span><strong>${escapeHtml(formatCurrencyAmount(item.amount))}</strong></div>
                                            <div class="portal-class-meta-item"><span>Period</span><strong>${escapeHtml(itemTermLabel)}</strong></div>
                                            <div class="portal-class-meta-item"><span>Due Date</span><strong>${escapeHtml(item.dueDate || "Not set")}</strong></div>
                                          </div>
                                          <div class="portal-fee-card-foot">
                                            <span>Click to edit or archive</span>
                                          </div>
                                        </article>
                                      `;
                                    })
                                    .join("")}
                                </div>
                              </section>
                            `;
                          })
                          .join("")}
                      </div>
                    </div>
                  </details>
                `;
                })
                .join("")}
            </div>
          </section>
        `;
      })
      .join("");
  }

  function renderPortalStudentManagementSection({
    isAdmin,
    manager,
    summaryTarget,
    form,
    status,
    listTarget,
    classFiltersTarget = null,
    selectedClass = "all",
    searchQuery = "",
    expandedClassTokens = null,
  }) {
    if (!summaryTarget || !form || !listTarget) {
      return;
    }

    if (!manager) {
      summaryTarget.innerHTML = `
        <article class="portal-class-stat">
          <span>Student tools unavailable</span>
          <strong>0</strong>
          <p>The shared student registry could not be loaded on this page.</p>
        </article>
      `;
      listTarget.innerHTML = "";
      return;
    }

    const {
      students,
      activeCount,
      archivedCount,
      transferredCount,
      guardianContacts,
      studentsWithMultipleGuardians,
    } =
      manager.summarize();

    summaryTarget.innerHTML = `
      <article class="portal-class-stat portal-class-stat-blue">
        <span>Active students</span>
        <strong>${activeCount}</strong>
        <p>Students currently available for class and attendance operations.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-violet">
        <span>Guardian contacts</span>
        <strong>${guardianContacts}</strong>
        <p>Total guardian contact entries linked to active students.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-green">
        <span>Multiple guardians</span>
        <strong>${studentsWithMultipleGuardians}</strong>
        <p>Students with more than one guardian relationship on file.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-rose">
        <span>Transferred out</span>
        <strong>${transferredCount || 0}</strong>
        <p>Students moved out of this school workspace.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-rose">
        <span>Archived students</span>
        <strong>${archivedCount || 0}</strong>
        <p>Inactive records retained for historical continuity.</p>
      </article>
    `;

    Array.from(form.elements).forEach((field) => {
      if (field instanceof HTMLElement) {
        field.disabled = !isAdmin;
      }
    });

    const normalizedSearch = String(searchQuery || "").trim().toLowerCase();
    const normalizedSelectedClass = normalizeLevelToken(selectedClass === "all" ? "" : selectedClass);
    const classLevelGroups = Array.from(
      students
        .reduce((map, record) => {
          const level = String(record.level || "").trim();
          const token = normalizeLevelToken(level);

          if (!level || !token) {
            return map;
          }

          if (!map.has(token)) {
            map.set(token, {
              token,
              label: getStudentLevelDisplayLabel(level),
            });
          }

          return map;
        }, new Map())
        .values(),
    ).sort((left, right) => left.label.localeCompare(right.label, undefined, { numeric: true }));
    const countAllStudentsForLevel = (level) =>
      students.filter((record) => normalizeLevelToken(record.level) === normalizeLevelToken(level)).length;

    if (classFiltersTarget) {
      const classButtons = [
        `<button class="portal-student-class-filter ${selectedClass === "all" ? "is-active" : ""}" type="button" data-student-class="all">All classes</button>`,
        ...classLevelGroups.map(
          (group) => `
            <button class="portal-student-class-filter ${
              group.token === normalizedSelectedClass ? "is-active" : ""
            }" type="button" data-student-class="${escapeHtml(group.token)}">${escapeHtml(group.label)}</button>
          `,
        ),
      ];
      classFiltersTarget.innerHTML = classButtons.join("");
    }

    const filteredStudents = students.filter((record) => {
      const classMatches =
        !normalizedSelectedClass || normalizeLevelToken(record.level) === normalizedSelectedClass;

      if (!classMatches) {
        return false;
      }

      if (!normalizedSearch) {
        return true;
      }

      const guardians = Array.isArray(record.guardians) ? record.guardians : [];
      const guardianText = guardians
        .map((guardian) => `${guardian.name || ""} ${guardian.email || ""} ${guardian.phone || ""}`)
        .join(" ");
      const searchableText = [
        record.fullName,
        record.firstName,
        record.lastName,
        record.level,
        getStudentLevelDisplayLabel(record.level),
        record.admissionNo,
        record.studentEmail,
        record.gender,
        record.promotionDecision,
        guardianText,
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();

      return searchableText.includes(normalizedSearch);
    });

    if (!filteredStudents.length) {
      listTarget.innerHTML = `
        <article class="portal-class-empty">
          <strong>No student records match this filter</strong>
          <p>Try another class option or search keyword (student name, class, admission number, or guardian details).</p>
        </article>
      `;
    } else {
      const groups = filteredStudents.reduce((map, record) => {
        const rawLevel = String(record.level || "").trim();
        const levelToken = normalizeLevelToken(rawLevel) || "unassigned";
        if (!map.has(levelToken)) {
          map.set(levelToken, {
            label: rawLevel ? getStudentLevelDisplayLabel(rawLevel) : "Unassigned",
            records: [],
            token: levelToken,
          });
        }
        map.get(levelToken).records.push(record);
        return map;
      }, new Map());

      listTarget.innerHTML = Array.from(groups.values())
        .sort((left, right) => left.label.localeCompare(right.label, undefined, { numeric: true }))
        .map((group, groupIndex) => {
          const { label: level, records } = group;
          const levelToken = group.token || `group-${groupIndex + 1}`;
          const isExpanded = expandedClassTokens instanceof Set ? expandedClassTokens.has(levelToken) : false;
          const allLevelStudentCount = countAllStudentsForLevel(levelToken);
          return `
            <section class="portal-student-group">
              <header class="portal-student-group-head">
                <div class="portal-student-group-title">
                  <h3>${escapeHtml(level)}</h3>
                  <span>${records.length} student${records.length === 1 ? "" : "s"}</span>
                </div>
                <div class="portal-student-group-actions">
                  ${
                    isAdmin
                      ? `<button
                          class="portal-class-button portal-student-group-delete"
                          type="button"
                          data-student-bulk-delete-level="${escapeHtml(level)}"
                          data-student-bulk-delete-count="${escapeHtml(String(allLevelStudentCount))}"
                        >
                          Delete class students
                        </button>`
                      : ""
                  }
                  <button
                    class="portal-student-group-toggle"
                    type="button"
                    data-student-class-toggle="${escapeHtml(levelToken)}"
                    aria-expanded="${isExpanded ? "true" : "false"}"
                    aria-label="${isExpanded ? "Collapse class list" : "Expand class list"}"
                  >
                    <span class="portal-student-group-toggle-arrow" aria-hidden="true">${isExpanded ? "▴" : "▾"}</span>
                  </button>
                </div>
              </header>
              <div class="portal-student-group-list" ${isExpanded ? "" : "hidden"}>
                ${records
                  .map(
                    (record) => {
                      const isArchived = record.status === "archived";
                      const isTransferred = record.status === "transferred";
                      const statusClass = isArchived || isTransferred ? "is-archived" : "is-active";
                      const statusLabel = isArchived
                        ? "Archived"
                        : isTransferred
                          ? "Transferred"
                          : "Active";
                      const documentCount = Array.isArray(record.documents) ? record.documents.length : 0;
                      const profilePhotoUrl = String(record.profilePhotoUrl || "").trim();
                      const studentInitials = getInitials(record.fullName || "Student").slice(0, 2) || "ST";
                      const manageDocsAction = `
                        <button
                          class="portal-class-button"
                          type="button"
                          data-student-action="manage-docs"
                          data-student-id="${record.id}"
                        >
                          Documents
                        </button>
                      `;
                      const adminActions = !isAdmin
                        ? ""
                        : isArchived || isTransferred
	                          ? `
	                            ${manageDocsAction}
	                            <button
	                              class="portal-class-button is-restore"
	                              type="button"
                              data-student-action="activate"
                              data-student-id="${record.id}"
	                            >
	                              Reactivate
	                            </button>
	                            <button
	                              class="portal-class-button is-danger"
	                              type="button"
	                              data-student-action="delete"
	                              data-student-id="${record.id}"
	                            >
	                              Delete
	                            </button>
	                          `
	                          : `
	                            ${manageDocsAction}
                            <button
                              class="portal-class-button"
                              type="button"
                              data-student-action="edit"
                              data-student-id="${record.id}"
                            >
                              Edit
                            </button>
                            <button
                              class="portal-class-button"
                              type="button"
                              data-student-action="promote"
                              data-student-id="${record.id}"
                            >
                              Promote
                            </button>
                            <button
                              class="portal-class-button"
                              type="button"
                              data-student-action="mark-repeat"
                              data-student-id="${record.id}"
                            >
                              Set Repeat
                            </button>
                            <button
                              class="portal-class-button"
                              type="button"
                              data-student-action="mark-resit"
                              data-student-id="${record.id}"
                            >
                              Set Resit
                            </button>
                            <button
                              class="portal-class-button is-archive"
                              type="button"
                              data-student-action="transfer"
                              data-student-id="${record.id}"
                            >
                              Transfer Out
                            </button>
                            <button
                              class="portal-class-button is-archive"
                              type="button"
                              data-student-action="archive"
                              data-student-id="${record.id}"
	                            >
	                              Archive
	                            </button>
	                            <button
	                              class="portal-class-button is-danger"
	                              type="button"
	                              data-student-action="delete"
	                              data-student-id="${record.id}"
	                            >
	                              Delete
	                            </button>
	                          `;
                      return `
                      <article class="portal-student-row ${record.status === "archived" || record.status === "transferred" ? "is-archived" : ""}">
                        <button
                          class="portal-student-row-main"
                          type="button"
                          data-student-action="view"
                          data-student-id="${record.id}"
                        >
                          <span class="portal-student-row-avatar">
                            ${
                              profilePhotoUrl
                                ? `<img src="${escapeHtml(profilePhotoUrl)}" alt="" />`
                                : escapeHtml(studentInitials)
                            }
                          </span>
                          <div class="portal-student-row-copy">
                            <strong>${escapeHtml(record.fullName)}</strong>
                            <span>Admission ${escapeHtml(record.admissionNo)} • ${escapeHtml(
                              record.studentEmail || "No student email",
                            )}</span>
                            <span>${record.guardians.length} guardian contact${
                              record.guardians.length === 1 ? "" : "s"
                            }</span>
                            <span>Session close: ${escapeHtml(
                              record.promotionDecision === "repeat"
                                ? "Repeat class"
                                : record.promotionDecision === "resit"
                                  ? "Resit required"
                                  : "Auto promote",
                            )}</span>
                            <span>${documentCount} document${documentCount === 1 ? "" : "s"}</span>
                          </div>
                          <span class="portal-class-status ${statusClass}">${statusLabel}</span>
                        </button>
                        <div class="portal-class-actions">
                          ${adminActions}
                        </div>
                      </article>
                    `;
                    },
                  )
                  .join("")}
              </div>
            </section>
          `;
        })
        .join("");
    }

    if (!isAdmin) {
      setStatus(
        status,
        "info",
        "Only admin accounts with student permission can create, edit, promote, queue repeat/resit, transfer, archive, or reactivate student records.",
      );
    }
  }

  function backfillGuardianAccessFromStudents(manager) {
    if (!manager || typeof manager.getStudents !== "function") {
      return 0;
    }

    const workspaceId = normalizeWorkspaceId(getCurrentWorkspaceId());
    const grants = getAccessGrants({ workspaceId });
    const existingGrantEmails = new Set(grants.map((entry) => normalizeEmail(entry.email || "")));
    let createdCount = 0;

    manager.getStudents().forEach((student) => {
      const guardians = Array.isArray(student?.guardians) ? student.guardians : [];

      guardians.forEach((guardian) => {
        const email = String(guardian?.email || "").trim();

        if (!email || !EMAIL_REGEX.test(email)) {
          return;
        }

        const normalizedEmail = normalizeEmail(email);

        if (existingGrantEmails.has(normalizedEmail)) {
          return;
        }

        upsertAccessGrant(
          {
            email,
            role: "Parent",
            authMethod: "any",
            status: "active",
          },
          workspaceId,
        );
        existingGrantEmails.add(normalizedEmail);
        createdCount += 1;
      });
    });

    return createdCount;
  }

  function clearPortalStudentErrors(form) {
    form.querySelectorAll(".portal-field").forEach((field) => field.classList.remove("is-invalid"));
    form.querySelectorAll("[data-student-error-for]").forEach((error) => {
      error.textContent = "";
    });
  }

  function setPortalStudentError(form, fieldName, message) {
    const error = form.querySelector(`[data-student-error-for="${fieldName}"]`);
    const control = form.elements[fieldName];
    const field = control ? control.closest(".portal-field") : null;

    if (error) {
      error.textContent = message;
    }

    if (field) {
      field.classList.add("is-invalid");
    }
  }

  function normalizePhoneValue(value) {
    return String(value || "").trim();
  }

  function isValidPhoneNumber(value) {
    const digits = normalizePhoneValue(value).replace(/\D/g, "");
    return digits.length >= 10 && digits.length <= 15;
  }

  function normalizeLevelToken(value) {
    const token = String(value || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]/g, "");

    const juniorSecondaryMatch = token.match(/(?:juniorsecondaryschool|jss)([1-3])/);
    if (juniorSecondaryMatch) {
      return `jss${juniorSecondaryMatch[1]}`;
    }

    const seniorSecondaryMatch = token.match(/(?:seniorsecondaryschool|sss|ss)([1-3])/);
    if (seniorSecondaryMatch) {
      return `sss${seniorSecondaryMatch[1]}`;
    }

    const romanLevelMap = { i: "1", ii: "2", iii: "3" };
    const higherDiplomaMatch = token.match(/^(nd|hnd|nce)(i{1,3}|[1-3])$/);
    if (higherDiplomaMatch) {
      return `${higherDiplomaMatch[1]}${romanLevelMap[higherDiplomaMatch[2]] || higherDiplomaMatch[2]}`;
    }

    return token;
  }

  function getStudentLevelDisplayLabel(value) {
    const raw = String(value || "").trim();
    const token = normalizeLevelToken(raw);

    if (!raw || !token) {
      return "";
    }

    const secondaryLevel = SECONDARY_LEVEL_TEMPLATES.find(
      (level) => normalizeLevelToken(level) === token,
    );

    if (secondaryLevel) {
      return secondaryLevel;
    }

    const juniorSecondaryMatch = token.match(/^jss([1-3])$/);
    if (juniorSecondaryMatch) {
      return `Junior Secondary School ${juniorSecondaryMatch[1]} (JSS${juniorSecondaryMatch[1]})`;
    }

    const seniorSecondaryMatch = token.match(/^sss([1-3])$/);
    if (seniorSecondaryMatch) {
      return `Senior Secondary School ${seniorSecondaryMatch[1]} (SSS${seniorSecondaryMatch[1]})`;
    }

    return raw;
  }

  function getTodayDateValue() {
    const date = new Date();
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }

  function normalizeAttendanceStatus(value) {
    const normalized = String(value || "present").trim().toLowerCase();
    return ATTENDANCE_STATUSES.includes(normalized) ? normalized : "present";
  }

  function getAttendanceStatusLabel(value) {
    const status = normalizeAttendanceStatus(value);
    if (status === "late") return "Late";
    if (status === "absent") return "Absent";
    if (status === "excused") return "Excused";
    return "Present";
  }

  function getAttendanceStatusClass(value) {
    return `is-${normalizeAttendanceStatus(value)}`;
  }

  function getTeacherDisplayNameForValue(value = "") {
    const teacherValue = String(value || "").trim();
    if (!teacherValue) {
      return "";
    }

    const teacherEmail = EMAIL_REGEX.test(teacherValue) ? normalizeEmail(teacherValue) : "";
    const teacherLookup = teacherValue.toLowerCase();
    const matchedUser = getUsers().find((user) => {
      if (normalizeRoleLabel(user.role || DEFAULT_AUTH_ROLE) !== "Teacher") {
        return false;
      }
      const userEmail = normalizeEmail(user.email || "");
      const userName = String(user.displayName || "").trim().toLowerCase();
      return (teacherEmail && userEmail === teacherEmail) || (userName && userName === teacherLookup);
    });

    if (matchedUser?.displayName) {
      return matchedUser.displayName;
    }

    if (teacherEmail) {
      return buildDisplayName(teacherEmail) || "Teacher";
    }

    return teacherValue;
  }

  function getActiveStudentsForClass(classRecord = {}) {
    const studentManager = getStudentManager();
    const students =
      studentManager && typeof studentManager.getStudents === "function"
        ? studentManager.getStudents()
        : [];
    const classId = String(classRecord.id || "").trim();
    const hasDistinctArm =
      classRecord.name &&
      classRecord.level &&
      normalizeLevelToken(classRecord.name) !== normalizeLevelToken(classRecord.level);
    const classTokens = [
      hasDistinctArm ? "" : normalizeLevelToken(classRecord.level),
      hasDistinctArm ? "" : normalizeLevelToken(classRecord.name),
      normalizeLevelToken(`${classRecord.level || ""} ${classRecord.name || ""}`),
      normalizeLevelToken(getClassDisplayName(classRecord)),
    ].filter(Boolean);
    const baseLevelToken = normalizeLevelToken(classRecord.level);
    const armToken = normalizeLevelToken(classRecord.name);

    return students.filter((student) => {
      if (student.status !== "active") {
        return false;
      }

      const studentClassId = String(student.classId || student.classRecordId || "").trim();
      if (studentClassId) {
        return Boolean(classId && studentClassId === classId);
      }

      const studentLevelToken = normalizeLevelToken(student.level);
      const studentBaseLevelToken = normalizeLevelToken(student.classLevel || student.baseLevel);
      const studentArmToken = normalizeLevelToken(student.classArm);

      if (hasDistinctArm) {
        const exactLevelMatches = classTokens.includes(studentLevelToken);
        const baseLevelMatches = Boolean(
          baseLevelToken &&
            ((studentBaseLevelToken && studentBaseLevelToken === baseLevelToken) ||
              (studentLevelToken && studentLevelToken === baseLevelToken)),
        );
        if (studentArmToken) {
          return (
            studentArmToken === armToken &&
            (exactLevelMatches || baseLevelMatches)
          );
        }

        return exactLevelMatches;
      }

      return classTokens.includes(studentLevelToken) || Boolean(studentBaseLevelToken && studentBaseLevelToken === baseLevelToken);
    });
  }

  function getClassDisplayName(classRecord = {}) {
    const level = String(classRecord.level || "").trim();
    const name = String(classRecord.name || "").trim();

    if (level && name && normalizeLevelToken(level) !== normalizeLevelToken(name)) {
      return `${level} ${name.replace(/^Arm\s+/i, "")}`.trim();
    }

    return level || name || "Class";
  }

  function courseAppliesToClassRecord(course = {}, classRecord = {}) {
    const courseClassId = String(course.classId || course.classRecordId || "").trim();
    const classId = String(classRecord.id || "").trim();
    const courseScope = String(course.classScope || "").trim().toLowerCase();

    if (courseClassId) {
      return Boolean(classId && courseClassId === classId);
    }

    if (courseScope === "all-arms") {
      return normalizeLevelToken(course.level) === normalizeLevelToken(classRecord.level);
    }

    const classTokens = [
      normalizeLevelToken(classRecord.level),
      normalizeLevelToken(classRecord.name),
      normalizeLevelToken(getClassDisplayName(classRecord)),
    ].filter(Boolean);
    const courseTokens = [
      normalizeLevelToken(course.classLabel),
      normalizeLevelToken(course.level),
    ].filter(Boolean);

    return courseTokens.some((token) => classTokens.includes(token));
  }

  function getTeacherAssignedClasses(user = {}) {
    const classManager = getClassManager();
    const courseManager = getCourseManager();
    const teacherEmail = normalizeEmail(user.email || "");
    const teacherName = String(user.displayName || user.email || "").trim().toLowerCase();
    const classes =
      classManager && typeof classManager.getClasses === "function"
        ? classManager.getClasses().filter((record) => record.status !== "archived")
        : [];
    const courses =
      courseManager && typeof courseManager.getCourses === "function"
        ? courseManager.getCourses().filter((record) => record.status !== "archived")
        : [];
    const teacherCourses = courses.filter((course) =>
      (course.teacherAssignments || []).some((teacher) => {
        const value = String(teacher || "").trim();
        return normalizeEmail(value) === teacherEmail || value.toLowerCase() === teacherName;
      }),
    );
    const courseClassIds = new Set(
      teacherCourses
        .map((course) => String(course.classId || course.classRecordId || "").trim())
        .filter(Boolean),
    );
    const courseLevelTokens = new Set(
      teacherCourses
        .filter((course) => !String(course.classId || course.classRecordId || "").trim())
        .map((course) =>
          String(course.classScope || "").trim().toLowerCase() === "all-arms"
            ? normalizeLevelToken(course.level)
            : normalizeLevelToken(course.classLabel || course.level),
        )
        .filter(Boolean),
    );
    const assigned = classes.filter((classRecord) => {
      const classTeacher = String(classRecord.classTeacher || "").trim();
      const isClassTeacher =
        normalizeEmail(classTeacher) === teacherEmail || classTeacher.toLowerCase() === teacherName;
      const hasSubjectAssignment = (classRecord.teacherAssignments || []).some((assignment) => {
        const assignmentTeacher = String(assignment?.teacher || "").trim();
        return normalizeEmail(assignmentTeacher) === teacherEmail || assignmentTeacher.toLowerCase() === teacherName;
      });
      const exactClassTokens = [
        normalizeLevelToken(classRecord.level),
        normalizeLevelToken(getClassDisplayName(classRecord)),
        normalizeLevelToken(`${classRecord.level || ""} ${classRecord.name || ""}`),
      ].filter(Boolean);
      const hasCourseAssignment =
        courseClassIds.has(String(classRecord.id || "").trim()) ||
        exactClassTokens.some((token) => courseLevelTokens.has(token));

      return isClassTeacher || hasSubjectAssignment || hasCourseAssignment;
    });
    const seen = new Set();

    return assigned.filter((classRecord) => {
      const key = classRecord.id || `${classRecord.level}:${classRecord.name}`;
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
  }

  function getTeacherResultManagedClasses(user = {}) {
    const classManager = getClassManager();
    const classes =
      classManager && typeof classManager.getClasses === "function"
        ? classManager.getClasses().filter((record) => record.status !== "archived")
        : [];
    const seen = new Set();

    return classes
      .filter((classRecord) => staffValueMatchesUser(classRecord.classTeacher, user))
      .filter((classRecord) => {
        const key = classRecord.id || `${classRecord.level}:${classRecord.name}`;
        if (seen.has(key)) {
          return false;
        }
        seen.add(key);
        return true;
      });
  }

  function getAttendanceRecordEntryMap(record = null) {
    return new Map(
      (record?.entries || []).map((entry) => [
        String(entry.studentId || "").trim(),
        {
          status: normalizeAttendanceStatus(entry.status),
          note: String(entry.note || "").trim(),
        },
      ]),
    );
  }

  function syncAttendanceAbsenceNotifications(record = null, workspaceId = null) {
    if (!record?.id) {
      return;
    }

    const normalizedWorkspaceId = normalizeWorkspaceId(workspaceId || getCurrentWorkspaceId());
    const existing = getNotifications(normalizedWorkspaceId);
    const recordNotifications = new Map(
      existing
        .filter(
          (entry) =>
            String(entry.entityType || "").trim().toLowerCase() === "attendance-absence" &&
            String(entry.metadata?.attendanceRecordId || "") === String(record.id),
        )
        .map((entry) => [String(entry.metadata?.studentId || entry.entityId || ""), entry]),
    );
    const retained = existing.filter(
      (entry) =>
        !(
          String(entry.entityType || "").trim().toLowerCase() === "attendance-absence" &&
          String(entry.metadata?.attendanceRecordId || "") === String(record.id)
        ),
    );
    const absenceNotifications = (record.entries || [])
      .filter((entry) => normalizeAttendanceStatus(entry.status) === "absent")
      .map((entry) => {
        const previous = recordNotifications.get(String(entry.studentId || "")) || {};
        return normalizeNotificationEntry(
          {
            ...previous,
            id: `attendance-absence:${record.id}:${entry.studentId}`,
            title: `Absence recorded for ${entry.studentName || "student"}`,
            message: `${entry.studentName || "The student"} was marked absent on ${record.date || "the selected date"}${
              entry.note ? `. Note: ${entry.note}` : "."
            }`,
            entityType: "attendance-absence",
            entityId: entry.studentId,
            action: "recorded",
            actorName: record.submittedByName || record.submittedByEmail || "School",
            createdAt: previous.createdAt || record.takenAt || record.updatedAt || nowIso(),
            visibleToRoles: ["Parent", "Student"],
            metadata: {
              ...(previous.metadata || {}),
              attendanceRecordId: record.id,
              studentId: entry.studentId,
              studentName: entry.studentName || "",
              classId: record.classId || "",
              className: record.className || record.level || "",
              attendanceDate: record.date || "",
              note: entry.note || "",
            },
          },
          normalizedWorkspaceId,
        );
      });

    saveNotifications([...absenceNotifications, ...retained], normalizedWorkspaceId);
    window.dispatchEvent(
      new CustomEvent(NOTIFICATION_EVENT_NAME, {
        detail: { workspaceId: normalizedWorkspaceId },
      }),
    );
  }

  function syncStoredAttendanceAbsenceNotifications(workspaceId = null) {
    const attendanceManager = getAttendanceManager();
    const records =
      attendanceManager && typeof attendanceManager.getRecords === "function"
        ? attendanceManager.getRecords()
        : [];
    records.forEach((record) => syncAttendanceAbsenceNotifications(record, workspaceId));
  }

  function summarizeAttendanceForStudents(students = [], records = []) {
    const latestEntryByStudent = new Map();

    records.forEach((record) => {
      (record.entries || []).forEach((entry) => {
        latestEntryByStudent.set(entry.studentId, {
          ...entry,
          classId: record.classId,
          className: record.className,
          level: record.level,
          submittedByName: record.submittedByName,
          submittedByEmail: record.submittedByEmail,
          takenAt: record.takenAt,
        });
      });
    });

    return students.reduce(
      (summary, student) => {
        const entry = latestEntryByStudent.get(student.id);
        const status = entry?.status || "unmarked";
        summary.counts[status] = (summary.counts[status] || 0) + 1;
        summary.rows.push({ student, entry, status });
        return summary;
      },
      {
        counts: { present: 0, absent: 0, late: 0, excused: 0, unmarked: 0 },
        rows: [],
      },
    );
  }

  function isAttendanceDateWithinAcademicTerm(date, term = {}) {
    const normalizedDate = String(date || "").trim();
    const startDate = String(term.startDate || "").trim();
    const endDate = String(term.endDate || "").trim();

    return Boolean(
      normalizedDate &&
      startDate &&
      endDate &&
      normalizedDate >= startDate &&
      normalizedDate <= endDate,
    );
  }

  function getAttendanceAcademicTermForDate(cycleState = {}, date = "") {
    const matchingTerms = (cycleState.terms || []).filter((term) =>
      isAttendanceDateWithinAcademicTerm(date, term),
    );
    const openUndatedTerm = (cycleState.terms || []).find((term) => {
      const startDate = String(term.startDate || "").trim();
      const endDate = String(term.endDate || "").trim();
      return term.status === "open" && (!startDate || !endDate);
    });

    return matchingTerms.find((term) => term.status === "open") || matchingTerms[0] || openUndatedTerm || null;
  }

  function attendanceRecordMatchesAcademicTerm(record = {}, term = {}, cycleState = {}) {
    const recordTermId = String(record.termId || "").trim();

    if (recordTermId) {
      return recordTermId === term.id;
    }

    const inferredTerm = getAttendanceAcademicTermForDate(cycleState, record.date);
    return inferredTerm?.id === term.id;
  }

  function summarizeAttendancePeriodForStudents(students = [], records = []) {
    const latestEntryByStudentDate = new Map();

    records.forEach((record) => {
      (record.entries || []).forEach((entry) => {
        const key = `${entry.studentId}:${record.date}`;
        const previous = latestEntryByStudentDate.get(key);
        const previousTimestamp = new Date(previous?.takenAt || previous?.updatedAt || 0).getTime();
        const nextTimestamp = new Date(record.takenAt || record.updatedAt || 0).getTime();

        if (!previous || nextTimestamp >= previousTimestamp) {
          latestEntryByStudentDate.set(key, {
            ...entry,
            date: record.date,
            classId: record.classId,
            className: record.className,
            level: record.level,
            submittedByName: record.submittedByName,
            submittedByEmail: record.submittedByEmail,
            takenAt: record.takenAt,
            updatedAt: record.updatedAt,
          });
        }
      });
    });

    return students.reduce(
      (summary, student) => {
        const entries = Array.from(latestEntryByStudentDate.values())
          .filter((entry) => entry.studentId === student.id)
          .sort((left, right) => String(right.date || "").localeCompare(String(left.date || "")));
        const counts = entries.reduce(
          (totals, entry) => {
            const status = normalizeAttendanceStatus(entry.status);
            totals[status] += 1;
            summary.counts[status] += 1;
            return totals;
          },
          { present: 0, absent: 0, late: 0, excused: 0 },
        );
        const rateDenominator = counts.present + counts.late + counts.absent;
        const attendanceRate = rateDenominator
          ? Math.round(((counts.present + counts.late) / rateDenominator) * 100)
          : null;

        summary.rows.push({
          student,
          counts,
          recordedDays: entries.length,
          attendanceRate,
          lastEntry: entries[0] || null,
        });
        return summary;
      },
      {
        counts: { present: 0, absent: 0, late: 0, excused: 0 },
        rows: [],
      },
    );
  }

  function getActiveClassLevelTokenSet() {
    const classManager = window.SchoolSphereClasses;
    const set = new Set();

    getConfiguredStudentLevelOptions().forEach((level) => {
      const token = normalizeLevelToken(level);
      if (token) {
        set.add(token);
      }
    });

    if (!classManager || typeof classManager.getClasses !== "function") {
      return set;
    }

    return classManager.getClasses().reduce((tokens, record) => {
      if (record.status === "archived") {
        return tokens;
      }

      if (
        inferSchoolTypeFromLevel(record.level) === "higher" &&
        !isConfiguredHigherInstitutionLevel(record.level)
      ) {
        return tokens;
      }

      const recordTokens = [
        normalizeLevelToken(record.level),
        normalizeLevelToken(record.name),
        normalizeLevelToken(`${record.level || ""} ${record.name || ""}`),
      ].filter(Boolean);
      recordTokens.forEach((token) => tokens.add(token));
      return tokens;
    }, set);
  }

  function isKnownClassLevel(levelValue, tokenSet) {
    const levelToken = normalizeLevelToken(levelValue);
    if (!levelToken || !(tokenSet instanceof Set) || tokenSet.size === 0) {
      return true;
    }
    return tokenSet.has(levelToken);
  }

  function getSchoolAcronymForAdmission() {
    const settingsManager = getSchoolSettingsManager();
    const schoolName = settingsManager?.getSettings?.().schoolName || "SchoolSphere";
    const words = schoolName
      .toLowerCase()
      .split(/[^a-z0-9]+/g)
      .filter(Boolean);

    if (words.length >= 2) {
      return words
        .slice(0, 3)
        .map((word) => word.charAt(0))
        .join("");
    }

    const fallback = (words[0] || "schoolsphere").slice(0, 3);
    return fallback.padEnd(3, "x");
  }

  function buildAdmissionPrefix(levelValue) {
    const schoolAcronym = getSchoolAcronymForAdmission();
    const yearCode = String(new Date().getFullYear()).slice(-2);
    const levelCode = normalizeLevelToken(levelValue) || "general";
    return `${schoolAcronym}${yearCode}/${levelCode}`;
  }

  function generateAdmissionNumber({
    manager,
    levelValue,
    excludeStudentId,
    takenAdmissions,
  }) {
    const prefix = buildAdmissionPrefix(levelValue);
    const used = new Set();

    if (takenAdmissions instanceof Set) {
      takenAdmissions.forEach((value) => used.add(String(value || "").toLowerCase()));
    }

    if (manager && typeof manager.getStudents === "function") {
      manager.getStudents().forEach((student) => {
        if (excludeStudentId && student.id === excludeStudentId) {
          return;
        }
        if (student.admissionNo) {
          used.add(String(student.admissionNo).toLowerCase());
        }
      });
    }

    let highestSequence = 0;
    const prefixLower = `${prefix.toLowerCase()}/`;
    used.forEach((entry) => {
      if (!entry.startsWith(prefixLower)) {
        return;
      }
      const maybeSequence = Number(entry.slice(prefixLower.length));
      if (Number.isFinite(maybeSequence) && maybeSequence > highestSequence) {
        highestSequence = maybeSequence;
      }
    });

    let nextSequence = highestSequence + 1;
    let candidate = `${prefix}/${String(nextSequence).padStart(3, "0")}`;
    while (used.has(candidate.toLowerCase())) {
      nextSequence += 1;
      candidate = `${prefix}/${String(nextSequence).padStart(3, "0")}`;
    }

    return candidate.toLowerCase();
  }

  function resolveGuardianRelationshipFields(row) {
    const relationshipType =
      row.querySelector('[data-guardian-field="relationshipType"]')?.value.trim() || "";
    const relationshipOther =
      row.querySelector('[data-guardian-field="relationshipOther"]')?.value.trim() || "";
    const relationship =
      relationshipType === "Other" ? relationshipOther : relationshipType;

    return {
      relationshipType,
      relationshipOther,
      relationship,
    };
  }

  function updateGuardianRelationshipCustomField(row) {
    if (!row) {
      return;
    }

    const relationshipTypeControl = row.querySelector('[data-guardian-field="relationshipType"]');
    const relationshipOtherControl = row.querySelector('[data-guardian-field="relationshipOther"]');

    if (!(relationshipTypeControl instanceof HTMLSelectElement) || !(relationshipOtherControl instanceof HTMLInputElement)) {
      return;
    }

    const isOther = relationshipTypeControl.value === "Other";
    relationshipOtherControl.classList.toggle("is-hidden", !isOther);
    relationshipOtherControl.disabled = !isOther;

    if (!isOther) {
      relationshipOtherControl.value = "";
    }
  }

  function appendGuardianRow(container, guardian = {}, isAdmin = true) {
    if (!container) {
      return;
    }

    const relationshipValue = String(guardian.relationship || "").trim();
    const hasPresetRelationship = GUARDIAN_RELATIONSHIP_TYPES
      .filter((type) => type !== "Other")
      .some((type) => type.toLowerCase() === relationshipValue.toLowerCase());
    const selectedRelationshipType = relationshipValue
      ? hasPresetRelationship
        ? GUARDIAN_RELATIONSHIP_TYPES.find(
            (type) => type.toLowerCase() === relationshipValue.toLowerCase(),
          ) || ""
        : "Other"
      : "";
    const customRelationship = selectedRelationshipType === "Other" ? relationshipValue : "";
    const relationshipOptions = [
      '<option value="">Relationship type</option>',
      ...GUARDIAN_RELATIONSHIP_TYPES.map(
        (type) =>
          `<option value="${escapeHtml(type)}" ${
            selectedRelationshipType === type ? "selected" : ""
          }>${escapeHtml(type)}</option>`,
      ),
    ].join("");

    const row = document.createElement("div");
    row.className = "portal-guardian-row";
    row.dataset.guardianId = guardian.id || createId();
    row.innerHTML = `
      <input type="text" data-guardian-field="name" placeholder="Guardian name" value="${escapeHtml(
        guardian.name || "",
      )}" ${isAdmin ? "" : "disabled"} />
      <select data-guardian-field="relationshipType" ${isAdmin ? "" : "disabled"}>
        ${relationshipOptions}
      </select>
      <input
        type="text"
        data-guardian-field="relationshipOther"
        class="${selectedRelationshipType === "Other" ? "" : "is-hidden"}"
        placeholder="Enter relationship type"
        value="${escapeHtml(customRelationship)}"
        ${isAdmin && selectedRelationshipType === "Other" ? "" : "disabled"}
      />
      <input type="text" data-guardian-field="phone" placeholder="+234 800 000 0000" value="${escapeHtml(
        guardian.phone || "",
      )}" ${isAdmin ? "" : "disabled"} />
      <input type="email" data-guardian-field="email" placeholder="guardian@email.com" value="${escapeHtml(
        guardian.email || "",
      )}" ${isAdmin ? "" : "disabled"} />
      <button type="button" class="portal-guardian-remove" data-remove-guardian ${isAdmin ? "" : "disabled"}>Remove</button>
    `;
    container.appendChild(row);
    updateGuardianRelationshipCustomField(row);
  }

  function parseGuardianRows(container, options = {}) {
    const { validatePhone = false } = options;
    const rows = Array.from(container.querySelectorAll(".portal-guardian-row"));
    const guardians = [];
    let hasInvalidRow = false;
    let hasInvalidPhone = false;

    rows.forEach((row) => {
      const name = row.querySelector('[data-guardian-field="name"]')?.value.trim() || "";
      const { relationshipType, relationship } = resolveGuardianRelationshipFields(row);
      const phone = row.querySelector('[data-guardian-field="phone"]')?.value.trim() || "";
      const email = row.querySelector('[data-guardian-field="email"]')?.value.trim() || "";

      if (!name && !relationship && !phone && !email) {
        return;
      }

      if (
        !name ||
        !relationship ||
        (relationshipType === "Other" && !relationship) ||
        (!phone && !email)
      ) {
        hasInvalidRow = true;
        return;
      }

      if (validatePhone && phone && !isValidPhoneNumber(phone)) {
        hasInvalidPhone = true;
      }

      guardians.push({
        id: row.dataset.guardianId || createId(),
        name,
        relationship,
        phone,
        email,
      });
    });

    return { guardians, hasInvalidRow, hasInvalidPhone };
  }

  function resetPortalStudentForm(form, guardianList, isAdmin) {
    if (!form) {
      return;
    }

    form.reset();

    if (form.elements.studentId) {
      form.elements.studentId.value = "";
    }

    if (form.elements.admissionNo) {
      form.elements.admissionNo.dataset.autoGenerated = "false";
    }
    if (form.elements.promotionDecision) {
      form.elements.promotionDecision.value = "promote";
    }
    if (form.elements.level instanceof HTMLSelectElement) {
      renderStudentLevelSelectOptions(form.elements.level);
    }
    renderStudentClassArmOptions(form, "", { autoPick: false });

    if (guardianList) {
      guardianList.innerHTML = "";
      appendGuardianRow(guardianList, {}, isAdmin);
    }

    const submitButton = form.querySelector("[data-student-submit]");
    const cancelButton = form.querySelector("[data-student-cancel]");

    if (submitButton) {
      submitButton.textContent = "Create student";
    }

    if (cancelButton) {
      cancelButton.hidden = true;
    }

    Array.from(form.elements).forEach((field) => {
      if (field instanceof HTMLElement) {
        field.disabled = !isAdmin;
      }
    });
  }

  function populatePortalStudentForm(form, guardianList, record, isAdmin) {
    if (!form || !record) {
      return;
    }

    form.elements.studentId.value = record.id;
    form.elements.firstName.value = record.firstName || "";
    form.elements.lastName.value = record.lastName || "";
    form.elements.admissionNo.value = record.admissionNo || "";
    if (form.elements.studentEmail) {
      form.elements.studentEmail.value = record.studentEmail || "";
    }
    form.elements.admissionNo.dataset.autoGenerated = "false";
    if (form.elements.level instanceof HTMLSelectElement) {
      const baseLevel = getStudentBaseClassLevel(record);
      const levels = renderStudentLevelSelectOptions(form.elements.level, baseLevel || record.level || "");
      const matchingLevel =
        levels.find((level) => normalizeLevelToken(level) === normalizeLevelToken(baseLevel)) ||
        baseLevel ||
        record.level ||
        "";
      form.elements.level.value = matchingLevel;
    } else {
      form.elements.level.value = getStudentBaseClassLevel(record) || record.level || "";
    }
    renderStudentClassArmOptions(form, record.classId || record.classRecordId || findClassRecordForStudent(record)?.id || "", {
      autoPick: true,
    });
    if (form.elements.dateOfBirth) {
      form.elements.dateOfBirth.value = record.dateOfBirth || "";
    }
    if (form.elements.gender) {
      form.elements.gender.value = record.gender || "";
    }
    if (form.elements.promotionDecision) {
      const decision = String(record.promotionDecision || "promote").toLowerCase();
      form.elements.promotionDecision.value =
        decision === "repeat" || decision === "resit" ? decision : "promote";
    }

    if (guardianList) {
      guardianList.innerHTML = "";
      (record.guardians || []).forEach((guardian) => {
        appendGuardianRow(guardianList, guardian, isAdmin);
      });

      if (!record.guardians || !record.guardians.length) {
        appendGuardianRow(guardianList, {}, isAdmin);
      }
    }

    const submitButton = form.querySelector("[data-student-submit]");
    const cancelButton = form.querySelector("[data-student-cancel]");

    if (submitButton) {
      submitButton.textContent = "Save changes";
    }

    if (cancelButton) {
      cancelButton.hidden = !isAdmin;
    }

    Array.from(form.elements).forEach((field) => {
      if (field instanceof HTMLElement) {
        field.disabled = !isAdmin;
      }
    });
  }

  function normalizeImportHeader(value) {
    return String(value || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
  }

  function parseCsvLine(line) {
    const values = [];
    let current = "";
    let inQuotes = false;

    for (let index = 0; index < line.length; index += 1) {
      const character = line[index];

      if (character === '"') {
        if (inQuotes && line[index + 1] === '"') {
          current += '"';
          index += 1;
        } else {
          inQuotes = !inQuotes;
        }
        continue;
      }

      if (character === "," && !inQuotes) {
        values.push(current.trim());
        current = "";
        continue;
      }

      current += character;
    }

    values.push(current.trim());
    return values;
  }

  function parseCsvRows(content) {
    const lines = String(content || "")
      .replace(/\r\n/g, "\n")
      .replace(/\r/g, "\n")
      .split("\n")
      .filter((line) => line.trim().length);

    if (!lines.length) {
      return [];
    }

    const headers = parseCsvLine(lines[0]).map(normalizeImportHeader);
    return lines.slice(1).map((line) => {
      const values = parseCsvLine(line);
      return headers.reduce((row, header, index) => {
        row[header] = values[index] || "";
        return row;
      }, {});
    });
  }

  function parseSpreadsheetXmlRows(content) {
    const parser = new DOMParser();
    const xml = parser.parseFromString(String(content || ""), "application/xml");

    if (xml.querySelector("parsererror")) {
      throw new Error("Unable to read this Excel file. Please use the provided template or upload CSV.");
    }

    const rowNodes = Array.from(xml.getElementsByTagName("Row"));

    if (!rowNodes.length) {
      throw new Error("No worksheet rows found. Please use the provided template or upload CSV.");
    }

    const rows = rowNodes.map((rowNode) => {
      const result = [];
      let pointer = 1;

      Array.from(rowNode.children)
        .filter((child) => child.localName === "Cell" || child.tagName.endsWith(":Cell"))
        .forEach((cellNode) => {
          const indexAttr =
            cellNode.getAttribute("ss:Index") ||
            cellNode.getAttribute("Index") ||
            cellNode.getAttributeNS("urn:schemas-microsoft-com:office:spreadsheet", "Index");

          if (indexAttr) {
            pointer = Number(indexAttr);
          }

          const dataNode =
            cellNode.querySelector("Data") ||
            cellNode.querySelector("ss\\:Data") ||
            cellNode.getElementsByTagName("Data")[0] ||
            cellNode.getElementsByTagName("ss:Data")[0];
          result[pointer - 1] = dataNode ? String(dataNode.textContent || "").trim() : "";
          pointer += 1;
        });

      return result;
    });

    const [headerRow, ...dataRows] = rows;
    const headers = (headerRow || []).map(normalizeImportHeader);
    return dataRows
      .filter((row) => row.some((cell) => String(cell || "").trim()))
      .map((row) =>
        headers.reduce((record, header, index) => {
          record[header] = String(row[index] || "").trim();
          return record;
        }, {}),
      );
  }

  function toTemplateRows() {
    return [
      [
        "first name",
        "last name",
        "student email",
        "admission number",
        "level/class",
        "date of birth",
        "gender",
        "parent/guardian name",
        "parent/guardian number",
        "parent/guardian email",
      ],
      [
        "First Name",
        "Last Name",
        "student@example.com",
        "csa26/jss1/001",
        "Junior Secondary School 1 (JSS1)",
        "2013-10-08",
        "Female",
        "Guardian Name",
        "+2348000000000",
        "guardian@example.com",
      ],
    ];
  }

  function downloadTextFile(filename, content, mimeType) {
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  }

  function downloadStudentCsvTemplate() {
    const rows = toTemplateRows();
    const csv = rows
      .map((row) =>
        row
          .map((value) => {
            const stringValue = String(value || "");
            if (/[",\n]/.test(stringValue)) {
              return `"${stringValue.replace(/"/g, '""')}"`;
            }
            return stringValue;
          })
          .join(","),
      )
      .join("\n");
    downloadTextFile("students-import-template.csv", csv, "text/csv;charset=utf-8");
  }

  function downloadStudentExcelTemplate() {
    const rows = toTemplateRows();
    const escapedRows = rows
      .map(
        (row) => `
          <Row>${row.map((cell) => `<Cell><Data ss:Type="String">${escapeHtml(cell)}</Data></Cell>`).join("")}</Row>`,
      )
      .join("");
    const xml = `<?xml version="1.0"?>
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:o="urn:schemas-microsoft-com:office:office"
 xmlns:x="urn:schemas-microsoft-com:office:excel"
 xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">
  <Worksheet ss:Name="Students">
    <Table>
      ${escapedRows}
    </Table>
  </Worksheet>
</Workbook>`;
    downloadTextFile(
      "students-import-template.xls",
      xml,
      "application/vnd.ms-excel;charset=utf-8",
    );
  }

  function getImportFieldValue(row, aliases) {
    for (const alias of aliases) {
      const normalizedAlias = normalizeImportHeader(alias);
      if (row[normalizedAlias] !== undefined && row[normalizedAlias] !== null) {
        return String(row[normalizedAlias]).trim();
      }
    }
    return "";
  }

  function buildStudentPayloadFromImportRow(row, manager, takenAdmissions) {
    const firstName = getImportFieldValue(row, ["first name", "firstname"]);
    const lastName = getImportFieldValue(row, ["last name", "lastname"]);
    const studentEmail = getImportFieldValue(row, ["student email", "learner email", "student e-mail"]);
    const level = getImportFieldValue(row, ["level/class", "level class", "level"]);
    const dateOfBirth = getImportFieldValue(row, ["date of birth", "dob"]);
    const gender = getImportFieldValue(row, ["gender"]);
    const guardianName = getImportFieldValue(row, ["parent/guardian name", "guardian name", "parent name"]);
    const guardianPhone = getImportFieldValue(row, ["parent/guardian number", "guardian number", "parent number", "phone"]);
    const guardianEmail = getImportFieldValue(row, ["parent/guardian email", "guardian email", "parent email", "email"]);
    let admissionNo = getImportFieldValue(row, ["admission number", "admission no", "admission"]);

    if (!admissionNo) {
      admissionNo = generateAdmissionNumber({ manager, levelValue: level, takenAdmissions });
    }

    if (takenAdmissions instanceof Set) {
      takenAdmissions.add(admissionNo.toLowerCase());
    }
    const selectedClassRecord = chooseStudentClassRecordForLevel(level);
    const classAssignment = buildStudentClassAssignment(level, selectedClassRecord);

    return {
      firstName,
      lastName,
      fullName: [firstName, lastName].filter(Boolean).join(" ").trim(),
      studentEmail,
      admissionNo,
      ...classAssignment,
      dateOfBirth,
      gender,
      promotionDecision: "promote",
      examOutcome: "pass",
      guardians: guardianName
        ? [
            {
              id: createId(),
              name: guardianName,
              relationship: "Guardian",
              phone: guardianPhone,
              email: guardianEmail,
            },
          ]
        : [],
    };
  }

  function validateImportPayload(payload, manager, classLevelSet, seenAdmissions) {
    const errors = [];

    if (!payload.firstName || !payload.lastName) {
      errors.push("Missing name");
    }

    if (!payload.level) {
      errors.push("Missing level/class");
    } else if (!isKnownClassLevel(payload.level, classLevelSet)) {
      errors.push("Invalid class");
    }

    if (!payload.admissionNo) {
      errors.push("Admission number missing");
    }

    if (payload.studentEmail && !EMAIL_REGEX.test(payload.studentEmail)) {
      errors.push("Invalid student email");
    }

    if (payload.admissionNo) {
      const admissionLower = payload.admissionNo.toLowerCase();
      const duplicateExisting = manager
        ?.getStudents?.()
        .some((record) => String(record.admissionNo || "").toLowerCase() === admissionLower);
      if (duplicateExisting || seenAdmissions.has(admissionLower)) {
        errors.push("Duplicate admission number");
      }
      seenAdmissions.add(admissionLower);
    }

    const guardian = payload.guardians[0] || null;
    if (!guardian || !guardian.name) {
      errors.push("Missing parent/guardian name");
    }

    if (guardian?.phone && !isValidPhoneNumber(guardian.phone)) {
      errors.push("Wrong phone number format");
    }

    if (!guardian?.email) {
      errors.push("Missing parent/guardian email");
    }

    if (guardian?.email && !EMAIL_REGEX.test(guardian.email)) {
      errors.push("Invalid parent/guardian email");
    }

    if (payload.dateOfBirth) {
      const parsed = new Date(payload.dateOfBirth);
      if (Number.isNaN(parsed.getTime())) {
        errors.push("Invalid date of birth");
      }
    }

    return errors;
  }

  function renderImportPreview(target, previewRows) {
    if (!target) {
      return;
    }

    if (!previewRows.length) {
      target.innerHTML = "";
      return;
    }

    const validCount = previewRows.filter((item) => !item.errors.length).length;
    const invalidCount = previewRows.length - validCount;

    target.innerHTML = `
      <div class="portal-import-summary">
        ${previewRows.length} row(s) parsed • ${validCount} valid • ${invalidCount} with errors.
      </div>
      <div class="portal-import-table-wrap">
        <table class="portal-import-table">
          <thead>
            <tr>
              <th>#</th>
              <th>First name</th>
              <th>Last name</th>
              <th>Student email</th>
              <th>Admission no.</th>
              <th>Level/Class</th>
              <th>DOB</th>
              <th>Gender</th>
              <th>Guardian</th>
              <th>Guardian phone</th>
              <th>Guardian email</th>
              <th>Validation</th>
            </tr>
          </thead>
          <tbody>
            ${previewRows
              .map(
                (item, index) => `
                  <tr class="${item.errors.length ? "portal-import-row-error" : ""}">
                    <td>${index + 1}</td>
                    <td>${escapeHtml(item.payload.firstName || "—")}</td>
                    <td>${escapeHtml(item.payload.lastName || "—")}</td>
                    <td>${escapeHtml(item.payload.studentEmail || "—")}</td>
                    <td>${escapeHtml(item.payload.admissionNo || "—")}</td>
                    <td>${escapeHtml(item.payload.level || "—")}</td>
                    <td>${escapeHtml(item.payload.dateOfBirth || "—")}</td>
                    <td>${escapeHtml(item.payload.gender || "—")}</td>
                    <td>${escapeHtml(item.payload.guardians[0]?.name || "—")}</td>
                    <td>${escapeHtml(item.payload.guardians[0]?.phone || "—")}</td>
                    <td>${escapeHtml(item.payload.guardians[0]?.email || "—")}</td>
                    <td>
                      ${
                        item.errors.length
                          ? `<ul class="portal-import-errors">${item.errors
                              .map((error) => `<li>${escapeHtml(error)}</li>`)
                              .join("")}</ul>`
                          : "OK"
                      }
                    </td>
                  </tr>
                `,
              )
              .join("")}
          </tbody>
        </table>
      </div>
    `;
  }

  function getActiveStudentClassLevels() {
    const classManager = getClassManager();
    if (!classManager || typeof classManager.getClasses !== "function") {
      return [];
    }

    return Array.from(
      new Set(
        classManager
          .getClasses()
          .filter((item) => item.status !== "archived")
          .filter(
            (item) =>
              inferSchoolTypeFromLevel(item.level) !== "higher" ||
              isConfiguredHigherInstitutionLevel(item.level),
          )
          .map((item) => String(item.level || "").trim())
          .filter(Boolean),
      ),
    ).sort((left, right) => left.localeCompare(right, undefined, { numeric: true }));
  }

  function getNextStudentLevel(currentLevel) {
    const levels = getActiveStudentClassLevels();
    const normalizedCurrent = normalizeLevelToken(currentLevel);
    if (!normalizedCurrent || !levels.length) {
      return "";
    }

    const currentIndex = levels.findIndex((level) => normalizeLevelToken(level) === normalizedCurrent);
    if (currentIndex < 0 || currentIndex >= levels.length - 1) {
      return "";
    }

    return levels[currentIndex + 1];
  }

  function appendStudentProgression(record, entry = {}) {
    const existing = Array.isArray(record?.progressionHistory) ? record.progressionHistory : [];
    return [
      ...existing,
      {
        id: createId(),
        type: String(entry.type || "updated").trim() || "updated",
        fromLevel: String(entry.fromLevel || "").trim(),
        toLevel: String(entry.toLevel || "").trim(),
        note: String(entry.note || "").trim(),
        timestamp: nowIso(),
      },
    ];
  }

  function formatFileSize(bytes) {
    const value = Number(bytes);
    if (!Number.isFinite(value) || value <= 0) {
      return "0 B";
    }
    if (value < 1024) {
      return `${Math.round(value)} B`;
    }
    if (value < 1024 * 1024) {
      return `${(value / 1024).toFixed(1)} KB`;
    }
    return `${(value / (1024 * 1024)).toFixed(2)} MB`;
  }

  function runAutomaticPromotionForClosedSession(sessionRecord, studentManager) {
    const summary = {
      processed: 0,
      promoted: 0,
      repeated: 0,
      resit: 0,
      retainedTopLevel: 0,
      skippedAlreadyProcessed: 0,
    };

    if (
      !sessionRecord?.id ||
      !studentManager ||
      typeof studentManager.getStudents !== "function" ||
      typeof studentManager.updateStudentProgression !== "function"
    ) {
      return summary;
    }

    const sessionId = String(sessionRecord.id || "").trim();
    const sessionLabel = String(sessionRecord.name || "session").trim();
    const activeStudents = studentManager
      .getStudents()
      .filter((student) => String(student.status || "").toLowerCase() === "active");

    activeStudents.forEach((student) => {
      if (String(student.lastPromotionSessionId || "").trim() === sessionId) {
        summary.skippedAlreadyProcessed += 1;
        return;
      }

      const rawDecision = String(student.promotionDecision || "promote").trim().toLowerCase();
      const decision = rawDecision === "repeat" || rawDecision === "resit" ? rawDecision : "promote";
      summary.processed += 1;

      if (decision === "repeat") {
        studentManager.updateStudentProgression(student.id, (current) => ({
          ...current,
          status: "active",
          examOutcome: "fail",
          promotionDecision: "promote",
          lastPromotionSessionId: sessionId,
          lastPromotionOutcome: "repeated",
          progressionHistory: appendStudentProgression(current, {
            type: "auto-repeated",
            fromLevel: current.level,
            toLevel: current.level,
            note: `Repeated automatically after ${sessionLabel} close`,
          }),
        }));
        summary.repeated += 1;
        return;
      }

      if (decision === "resit") {
        studentManager.updateStudentProgression(student.id, (current) => ({
          ...current,
          status: "active",
          examOutcome: "resit",
          promotionDecision: "promote",
          lastPromotionSessionId: sessionId,
          lastPromotionOutcome: "resit",
          progressionHistory: appendStudentProgression(current, {
            type: "auto-resit",
            fromLevel: current.level,
            toLevel: current.level,
            note: `Marked for resit automatically after ${sessionLabel} close`,
          }),
        }));
        summary.resit += 1;
        return;
      }

      const currentBaseLevel = getStudentBaseClassLevel(student);
      const nextLevel = getNextStudentLevel(currentBaseLevel);

      if (!nextLevel) {
        studentManager.updateStudentProgression(student.id, (current) => ({
          ...current,
          status: "active",
          examOutcome: "pass",
          promotionDecision: "promote",
          lastPromotionSessionId: sessionId,
          lastPromotionOutcome: "retained-top-level",
          progressionHistory: appendStudentProgression(current, {
            type: "auto-retained",
            fromLevel: current.level,
            toLevel: current.level,
            note: `No next class level configured during ${sessionLabel} auto-promotion`,
          }),
        }));
        summary.retainedTopLevel += 1;
        return;
      }
      const selectedClassRecord = chooseStudentClassRecordForLevel(nextLevel, {
        excludeStudentId: student.id,
      });
      const classAssignment = buildStudentClassAssignment(nextLevel, selectedClassRecord);

      studentManager.updateStudentProgression(student.id, (current) => ({
        ...current,
        ...classAssignment,
        status: "active",
        examOutcome: "pass",
        promotionDecision: "promote",
        lastPromotionSessionId: sessionId,
        lastPromotionOutcome: "promoted",
        progressionHistory: appendStudentProgression(current, {
          type: "auto-promoted",
          fromLevel: current.level,
          toLevel: classAssignment.level,
          note: `Promoted automatically after ${sessionLabel} close`,
        }),
      }));
      summary.promoted += 1;
    });

    return summary;
  }

  function initStudentManagementControls({
    isAdmin,
    manager,
    summaryTarget,
    form,
    status,
    listTarget,
    guardianList,
    formToggleButton,
  }) {
    if (!summaryTarget || !form || !status || !listTarget || !guardianList) {
      return;
    }

    const addGuardianButton = form.querySelector("[data-add-guardian]");
    const quickAddForm = document.getElementById("portal-student-quick-add-form");
    const quickAddStatus = document.getElementById("portal-student-quick-add-status");
    const importToggleButton = document.querySelector("[data-student-import-toggle]");
    const importPanel = document.getElementById("portal-student-import-panel");
    const createOverlay = document.getElementById("portal-student-create-overlay");
    const importOverlay = document.getElementById("portal-student-import-overlay");
    const viewOverlay = document.getElementById("portal-student-view-overlay");
    const viewContent = document.getElementById("portal-student-view-content");
    const docsOverlay = document.getElementById("portal-student-docs-overlay");
    const docsStatus = document.getElementById("portal-student-docs-status");
    const docsList = document.getElementById("portal-student-doc-list");
    const docsStudentIdInput = document.getElementById("portal-student-docs-student-id");
    const docsStudentName = document.getElementById("portal-student-docs-student-name");
    const docsTypeSelect = document.getElementById("portal-student-doc-type");
    const docsFileInput = document.getElementById("portal-student-doc-file");
    const docsUploadButton = document.querySelector("[data-student-doc-upload]");
    const classFiltersTarget = document.getElementById("portal-student-class-filters");
    const searchInput = document.getElementById("portal-student-search");
    const importStatus = document.getElementById("portal-student-import-status");
    const importFileInput = document.getElementById("portal-student-import-file");
    const importPreviewButton = document.querySelector("[data-student-import-preview]");
    const importConfirmButton = document.querySelector("[data-student-import-confirm]");
    const importPreviewTarget = document.getElementById("portal-student-import-preview");
    const classManager = getClassManager();
    const settingsManager = getSchoolSettingsManager();
    const levelSelect = form.elements.level;
    const createTitle = document.getElementById("portal-student-create-title");
    let importPreviewRows = [];
    let selectedClass = "all";
    let searchQuery = "";
    const expandedClassTokens = new Set();

    const refreshStudentLevelOptions = () => {
      if (levelSelect instanceof HTMLSelectElement) {
        renderStudentLevelSelectOptions(levelSelect, levelSelect.value);
        renderStudentClassArmOptions(form, form.elements.classId?.value || "", { autoPick: false });
        levelSelect.disabled = !isAdmin;
      }
    };

    const setOverlayState = (overlay, isVisible) => {
      if (!overlay) {
        return;
      }
      overlay.hidden = !isVisible;
      const hasOpenOverlay = [createOverlay, importOverlay, viewOverlay, docsOverlay].some(
        (item) => item && !item.hidden,
      );
      document.body.classList.toggle("portal-overlay-open", hasOpenOverlay);
    };

    const setStudentFormVisibility = (isVisible) => {
      setOverlayState(createOverlay, isVisible);

      if (formToggleButton) {
        formToggleButton.textContent = "Create student";
        formToggleButton.setAttribute("aria-expanded", String(isVisible));
      }

      if (isVisible) {
        window.setTimeout(() => {
          form.elements.firstName?.focus?.();
        }, 0);
      }
    };

    const setImportPanelVisibility = (isVisible) => {
      if (!importOverlay) {
        return;
      }
      setOverlayState(importOverlay, isVisible);
      if (importToggleButton) {
        importToggleButton.textContent = "Import Students";
      }
    };

    const renderStudentDocuments = (record) => {
      if (!docsList) {
        return;
      }

      const documents = Array.isArray(record?.documents) ? record.documents : [];

      if (!documents.length) {
        docsList.innerHTML = `
          <article class="portal-student-doc-empty">
            <strong>No documents uploaded yet</strong>
            <p>Use the upload controls above to attach student files.</p>
          </article>
        `;
        return;
      }

      docsList.innerHTML = documents
        .map(
          (entry) => {
            const documentType = entry.documentType || "Other";
            const documentIcon = getInitials(documentType).slice(0, 2) || "DC";
            return `
            <article class="portal-student-doc-item">
              <span class="portal-student-doc-icon">${escapeHtml(documentIcon)}</span>
              <div class="portal-student-doc-copy">
                <strong>${escapeHtml(entry.name || "Document")}</strong>
                <div class="portal-student-doc-tags">
                  <span>${escapeHtml(documentType)}</span>
                  <span>${escapeHtml(formatFileSize(entry.sizeBytes))}</span>
                  <span>${escapeHtml(formatTimestamp(entry.uploadedAt || nowIso()))}</span>
                </div>
              </div>
              <div class="portal-student-doc-actions">
                <button
                  class="portal-class-button"
                  type="button"
                  data-student-doc-action="download"
                  data-student-doc-id="${escapeHtml(entry.id)}"
                >
                  Download
                </button>
                <button
                  class="portal-class-button is-archive"
                  type="button"
                  data-student-doc-action="delete"
                  data-student-doc-id="${escapeHtml(entry.id)}"
                  ${isAdmin ? "" : "disabled"}
                >
                  Delete
                </button>
              </div>
            </article>
          `;
          },
        )
        .join("");
    };

    const openStudentDocuments = (record) => {
      if (!docsOverlay || !docsStudentIdInput || !docsStudentName || !docsList) {
        return;
      }

      docsStudentIdInput.value = String(record?.id || "");
      docsStudentName.textContent = record?.fullName
        ? `${record.fullName} (${record.admissionNo || "No Admission No."})`
        : "Student documents";
      if (docsFileInput) {
        docsFileInput.value = "";
      }
      if (docsTypeSelect) {
        docsTypeSelect.value = "Passport Photograph";
      }
      setStatus(docsStatus, "", "");
      renderStudentDocuments(record);
      setOverlayState(docsOverlay, true);
    };

    const tryAutoFillAdmissionNo = () => {
      const admissionInput = form.elements.admissionNo;
      const levelInput = form.elements.level;
      const studentId = form.elements.studentId?.value || "";
      if (!admissionInput || !levelInput || !manager || !isAdmin) {
        return;
      }

      const currentValue = String(admissionInput.value || "").trim();
      const shouldGenerate =
        !currentValue || admissionInput.dataset.autoGenerated === "true";

      if (!shouldGenerate || !String(levelInput.value || "").trim()) {
        return;
      }

      const generated = generateAdmissionNumber({
        manager,
        levelValue: levelInput.value,
        excludeStudentId: studentId || undefined,
      });
      admissionInput.value = generated;
      admissionInput.dataset.autoGenerated = "true";
    };

    const toggleStudentFormVisibility = () => {
      if (!isAdmin || !manager) {
        return;
      }

      const shouldOpen = createOverlay ? createOverlay.hidden : false;
      setStudentFormVisibility(shouldOpen);

      if (!shouldOpen) {
        clearPortalStudentErrors(form);
        resetPortalStudentForm(form, guardianList, isAdmin);
        setStatus(status, "", "");
      }
    };

    const refreshStudentSection = () => {
      refreshStudentLevelOptions();
      renderPortalStudentManagementSection({
        isAdmin,
        manager,
        summaryTarget,
        form,
        status,
        listTarget,
        classFiltersTarget,
        selectedClass,
        searchQuery,
        expandedClassTokens,
      });
    };

    refreshStudentSection();
    resetPortalStudentForm(form, guardianList, isAdmin);
    setStudentFormVisibility(false);
    setImportPanelVisibility(false);

    if (formToggleButton) {
      formToggleButton.disabled = !isAdmin || !manager;
      formToggleButton.addEventListener("click", () => {
        if (createTitle) {
          createTitle.textContent = "Create Student";
        }
        if (createOverlay?.hidden) {
          clearPortalStudentErrors(form);
          resetPortalStudentForm(form, guardianList, isAdmin);
          setStatus(status, "", "");
        }
        toggleStudentFormVisibility();
      });
    }

    if (importToggleButton) {
      importToggleButton.disabled = !isAdmin || !manager;
      importToggleButton.addEventListener("click", () => {
        setImportPanelVisibility(importOverlay ? importOverlay.hidden : false);
        if (importStatus) {
          setStatus(importStatus, "", "");
        }
      });
    }

    if (searchInput) {
      searchInput.addEventListener("input", () => {
        searchQuery = String(searchInput.value || "").trim();
        refreshStudentSection();
      });
    }

    if (classFiltersTarget) {
      classFiltersTarget.addEventListener("click", (event) => {
        const button = event.target.closest("[data-student-class]");

        if (!button) {
          return;
        }

        selectedClass = String(button.dataset.studentClass || "all");
        refreshStudentSection();
      });
    }

    document.querySelectorAll("[data-student-create-close]").forEach((button) => {
      button.addEventListener("click", () => {
        clearPortalStudentErrors(form);
        resetPortalStudentForm(form, guardianList, isAdmin);
        setStudentFormVisibility(false);
        setStatus(status, "", "");
      });
    });

    document.querySelectorAll("[data-student-import-close]").forEach((button) => {
      button.addEventListener("click", () => {
        setImportPanelVisibility(false);
      });
    });

    document.querySelectorAll("[data-student-view-close]").forEach((button) => {
      button.addEventListener("click", () => {
        setOverlayState(viewOverlay, false);
      });
    });

    document.querySelectorAll("[data-student-docs-close]").forEach((button) => {
      button.addEventListener("click", () => {
        setOverlayState(docsOverlay, false);
      });
    });

    window.addEventListener("keydown", (event) => {
      if (event.key !== "Escape") {
        return;
      }
      if (createOverlay && !createOverlay.hidden) {
        setStudentFormVisibility(false);
      }
      if (importOverlay && !importOverlay.hidden) {
        setImportPanelVisibility(false);
      }
      if (viewOverlay && !viewOverlay.hidden) {
        setOverlayState(viewOverlay, false);
      }
      if (docsOverlay && !docsOverlay.hidden) {
        setOverlayState(docsOverlay, false);
      }
    });

    if (!manager) {
      setStudentFormVisibility(false);
      return;
    }

    if (docsUploadButton && docsStudentIdInput && docsFileInput) {
      docsUploadButton.disabled = !isAdmin;
      docsUploadButton.addEventListener("click", async () => {
        if (!isAdmin) {
          setStatus(docsStatus, "info", "Only administrators can upload student documents.");
          return;
        }

        const studentId = String(docsStudentIdInput.value || "").trim();
        const record = manager.getStudents().find((item) => item.id === studentId);
        const file = docsFileInput.files?.[0] || null;

        if (!record) {
          setStatus(docsStatus, "error", "Select a valid student first.");
          return;
        }

        if (!file) {
          setStatus(docsStatus, "error", "Choose a document file to upload.");
          return;
        }

        const maxBytes = 8 * 1024 * 1024;
        if (file.size > maxBytes) {
          setStatus(docsStatus, "error", "File too large. Max upload size is 8MB.");
          return;
        }

        let dataUrl = "";
        try {
          dataUrl = await readFileAsDataUrl(file);
        } catch {
          setStatus(docsStatus, "error", "Could not read the selected file.");
          return;
        }

        if (!dataUrl) {
          setStatus(docsStatus, "error", "Upload failed. Try another file.");
          return;
        }

        const documentType = String(docsTypeSelect?.value || "Other").trim() || "Other";
        const newDocument = {
          id: createId(),
          name: String(file.name || "Document").trim() || "Document",
          documentType,
          mimeType: String(file.type || "").trim(),
          sizeBytes: Number(file.size) || 0,
          dataUrl,
          uploadedAt: nowIso(),
          uploadedBy: getSession()?.email || "admin",
        };

        manager.updateStudentProgression(studentId, (current) => ({
          ...current,
          documents: [...(Array.isArray(current.documents) ? current.documents : []), newDocument],
        }));

        recordAuditEvent({
          action: "uploaded",
          entityType: "student-document",
          entityId: record.admissionNo || record.id,
          summary: `Uploaded ${newDocument.documentType} for ${record.fullName}`,
          details: newDocument.name,
        });

        if (docsFileInput) {
          docsFileInput.value = "";
        }

        const updated = manager.getStudents().find((item) => item.id === studentId) || record;
        renderStudentDocuments(updated);
        refreshStudentSection();
        setStatus(
          docsStatus,
          "success",
          `Uploaded <strong>${escapeHtml(newDocument.name)}</strong> for <strong>${escapeHtml(
            record.fullName,
          )}</strong>.`,
        );
      });
    }

    if (docsList) {
      docsList.addEventListener("click", (event) => {
        const button = event.target.closest("[data-student-doc-action]");

        if (!button) {
          return;
        }

        const studentId = String(docsStudentIdInput?.value || "").trim();
        const record = manager.getStudents().find((item) => item.id === studentId);

        if (!record) {
          return;
        }

        const action = String(button.dataset.studentDocAction || "").trim();
        const docId = String(button.dataset.studentDocId || "").trim();
        const doc = (record.documents || []).find((item) => String(item.id || "") === docId);

        if (!doc) {
          return;
        }

        if (action === "download") {
          if (!doc.dataUrl) {
            setStatus(docsStatus, "error", "This file source is missing.");
            return;
          }
          const link = document.createElement("a");
          link.href = doc.dataUrl;
          link.download = doc.name || "document";
          link.rel = "noopener";
          document.body.appendChild(link);
          link.click();
          link.remove();
          return;
        }

        if (action === "delete") {
          if (!isAdmin) {
            return;
          }

          manager.updateStudentProgression(studentId, (current) => ({
            ...current,
            documents: (current.documents || []).filter(
              (entry) => String(entry.id || "") !== docId,
            ),
          }));

          recordAuditEvent({
            action: "deleted",
            entityType: "student-document",
            entityId: record.admissionNo || record.id,
            summary: `Deleted ${doc.documentType || "document"} for ${record.fullName}`,
            details: doc.name || "",
          });

          const updated = manager.getStudents().find((item) => item.id === studentId) || record;
          renderStudentDocuments(updated);
          refreshStudentSection();
          setStatus(
            docsStatus,
            "success",
            `Removed <strong>${escapeHtml(doc.name || "document")}</strong> from <strong>${escapeHtml(
              record.fullName,
            )}</strong>.`,
          );
        }
      });
    }

    if (isAdmin) {
      backfillGuardianAccessFromStudents(manager);
    }

    if (addGuardianButton) {
      addGuardianButton.disabled = !isAdmin;
      addGuardianButton.addEventListener("click", () => {
        appendGuardianRow(guardianList, {}, isAdmin);
      });
    }

    guardianList.addEventListener("change", (event) => {
      const relationshipControl = event.target.closest('[data-guardian-field="relationshipType"]');

      if (!(relationshipControl instanceof HTMLSelectElement)) {
        return;
      }

      const row = relationshipControl.closest(".portal-guardian-row");
      updateGuardianRelationshipCustomField(row);
    });

    guardianList.addEventListener("click", (event) => {
      const removeButton = event.target.closest("[data-remove-guardian]");

      if (!removeButton || !isAdmin) {
        return;
      }

      const row = removeButton.closest(".portal-guardian-row");

      if (!row) {
        return;
      }

      row.remove();

      if (!guardianList.children.length) {
        appendGuardianRow(guardianList, {}, isAdmin);
      }
    });

    form.addEventListener("input", (event) => {
      clearPortalStudentErrors(form);

      if (event?.target === form.elements.admissionNo) {
        form.elements.admissionNo.dataset.autoGenerated = "false";
      }

      if (isAdmin) {
        setStatus(status, "", "");
      }
    });

    if (form.elements.level) {
      form.elements.level.addEventListener("change", () => {
        renderStudentClassArmOptions(form, "", { autoPick: true });
        tryAutoFillAdmissionNo();
      });
      form.elements.level.addEventListener("blur", tryAutoFillAdmissionNo);
    }

    if (form.elements.admissionNo) {
      form.elements.admissionNo.addEventListener("input", () => {
        form.elements.admissionNo.dataset.autoGenerated = "false";
      });
    }

    form.addEventListener("submit", async (event) => {
      event.preventDefault();

      if (!isAdmin) {
        setStatus(status, "info", "Only administrators can manage student records.");
        return;
      }

      clearPortalStudentErrors(form);
      setStatus(status, "", "");

      const studentId = form.elements.studentId.value;
      const firstName = form.elements.firstName.value.trim();
      const lastName = form.elements.lastName.value.trim();
      const studentEmail = String(form.elements.studentEmail?.value || "").trim();
      const baseLevel = form.elements.level.value.trim();
      const selectedClassRecord = chooseStudentClassRecordForLevel(baseLevel, {
        selectedClassId: form.elements.classId?.value || "",
        excludeStudentId: studentId || "",
      });
      const classAssignment = buildStudentClassAssignment(baseLevel, selectedClassRecord);
      const admissionNoRaw = form.elements.admissionNo.value.trim();
      const promotionDecisionRaw = String(form.elements.promotionDecision?.value || "promote")
        .trim()
        .toLowerCase();
      const promotionDecision =
        promotionDecisionRaw === "repeat" || promotionDecisionRaw === "resit"
          ? promotionDecisionRaw
          : "promote";
      const payload = {
        id: studentId || undefined,
        firstName,
        lastName,
        fullName: [firstName, lastName].filter(Boolean).join(" ").trim(),
        studentEmail,
        admissionNo:
          admissionNoRaw ||
          generateAdmissionNumber({
            manager,
            levelValue: baseLevel,
            excludeStudentId: studentId || undefined,
          }),
        ...classAssignment,
        dateOfBirth: form.elements.dateOfBirth?.value || "",
        gender: form.elements.gender?.value || "",
        promotionDecision,
        examOutcome:
          promotionDecision === "resit"
            ? "resit"
            : promotionDecision === "repeat"
              ? "fail"
              : "pass",
      };
      const guardianParse = parseGuardianRows(guardianList, { validatePhone: true });
      payload.guardians = guardianParse.guardians;
      const hasGuardianEmail = payload.guardians.some((guardian) =>
        EMAIL_REGEX.test(String(guardian.email || "").trim()),
      );

      let hasError = false;

      if (!payload.firstName) {
        setPortalStudentError(form, "firstName", "Enter the first name.");
        hasError = true;
      }

      if (!payload.lastName) {
        setPortalStudentError(form, "lastName", "Enter the last name.");
        hasError = true;
      }

      if (!payload.admissionNo) {
        setPortalStudentError(form, "admissionNo", "Enter the admission number.");
        hasError = true;
      }

      if (payload.studentEmail && !EMAIL_REGEX.test(payload.studentEmail)) {
        setPortalStudentError(form, "studentEmail", "Enter a valid student email format.");
        hasError = true;
      }

      if (!baseLevel) {
        setPortalStudentError(form, "level", "Enter the student level or class.");
        hasError = true;
      } else if (!isKnownClassLevel(baseLevel, getActiveClassLevelTokenSet())) {
        setPortalStudentError(form, "level", "Select a level or class from the school structure.");
        hasError = true;
      }

      if (guardianParse.hasInvalidRow) {
        setPortalStudentError(
          form,
          "guardians",
          "Each guardian row needs name, relationship, and at least one contact (phone or email).",
        );
        hasError = true;
      } else if (guardianParse.hasInvalidPhone) {
        setPortalStudentError(
          form,
          "guardians",
          "Wrong phone number format detected in guardian contacts.",
        );
        hasError = true;
      } else if (!payload.guardians.length) {
        setPortalStudentError(form, "guardians", "Add at least one guardian contact.");
        hasError = true;
      } else if (!hasGuardianEmail) {
        setPortalStudentError(
          form,
          "guardians",
          "Add at least one valid guardian email so a parent login can be created automatically.",
        );
        hasError = true;
      }

      const duplicateAdmission = manager
        .getStudents()
        .find(
          (record) =>
            record.id !== studentId &&
            record.admissionNo.toLowerCase() === payload.admissionNo.toLowerCase(),
        );

      if (duplicateAdmission) {
        setPortalStudentError(form, "admissionNo", "This admission number is already in use.");
        hasError = true;
      }

      if (hasError) {
        setStatus(status, "error", "Fix the highlighted student details and try again.");
        return;
      }

      const currentRecord = manager.getStudents().find((record) => record.id === studentId) || null;
      const savedStudentPayload = {
        ...currentRecord,
        ...payload,
        status: currentRecord ? currentRecord.status : "active",
      };
      manager.upsertStudent(savedStudentPayload);
      const persistedStudent =
        manager.getStudents().find(
          (record) =>
            (studentId && record.id === studentId) ||
            String(record.admissionNo || "").toLowerCase() === payload.admissionNo.toLowerCase(),
        ) || savedStudentPayload;
      const parentProvisioning = await provisionParentAccountsForStudent(persistedStudent);
      const studentProvisioning = await provisionStudentAccountForStudent(persistedStudent);

      recordAuditEvent({
        action: currentRecord ? "updated" : "created",
        entityType: "student",
        entityId: payload.admissionNo,
        summary: currentRecord
          ? `Updated student record for ${payload.fullName || payload.admissionNo}`
          : `Created student record for ${payload.fullName || payload.admissionNo}`,
        details: `${payload.level} • ${payload.guardians.length} guardian contact(s)`,
      });

      resetPortalStudentForm(form, guardianList, isAdmin);
      clearFormDraftFor(form);
      setStudentFormVisibility(false);
      const createdParentCopy = parentProvisioning.created.length
        ? ` Parent login created: <strong>${escapeHtml(
            parentProvisioning.created[0].email,
          )}</strong>${parentProvisioning.created.length > 1 ? ` +${parentProvisioning.created.length - 1} more` : ""}. Default password: <strong>${escapeHtml(
            DEFAULT_PARENT_PASSWORD,
          )}</strong>.`
        : "";
      const googleParentCopy = parentProvisioning.existingGoogle.length
        ? ` ${parentProvisioning.existingGoogle.length} guardian account(s) already use Google sign-in.`
        : "";
      const failedParentCopy = parentProvisioning.failed?.length
        ? ` ${parentProvisioning.failed.length} guardian account(s) could not be created online. Check account service setup.`
        : "";
      const studentLoginCopy =
        studentProvisioning.status === "created"
          ? ` Student login created: <strong>${escapeHtml(
              studentProvisioning.user.email,
            )}</strong>. Default password: <strong>${escapeHtml(DEFAULT_STUDENT_PASSWORD)}</strong>.`
          : studentProvisioning.status === "updated"
            ? ` Student login updated for <strong>${escapeHtml(studentProvisioning.user.email)}</strong>.`
            : studentProvisioning.status === "existing_google"
              ? " Student account already uses Google sign-in."
              : studentProvisioning.status === "skipped"
                ? ""
                : studentProvisioning.message
                  ? ` ${escapeHtml(studentProvisioning.message)}`
                  : "";
      setStatus(
        status,
        "success",
        currentRecord
          ? `Student <strong>${escapeHtml(payload.fullName || payload.admissionNo)}</strong> updated with guardian relationships.${createdParentCopy}${googleParentCopy}${failedParentCopy}${studentLoginCopy}`
          : `Student <strong>${escapeHtml(payload.fullName || payload.admissionNo)}</strong> created with guardian relationships.${createdParentCopy}${googleParentCopy}${failedParentCopy}${studentLoginCopy}`,
      );
    });

    const cancelButton = form.querySelector("[data-student-cancel]");

    if (cancelButton) {
      cancelButton.addEventListener("click", () => {
        clearPortalStudentErrors(form);
        resetPortalStudentForm(form, guardianList, isAdmin);
        setStudentFormVisibility(false);
        setStatus(status, "", "");
      });
    }

    listTarget.addEventListener("click", async (event) => {
      const bulkDeleteButton = event.target.closest("[data-student-bulk-delete-level]");

      if (bulkDeleteButton) {
        event.preventDefault();
        event.stopPropagation();

        if (!isAdmin) {
          setStatus(status, "info", "Only administrators can delete student records.");
          return;
        }

        const level = String(bulkDeleteButton.dataset.studentBulkDeleteLevel || "").trim();
        const matchingStudents = manager
          .getStudents()
          .filter((student) => normalizeLevelToken(student.level) === normalizeLevelToken(level));

        if (!level || !matchingStudents.length) {
          setStatus(status, "info", "No students found for this class.");
          return;
        }

        const confirmed = await showAppConfirm({
          title: "Delete class students?",
          message: `Delete all ${matchingStudents.length} student record${matchingStudents.length === 1 ? "" : "s"} in ${level}?`,
          details: "This permanently removes these student profiles from the registry.",
          confirmLabel: "Delete students",
          variant: "danger",
        });

        if (!confirmed) {
          return;
        }

        const result =
          typeof manager.deleteStudentsByLevel === "function"
            ? manager.deleteStudentsByLevel(level)
            : {
                deletedCount: matchingStudents.length,
                students: manager.saveStudents(
                  manager
                    .getStudents()
                    .filter((student) => normalizeLevelToken(student.level) !== normalizeLevelToken(level)),
                ),
              };

        recordAuditEvent({
          action: "deleted",
          entityType: "student-class",
          entityId: level,
          summary: `Deleted ${result.deletedCount || matchingStudents.length} student record(s) from ${level}`,
          details: matchingStudents
            .slice(0, 8)
            .map((student) => student.admissionNo || student.fullName)
            .filter(Boolean)
            .join(", "),
        });

        resetPortalStudentForm(form, guardianList, isAdmin);
        setStudentFormVisibility(false);
        setOverlayState(viewOverlay, false);
        setOverlayState(docsOverlay, false);
        expandedClassTokens.delete(normalizeLevelToken(level));
        refreshStudentSection();
        setStatus(
          status,
          "success",
          `Deleted <strong>${escapeHtml(String(result.deletedCount || matchingStudents.length))}</strong> student record${
            (result.deletedCount || matchingStudents.length) === 1 ? "" : "s"
          } from <strong>${escapeHtml(level)}</strong>.`,
        );
        return;
      }

      const classToggleButton = event.target.closest("[data-student-class-toggle]");

      if (classToggleButton) {
        const classToken = String(classToggleButton.dataset.studentClassToggle || "").trim();

        if (classToken) {
          const shouldExpand = !expandedClassTokens.has(classToken);
          if (shouldExpand) {
            expandedClassTokens.add(classToken);
          } else {
            expandedClassTokens.delete(classToken);
          }

          const group = classToggleButton.closest(".portal-student-group");
          const groupList = group ? group.querySelector(".portal-student-group-list") : null;
          const arrow = classToggleButton.querySelector(".portal-student-group-toggle-arrow");

          classToggleButton.setAttribute("aria-expanded", shouldExpand ? "true" : "false");
          classToggleButton.setAttribute(
            "aria-label",
            shouldExpand ? "Collapse class list" : "Expand class list",
          );

          if (groupList) {
            groupList.hidden = !shouldExpand;
          }

          if (arrow) {
            arrow.textContent = shouldExpand ? "▴" : "▾";
          }
        }
        return;
      }

      const actionButton = event.target.closest("[data-student-action]");

      if (!actionButton) {
        return;
      }

      const studentId = actionButton.dataset.studentId;
      const action = actionButton.dataset.studentAction;
      const record = manager.getStudents().find((item) => item.id === studentId);

      if (!record) {
        return;
      }

      if (action === "view") {
        const statusLabel =
          record.status === "archived"
            ? "Archived"
            : record.status === "transferred"
              ? "Transferred Out"
              : "Active";
        const statusClass =
          record.status === "archived"
            ? "is-archived"
            : record.status === "transferred"
              ? "is-transferred"
              : "is-active";
        const guardians = Array.isArray(record.guardians) ? record.guardians : [];
        const documents = Array.isArray(record.documents) ? record.documents : [];
        const profileName = record.fullName || "Unnamed student";
        const initials = getInitials(profileName).slice(0, 2) || "ST";
        const profilePhotoUrl = String(record.profilePhotoUrl || "").trim();
        const admissionLabel = record.admissionNo ? `Admission No. ${record.admissionNo}` : "No admission number";
        const levelLabel = getStudentLevelDisplayLabel(record.level) || "No class assigned";
        const academicHistory = getStudentAcademicHistory(record);
        const progressionLabel =
          record.promotionDecision === "repeat"
            ? "Repeat class"
            : record.promotionDecision === "resit"
              ? "Resit required"
              : "Auto promote";
        const guardianCards = guardians.length
          ? guardians
              .map((guardian) => {
                const guardianName = guardian.name || "Guardian";
                return `
                  <article class="portal-student-mini-card">
                    <span class="portal-student-mini-icon">${escapeHtml(
                      getInitials(guardianName).slice(0, 2) || "GC",
                    )}</span>
                    <div class="portal-student-mini-copy">
                      <strong>${escapeHtml(guardianName)}</strong>
                      <span>${escapeHtml(guardian.relationship || "Guardian")}</span>
                      <small>${escapeHtml(guardian.phone || "No phone")} &middot; ${escapeHtml(
                        guardian.email || "No email",
                      )}</small>
                    </div>
                  </article>
                `;
              })
              .join("")
          : `
              <article class="portal-student-view-empty">
                <strong>No guardian contacts saved</strong>
                <p>Add guardian contacts from the student profile form.</p>
              </article>
            `;
        const documentCards = documents.length
          ? documents
              .map((doc) => {
                const documentType = doc.documentType || "Other";
                return `
                  <article class="portal-student-mini-card">
                    <span class="portal-student-mini-icon">${escapeHtml(
                      getInitials(documentType).slice(0, 2) || "DC",
                    )}</span>
                    <div class="portal-student-mini-copy">
                      <strong>${escapeHtml(doc.name || "Document")}</strong>
                      <span>${escapeHtml(documentType)}</span>
                      <small>${escapeHtml(formatFileSize(doc.sizeBytes))} &middot; ${escapeHtml(
                        formatTimestamp(doc.uploadedAt || nowIso()),
                      )}</small>
                    </div>
                  </article>
                `;
              })
              .join("")
          : `
              <article class="portal-student-view-empty">
                <strong>No documents uploaded</strong>
                <p>Use the student documents action to keep files on this record.</p>
              </article>
            `;
        const academicResultRows = academicHistory.reportRows.length
          ? academicHistory.reportRows
              .map(
                (entry) => `
                  <article class="portal-student-history-row">
                    <div>
                      <strong>${escapeHtml(entry.termName)}</strong>
                      <span>${escapeHtml(entry.sessionName)} • ${escapeHtml(entry.classLevel)}</span>
                    </div>
                    <div class="portal-student-history-metrics">
                      <span>${escapeHtml(String(entry.subjectCount || 0))} subject${entry.subjectCount === 1 ? "" : "s"}</span>
                      <strong>${escapeHtml(formatReportPercent(entry.averageScore || 0))}</strong>
                      <em class="portal-student-history-badge ${entry.status === "released" ? "is-live" : "is-draft"}">${escapeHtml(
                        `${String(entry.grade || "—")} • ${entry.status === "released" ? "Released" : "Draft"}`,
                      )}</em>
                    </div>
                  </article>
                `,
              )
              .join("")
          : `
              <article class="portal-student-view-empty">
                <strong>No term results yet</strong>
                <p>Report card history will appear here once results are drafted or released.</p>
              </article>
            `;
        const progressionRows = academicHistory.progressionRows.length
          ? academicHistory.progressionRows
              .map(
                (entry) => `
                  <article class="portal-student-history-event">
                    <div>
                      <strong>${escapeHtml(entry.note || "Profile updated")}</strong>
                      <span>${escapeHtml(
                        [entry.fromLevel, entry.toLevel].filter(Boolean).join(" → ") || record.level || "Class",
                      )}</span>
                    </div>
                    <small>${escapeHtml(formatTimestamp(entry.timestamp || nowIso()))}</small>
                  </article>
                `,
              )
              .join("")
          : `
              <article class="portal-student-view-empty">
                <strong>No progression history yet</strong>
                <p>Promotions, repeats, transfers, and other academic movement will be tracked here.</p>
              </article>
            `;
        if (viewContent) {
          viewContent.innerHTML = `
            <section class="portal-student-profile-hero">
              <div class="portal-student-profile-photo">
                <span class="portal-student-profile-avatar portal-student-profile-photo-media">
                  ${
                    profilePhotoUrl
                      ? `<img src="${escapeHtml(profilePhotoUrl)}" alt="${escapeHtml(profileName)} profile picture" />`
                      : escapeHtml(initials)
                  }
                </span>
                ${
                  isAdmin
                    ? `<div class="portal-student-profile-photo-actions">
                        <button class="portal-class-button" type="button" data-student-photo-action="replace" data-student-id="${escapeHtml(record.id)}">
                          ${profilePhotoUrl ? "Replace" : "Add photo"}
                        </button>
                        <button class="portal-class-button is-danger" type="button" data-student-photo-action="remove" data-student-id="${escapeHtml(record.id)}" ${profilePhotoUrl ? "" : "hidden"}>
                          Remove
                        </button>
                        <input type="file" accept=".jpg,.jpeg,.png,.webp" data-student-photo-input data-student-id="${escapeHtml(record.id)}" hidden />
                      </div>`
                    : ""
                }
              </div>
              <div class="portal-student-profile-copy">
                <span>${escapeHtml(levelLabel)}</span>
                <h4>${escapeHtml(profileName)}</h4>
                <p>${escapeHtml(admissionLabel)}</p>
              </div>
              <span class="portal-student-profile-status ${statusClass}">${escapeHtml(statusLabel)}</span>
            </section>
            <div class="portal-student-view-sections">
              <section class="portal-student-view-card">
                <div class="portal-student-view-card-head">
                  <strong>Academic record</strong>
                  <span>Class, identity, and progression.</span>
                </div>
                <div class="portal-student-detail-grid">
                  <article>
                    <span>Admission No</span>
                    <strong>${escapeHtml(record.admissionNo || "Not recorded")}</strong>
                  </article>
                  <article>
                    <span>Student email</span>
                    <strong>${escapeHtml(record.studentEmail || "Not recorded")}</strong>
                  </article>
                  <article>
                    <span>Level / Class</span>
                    <strong>${escapeHtml(levelLabel || "Not assigned")}</strong>
                  </article>
                  <article>
                    <span>Gender</span>
                    <strong>${escapeHtml(record.gender || "Not recorded")}</strong>
                  </article>
                  <article>
                    <span>Date of birth</span>
                    <strong>${escapeHtml(record.dateOfBirth || "Not recorded")}</strong>
                  </article>
                  <article>
                    <span>Session close</span>
                    <strong>${escapeHtml(progressionLabel)}</strong>
                  </article>
                  <article>
                    <span>Status</span>
                    <strong>${escapeHtml(statusLabel)}</strong>
                  </article>
                </div>
              </section>
              <section class="portal-student-view-card">
                <div class="portal-student-view-card-head">
                  <strong>Academic history</strong>
                  <span>Across terms and sessions.</span>
                </div>
                <div class="portal-student-history-summary">
                  <article>
                    <span>Sessions</span>
                    <strong>${escapeHtml(String(academicHistory.sessionCount || 0))}</strong>
                  </article>
                  <article>
                    <span>Terms / Semesters</span>
                    <strong>${escapeHtml(String(academicHistory.termCount || 0))}</strong>
                  </article>
                  <article>
                    <span>Released cards</span>
                    <strong>${escapeHtml(String(academicHistory.releasedCount || 0))}</strong>
                  </article>
                  <article>
                    <span>Latest average</span>
                    <strong>${escapeHtml(
                      academicHistory.latestAverage === null ? "Not available" : formatReportPercent(academicHistory.latestAverage),
                    )}</strong>
                  </article>
                </div>
                <div class="portal-student-history-block">
                  <div class="portal-student-history-list">
                    ${academicResultRows}
                  </div>
                  <div class="portal-student-history-timeline">
                    <div class="portal-student-view-card-head">
                      <strong>Progression timeline</strong>
                      <span>Promotions, repeats, transfers, and updates.</span>
                    </div>
                    <div class="portal-student-history-events">
                      ${progressionRows}
                    </div>
                  </div>
                </div>
              </section>
              <section class="portal-student-view-card">
                <div class="portal-student-view-card-head">
                  <strong>Guardian contacts</strong>
                  <span>${guardians.length} saved contact${guardians.length === 1 ? "" : "s"}.</span>
                </div>
                <div class="portal-student-mini-list">
                  ${guardianCards}
                </div>
              </section>
              <section class="portal-student-view-card">
                <div class="portal-student-view-card-head">
                  <strong>Documents</strong>
                  <span>${documents.length} uploaded file${documents.length === 1 ? "" : "s"}.</span>
                </div>
                <div class="portal-student-mini-list">
                  ${documentCards}
                </div>
              </section>
            </div>
          `;
        }
        setOverlayState(viewOverlay, true);
        return;
      }

      if (action === "manage-docs") {
        if (!isAdmin) {
          return;
        }
        openStudentDocuments(record);
        return;
      }

      if (!isAdmin) {
        return;
      }

      clearPortalStudentErrors(form);

      if (action === "delete") {
        const confirmed = await showAppConfirm({
          title: "Delete student?",
          message: `Delete ${record.fullName || record.admissionNo || "this student"} permanently?`,
          details: "This permanently removes the student profile and saved documents from the registry.",
          confirmLabel: "Delete student",
          variant: "danger",
        });

        if (!confirmed) {
          return;
        }

        const result =
          typeof manager.deleteStudent === "function"
            ? manager.deleteStudent(record.id)
            : {
                deletedCount: 1,
                students: manager.saveStudents(
                  manager.getStudents().filter((student) => student.id !== record.id),
                ),
              };
        const deletedCount = result.deletedCount || 0;

        recordAuditEvent({
          action: "deleted",
          entityType: "student",
          entityId: record.admissionNo || record.id,
          summary: `Deleted student record for ${record.fullName || record.admissionNo || "student"}`,
          details: record.level || "",
        });
        resetPortalStudentForm(form, guardianList, isAdmin);
        setStudentFormVisibility(false);
        setOverlayState(viewOverlay, false);
        setOverlayState(docsOverlay, false);
        refreshStudentSection();
        setStatus(
          status,
          deletedCount ? "success" : "info",
          deletedCount
            ? `Student <strong>${escapeHtml(record.fullName || record.admissionNo || "record")}</strong> deleted.`
            : "Student record was not found.",
        );
        return;
      }

      if (action === "edit") {
        if (createTitle) {
          createTitle.textContent = "Edit Student";
        }
        populatePortalStudentForm(form, guardianList, record, isAdmin);
        setStudentFormVisibility(true);
        setStatus(
          status,
          "info",
          `Editing <strong>${escapeHtml(record.fullName)}</strong>. Save to update this student record.`,
        );
        return;
      }

      if (action === "promote") {
        const currentBaseLevel = getStudentBaseClassLevel(record);
        const nextLevel = getNextStudentLevel(currentBaseLevel);
        if (!nextLevel) {
          setStatus(
            status,
            "error",
            `No next class level found after <strong>${escapeHtml(
              record.level || "current level",
            )}</strong>. Add the next level in Class Management first.`,
          );
          return;
        }
        const selectedClassRecord = chooseStudentClassRecordForLevel(nextLevel, {
          excludeStudentId: record.id,
        });
        const classAssignment = buildStudentClassAssignment(nextLevel, selectedClassRecord);

        manager.updateStudentProgression(record.id, (current) => ({
          ...current,
          ...classAssignment,
          status: "active",
          promotionDecision: "promote",
          examOutcome: "pass",
          lastPromotionOutcome: "manual-promoted",
          archivedAt: null,
          transferredAt: null,
          transferReason: "",
          progressionHistory: appendStudentProgression(current, {
            type: "promoted",
            fromLevel: current.level,
            toLevel: classAssignment.level,
            note: "Promoted by admin",
          }),
        }));
        recordAuditEvent({
          action: "updated",
          entityType: "student",
          entityId: record.admissionNo,
          summary: `Promoted ${record.fullName}`,
          details: `${record.level} → ${classAssignment.level}`,
        });
        setStatus(
          status,
          "success",
          `Student <strong>${escapeHtml(record.fullName)}</strong> promoted from <strong>${escapeHtml(
            record.level,
          )}</strong> to <strong>${escapeHtml(classAssignment.level)}</strong>.`,
        );
        return;
      }

      if (action === "mark-repeat") {
        manager.updateStudentProgression(record.id, (current) => ({
          ...current,
          status: "active",
          promotionDecision: "repeat",
          examOutcome: "fail",
          lastPromotionSessionId: "",
          lastPromotionOutcome: "queued-repeat",
          archivedAt: null,
          transferredAt: null,
          transferReason: "",
          progressionHistory: appendStudentProgression(current, {
            type: "repeat-queued",
            fromLevel: current.level,
            toLevel: current.level,
            note: "Queued to repeat class at next session close",
          }),
        }));
        recordAuditEvent({
          action: "updated",
          entityType: "student",
          entityId: record.admissionNo,
          summary: `${record.fullName} set to repeat`,
          details: `${record.level}`,
        });
        setStatus(
          status,
          "success",
          `Student <strong>${escapeHtml(record.fullName)}</strong> will repeat <strong>${escapeHtml(
            record.level,
          )}</strong> when this session is closed.`,
        );
        return;
      }

      if (action === "mark-resit") {
        manager.updateStudentProgression(record.id, (current) => ({
          ...current,
          status: "active",
          promotionDecision: "resit",
          examOutcome: "resit",
          lastPromotionSessionId: "",
          lastPromotionOutcome: "queued-resit",
          archivedAt: null,
          transferredAt: null,
          transferReason: "",
          progressionHistory: appendStudentProgression(current, {
            type: "resit-queued",
            fromLevel: current.level,
            toLevel: current.level,
            note: "Queued for resit at next session close",
          }),
        }));
        recordAuditEvent({
          action: "updated",
          entityType: "student",
          entityId: record.admissionNo,
          summary: `${record.fullName} set to resit`,
          details: `${record.level}`,
        });
        setStatus(
          status,
          "success",
          `Student <strong>${escapeHtml(record.fullName)}</strong> is set for resit and will stay in <strong>${escapeHtml(
            record.level,
          )}</strong> when this session is closed.`,
        );
        return;
      }

      if (action === "transfer") {
        const transferNote = await showAppPrompt({
          title: "Transfer student",
          message: `Add a transfer note for ${record.fullName || record.admissionNo || "this student"}.`,
          inputLabel: "Transfer note",
          defaultValue: record.transferReason || "",
          placeholder: "Reason or destination school",
          confirmLabel: "Transfer out",
          variant: "danger",
        });
        if (transferNote === null) {
          return;
        }
        manager.updateStudentProgression(record.id, (current) => ({
          ...current,
          status: "transferred",
          transferredAt: nowIso(),
          transferReason: String(transferNote || "").trim(),
          archivedAt: null,
          progressionHistory: appendStudentProgression(current, {
            type: "transferred",
            fromLevel: current.level,
            toLevel: "",
            note: String(transferNote || "").trim() || "Transferred out by admin",
          }),
        }));
        recordAuditEvent({
          action: "updated",
          entityType: "student",
          entityId: record.admissionNo,
          summary: `Transferred out ${record.fullName}`,
          details: `${record.level}${transferNote ? ` • ${transferNote}` : ""}`,
        });
        setStatus(
          status,
          "success",
          `Student <strong>${escapeHtml(record.fullName)}</strong> transferred out successfully.`,
        );
        return;
      }

      if (action === "archive") {
        manager.archiveStudent(record.id);
        recordAuditEvent({
          action: "archived",
          entityType: "student",
          entityId: record.admissionNo,
          summary: `Archived student record for ${record.fullName}`,
          details: `${record.level}`,
        });
        resetPortalStudentForm(form, guardianList, isAdmin);
        setStudentFormVisibility(false);
        setStatus(status, "success", `Student <strong>${escapeHtml(record.fullName)}</strong> archived.`);
        return;
      }

      if (action === "activate") {
        manager.activateStudent(record.id);
        recordAuditEvent({
          action: "reactivated",
          entityType: "student",
          entityId: record.admissionNo,
          summary: `Reactivated student record for ${record.fullName}`,
          details: `${record.level}`,
        });
        resetPortalStudentForm(form, guardianList, isAdmin);
        setStudentFormVisibility(false);
        setStatus(status, "success", `Student <strong>${escapeHtml(record.fullName)}</strong> reactivated.`);
      }
    });

    window.addEventListener(manager.eventName, refreshStudentSection);
    if (classManager?.eventName) {
      window.addEventListener(classManager.eventName, refreshStudentSection);
    }
    if (settingsManager?.eventName) {
      window.addEventListener(settingsManager.eventName, refreshStudentSection);
    }

    if (quickAddForm && quickAddStatus) {
      Array.from(quickAddForm.elements).forEach((field) => {
        if (field instanceof HTMLElement) {
          field.disabled = !isAdmin;
        }
      });
      quickAddForm.addEventListener("submit", async (event) => {
        event.preventDefault();

        if (!isAdmin) {
          setStatus(quickAddStatus, "info", "Only administrators can add students.");
          return;
        }

        const firstName = quickAddForm.elements.firstName.value.trim();
        const lastName = quickAddForm.elements.lastName.value.trim();
        const level = quickAddForm.elements.level.value.trim();
        const guardianName = quickAddForm.elements.guardianName.value.trim();
        const guardianPhone = quickAddForm.elements.guardianPhone.value.trim();
        const guardianEmail = quickAddForm.elements.guardianEmail.value.trim();

        if (!firstName || !lastName || !level || !guardianName || !guardianEmail) {
          setStatus(
            quickAddStatus,
            "error",
            "First name, last name, level/class, parent/guardian name, and guardian email are required for quick add.",
          );
          return;
        }

        if (!isKnownClassLevel(level, getActiveClassLevelTokenSet())) {
          setStatus(quickAddStatus, "error", "Invalid class. Select a valid class from the school structure.");
          return;
        }

        if (guardianPhone && !isValidPhoneNumber(guardianPhone)) {
          setStatus(quickAddStatus, "error", "Wrong phone number format.");
          return;
        }

        if (guardianEmail && !EMAIL_REGEX.test(guardianEmail)) {
          setStatus(quickAddStatus, "error", "Invalid parent/guardian email format.");
          return;
        }

        const admissionNo = generateAdmissionNumber({ manager, levelValue: level });
        const selectedClassRecord = chooseStudentClassRecordForLevel(level);
        const classAssignment = buildStudentClassAssignment(level, selectedClassRecord);
        const payload = {
          firstName,
          lastName,
          fullName: `${firstName} ${lastName}`,
          admissionNo,
          ...classAssignment,
          dateOfBirth: "",
          gender: "",
          promotionDecision: "promote",
          examOutcome: "pass",
          guardians: [
            {
              id: createId(),
              name: guardianName,
              relationship: "Guardian",
              phone: guardianPhone,
              email: guardianEmail,
            },
          ],
          status: "active",
        };

        manager.upsertStudent(payload);
        const parentProvisioning = await provisionParentAccountsForStudent(payload);
        const failedParentCopy = parentProvisioning.failed?.length
          ? ` ${parentProvisioning.failed.length} guardian login(s) could not be provisioned.`
          : "";
        quickAddForm.reset();
        setStatus(
          quickAddStatus,
          "success",
          `Student <strong>${escapeHtml(payload.fullName)}</strong> added with admission number <strong>${escapeHtml(
            payload.admissionNo,
          )}</strong>.${
            parentProvisioning.created.length
              ? ` Parent login created with default password <strong>${escapeHtml(DEFAULT_PARENT_PASSWORD)}</strong>.`
              : ""
          }${failedParentCopy}`,
        );
        recordAuditEvent({
          action: "created",
          entityType: "student",
          entityId: payload.admissionNo,
          summary: `Quick-added student record for ${payload.fullName}`,
          details: `${payload.level} • 1 guardian contact`,
        });
      });
    }

    if (viewContent) {
      viewContent.addEventListener("click", async (event) => {
        const button = event.target.closest("[data-student-photo-action]");
        if (!button || !isAdmin) {
          return;
        }

        const studentId = String(button.dataset.studentId || "").trim();
        const record = manager.getStudents().find((item) => item.id === studentId);
        if (!record) {
          return;
        }

        const action = String(button.dataset.studentPhotoAction || "").trim();
        if (action === "replace") {
          viewContent.querySelector("[data-student-photo-input]")?.click();
          return;
        }

        if (action !== "remove" || !record.profilePhotoUrl) {
          return;
        }

        const confirmed = await showAppConfirm({
          title: "Remove profile picture?",
          message: `Remove the profile picture for ${record.fullName || "this student"}?`,
          details: "The profile will return to showing the student's initials. Another picture can be added later.",
          confirmLabel: "Remove picture",
          variant: "danger",
        });
        if (!confirmed) {
          return;
        }

        manager.updateStudentProgression(studentId, (current) => ({
          ...current,
          profilePhotoUrl: "",
          profilePhotoName: "",
          profilePhotoMimeType: "",
          profilePhotoSizeBytes: 0,
          profilePhotoRemoved: true,
        }));
        const media = viewContent.querySelector(".portal-student-profile-photo-media");
        if (media) {
          media.textContent = getInitials(record.fullName || "Student").slice(0, 2) || "ST";
        }
        button.hidden = true;
        const replaceButton = viewContent.querySelector('[data-student-photo-action="replace"]');
        if (replaceButton) {
          replaceButton.textContent = "Add photo";
        }
        refreshStudentSection();
      });

      viewContent.addEventListener("change", async (event) => {
        const input = event.target.closest("[data-student-photo-input]");
        if (!input || !isAdmin) {
          return;
        }

        const studentId = String(input.dataset.studentId || "").trim();
        const record = manager.getStudents().find((item) => item.id === studentId);
        const file = input.files?.[0] || null;
        input.value = "";

        if (!record || !file) {
          return;
        }
        if (!String(file.type || "").startsWith("image/")) {
          setStatus(status, "error", "Choose a JPG, PNG, or WebP image for the student profile.");
          return;
        }
        if (file.size > 2 * 1024 * 1024) {
          setStatus(status, "error", "Profile picture is too large. Maximum size is 2MB.");
          return;
        }

        let profilePhotoUrl = "";
        try {
          profilePhotoUrl = await readFileAsDataUrl(file);
        } catch {
          setStatus(status, "error", "Could not read the selected profile picture.");
          return;
        }

        manager.updateStudentProgression(studentId, (current) => ({
          ...current,
          profilePhotoUrl,
          profilePhotoName: String(file.name || "Profile picture"),
          profilePhotoMimeType: String(file.type || ""),
          profilePhotoSizeBytes: Number(file.size) || 0,
          profilePhotoRemoved: false,
        }));
        const media = viewContent.querySelector(".portal-student-profile-photo-media");
        if (media) {
          media.innerHTML = `<img src="${escapeHtml(profilePhotoUrl)}" alt="${escapeHtml(
            record.fullName || "Student",
          )} profile picture" />`;
        }
        const removeButton = viewContent.querySelector('[data-student-photo-action="remove"]');
        if (removeButton) {
          removeButton.hidden = false;
        }
        const replaceButton = viewContent.querySelector('[data-student-photo-action="replace"]');
        if (replaceButton) {
          replaceButton.textContent = "Replace";
        }
        refreshStudentSection();
      });
    }

    document.querySelectorAll("[data-student-template-download]").forEach((button) => {
      button.addEventListener("click", () => {
        if (!isAdmin) {
          return;
        }
        if (button.dataset.studentTemplateDownload === "excel") {
          downloadStudentExcelTemplate();
        } else {
          downloadStudentCsvTemplate();
        }
      });
    });

    if (importPreviewButton && importStatus && importPreviewTarget && importFileInput) {
      importFileInput.disabled = !isAdmin;
      importPreviewButton.disabled = !isAdmin;
      importPreviewButton.addEventListener("click", async () => {
        if (!isAdmin) {
          setStatus(importStatus, "info", "Only administrators can import students.");
          return;
        }

        const selectedFile = importFileInput.files?.[0] || null;
        if (!selectedFile) {
          setStatus(importStatus, "error", "Choose a CSV or Excel file to preview.");
          return;
        }

        const extension = selectedFile.name.split(".").pop()?.toLowerCase() || "";
        if (!["csv", "xls", "xlsx"].includes(extension)) {
          setStatus(importStatus, "error", "Unsupported file type. Upload CSV or Excel file.");
          return;
        }

        if (extension === "xlsx") {
          setStatus(
            importStatus,
            "error",
            "For this build, upload CSV or the provided Excel template (.xls).",
          );
          return;
        }

        let rows = [];
        try {
          const content = await selectedFile.text();
          rows = extension === "csv" ? parseCsvRows(content) : parseSpreadsheetXmlRows(content);
        } catch (error) {
          setStatus(importStatus, "error", error?.message || "Could not parse the uploaded file.");
          return;
        }

        if (!rows.length) {
          setStatus(importStatus, "error", "No student rows found in the uploaded file.");
          importPreviewRows = [];
          renderImportPreview(importPreviewTarget, importPreviewRows);
          if (importConfirmButton) {
            importConfirmButton.disabled = true;
          }
          return;
        }

        const admissionTaken = new Set(
          manager.getStudents().map((student) => String(student.admissionNo || "").toLowerCase()),
        );
        const seenAdmissions = new Set();
        importPreviewRows = rows.map((row) => {
          const payload = buildStudentPayloadFromImportRow(row, manager, admissionTaken);
          const errors = validateImportPayload(payload, manager, classLevelSet, seenAdmissions);
          return { payload, errors };
        });

        renderImportPreview(importPreviewTarget, importPreviewRows);
        const validCount = importPreviewRows.filter((item) => !item.errors.length).length;
        const invalidCount = importPreviewRows.length - validCount;

        if (importConfirmButton) {
          importConfirmButton.disabled = validCount === 0;
        }

        if (invalidCount) {
          setStatus(
            importStatus,
            "error",
            `${invalidCount} row(s) have validation errors. Fix and upload again, or confirm to import valid rows only.`,
          );
        } else {
          setStatus(importStatus, "success", `${validCount} student row(s) ready for import.`);
        }
      });
    }

    if (importConfirmButton && importStatus && importPreviewTarget) {
      if (!isAdmin) {
        importConfirmButton.disabled = true;
      }
      importConfirmButton.addEventListener("click", async () => {
        if (!isAdmin) {
          setStatus(importStatus, "info", "Only administrators can import students.");
          return;
        }

        if (!importPreviewRows.length) {
          setStatus(importStatus, "error", "Preview records first before confirming import.");
          return;
        }

        const validRows = importPreviewRows.filter((item) => !item.errors.length);

        if (!validRows.length) {
          setStatus(importStatus, "error", "No valid rows to import.");
          return;
        }

        let createdParentLogins = 0;
        let failedParentLogins = 0;
        let createdStudentLogins = 0;
        let failedStudentLogins = 0;

        for (const row of validRows) {
          manager.upsertStudent({
            ...row.payload,
            status: "active",
          });
          const persistedStudent =
            manager.getStudents().find(
              (record) =>
                String(record.admissionNo || "").toLowerCase() ===
                String(row.payload.admissionNo || "").toLowerCase(),
            ) || row.payload;
          const parentProvisioning = await provisionParentAccountsForStudent(persistedStudent);
          const studentProvisioning = await provisionStudentAccountForStudent(persistedStudent);
          createdParentLogins += parentProvisioning.created.length;
          failedParentLogins += parentProvisioning.failed?.length || 0;
          if (studentProvisioning.status === "created") {
            createdStudentLogins += 1;
          } else if (
            row.payload.studentEmail &&
            !["updated", "existing_google"].includes(studentProvisioning.status)
          ) {
            failedStudentLogins += 1;
          }
        }

        recordAuditEvent({
          action: "imported",
          entityType: "student",
          entityId: `bulk-${validRows.length}`,
          summary: `Imported ${validRows.length} student records`,
          details: "Bulk import from CSV/Excel template.",
        });

        const invalidCount = importPreviewRows.length - validRows.length;
        importPreviewRows = [];
        renderImportPreview(importPreviewTarget, importPreviewRows);
        if (importFileInput) {
          importFileInput.value = "";
        }
        importConfirmButton.disabled = true;
        setStatus(
          importStatus,
          "success",
          invalidCount
            ? `Imported ${validRows.length} valid students. ${invalidCount} invalid row(s) were skipped.${
                createdParentLogins
                  ? ` ${createdParentLogins} parent login account(s) were auto-created (default password: ${DEFAULT_PARENT_PASSWORD}).`
                  : ""
              }${
                failedParentLogins
                  ? ` ${failedParentLogins} parent login account(s) could not be provisioned.`
                  : ""
              }${
                createdStudentLogins
                  ? ` ${createdStudentLogins} student login account(s) were auto-created (default password: ${DEFAULT_STUDENT_PASSWORD}).`
                  : ""
              }${
                failedStudentLogins
                  ? ` ${failedStudentLogins} student login account(s) could not be created.`
                  : ""
              }`
            : `Imported ${validRows.length} students successfully.${
                createdParentLogins
                  ? ` ${createdParentLogins} parent login account(s) were auto-created (default password: ${DEFAULT_PARENT_PASSWORD}).`
                  : ""
              }${
                failedParentLogins
                  ? ` ${failedParentLogins} parent login account(s) could not be provisioned.`
                  : ""
              }${
                createdStudentLogins
                  ? ` ${createdStudentLogins} student login account(s) were auto-created (default password: ${DEFAULT_STUDENT_PASSWORD}).`
                  : ""
              }${
                failedStudentLogins
                  ? ` ${failedStudentLogins} student login account(s) could not be created.`
                  : ""
              }`,
        );
      });
    }

  }

  function findUserByEmail(email) {
    const normalized = normalizeEmail(email);
    return getUsers().find((user) => user.normalizedEmail === normalized) || null;
  }

  function getSelectedRole() {
    const activeRole = document.querySelector(".auth-role.is-active");

    if (!activeRole) {
      return DEFAULT_AUTH_ROLE;
    }

    if (activeRole.dataset.authRole) {
      return normalizeRoleLabel(activeRole.dataset.authRole);
    }

    const activeRoleLabel = activeRole.querySelector(".auth-role-label");
    return normalizeRoleLabel(activeRoleLabel ? activeRoleLabel.textContent : DEFAULT_AUTH_ROLE);
  }

  function initRoleButtons() {
    const refreshLoginIdentifierCopy = () => {
      if (getPage() !== "login") {
        return;
      }

      const selectedRole = getSelectedRole();
      const emailInput = document.getElementById("login-email");
      const emailLabel = document.querySelector('.auth-field-label[for="login-email"]');

      if (emailLabel) {
        emailLabel.textContent = selectedRole === "Student" ? "Email or admission number" : "Email";
      }

      if (emailInput instanceof HTMLInputElement) {
        emailInput.placeholder = selectedRole === "Student" ? "Email or admission number" : "name@school.edu";
      }
    };

    document.querySelectorAll(".auth-role").forEach((button) => {
      button.addEventListener("click", () => {
        document.querySelectorAll(".auth-role").forEach((item) => item.classList.remove("is-active"));
        button.classList.add("is-active");
        refreshLoginIdentifierCopy();
      });
    });
    refreshLoginIdentifierCopy();
  }

  function initPasswordToggles() {
    document.querySelectorAll("[data-password-toggle]").forEach((button) => {
      button.addEventListener("click", () => {
        const targetId = button.dataset.passwordToggle;
        const input = document.getElementById(targetId);

        if (!input) {
          return;
        }

        const nextType = input.type === "password" ? "text" : "password";
        input.type = nextType;
        button.setAttribute("aria-label", nextType === "password" ? "Show password" : "Hide password");
        button.classList.toggle("is-active", nextType === "text");
      });
    });
  }

  function setStatus(target, type, message) {
    if (!target) {
      return;
    }

    if (!message) {
      target.hidden = true;
      target.className = "auth-status";
      target.innerHTML = "";
      return;
    }

    target.hidden = false;
    target.className = `auth-status auth-status--${type}`;
    target.innerHTML = message;
  }

  function clearFieldErrors(form) {
    form.querySelectorAll(".auth-line-field").forEach((field) => field.classList.remove("is-invalid"));
    form.querySelectorAll(".auth-check").forEach((field) => field.classList.remove("is-invalid"));
    form.querySelectorAll(".portal-field").forEach((field) => field.classList.remove("is-invalid"));
    form.querySelectorAll(".auth-field-error").forEach((error) => {
      error.textContent = "";
    });
  }

  function setFieldError(form, fieldName, message) {
    const error = form.querySelector(`[data-error-for="${fieldName}"]`);
    const control = form.elements[fieldName];
    const target =
      control && control.closest(".auth-line-field")
        ? control.closest(".auth-line-field")
        : control && control.closest(".auth-check")
          ? control.closest(".auth-check")
          : control && control.closest(".portal-field")
            ? control.closest(".portal-field")
            : null;

    if (error) {
      error.textContent = message;
    }

    if (target) {
      target.classList.add("is-invalid");
    }
  }

  function storeConfirmationMail(user) {
    const mailLog = getMailLog();
    mailLog.unshift({
      id: createId(),
      to: user.email,
      subject: "Confirm your SchoolSphere account",
      token: user.confirmationToken,
      confirmationUrl: buildConfirmationUrl(user.confirmationToken),
      sentAt: user.confirmationSentAt,
    });
    saveMailLog(mailLog.slice(0, 20));
  }

  function updateUser(userId, updater) {
    const users = getUsers();
    const index = users.findIndex((user) => user.id === userId);

    if (index === -1) {
      return null;
    }

    const updatedUser = updater({ ...users[index] });
    users[index] = updatedUser;
    saveUsers(users);
    return updatedUser;
  }

  function removeUser(userId, workspaceId = null) {
    const targetWorkspaceId = normalizeWorkspaceId(workspaceId || getCurrentWorkspaceId());
    const users = getUsers();
    const nextUsers = users.filter(
      (user) =>
        !(
          user.id === userId &&
          normalizeWorkspaceId(user.workspaceId || "public") === targetWorkspaceId
        ),
    );

    if (nextUsers.length === users.length) {
      return false;
    }

    saveUsers(nextUsers);
    return true;
  }

  function updateUserByEmail(email, updater, workspaceId = null) {
    const normalized = normalizeEmail(email || "");
    const hasSession = Boolean(getSession());
    const targetWorkspaceId = workspaceId
      ? normalizeWorkspaceId(workspaceId)
      : hasSession
        ? normalizeWorkspaceId(getCurrentWorkspaceId())
        : null;
    const users = getUsers();
    const index = users.findIndex(
      (user) =>
        user.normalizedEmail === normalized &&
        (targetWorkspaceId ? normalizeWorkspaceId(user.workspaceId || "public") === targetWorkspaceId : true),
    );

    if (index === -1) {
      return null;
    }

    const updatedUser = normalizeUserRecord(updater({ ...users[index] }));
    users[index] = updatedUser;
    saveUsers(users);
    return updatedUser;
  }

  function initSignupFlow() {
    if (getPage() !== "signup") {
      return;
    }

    const form = document.getElementById("signup-form");
    const status = document.getElementById("signup-status");

    if (!form || !status) {
      return;
    }

    const guardNotice = getAccessGuardNotice();

    if (guardNotice) {
      setStatus(status, "info", guardNotice);
    }

    status.addEventListener("click", async (event) => {
      const resendButton = event.target.closest("[data-supabase-resend-confirmation]");

      if (!resendButton || !isSupabaseConfigured()) {
        return;
      }

      event.preventDefault();

      const email = normalizeEmail(resendButton.dataset.email || form.elements.email.value);

      if (!email || !EMAIL_REGEX.test(email)) {
        setStatus(status, "error", "Enter a valid email address before resending the confirmation email.");
        return;
      }

      resendButton.disabled = true;
      resendButton.textContent = "Sending...";

      const client = await getSupabaseClient();
      let error;

      try {
        ({ error } = await withNetworkTimeout(
          client.auth.resend({
            type: "signup",
            email,
            options: {
              emailRedirectTo: buildSupabaseEmailRedirectUrl(),
            },
          }),
        ));
      } catch (requestError) {
        error = requestError;
      }

      if (error) {
        setStatus(
          status,
          "error",
          `${formatSupabaseAuthError(error, "We could not resend the confirmation email.")} If this keeps happening, check your email delivery settings and rate limits.`,
        );
        return;
      }

      setStatus(
        status,
        "success",
        `Confirmation email resent to <strong>${escapeHtml(
          email,
        )}</strong>. Check Inbox, Spam, Promotions, and Updates. If it still does not arrive, check your email delivery settings.`,
      );
    });

    form.addEventListener("input", () => {
      clearFieldErrors(form);
      setStatus(status, "", "");
    });

    form.addEventListener("submit", async (event) => {
      event.preventDefault();

      clearFieldErrors(form);
      setStatus(status, "", "");

      const email = form.elements.email.value.trim();
      const signupWorkspaceId = normalizeWorkspaceId(normalizeEmail(email));
      const password = form.elements.password.value;
      const confirmPassword = form.elements.confirmPassword.value;
      const termsAccepted = form.elements.terms.checked;
      const grantedRole = "Admin";

      let hasError = false;

      if (!email) {
        setFieldError(form, "email", "Enter your school email address.");
        hasError = true;
      } else if (!EMAIL_REGEX.test(email)) {
        setFieldError(form, "email", "Enter a valid email address.");
        hasError = true;
      }

      if (!password) {
        setFieldError(form, "password", "Create a password.");
        hasError = true;
      } else if (!isStrongPassword(password)) {
        setFieldError(form, "password", "Use at least 8 characters with letters and numbers.");
        hasError = true;
      }

      if (!confirmPassword) {
        setFieldError(form, "confirmPassword", "Confirm your password.");
        hasError = true;
      } else if (confirmPassword !== password) {
        setFieldError(form, "confirmPassword", "Passwords do not match.");
        hasError = true;
      }

      if (!termsAccepted) {
        setFieldError(form, "terms", "You need to accept the terms to continue.");
        hasError = true;
      }

      const existingUser = email ? findUserByEmail(email) : null;

      if (existingUser) {
        setFieldError(form, "email", "This email is already registered.");
        const confirmationLink =
          !existingUser.isConfirmed && existingUser.confirmationToken
            ? ` <a href="${buildConfirmationUrl(existingUser.confirmationToken)}">Open the latest confirmation link</a>.`
            : "";
        setStatus(
          status,
          "error",
          `We already have an account for <strong>${escapeHtml(email)}</strong>.${confirmationLink}`,
        );
        hasError = true;
      }

      if (hasError) {
        if (!status.hidden || status.innerHTML) {
          return;
        }
        setStatus(status, "error", "Fix the highlighted fields and try again.");
        return;
      }

      if (isSupabaseConfigured()) {
        setAuthPersistencePreference(true);
        rememberPendingRole(grantedRole);

        const client = await getSupabaseClient();
        let data;
        let error;

        try {
          ({ data, error } = await withNetworkTimeout(
            client.auth.signUp({
              email,
              password,
              options: {
                emailRedirectTo: buildSupabaseEmailRedirectUrl(),
                data: {
                  display_name: buildDisplayName(email) || "School User",
                  role: grantedRole,
                  workspace_id: signupWorkspaceId,
                },
              },
            }),
          ));
        } catch (requestError) {
          setStatus(
            status,
            "error",
            formatSupabaseAuthError(requestError, "We couldn't create your account."),
          );
          return;
        }

        if (error) {
          setStatus(status, "error", formatSupabaseAuthError(error, "We couldn't create your account."));
          return;
        }

        if (data?.session) {
          await syncSupabaseSessionToLocal({
            preferredRole: grantedRole,
            preferredWorkspaceId: signupWorkspaceId,
            redirectAuthenticatedAuthPages: false,
          });
          clearFormDraftFor(form);
          window.location.assign(getRoleHomeRoute(grantedRole));
          return;
        }

        form.reset();
        clearFormDraftFor(form);
        markAccessGrantClaimed(email, grantedRole, "password", data?.user?.id || null, signupWorkspaceId);
        const signupDiagnostic = data?.user?.id
          ? `
            <details class="auth-debug-details">
              <summary>Signup diagnostic</summary>
              <span>The account service accepted this signup.</span>
              <span>User ID: <code>${escapeHtml(data.user.id)}</code></span>
              <span>Email confirmed: ${data.user.email_confirmed_at ? "Yes" : "No"}</span>
            </details>
          `
          : `
            <details class="auth-debug-details">
              <summary>Signup diagnostic</summary>
              <span>No online account ID was returned. Check the app configuration and browser network request.</span>
            </details>
          `;
        setStatus(
          status,
          "success",
          `A confirmation email has been sent to <strong>${escapeHtml(
            email,
          )}</strong>. Check Inbox, Spam, Promotions, and Updates. <button class="auth-status-button" type="button" data-supabase-resend-confirmation data-email="${escapeHtml(
            email,
          )}">Resend confirmation email</button>${signupDiagnostic}`,
        );
        return;
      }

      const confirmationToken = createToken();
      const user = {
        id: createId(),
        email,
        normalizedEmail: normalizeEmail(email),
        workspaceId: signupWorkspaceId,
        displayName: buildDisplayName(email) || "School User",
        passwordHash: await hashSecret(password),
        provider: "password",
        role: grantedRole,
        isConfirmed: false,
        confirmationToken,
        confirmationSentAt: nowIso(),
        confirmedAt: null,
        createdAt: nowIso(),
        lastLoginAt: null,
        status: "active",
      };

      const users = getUsers();
      users.push(user);
      saveUsers(users);
      storeConfirmationMail(user);
      markAccessGrantClaimed(user.email, user.role, "password", user.id, user.workspaceId);

      form.reset();
      clearFormDraftFor(form);
      setStatus(
        status,
        "success",
        `Confirmation email sent to <strong>${escapeHtml(user.email)}</strong>. <a href="${buildConfirmationUrl(
          confirmationToken,
        )}">Open the confirmation link</a> to activate this prototype account.`,
      );
    });
  }

  function initLoginFlow() {
    if (getPage() !== "login") {
      return;
    }

    const form = document.getElementById("login-form");
    const status = document.getElementById("login-status");

    if (!form || !status) {
      return;
    }

    const guardNotice = getAccessGuardNotice();

    if (guardNotice) {
      setStatus(status, "info", guardNotice);
    }

    form.addEventListener("input", () => {
      clearFieldErrors(form);
      setStatus(status, "", "");
    });

    form.addEventListener("submit", async (event) => {
      event.preventDefault();

      clearFieldErrors(form);
      setStatus(status, "", "");

      const loginIdentifier = form.elements.email.value.trim();
      const password = form.elements.password.value;
      const remember = form.elements.remember.checked;
      const selectedRole = getSelectedRole();
      const studentLogin =
        selectedRole === "Student" ? resolveStudentLoginIdentifier(loginIdentifier) : null;
      const email = studentLogin ? studentLogin.email : loginIdentifier;

      let hasError = false;

      if (!loginIdentifier) {
        setFieldError(
          form,
          "email",
          selectedRole === "Student"
            ? "Enter your student email or admission number."
            : "Enter your school email address.",
        );
        hasError = true;
      } else if (studentLogin?.error) {
        setFieldError(form, "email", studentLogin.error);
        hasError = true;
      } else if (!EMAIL_REGEX.test(email)) {
        setFieldError(form, "email", "Enter a valid email address.");
        hasError = true;
      }

      if (!password) {
        setFieldError(form, "password", "Enter your password.");
        hasError = true;
      }

      if (hasError) {
        setStatus(status, "error", "Enter your login details to continue.");
        return;
      }

      if (isSupabaseConfigured()) {
        setAuthPersistencePreference(remember);
        rememberPendingRole(selectedRole);

        const client = await getSupabaseClient();
        let data;
        let error;

        try {
          ({ data, error } = await withNetworkTimeout(
            client.auth.signInWithPassword({
              email,
              password,
            }),
          ));
        } catch (requestError) {
          setStatus(
            status,
            "error",
            formatSupabaseAuthError(requestError, "We could not sign you in with those credentials."),
          );
          return;
        }

        if (error) {
          const friendlyMessage = formatSupabaseAuthError(
            error,
            "We could not sign you in with those credentials.",
          );

          if (/incorrect|invalid login credentials/i.test(friendlyMessage)) {
            const fallbackUser = findUserByEmail(email);

            if (
              fallbackUser &&
              !isUserDeactivated(fallbackUser) &&
              fallbackUser.provider !== "google" &&
              fallbackUser.isConfirmed &&
              fallbackUser.passwordHash
            ) {
              const passwordHash = await hashSecret(password);

              if (passwordHash === fallbackUser.passwordHash) {
                const fallbackRole = normalizeRoleLabel(fallbackUser.role || DEFAULT_AUTH_ROLE);

                if (selectedRole !== fallbackRole) {
                  setStatus(
                    status,
                    "error",
                    `This account is registered as <strong>${escapeHtml(
                      fallbackRole,
                    )}</strong>. Switch role to continue.`,
                  );
                  return;
                }

                const updatedFallbackUser = updateUser(fallbackUser.id, (currentUser) => ({
                  ...currentUser,
                  lastLoginAt: nowIso(),
                }));

                setSession(
                  {
                    userId: updatedFallbackUser.id,
                    email: updatedFallbackUser.email,
                    displayName: updatedFallbackUser.displayName,
                    role: fallbackRole,
                    provider: updatedFallbackUser.provider,
                    workspaceId: updatedFallbackUser.workspaceId,
                    persistence: remember ? "persistent" : "session",
                    signedInAt: nowIso(),
                    source: "local-fallback",
                  },
                  remember,
                );

                clearFormDraftFor(form);
                window.location.assign(getPostLoginRoute(fallbackRole, updatedFallbackUser));
                return;
              }
            }

            setFieldError(form, "password", "Incorrect login details.");
          }

          setStatus(status, "error", friendlyMessage);
          return;
        }

        const provisionedRole = getProvisioningGrant(email, null, "password")?.role || null;
        const localUserRole = findUserByEmail(email)?.role || null;
        const resolvedRole = normalizeRoleLabel(
          data?.user?.user_metadata?.role ||
            provisionedRole ||
            localUserRole ||
            DEFAULT_AUTH_ROLE,
        );

        if (selectedRole !== resolvedRole) {
          await client.auth.signOut();
          clearSession();
          setStatus(
            status,
            "error",
            `This account is registered as <strong>${escapeHtml(
              resolvedRole,
            )}</strong>. Switch role to continue.`,
          );
          return;
        }

        const authResult = await syncSupabaseSessionToLocal({
          preferredRole: resolvedRole,
          preferredWorkspaceId: studentLogin?.workspaceId || null,
          redirectAuthenticatedAuthPages: false,
        });

        if (!authResult?.user) {
          const guardMessage = sessionStorage.getItem(ACCESS_GUARD_NOTICE_KEY);
          setStatus(
            status,
            "error",
            guardMessage || "Sign-in could not be completed. Confirm your role and account access.",
          );
          return;
        }

        const signedInRole = normalizeRoleLabel(authResult.user.role || DEFAULT_AUTH_ROLE);

        if (signedInRole !== selectedRole) {
          await client.auth.signOut();
          clearSession();
          setStatus(
            status,
            "error",
            `This account is registered as <strong>${escapeHtml(
              signedInRole,
            )}</strong>. Switch role to continue.`,
          );
          return;
        }

        clearFormDraftFor(form);
        window.location.assign(getPostLoginRoute(signedInRole, authResult.user));
        return;
      }

      const user = findUserByEmail(email);

      if (!user) {
        setFieldError(form, "email", "No account was found with that email.");
        setStatus(status, "error", "We could not find an account with those credentials.");
        return;
      }

      if (isUserDeactivated(user)) {
        setStatus(status, "error", "This account is deactivated. Contact an administrator for reactivation.");
        return;
      }

      if (user.provider === "google") {
        setStatus(
          status,
          "info",
          `This account uses Google sign-in. Use <strong>Continue with Google</strong> instead.`,
        );
        return;
      }

      if (!user.isConfirmed && user.confirmationToken) {
        setStatus(
          status,
          "error",
          `Please confirm your email before signing in. <a href="${buildConfirmationUrl(
            user.confirmationToken,
          )}">Open the confirmation link</a>.`,
        );
        return;
      }

      const passwordHash = await hashSecret(password);

      if (passwordHash !== user.passwordHash) {
        setFieldError(form, "password", "Incorrect password.");
        setStatus(status, "error", "Your email or password is incorrect.");
        return;
      }

      const userRole = normalizeRoleLabel(user.role || DEFAULT_AUTH_ROLE);

      if (selectedRole !== userRole) {
        setStatus(
          status,
          "error",
          `This account is registered as <strong>${escapeHtml(
            userRole,
          )}</strong>. Switch role to continue.`,
        );
        return;
      }

      const updatedUser = updateUser(user.id, (currentUser) => ({
        ...currentUser,
        lastLoginAt: nowIso(),
      }));

      setSession(
        {
          userId: updatedUser.id,
          email: updatedUser.email,
          displayName: updatedUser.displayName,
          role: userRole,
          provider: updatedUser.provider,
          workspaceId: updatedUser.workspaceId,
          persistence: remember ? "persistent" : "session",
          signedInAt: nowIso(),
        },
        remember,
      );

      clearFormDraftFor(form);
      window.location.assign(getPostLoginRoute(userRole, updatedUser));
    });
  }

  function initForgotPasswordFlow() {
    if (getPage() !== "forgot-password") {
      return;
    }

    const form = document.getElementById("forgot-form");
    const status = document.getElementById("forgot-status");
    const formView = document.getElementById("forgot-form-view");
    const sentView = document.getElementById("forgot-sent-view");
    const sentEmail = sentView?.querySelector("[data-sent-email]");
    const devPanel = sentView?.querySelector("[data-dev-panel]");
    const devResetLink = sentView?.querySelector("[data-dev-reset-link]");

    if (!form || !status || !formView || !sentView) {
      return;
    }

    form.addEventListener("input", () => {
      clearFieldErrors(form);
      setStatus(status, "", "");
    });

    form.addEventListener("submit", async (event) => {
      event.preventDefault();

      clearFieldErrors(form);
      setStatus(status, "", "");

      const email = String(form.elements.email?.value || "").trim();

      if (!email) {
        setFieldError(form, "email", "Enter your account email.");
        setStatus(status, "error", "Enter your account email to continue.");
        return;
      }

      if (!EMAIL_REGEX.test(email)) {
        setFieldError(form, "email", "Enter a valid email address.");
        setStatus(status, "error", "Enter a valid email address to continue.");
        return;
      }

      const normalizedEmail = normalizeEmail(email);
      const user = findUserByEmail(normalizedEmail);
      let resetUrl = "";
      if (isSupabaseConfigured()) {
        const client = await getSupabaseClient();
        let error;

        try {
          ({ error } = await withNetworkTimeout(
            client.auth.resetPasswordForEmail(normalizedEmail, {
              redirectTo: buildSupabaseRedirectUrl("reset-password.html"),
            }),
          ));
        } catch (requestError) {
          error = requestError;
        }

        if (error) {
          setStatus(status, "error", formatSupabaseAuthError(error, "Could not send the password reset email."));
          return;
        }
      } else if (user && !isUserDeactivated(user) && user.provider !== "google") {
        const recoveryRequest = createLocalPasswordRecoveryRequest(user, user.email);
        storePasswordRecoveryMail(user, recoveryRequest);
        resetUrl = buildPasswordRecoveryUrl(recoveryRequest.token);
      }

      recordAuditEvent({
        action: "created",
        entityType: "password-recovery",
        entityId: normalizedEmail,
        summary: `Password reset requested for ${normalizedEmail}`,
        details: "Recovery email requested",
      });

      if (sentEmail) {
        sentEmail.textContent = normalizedEmail;
      }
      if (devPanel && devResetLink) {
        devPanel.hidden = isSupabaseConfigured() || !resetUrl;
        devResetLink.href = resetUrl || "#";
      }
      formView.hidden = true;
      sentView.hidden = false;
    });
  }

  async function initResetPasswordFlow() {
    if (getPage() !== "reset-password") {
      return;
    }

    const form = document.getElementById("reset-form");
    const status = document.getElementById("reset-status");
    const formWrapper = document.getElementById("reset-form-wrapper");
    const invalidView = document.getElementById("reset-invalid-view");
    const successView = document.getElementById("reset-success-view");
    const params = new URLSearchParams(window.location.search);
    const token = String(params.get("token") || "").trim();
    const authorizationCode = String(params.get("code") || "").trim();
    const recoveryHash = String(window.location.hash || "");
    const recoveryMarker = parseJSON(localStorage.getItem(AUTH_PASSWORD_RECOVERY_KEY), null);
    const recoveryMarkerAge = recoveryMarker?.updatedAt
      ? Date.now() - new Date(recoveryMarker.updatedAt).getTime()
      : Number.POSITIVE_INFINITY;
    const hasActiveRecoveryMarker =
      recoveryMarkerAge >= 0 &&
      recoveryMarkerAge <= 2 * 60 * 60 * 1000 &&
      String(recoveryMarker?.status || "") === "active";
    const hasRecoveryUrlEvidence =
      Boolean(authorizationCode) ||
      params.get("type") === "recovery" ||
      /(?:^|[#&])type=recovery(?:&|$)/.test(recoveryHash) ||
      /(?:^|[#&])access_token=/.test(recoveryHash);
    const localRequest = token ? getPasswordRecoveryRequestByToken(token) : null;
    const hasValidLocalRequest = isPasswordRecoveryRequestValid(localRequest);
    let hostedRecoveryResult = null;

    if (isSupabaseConfigured() && (hasRecoveryUrlEvidence || hasActiveRecoveryMarker)) {
      const client = await getSupabaseClient();

      for (let attempt = 0; attempt < 4 && !hostedRecoveryResult; attempt += 1) {
        try {
          const {
            data: { session: hostedSession },
          } = await client.auth.getSession();

          if (hostedSession?.user) {
            hostedRecoveryResult = await syncSupabaseSessionToLocal({
              redirectAuthenticatedAuthPages: false,
            });
            break;
          }

          if (attempt === 0 && authorizationCode && typeof client.auth.exchangeCodeForSession === "function") {
            const { error: exchangeError } = await client.auth.exchangeCodeForSession(authorizationCode);
            if (exchangeError) {
              break;
            }
          }
        } catch {
          // Retry briefly while the recovery session is being restored from the URL.
        }

        await new Promise((resolve) => window.setTimeout(resolve, 200));
      }
    }

    const hasSupabaseRecoverySession = Boolean(hostedRecoveryResult?.session?.user && hostedRecoveryResult?.user);
    const activeUser = hasValidLocalRequest
      ? getUsers().find((entry) => entry.id === localRequest.userId) || null
      : hasSupabaseRecoverySession
        ? hostedRecoveryResult.user
        : null;

    if (!form || !status || !formWrapper || !invalidView || !successView) {
      return;
    }

    if (!activeUser) {
      formWrapper.hidden = true;
      invalidView.hidden = false;
      successView.hidden = true;
      return;
    }

    invalidView.hidden = true;
    formWrapper.hidden = false;
    successView.hidden = true;

    form.addEventListener("input", () => {
      clearFieldErrors(form);
      setStatus(status, "", "");
    });

    form.addEventListener("submit", async (event) => {
      event.preventDefault();

      clearFieldErrors(form);
      setStatus(status, "", "");

      const password = String(form.elements.password?.value || "");
      const confirmPassword = String(form.elements.confirmPassword?.value || "");
      let hasError = false;

      if (!password) {
        setFieldError(form, "password", "Enter a new password.");
        hasError = true;
      } else if (!isStrongPassword(password)) {
        setFieldError(form, "password", "Use at least 8 characters with letters and numbers.");
        hasError = true;
      }

      if (!confirmPassword) {
        setFieldError(form, "confirmPassword", "Confirm your new password.");
        hasError = true;
      } else if (password !== confirmPassword) {
        setFieldError(form, "confirmPassword", "Passwords do not match.");
        hasError = true;
      }

      if (hasError) {
        setStatus(status, "error", "Fix the highlighted fields and try again.");
        return;
      }

      if (activeUser.provider === "google" && !hasSupabaseRecoverySession) {
        setStatus(status, "info", "This account uses Google sign-in. Reset the password from your Google account instead.");
        return;
      }

      if (isSupabaseConfigured() && hasSupabaseRecoverySession) {
        const client = await getSupabaseClient();
        let error;

        try {
          ({ error } = await withNetworkTimeout(
            client.auth.updateUser({
              password,
            }),
          ));
        } catch (requestError) {
          error = requestError;
        }

        if (error) {
          setStatus(status, "error", formatSupabaseAuthError(error, "Could not update the password."));
          return;
        }
      }

      const nextPasswordHash = await hashSecret(password);
      updateUser(activeUser.id, (record) => ({
        ...record,
        passwordHash: nextPasswordHash,
        mustChangePassword: false,
      }));

      if (hasValidLocalRequest) {
        markPasswordRecoveryRequestUsed(token);
      }
      localStorage.removeItem(AUTH_PASSWORD_RECOVERY_KEY);

      recordAuditEvent({
        action: "updated",
        entityType: "user-password",
        entityId: activeUser.email,
        summary: `Password reset completed for ${activeUser.email}`,
        details: hasValidLocalRequest ? "Verified contact recovery" : "Hosted recovery session",
      });

      form.reset();
      clearFormDraftFor(form);
      formWrapper.hidden = true;
      successView.hidden = false;

      if (isSupabaseConfigured() && hasSupabaseRecoverySession) {
        try {
          const client = await getSupabaseClient();
          await client.auth.signOut();
        } catch {
          // Keep the local success path even if the sign-out request stalls.
        }
      }

      clearSession();
      window.setTimeout(() => {
        window.location.assign("./login.html");
      }, 1400);
    });
  }

  function ensureGoogleModal() {
    let modal = document.getElementById("auth-google-modal");

    if (modal) {
      return modal;
    }

    const wrapper = document.createElement("div");
    wrapper.innerHTML = `
      <div class="auth-modal" id="auth-google-modal" hidden>
        <div class="auth-modal-scrim" data-auth-modal-close></div>
        <div class="auth-modal-card" role="dialog" aria-modal="true" aria-labelledby="auth-google-title">
          <button class="auth-modal-close" type="button" data-auth-modal-close aria-label="Close">&times;</button>
          <span class="auth-modal-kicker">Google Account</span>
          <h2 id="auth-google-title" class="auth-modal-title">Continue with Google</h2>
          <p class="auth-modal-copy" id="auth-google-copy">
            Enter the Google account email you want to use with this prototype.
          </p>
          <form id="auth-google-form" class="auth-modal-form" novalidate>
            <input id="auth-google-email" name="email" type="email" placeholder="name@gmail.com" autocomplete="email" />
            <p id="auth-google-error" class="auth-field-error"></p>
            <div class="auth-modal-actions">
              <button class="button button-outline" type="button" data-auth-modal-close>Cancel</button>
              <button class="button button-primary" type="submit">Continue</button>
            </div>
          </form>
        </div>
      </div>
    `;

    document.body.appendChild(wrapper.firstElementChild);
    modal = document.getElementById("auth-google-modal");

    modal.querySelectorAll("[data-auth-modal-close]").forEach((button) => {
      button.addEventListener("click", () => closeGoogleModal());
    });

    modal.querySelector("#auth-google-form").addEventListener("submit", handleGoogleSubmit);

    return modal;
  }

  function openGoogleModal(mode) {
    const modal = ensureGoogleModal();
    const title = modal.querySelector("#auth-google-title");
    const copy = modal.querySelector("#auth-google-copy");
    const error = modal.querySelector("#auth-google-error");
    const emailInput = modal.querySelector("#auth-google-email");

    modal.dataset.mode = mode;
    title.textContent =
      mode === "signup" ? "Create your account with Google" : "Continue with Google";
    copy.textContent =
      mode === "signup"
        ? "Use any Google account you want to connect to this prototype school workspace."
        : "Use the Google account linked to your school workspace.";
    error.textContent = "";
    emailInput.value = "";
    modal.hidden = false;
    document.body.classList.add("auth-modal-open");
    emailInput.focus();
  }

  function closeGoogleModal() {
    const modal = document.getElementById("auth-google-modal");

    if (!modal) {
      return;
    }

    modal.hidden = true;
    document.body.classList.remove("auth-modal-open");
  }

  async function startSupabaseGoogleAuth(mode) {
    const page = getPage();
    const status = document.getElementById(page === "signup" ? "signup-status" : "login-status");
    const rememberCheckbox = document.getElementById("login-remember");
    const remember = page === "login" ? Boolean(rememberCheckbox?.checked) : true;
    const selectedRole = page === "login" ? getSelectedRole() : null;

    setAuthPersistencePreference(remember);
    if (selectedRole) {
      rememberPendingRole(selectedRole);
    }

    const client = await getSupabaseClient();
    let error;

    try {
      ({ error } = await withNetworkTimeout(
        client.auth.signInWithOAuth({
          provider: "google",
          options: {
            redirectTo: buildSupabaseRedirectUrl(),
          },
        }),
      ));
    } catch (requestError) {
      error = requestError;
    }

    if (error && status) {
      setStatus(
        status,
        "error",
        formatSupabaseAuthError(error, `We couldn't start Google ${mode === "signup" ? "sign up" : "sign in"}.`),
      );
    }
  }

  async function handleGoogleSubmit(event) {
    event.preventDefault();

    const modal = document.getElementById("auth-google-modal");
    const form = event.currentTarget;
    const error = modal.querySelector("#auth-google-error");
    const email = form.elements.email.value.trim();
    const mode = modal.dataset.mode || "login";
    const selectedRole = mode === "login" ? getSelectedRole() : null;

    error.textContent = "";

    if (!email) {
      error.textContent = "Enter your Google account email address.";
      return;
    }

    if (!isGoogleAuthEmail(email)) {
      error.textContent = "Enter a valid email address to continue with Google.";
      return;
    }

    const users = getUsers();
    const existingUser = users.find((user) => user.normalizedEmail === normalizeEmail(email)) || null;

    if (mode === "signup") {
      if (existingUser) {
        error.textContent =
          existingUser.provider === "google"
            ? "This Google account is already registered. Use login instead."
            : "This email already uses email and password. Sign in with that method instead.";
        return;
      }

      const grantedRole = "Admin";
      const signupWorkspaceId = normalizeWorkspaceId(normalizeEmail(email));

      const user = {
        id: createId(),
        email,
        normalizedEmail: normalizeEmail(email),
        workspaceId: signupWorkspaceId,
        displayName: buildDisplayName(email) || "School User",
        passwordHash: null,
        provider: "google",
        role: grantedRole,
        isConfirmed: true,
        confirmationToken: null,
        confirmationSentAt: null,
        confirmedAt: nowIso(),
        createdAt: nowIso(),
        lastLoginAt: null,
        status: "active",
      };

      users.push(user);

      user.lastLoginAt = nowIso();
      saveUsers(users);
      markAccessGrantClaimed(user.email, user.role, "google", user.id, user.workspaceId);
      setSession(
        {
          userId: user.id,
          email: user.email,
          displayName: user.displayName,
          role: user.role,
          provider: user.provider,
          workspaceId: user.workspaceId,
          persistence: "persistent",
          signedInAt: nowIso(),
        },
        true,
      );

      closeGoogleModal();
      if (getPage() === "signup") {
        clearFormDraft("signup-form");
      }
      window.location.assign(getRoleHomeRoute(user.role));
      return;
    }

    if (!existingUser) {
      error.textContent = "No Google account was found with this email yet. Create one from the sign-up page first.";
      return;
    }

    if (existingUser.provider !== "google") {
      error.textContent = "This account was created with email and password. Use that login method instead.";
      return;
    }

    if (isUserDeactivated(existingUser)) {
      error.textContent = "This account is deactivated. Contact an administrator for reactivation.";
      return;
    }

    const existingRole = normalizeRoleLabel(existingUser.role || DEFAULT_AUTH_ROLE);

    if (selectedRole && selectedRole !== existingRole) {
      error.textContent = `This account is registered as ${existingRole}. Switch role and try again.`;
      return;
    }

    existingUser.lastLoginAt = nowIso();
    saveUsers(users);
    setSession(
      {
        userId: existingUser.id,
        email: existingUser.email,
        displayName: existingUser.displayName,
        role: existingRole,
        provider: existingUser.provider,
        workspaceId: existingUser.workspaceId,
        persistence: "persistent",
        signedInAt: nowIso(),
      },
      true,
    );

    closeGoogleModal();
    if (getPage() === "login") {
      clearFormDraft("login-form");
    }
    window.location.assign(getRoleHomeRoute(existingRole));
  }

  function initGoogleButtons() {
    document.querySelectorAll("[data-google-auth]").forEach((button) => {
      button.addEventListener("click", async () => {
        const mode = button.dataset.googleAuth || "login";

        if (isSupabaseConfigured()) {
          await startSupabaseGoogleAuth(mode);
          return;
        }

        openGoogleModal(mode);
      });
    });
  }

  function initConfirmPage() {
    if (getPage() !== "confirm-email") {
      return;
    }

    const status = document.getElementById("confirm-status");
    const heading = document.getElementById("confirm-heading");
    const copy = document.getElementById("confirm-copy");
    const details = document.getElementById("confirm-details");
    const params = new URLSearchParams(window.location.search);
    const token = params.get("token");

    if (!status || !heading || !copy || !details) {
      return;
    }

    if (!token) {
      setStatus(status, "error", "This confirmation link is missing a token.");
      heading.textContent = "We could not confirm this account.";
      copy.textContent = "Open the confirmation link from your registration message and try again.";
      return;
    }

    const users = getUsers();
    const user = users.find((entry) => entry.confirmationToken === token);

    if (!user) {
      setStatus(status, "error", "That confirmation link is no longer valid.");
      heading.textContent = "This link has expired or was already used.";
      copy.textContent = "If you still need access, register again or use the latest confirmation link.";
      return;
    }

    user.isConfirmed = true;
    user.confirmedAt = nowIso();
    user.confirmationToken = null;
    saveUsers(users);

    setStatus(status, "success", "Your email address is now confirmed.");
    heading.textContent = "Account confirmed.";
    copy.textContent = "You can now sign in with your email and password. Redirecting to login...";
    details.innerHTML = `
      <div class="utility-item">
        <span>Confirmed account</span>
        <strong>${escapeHtml(user.email)}</strong>
      </div>
      <div class="utility-item">
        <span>Auth method</span>
        <strong>Email and password</strong>
      </div>
    `;

    window.setTimeout(() => {
      window.location.assign("./login.html");
    }, 1400);
  }

  function initAdmissionsApplyPage() {
    if (getPage() !== "admissions-apply") {
      return;
    }

    const form = document.getElementById("admissions-apply-form");
    const status = document.getElementById("admissions-apply-status");
    const workspaceInput = document.getElementById("admissions-workspace-id");
    const pageCopy = document.getElementById("admissions-apply-copy");
    const stepIndicator = document.getElementById("admissions-step-indicator");
    const reviewPanel = document.getElementById("admissions-review-panel");
    const healthConditionSelect = document.getElementById("apply-health-condition");
    const healthConditionDetailsWrap = document.getElementById("health-condition-details-wrap");
    const healthConditionDetailsInput = document.getElementById("apply-health-condition-details");
    const admissionConfigManager = getAdmissionConfigManager();
    const applyingClassSelect = form?.elements?.academicClassApplyingFor || null;
    const submitButton = form?.querySelector('button[type="submit"]') || null;
    const fileUploadInputs = form ? Array.from(form.querySelectorAll('input[type="file"]')) : [];

    if (!form || !status || !workspaceInput) {
      return;
    }

    const params = new URLSearchParams(window.location.search);
    const rawWorkspace = String(params.get("workspace") || "").trim();
    const rawInstitutionId = String(params.get("institution") || "").trim();
    const prefilledWorkspace = rawWorkspace ? normalizeWorkspaceId(rawWorkspace) : "";
    const prefilledInstitutionId = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
      rawInstitutionId,
    )
      ? rawInstitutionId
      : "";
    const lockedWorkspaceId =
      prefilledWorkspace && prefilledWorkspace !== "public" ? prefilledWorkspace : "";
    const lockedInstitutionId = prefilledInstitutionId;
    const brandMark = document.getElementById("admissions-apply-brand-mark");
    const brandName = document.getElementById("admissions-apply-school-name");

    const getLocalApplySchoolSettings = (workspaceId) => {
      const manager = getSchoolSettingsManager();
      const defaults =
        manager && typeof manager.defaults === "object"
          ? manager.defaults
          : getDefaultAdminSchoolSettings();
      const storageKeys = [
        workspaceId ? `${SUPABASE_STATE_KEY_SCHOOL_SETTINGS}::${normalizeWorkspaceId(workspaceId)}` : "",
        SUPABASE_STATE_KEY_SCHOOL_SETTINGS,
      ].filter(Boolean);

      for (const storageKey of storageKeys) {
        const storedSettings = parseJSON(localStorage.getItem(storageKey), null);
        if (storedSettings && typeof storedSettings === "object" && !Array.isArray(storedSettings)) {
          return {
            ...defaults,
            ...storedSettings,
          };
        }
      }

      return manager && typeof manager.getSettings === "function" ? manager.getSettings() : defaults;
    };

    const applyAdmissionsApplyBranding = (settings = {}) => {
      const rawSchoolName = String(settings.schoolName || "").trim();
      const displaySchoolName =
        rawSchoolName && rawSchoolName !== "SchoolSphere" ? rawSchoolName : "School Application";

      if (brandName) {
        brandName.textContent = displaySchoolName;
      }

      if (brandMark) {
        const logoUrl = String(settings.logoUrl || "").trim();
        if (logoUrl) {
          brandMark.classList.add("auth-brand-mark--image");
          brandMark.innerHTML = `<img class="school-brand-image" src="${escapeHtml(logoUrl)}" alt="${escapeHtml(
            displaySchoolName,
          )} logo" />`;
        } else {
          brandMark.classList.remove("auth-brand-mark--image");
          brandMark.textContent = getInitials(displaySchoolName).charAt(0) || "S";
        }
      }

      document.title = `${displaySchoolName} Admissions | SchoolSphere`;

      if (pageCopy) {
        pageCopy.textContent = lockedWorkspaceId
          ? `Complete the sections below and submit to ${displaySchoolName} for school admin review.`
          : "Use the official school application link to open this form.";
      }
    };

    const fetchInstitutionBranding = async (institutionId) => {
      if (!institutionId || !isSupabaseConfigured()) {
        return null;
      }

      try {
        const client = await getSupabaseClient();
        if (!client) {
          return null;
        }

        const { data, error } = await withNetworkTimeout(
          client
            .from("institutions")
            .select(
              "name, logo_url, school_profile, address, campus_details, phone, website, has_nursery, has_higher_institution, academic_year_start, academic_year_end",
            )
            .eq("id", institutionId)
            .maybeSingle(),
        );

        if (error || !data) {
          return null;
        }

        return mapInstitutionToSchoolSettings(data);
      } catch {
        return null;
      }
    };

    const normalizePublicAdmissionConfigStatus = (value) => {
      const normalized = String(value || "").trim().toLowerCase();
      return normalized === "archived" || normalized === "inactive" ? "archived" : "active";
    };

    const normalizePublicAdmissionSession = (record = {}) => ({
      ...record,
      id: String(record.id || "").trim(),
      name: String(record.name || "").trim(),
      status: String(record.status || "").trim().toLowerCase() === "open" ? "open" : "closed",
      createdAt: record.createdAt || "",
      updatedAt: record.updatedAt || "",
    });

    const normalizePublicAdmissionClass = (record = {}) => ({
      ...record,
      id: String(record.id || "").trim(),
      name: String(record.name || "").trim(),
      status: normalizePublicAdmissionConfigStatus(record.status),
      createdAt: record.createdAt || "",
      updatedAt: record.updatedAt || "",
    });

    const normalizePublicAdmissionStage = (record = {}, index = 0) => ({
      ...record,
      id: String(record.id || "").trim(),
      name: String(record.name || "").trim(),
      order: Number.isFinite(Number(record.order)) && Number(record.order) > 0 ? Number(record.order) : index + 1,
      status: normalizePublicAdmissionConfigStatus(record.status),
      createdAt: record.createdAt || "",
      updatedAt: record.updatedAt || "",
    });

    const summarizePublicAdmissionConfigState = (state = {}) => {
      const sessions = Array.isArray(state.sessions)
        ? state.sessions
            .map((record) => normalizePublicAdmissionSession(record))
            .filter((record) => record.name)
        : [];
      const classes = Array.isArray(state.classes)
        ? state.classes
            .map((record) => normalizePublicAdmissionClass(record))
            .filter((record) => record.name)
        : [];
      const defaultStages = [
        { id: "stage-submitted", name: "Submitted", order: 1, status: "active" },
        { id: "stage-review", name: "Review", order: 2, status: "active" },
        { id: "stage-shortlisted", name: "Shortlisted", order: 3, status: "active" },
        { id: "stage-approved", name: "Approved", order: 4, status: "active" },
      ];
      const stages = (Array.isArray(state.stages) && state.stages.length ? state.stages : defaultStages)
        .map((record, index) => normalizePublicAdmissionStage(record, index))
        .filter((record) => record.name)
        .sort((left, right) => left.order - right.order || left.name.localeCompare(right.name));
      const openSession = sessions.find((entry) => entry.status === "open") || null;
      const activeClasses = classes.filter((entry) => entry.status === "active");
      const activeStages = stages.filter((entry) => entry.status === "active");

      return {
        sessions,
        classes,
        stages,
        openSession,
        activeClasses,
        activeStages,
      };
    };

    const getPublicAdmissionConfigSummary = () => {
      const storageKeys = [
        lockedWorkspaceId ? `${SUPABASE_STATE_KEY_ADMISSION_CONFIG}::${normalizeWorkspaceId(lockedWorkspaceId)}` : "",
        SUPABASE_STATE_KEY_ADMISSION_CONFIG,
      ].filter(Boolean);

      for (const storageKey of storageKeys) {
        const storedConfig = parseJSON(localStorage.getItem(storageKey), null);
        if (storedConfig && typeof storedConfig === "object" && !Array.isArray(storedConfig)) {
          return summarizePublicAdmissionConfigState(storedConfig);
        }
      }

      return admissionConfigManager && typeof admissionConfigManager.summarize === "function"
        ? admissionConfigManager.summarize()
        : summarizePublicAdmissionConfigState();
    };

    applyAdmissionsApplyBranding(getLocalApplySchoolSettings(lockedWorkspaceId));
    if (lockedInstitutionId) {
      fetchInstitutionBranding(lockedInstitutionId).then((settings) => {
        if (settings) {
          applyAdmissionsApplyBranding(settings);
        }
      });
    }

    if (lockedWorkspaceId) {
      workspaceInput.value = lockedWorkspaceId;
    }

    const stepSections = Array.from(form.querySelectorAll("[data-admissions-step]"));
    let activeStepIndex = 0;
    let applyToastTimer = null;

    const showApplyToast = (type, message, autoHideMs = 4200) => {
      if (!message) {
        return;
      }

      let toast = document.getElementById("admissions-apply-toast");
      if (!toast) {
        toast = document.createElement("div");
        toast.id = "admissions-apply-toast";
        toast.setAttribute("role", "status");
        toast.setAttribute("aria-live", "polite");
        document.body.appendChild(toast);
      }

      const safeType = type === "error" ? "error" : type === "info" ? "info" : "success";
      toast.className = `portal-toast portal-toast--${safeType} portal-toast--center admissions-apply-toast`;
      toast.innerHTML = message;
      toast.hidden = false;
      window.clearTimeout(applyToastTimer);

      if (autoHideMs > 0) {
        applyToastTimer = window.setTimeout(() => {
          toast.hidden = true;
        }, autoHideMs);
      }
    };

    const setApplySubmitting = (isSubmitting) => {
      if (!submitButton) {
        return;
      }

      submitButton.disabled = Boolean(isSubmitting);
      submitButton.textContent = isSubmitting ? "Submitting..." : "Submit Application";
      submitButton.classList.toggle("is-loading", Boolean(isSubmitting));
    };

    const renderAdmissionFileSelection = (input) => {
      if (!input) {
        return;
      }

      const fieldBlock = input.closest(".auth-field-block");
      const selectionRow = fieldBlock?.querySelector("[data-apply-file-selection]");

      if (!selectionRow) {
        return;
      }

      const file = input.files?.[0] || null;
      if (!file) {
        selectionRow.hidden = true;
        selectionRow.innerHTML = "";
        return;
      }

      const fileName = String(file.name || "Selected document").trim() || "Selected document";
      const fileSize = Number(file.size || 0);
      const sizeLabel = fileSize ? formatFileSize(fileSize) : "";

      selectionRow.hidden = false;
      selectionRow.innerHTML = `
        <span>
          <strong>${escapeHtml(fileName)}</strong>
          ${sizeLabel ? `<small>${escapeHtml(sizeLabel)}</small>` : ""}
        </span>
        <button class="apply-file-remove" type="button" data-apply-file-remove="${escapeHtml(input.name || input.id || "")}" aria-label="Remove ${escapeHtml(fileName)}" title="Remove file">
          x
        </button>
      `;
    };

    const refreshAdmissionFileSelections = () => {
      fileUploadInputs.forEach((input) => renderAdmissionFileSelection(input));
    };

    const initAdmissionFileRemovers = () => {
      fileUploadInputs.forEach((input) => {
        const fieldBlock = input.closest(".auth-field-block");

        if (!fieldBlock || fieldBlock.querySelector("[data-apply-file-selection]")) {
          renderAdmissionFileSelection(input);
          return;
        }

        const selectionRow = document.createElement("div");
        selectionRow.className = "apply-file-selection";
        selectionRow.setAttribute("data-apply-file-selection", "");
        selectionRow.hidden = true;
        fieldBlock.appendChild(selectionRow);

        input.addEventListener("change", () => {
          const file = input.files?.[0] || null;
          if (file && Number(file.size || 0) > ADMISSION_FILE_SIZE_LIMIT_BYTES) {
            const message = getAdmissionFileSizeLimitMessage();
            input.value = "";
            renderAdmissionFileSelection(input);
            setStatus(status, "error", message);
            showApplyToast(
              "error",
              `<strong>File too large</strong><span>${escapeHtml(message)}</span>`,
              5200,
            );
            return;
          }

          renderAdmissionFileSelection(input);
        });
      });
    };

    const refreshPublicAdmissionClassOptions = () => {
      const admissionConfig = getPublicAdmissionConfigSummary();
      const activeClassNames = (admissionConfig?.activeClasses || [])
        .map((entry) => entry.name)
        .filter(Boolean);
      const classNames = activeClassNames.length ? activeClassNames : getConfiguredStudentLevelOptions();
      syncAdmissionClassFieldOptions(classNames, applyingClassSelect, {
        placeholder: "Select class applying for",
        emptyLabel: "No admission classes are open",
      });
    };

    const readFileName = (fieldName) => {
      const file = form.elements[fieldName]?.files?.[0];
      return file ? String(file.name || "").trim() : "";
    };

    const getPayload = () => {
      const firstName = String(form.elements.firstName?.value || "").trim();
      const middleName = String(form.elements.middleName?.value || "").trim();
      const lastName = String(form.elements.lastName?.value || "").trim();
      const fullName = [firstName, middleName, lastName].filter(Boolean).join(" ").trim();
      const academicClassApplyingFor = String(form.elements.academicClassApplyingFor?.value || "").trim();
      const studentEmail = String(form.elements.studentEmail?.value || form.elements.email?.value || "").trim();

      return {
        fullName,
        firstName,
        middleName,
        lastName,
        gender: String(form.elements.gender?.value || "").trim(),
        dateOfBirth: String(form.elements.dateOfBirth?.value || "").trim(),
        classApplyingFor: academicClassApplyingFor,
        previousSchool: String(form.elements.previousSchoolName?.value || "").trim(),
        passportPhotoName: readFileName("passportPhoto"),
        email: studentEmail,
        studentEmail,
        phone: String(form.elements.phone?.value || "").trim(),
        level: academicClassApplyingFor,
        guardianName: String(form.elements.guardianFullName?.value || "").trim(),
        guardianFullName: String(form.elements.guardianFullName?.value || "").trim(),
        guardianRelationship: String(form.elements.guardianRelationship?.value || "").trim(),
        guardianEmail: String(form.elements.guardianEmail?.value || "").trim(),
        guardianPhone: String(form.elements.guardianPhone?.value || "").trim(),
        guardianAddress: String(form.elements.guardianAddress?.value || "").trim(),
        guardianOccupation: String(form.elements.guardianOccupation?.value || "").trim(),
        lastClassAttended: String(form.elements.lastClassAttended?.value || "").trim(),
        academicClassApplyingFor,
        previousSchoolName: String(form.elements.previousSchoolName?.value || "").trim(),
        previousSchoolAddress: String(form.elements.previousSchoolAddress?.value || "").trim(),
        healthCondition: String(form.elements.healthCondition?.value || "").trim(),
        healthConditionDetails: String(form.elements.healthConditionDetails?.value || "").trim(),
        healthAllergies: String(form.elements.healthAllergies?.value || "").trim(),
        healthMedications: String(form.elements.healthMedications?.value || "").trim(),
        docPreviousReportName: readFileName("docPreviousReport"),
        docBirthCertificateName: readFileName("docBirthCertificate"),
        docPreviousSchoolResultName: readFileName("docPreviousSchoolResult"),
        docTransferCertificateName: readFileName("docTransferCertificate"),
        docOtherName: readFileName("docOther"),
        notes: String(form.elements.notes?.value || "").trim(),
        status: "pending",
        source: "public-apply",
      };
    };

    const toggleHealthConditionDetails = () => {
      if (!healthConditionSelect || !healthConditionDetailsWrap) {
        return;
      }

      const needsDetails = String(healthConditionSelect.value || "").trim().toLowerCase() === "yes";
      healthConditionDetailsWrap.hidden = !needsDetails;

      if (healthConditionDetailsInput) {
        healthConditionDetailsInput.toggleAttribute("required", needsDetails);
        if (!needsDetails) {
          healthConditionDetailsInput.value = "";
        }
      }
    };

    const renderReviewPanel = () => {
      if (!reviewPanel) {
        return;
      }

      const payload = getPayload();
      const documentNames = [
        payload.passportPhotoName,
        payload.docPreviousReportName,
        payload.docBirthCertificateName,
        payload.docPreviousSchoolResultName,
        payload.docTransferCertificateName,
        payload.docOtherName,
      ].filter(Boolean);

      reviewPanel.innerHTML = `
        <div class="admissions-review-group">
          <h4>Student Details</h4>
          <p><strong>Name:</strong> ${escapeHtml(payload.fullName || "—")}</p>
          <p><strong>Gender:</strong> ${escapeHtml(payload.gender || "—")}</p>
          <p><strong>Date of Birth:</strong> ${escapeHtml(payload.dateOfBirth || "—")}</p>
          <p><strong>Student Email:</strong> ${escapeHtml(payload.studentEmail || "—")}</p>
        </div>
        <div class="admissions-review-group">
          <h4>Parent/Guardian</h4>
          <p><strong>Full Name:</strong> ${escapeHtml(payload.guardianFullName || "—")}</p>
          <p><strong>Relationship:</strong> ${escapeHtml(payload.guardianRelationship || "—")}</p>
          <p><strong>Phone:</strong> ${escapeHtml(payload.guardianPhone || "—")}</p>
          <p><strong>Email:</strong> ${escapeHtml(payload.guardianEmail || "—")}</p>
          <p><strong>Address:</strong> ${escapeHtml(payload.guardianAddress || "—")}</p>
          <p><strong>Occupation:</strong> ${escapeHtml(payload.guardianOccupation || "—")}</p>
        </div>
        <div class="admissions-review-group">
          <h4>Academic Background</h4>
          <p><strong>Last Class Attended:</strong> ${escapeHtml(payload.lastClassAttended || "—")}</p>
          <p><strong>Class Applying For:</strong> ${escapeHtml(payload.academicClassApplyingFor || "—")}</p>
          <p><strong>Previous School Name:</strong> ${escapeHtml(payload.previousSchoolName || "—")}</p>
          <p><strong>Previous School Address:</strong> ${escapeHtml(payload.previousSchoolAddress || "—")}</p>
        </div>
        <div class="admissions-review-group">
          <h4>Health Information</h4>
          <p><strong>Existing Medical Condition:</strong> ${escapeHtml(payload.healthCondition || "—")}</p>
          <p><strong>Medical Condition Details:</strong> ${escapeHtml(payload.healthConditionDetails || "—")}</p>
          <p><strong>Allergies:</strong> ${escapeHtml(payload.healthAllergies || "—")}</p>
          <p><strong>Current Medications:</strong> ${escapeHtml(payload.healthMedications || "—")}</p>
        </div>
        <div class="admissions-review-group">
          <h4>Document Uploads</h4>
          <p>${escapeHtml(documentNames.join(", ") || "No documents selected.")}</p>
        </div>
      `;
    };

    const setStep = (index) => {
      if (!stepSections.length) {
        return;
      }

      const boundedIndex = Math.max(0, Math.min(index, stepSections.length - 1));
      activeStepIndex = boundedIndex;
      stepSections.forEach((section, sectionIndex) => {
        section.hidden = sectionIndex !== boundedIndex;
      });

      if (stepIndicator) {
        stepIndicator.textContent = `Section ${boundedIndex + 1} of ${stepSections.length}`;
      }

      if (boundedIndex === stepSections.length - 1) {
        renderReviewPanel();
      }
    };

    const validateStep = (stepIndex, focusStepOnError = true) => {
      const payload = getPayload();
      const workspaceId = lockedWorkspaceId;

      if (!workspaceId || workspaceId === "public") {
        setStatus(
          status,
          "error",
          "This application link is incomplete. Open the official school link/QR provided by the admin.",
        );
        return false;
      }

      if (stepIndex === 0) {
        if (!payload.firstName || !payload.lastName || !payload.gender || !payload.dateOfBirth) {
          setStatus(status, "error", "Complete all required fields in Section 1.");
          return false;
        }

        if (payload.studentEmail && !EMAIL_REGEX.test(payload.studentEmail)) {
          setStatus(status, "error", "Student email format is invalid.");
          return false;
        }
      }

      if (stepIndex === 1) {
        if (
          !payload.guardianFullName ||
          !payload.guardianRelationship ||
          !payload.guardianPhone ||
          !payload.guardianEmail ||
          !payload.guardianAddress ||
          !payload.guardianOccupation
        ) {
          setStatus(status, "error", "Complete all required fields in Section 2.");
          return false;
        }

        if (!EMAIL_REGEX.test(payload.guardianEmail)) {
          setStatus(status, "error", "Guardian email format is invalid.");
          return false;
        }
      }

      if (stepIndex === 2) {
        if (!payload.lastClassAttended || !payload.academicClassApplyingFor) {
          setStatus(status, "error", "Complete all required fields in Section 3.");
          return false;
        }
      }

      if (stepIndex === 3) {
        if (!payload.healthCondition) {
          setStatus(status, "error", "Select whether the student has an existing medical condition.");
          return false;
        }

        if (payload.healthCondition.toLowerCase() === "yes" && !payload.healthConditionDetails) {
          setStatus(status, "error", "List the existing medical condition(s) in Section 4.");
          return false;
        }
      }

      if (focusStepOnError) {
        setStatus(status, "", "");
      }

      return true;
    };

    form.addEventListener("input", () => {
      setStatus(status, "", "");
      if (activeStepIndex === stepSections.length - 1) {
        renderReviewPanel();
      }
    });

    form.addEventListener("change", () => {
      toggleHealthConditionDetails();
      refreshAdmissionFileSelections();
      if (activeStepIndex === stepSections.length - 1) {
        renderReviewPanel();
      }
    });

    form.addEventListener("click", (event) => {
      const removeButton = event.target.closest("[data-apply-file-remove]");

      if (!removeButton) {
        return;
      }

      const fieldName = String(removeButton.dataset.applyFileRemove || "").trim();
      const input = fileUploadInputs.find((entry) => entry.name === fieldName || entry.id === fieldName);

      if (!input) {
        return;
      }

      input.value = "";
      renderAdmissionFileSelection(input);
      setStatus(status, "", "");

      if (activeStepIndex === stepSections.length - 1) {
        renderReviewPanel();
      }
    });

    form.querySelectorAll("[data-admission-step-next]").forEach((button) => {
      button.addEventListener("click", () => {
        if (!validateStep(activeStepIndex, false)) {
          return;
        }
        setStep(activeStepIndex + 1);
      });
    });

    form.querySelectorAll("[data-admission-step-prev]").forEach((button) => {
      button.addEventListener("click", () => {
        setStep(activeStepIndex - 1);
      });
    });

    form.addEventListener("submit", async (event) => {
      event.preventDefault();

      if (activeStepIndex !== stepSections.length - 1) {
        if (validateStep(activeStepIndex, false)) {
          setStep(activeStepIndex + 1);
        }
        return;
      }

      for (let step = 0; step < stepSections.length - 1; step += 1) {
        if (!validateStep(step, false)) {
          const validationMessage = status.textContent || `Complete all required fields in Section ${step + 1}.`;
          setStep(step);
          showApplyToast(
            "error",
            `<strong>Check Section ${step + 1}</strong><span>${escapeHtml(validationMessage)}</span>`,
            5200,
          );
          return;
        }
      }

      const workspaceId = lockedWorkspaceId;
      const payload = getPayload();

      if (payload.studentEmail && !EMAIL_REGEX.test(payload.studentEmail)) {
        const message = "Student email format is invalid.";
        setStatus(status, "error", message);
        showApplyToast("error", `<strong>Cannot submit yet</strong><span>${escapeHtml(message)}</span>`, 5200);
        return;
      }

      if (!EMAIL_REGEX.test(payload.guardianEmail)) {
        const message = "Guardian email format is invalid.";
        setStatus(status, "error", message);
        showApplyToast("error", `<strong>Cannot submit yet</strong><span>${escapeHtml(message)}</span>`, 5200);
        return;
      }

      payload.level = payload.classApplyingFor || payload.academicClassApplyingFor;
      const admissionConfig = getPublicAdmissionConfigSummary();
      const openAdmissionSession = admissionConfig?.openSession || null;
      const firstActiveStage = (admissionConfig?.activeStages || [])[0] || null;
      payload.admissionSessionId = openAdmissionSession?.id || "";
      payload.admissionSessionName = openAdmissionSession?.name || "";
      payload.applicationStage = firstActiveStage?.name || "Submitted";

      setApplySubmitting(true);
      setStatus(status, "info", "Submitting application...");
      showApplyToast(
        "info",
        "<strong>Submitting application</strong><span>Please wait while we send it to the school.</span>",
        0,
      );

      try {
        Object.assign(payload, await collectAdmissionFormFiles(form, ADMISSION_FILE_FIELDS));

        let savedPayload = payload;

        if (isSupabaseConfigured()) {
          const remoteSubmitResult = await submitPublicAdmissionToSupabase({
            workspaceId,
            institutionId: lockedInstitutionId,
            payload,
          });

          if (!remoteSubmitResult.ok) {
            const message = remoteSubmitResult.message || "Could not submit application.";
            setStatus(status, "error", escapeHtml(message));
            showApplyToast("error", `<strong>Submission failed</strong><span>${escapeHtml(message)}</span>`, 6200);
            return;
          }

          if (remoteSubmitResult.record && typeof remoteSubmitResult.record === "object") {
            savedPayload = {
              ...payload,
              ...remoteSubmitResult.record,
            };
          }
        }

        const admissions = upsertAdmission(savedPayload, workspaceId);
        const latest = admissions[0] || savedPayload;
        pushNotification(
          {
            title: `New application: ${savedPayload.fullName}`,
            message: `${savedPayload.level} application submitted by guardian ${savedPayload.guardianFullName}.`,
            entityType: "admission-application",
            entityId: latest.id || "",
            action: "submitted",
            visibleToRoles: ["Admin"],
          },
          workspaceId,
        );

        const successMessage = `Application submitted successfully for <strong>${escapeHtml(savedPayload.fullName)}</strong>. The school admin will review and update the status.`;
        form.reset();
        workspaceInput.value = workspaceId;
        toggleHealthConditionDetails();
        refreshAdmissionFileSelections();
        refreshPublicAdmissionClassOptions();
        setStep(0);
        clearFormDraftFor(form);
        setStatus(status, "success", successMessage);
        showApplyToast("success", `<strong>Application submitted</strong><span>${escapeHtml(savedPayload.fullName)} has been sent to the school.</span>`, 5200);
      } catch (error) {
        const errorMessage =
          String(error?.message || "") === "admission_file_too_large"
            ? getAdmissionFileSizeLimitMessage()
            : String(error?.name || "").toLowerCase().includes("quota") ||
                String(error?.message || "").toLowerCase().includes("quota")
              ? "The uploaded files are too large for this browser. Reduce the file sizes and try again."
              : "Could not submit application. Please try again.";
        setStatus(status, "error", escapeHtml(errorMessage));
        showApplyToast("error", `<strong>Submission failed</strong><span>${escapeHtml(errorMessage)}</span>`, 6200);
      } finally {
        setApplySubmitting(false);
      }
    });

    toggleHealthConditionDetails();
    initAdmissionFileRemovers();
    refreshAdmissionFileSelections();
    refreshPublicAdmissionClassOptions();
    if (admissionConfigManager?.eventName) {
      window.addEventListener(admissionConfigManager.eventName, refreshPublicAdmissionClassOptions);
    }
    setStep(0);

    if (!lockedWorkspaceId) {
      setStatus(
        status,
        "info",
        "Open this form using the school-provided application link or QR so the workspace is auto-selected.",
      );
    }
  }

  function renderTeacherAttendanceWorkspace(target, user) {
    if (!target) {
      return;
    }

    const manager = getAttendanceManager();
    const assignedClasses = getTeacherAssignedClasses(user);
    const selectedDate = target.dataset.attendanceDate || getTodayDateValue();
    const flashMessage = target.dataset.attendanceFlash || "";
    delete target.dataset.attendanceFlash;
    const selectedClassId = assignedClasses.some((classRecord) => classRecord.id === target.dataset.attendanceClassId)
      ? target.dataset.attendanceClassId
      : assignedClasses[0]?.id || "";
    const selectedClass = assignedClasses.find((classRecord) => classRecord.id === selectedClassId) || null;
    const roster = selectedClass ? getActiveStudentsForClass(selectedClass) : [];
    const existingRecord =
      manager && selectedClass && typeof manager.getRecordForClassDate === "function"
        ? manager.getRecordForClassDate(selectedClass.id, selectedDate)
        : null;
    const attendanceDraftKey = selectedClass
      ? `teacher-attendance:${user.id || user.email || "teacher"}:${selectedClass.id}:${selectedDate}`
      : "";
    const attendanceDraft = readFormDraft(attendanceDraftKey);
    const draftEntries = Array.isArray(attendanceDraft?.entries)
      ? getAttendanceRecordEntryMap({ entries: attendanceDraft.entries })
      : new Map();
    const existingEntries = draftEntries.size ? draftEntries : getAttendanceRecordEntryMap(existingRecord);
    const submittedCount = existingRecord?.entries?.length || 0;
    const markedLabel = selectedClass
      ? `${submittedCount || 0}/${roster.length || 0}`
      : "0/0";

    target.hidden = false;
    target.dataset.attendanceDate = selectedDate;
    target.dataset.attendanceClassId = selectedClassId;

    if (!manager) {
      target.innerHTML = `
        <article class="admin-surface-card">
          <div class="admin-surface-head">
            <h2>Class Attendance</h2>
            <span>Unavailable</span>
          </div>
          <article class="portal-class-empty">
            <strong>Attendance tools unavailable</strong>
            <p>The attendance manager could not be loaded on this page.</p>
          </article>
        </article>
      `;
      return;
    }

    target.innerHTML = `
      <article class="admin-surface-card teacher-attendance-card">
        <div class="admin-surface-head">
          <div>
            <h2>Class Attendance</h2>
            <span>Take attendance for classes assigned to you.</span>
          </div>
          <span class="portal-class-status ${existingRecord ? "is-active" : "is-pending"}">
            ${existingRecord ? "Submitted" : "Not submitted"}
          </span>
        </div>

        <div class="portal-class-summary teacher-attendance-summary">
          <article class="portal-class-stat portal-class-stat-blue">
            <span>Assigned classes</span>
            <strong>${assignedClasses.length}</strong>
            <p>Classes where you are class teacher, subject teacher, or course teacher.</p>
          </article>
          <article class="portal-class-stat portal-class-stat-green">
            <span>Marked today</span>
            <strong>${escapeHtml(markedLabel)}</strong>
            <p>${selectedClass ? escapeHtml(getClassDisplayName(selectedClass)) : "Select a class to start."}</p>
          </article>
          <article class="portal-class-stat portal-class-stat-amber">
            <span>Register date</span>
            <strong>${escapeHtml(selectedDate)}</strong>
            <p>${existingRecord ? `Last submitted ${escapeHtml(formatTimestamp(existingRecord.takenAt))}` : "No register saved for this date yet."}</p>
          </article>
        </div>

        <div class="attendance-toolbar">
          <label class="portal-field" for="teacher-attendance-date">
            <span>Date</span>
            <input id="teacher-attendance-date" type="date" value="${escapeHtml(selectedDate)}" data-teacher-attendance-date />
          </label>
          <label class="portal-field" for="teacher-attendance-class">
            <span>Class</span>
            <select id="teacher-attendance-class" data-teacher-attendance-class>
              ${
                assignedClasses.length
                  ? assignedClasses
                      .map(
                        (classRecord) => `
                          <option value="${escapeHtml(classRecord.id)}" ${classRecord.id === selectedClassId ? "selected" : ""}>
                            ${escapeHtml(getClassDisplayName(classRecord))}
                          </option>
                        `,
                      )
                      .join("")
                  : `<option value="">No assigned classes</option>`
              }
            </select>
          </label>
          <div class="attendance-toolbar-actions">
            <button class="portal-class-button" type="button" data-attendance-mark-all ${roster.length ? "" : "disabled"}>
              Mark all present
            </button>
          </div>
        </div>

        <form class="teacher-attendance-form" data-teacher-attendance-form>
          ${
            selectedClass && roster.length
              ? `
                <div class="teacher-attendance-list">
                  ${roster
                    .map((student) => {
                      const existing = existingEntries.get(student.id) || {};
                      const selectedStatus = normalizeAttendanceStatus(existing.status || "present");
                      return `
                        <article class="attendance-student-row" data-attendance-student-row data-student-id="${escapeHtml(student.id)}">
                          <div class="attendance-student-main">
                            <strong>${escapeHtml(student.fullName)}</strong>
                            <span>${escapeHtml(student.admissionNo || "No admission no.")} • ${escapeHtml(student.level || selectedClass.level)}</span>
                          </div>
                          <div class="attendance-status-picker" role="radiogroup" aria-label="Attendance status for ${escapeHtml(student.fullName)}">
                            ${ATTENDANCE_STATUSES.map(
                              (status) => `
                                <label class="attendance-status-option ${status === selectedStatus ? "is-selected" : ""} ${getAttendanceStatusClass(status)}">
                                  <input type="radio" name="attendance-${escapeHtml(student.id)}" value="${escapeHtml(status)}" ${
                                    status === selectedStatus ? "checked" : ""
                                  } />
                                  <span>${escapeHtml(getAttendanceStatusLabel(status))}</span>
                                </label>
                              `,
                            ).join("")}
                          </div>
                          <input class="attendance-note-input" type="text" placeholder="Optional note" value="${escapeHtml(existing.note || "")}" data-attendance-note />
                        </article>
                      `;
                    })
                    .join("")}
                </div>
                <div class="attendance-submit-row">
                  <p id="teacher-attendance-status" class="auth-status" aria-live="polite" hidden></p>
                  <button class="portal-class-button is-restore" type="submit">
                    ${existingRecord ? "Update attendance" : "Submit attendance"}
                  </button>
                </div>
              `
              : `
                <article class="portal-class-empty">
                  <strong>${selectedClass ? "No enrolled students found" : "No class assigned yet"}</strong>
                  <p>${
                    selectedClass
                      ? "Add students to this class level from Student Management before taking attendance."
                      : "Ask an admin to assign you as class teacher, subject teacher, or course teacher."
                  }</p>
                </article>
              `
          }
        </form>
      </article>
    `;

    const dateInput = target.querySelector("[data-teacher-attendance-date]");
    const classSelect = target.querySelector("[data-teacher-attendance-class]");
    const form = target.querySelector("[data-teacher-attendance-form]");
    const statusTarget = target.querySelector("#teacher-attendance-status");

    if (flashMessage && statusTarget) {
      setStatus(statusTarget, "success", flashMessage);
    }

    if (dateInput instanceof HTMLInputElement) {
      dateInput.addEventListener("change", () => {
        target.dataset.attendanceDate = dateInput.value || getTodayDateValue();
        renderTeacherAttendanceWorkspace(target, user);
      });
    }

    if (classSelect instanceof HTMLSelectElement) {
      classSelect.addEventListener("change", () => {
        target.dataset.attendanceClassId = classSelect.value;
        renderTeacherAttendanceWorkspace(target, user);
      });
    }

    target.querySelectorAll(".attendance-status-option input").forEach((input) => {
      input.addEventListener("change", () => {
        const picker = input.closest(".attendance-status-picker");
        picker?.querySelectorAll(".attendance-status-option").forEach((label) => {
          label.classList.toggle("is-selected", label.contains(input) && input.checked);
        });
      });
    });

    const markAllButton = target.querySelector("[data-attendance-mark-all]");
    if (markAllButton) {
      markAllButton.addEventListener("click", () => {
        target.querySelectorAll('.attendance-status-option input[value="present"]').forEach((input) => {
          if (input instanceof HTMLInputElement) {
            input.checked = true;
            input.dispatchEvent(new Event("change", { bubbles: true }));
          }
        });
      });
    }

    if (form && selectedClass) {
      const persistAttendanceDraft = () => {
        const studentLookup = new Map(roster.map((student) => [student.id, student]));
        const entries = Array.from(form.querySelectorAll("[data-attendance-student-row]"))
          .map((row) => {
            const studentId = String(row.dataset.studentId || "").trim();
            const student = studentLookup.get(studentId);
            const checked = row.querySelector('input[type="radio"]:checked');

            if (!student || !(checked instanceof HTMLInputElement)) {
              return null;
            }

            return {
              studentId,
              status: normalizeAttendanceStatus(checked.value),
              note: row.querySelector("[data-attendance-note]")?.value || "",
            };
          })
          .filter(Boolean);

        writeFormDraft(attendanceDraftKey, {
          classId: selectedClass.id,
          date: selectedDate,
          entries,
          updatedAt: nowIso(),
        });
      };

      form.addEventListener("input", persistAttendanceDraft);
      form.addEventListener("change", persistAttendanceDraft);
      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const studentLookup = new Map(roster.map((student) => [student.id, student]));
        const entries = Array.from(form.querySelectorAll("[data-attendance-student-row]"))
          .map((row) => {
            const studentId = String(row.dataset.studentId || "").trim();
            const student = studentLookup.get(studentId);
            const checked = row.querySelector('input[type="radio"]:checked');
            const note = row.querySelector("[data-attendance-note]")?.value || "";

            if (!student || !(checked instanceof HTMLInputElement)) {
              return null;
            }

            return {
              studentId: student.id,
              studentName: student.fullName,
              admissionNo: student.admissionNo,
              status: normalizeAttendanceStatus(checked.value),
              note,
            };
          })
          .filter(Boolean);

        if (!entries.length) {
          setStatus(statusTarget, "error", "No student rows are available for this class.");
          return;
        }

        const cycleManager = getAcademicCycleManager();
        const cycleState =
          cycleManager && typeof cycleManager.getState === "function"
            ? cycleManager.getState()
            : { sessions: [], terms: [] };
        const academicTerm = getAttendanceAcademicTermForDate(cycleState, selectedDate);
        const savedRecords = manager.upsertRecord({
          id: existingRecord?.id,
          date: selectedDate,
          classId: selectedClass.id,
          sessionId: existingRecord?.sessionId || academicTerm?.sessionId || "",
          termId: existingRecord?.termId || academicTerm?.id || "",
          className: getClassDisplayName(selectedClass),
          level: selectedClass.level,
          submittedById: user.id,
          submittedByEmail: user.email,
          submittedByName: user.displayName || user.email,
          entries,
        });
        const savedRecord =
          savedRecords.find((record) => record.classId === selectedClass.id && record.date === selectedDate) || null;

        syncAttendanceAbsenceNotifications(savedRecord, user.workspaceId || getCurrentWorkspaceId());
        clearFormDraft(attendanceDraftKey);

        recordAuditEvent({
          action: existingRecord ? "updated" : "submitted",
          entityType: "attendance",
          entityId: savedRecord?.id || selectedClass.id,
          summary: `${existingRecord ? "Updated" : "Submitted"} attendance for ${getClassDisplayName(selectedClass)}`,
          details: `${entries.length} student${entries.length === 1 ? "" : "s"} marked by ${
            user.displayName || user.email
          }`,
        });

        target.dataset.attendanceFlash = `Attendance saved for <strong>${escapeHtml(getClassDisplayName(selectedClass))}</strong>.`;
        renderTeacherAttendanceWorkspace(target, user);
      });
    }
  }

  function initAttendanceReviewControls({
    isAdmin,
    manager,
    summaryTarget,
    statusTarget,
    listTarget,
    submissionTarget,
    viewSelect,
    dateInput,
    termSelect,
    classSelect,
    studentSelect,
    statusSelect,
    searchInput,
    dateWrap,
    termWrap,
    statusWrap,
    reviewCopyTarget,
    submissionCopyTarget,
  }) {
    if (!summaryTarget || !listTarget || !submissionTarget) {
      return;
    }

    const classManager = getClassManager();
    const studentManager = getStudentManager();
    const academicCycleManager = getAcademicCycleManager();
    const getClasses = () =>
      classManager && typeof classManager.getClasses === "function"
        ? classManager.getClasses().filter((record) => record.status !== "archived")
        : [];
    const getStudents = () =>
      studentManager && typeof studentManager.getStudents === "function"
        ? studentManager.getStudents().filter((student) => student.status === "active")
        : [];
    const getCycleState = () =>
      academicCycleManager && typeof academicCycleManager.getState === "function"
        ? academicCycleManager.getState()
        : { sessions: [], terms: [] };

    if (dateInput instanceof HTMLInputElement && !dateInput.value) {
      dateInput.value = getTodayDateValue();
    }

    const getState = () => ({
      view: viewSelect instanceof HTMLSelectElement && viewSelect.value === "term" ? "term" : "daily",
      date: dateInput instanceof HTMLInputElement ? dateInput.value || getTodayDateValue() : getTodayDateValue(),
      termId: termSelect instanceof HTMLSelectElement ? termSelect.value : "",
      classId: classSelect instanceof HTMLSelectElement ? classSelect.value || "all" : "all",
      studentId: studentSelect instanceof HTMLSelectElement ? studentSelect.value || "all" : "all",
      status: statusSelect instanceof HTMLSelectElement ? statusSelect.value || "all" : "all",
      search: searchInput instanceof HTMLInputElement ? searchInput.value.trim().toLowerCase() : "",
    });

    const render = () => {
      if (!manager || typeof manager.getRecords !== "function") {
        summaryTarget.innerHTML = "";
        listTarget.innerHTML = `
          <article class="portal-class-empty">
            <strong>Attendance tools unavailable</strong>
            <p>The attendance manager could not be loaded on this page.</p>
          </article>
        `;
        submissionTarget.innerHTML = "";
        return;
      }

      if (!isAdmin) {
        summaryTarget.innerHTML = "";
        listTarget.innerHTML = `
          <article class="portal-class-empty">
            <strong>Admin access required</strong>
            <p>Only administrators can review attendance for all enrolled students.</p>
          </article>
        `;
        submissionTarget.innerHTML = "";
        setStatus(statusTarget, "info", "Teachers can take attendance from their dashboard. Admin review is restricted to administrators.");
        return;
      }

      const state = getState();
      const cycleState = getCycleState();
      const terms = (cycleState.terms || [])
        .slice()
        .sort((left, right) => {
          const startDateComparison = String(right.startDate || "").localeCompare(String(left.startDate || ""));
          if (startDateComparison) {
            return startDateComparison;
          }
          return String(right.createdAt || "").localeCompare(String(left.createdAt || ""));
        });
      const openTerm = terms.find((term) => term.status === "open") || null;

      if (dateWrap instanceof HTMLElement) {
        dateWrap.hidden = state.view !== "daily";
      }
      if (termWrap instanceof HTMLElement) {
        termWrap.hidden = state.view !== "term";
      }
      if (statusWrap instanceof HTMLElement) {
        statusWrap.hidden = state.view !== "daily";
      }
      if (searchInput instanceof HTMLInputElement) {
        searchInput.placeholder =
          state.view === "term"
            ? "Student or admission no..."
            : "Student, admission no, teacher...";
      }

      if (termSelect instanceof HTMLSelectElement) {
        const previousValue = terms.some((term) => term.id === state.termId)
          ? state.termId
          : openTerm?.id || terms[0]?.id || "";
        const sessions = (cycleState.sessions || []).slice().sort((left, right) => {
          const startDateComparison = String(right.startDate || "").localeCompare(String(left.startDate || ""));
          if (startDateComparison) {
            return startDateComparison;
          }
          return String(right.createdAt || "").localeCompare(String(left.createdAt || ""));
        });

        termSelect.innerHTML = `
          <option value="">${terms.length ? "Select term or semester" : "No terms or semesters configured"}</option>
          ${sessions
            .map((session) => {
              const sessionTerms = terms.filter((term) => term.sessionId === session.id);
              if (!sessionTerms.length) {
                return "";
              }
              return `
                <optgroup label="${escapeHtml(session.name)}">
                  ${sessionTerms
                    .map((term) => {
                      const periodLabel = term.periodType === "semester" ? "Semester" : "Term";
                      return `<option value="${escapeHtml(term.id)}">${escapeHtml(
                        `${periodLabel}: ${term.name}${term.status === "open" ? " (Open)" : ""}`,
                      )}</option>`;
                    })
                    .join("")}
                </optgroup>
              `;
            })
            .join("")}
        `;
        termSelect.value = previousValue;
        termSelect.disabled = !terms.length;
        state.termId = previousValue;
      }

      const classes = getClasses();
      const allStudents = getStudents();

      if (classSelect instanceof HTMLSelectElement) {
        const previousValue = state.classId;
        classSelect.innerHTML = `
          <option value="all">All classes</option>
          ${classes
            .map(
              (classRecord) => `
                <option value="${escapeHtml(classRecord.id)}" ${classRecord.id === previousValue ? "selected" : ""}>
                  ${escapeHtml(getClassDisplayName(classRecord))}
                </option>
              `,
            )
            .join("")}
        `;
        if (!classes.some((classRecord) => classRecord.id === previousValue)) {
          classSelect.value = "all";
          state.classId = "all";
        }
      }

      const selectedClass = classes.find((classRecord) => classRecord.id === state.classId) || null;
      const studentsForClass = selectedClass ? getActiveStudentsForClass(selectedClass) : allStudents;

      if (studentSelect instanceof HTMLSelectElement) {
        const previousValue = studentsForClass.some((student) => student.id === state.studentId)
          ? state.studentId
          : "all";
        studentSelect.innerHTML = `
          <option value="all">All students</option>
          ${studentsForClass
            .slice()
            .sort((left, right) => String(left.fullName || "").localeCompare(String(right.fullName || "")))
            .map(
              (student) => `
                <option value="${escapeHtml(student.id)}">${escapeHtml(student.fullName)}${
                  student.admissionNo ? ` (${escapeHtml(student.admissionNo)})` : ""
                }</option>
              `,
            )
            .join("")}
        `;
        studentSelect.value = previousValue;
        state.studentId = previousValue;
      }

      const selectedStudent = studentsForClass.find((student) => student.id === state.studentId) || null;
      const studentsInView = selectedStudent ? [selectedStudent] : studentsForClass;
      const selectedTerm = terms.find((term) => term.id === state.termId) || null;
      const periodLabel = selectedTerm
        ? `${getSessionLabelFromCycle(cycleState, selectedTerm.sessionId)} • ${getTermLabelFromCycle(cycleState, selectedTerm.id)}`
        : "";
      const allRecords = manager.getRecords();

      if (state.view === "term" && !selectedTerm) {
        if (reviewCopyTarget) {
          reviewCopyTarget.textContent = "Select a term or semester to review attendance";
        }
        if (submissionCopyTarget) {
          submissionCopyTarget.textContent = "No academic period selected";
        }
        summaryTarget.innerHTML = "";
        listTarget.innerHTML = `
          <article class="portal-class-empty">
            <strong>No term or semester selected</strong>
            <p>Create an academic period in Settings, then return to review its attendance report.</p>
          </article>
        `;
        submissionTarget.innerHTML = "";
        setStatus(
          statusTarget,
          "info",
          `Add a term or semester under <a href="./admin-settings-academic.html">Settings &gt; Sessions and Terms</a> to review attendance by academic period.`,
        );
        return;
      }

      const recordsForView =
        state.view === "term"
          ? allRecords.filter((record) => attendanceRecordMatchesAcademicTerm(record, selectedTerm, cycleState))
          : allRecords.filter((record) => record.date === state.date);
      const scopedRecords = selectedClass
        ? recordsForView.filter((record) => record.classId === selectedClass.id)
        : recordsForView;
      const reportRecords = selectedStudent
        ? scopedRecords.filter((record) => (record.entries || []).some((entry) => entry.studentId === selectedStudent.id))
        : scopedRecords;

      if (reviewCopyTarget) {
        reviewCopyTarget.textContent =
          state.view === "term"
            ? `Aggregated attendance for ${periodLabel}`
            : `All enrolled students for ${state.date}`;
      }
      if (submissionCopyTarget) {
        submissionCopyTarget.textContent =
          state.view === "term"
            ? `Registers included in ${periodLabel}`
            : `Registers submitted for ${state.date}`;
      }

      if (state.view === "term") {
        const summary = summarizeAttendancePeriodForStudents(studentsInView, reportRecords);
        const rateDenominator = summary.counts.present + summary.counts.late + summary.counts.absent;
        const rate = rateDenominator
          ? Math.round(((summary.counts.present + summary.counts.late) / rateDenominator) * 100)
          : null;
        const registerDays = new Set(reportRecords.map((record) => record.date).filter(Boolean)).size;

        summaryTarget.innerHTML = `
          <article class="portal-class-stat portal-class-stat-blue">
            <span>Students in view</span>
            <strong>${studentsInView.length}</strong>
            <p>${selectedStudent ? escapeHtml(selectedStudent.fullName) : selectedClass ? escapeHtml(getClassDisplayName(selectedClass)) : "Active students across all classes."}</p>
          </article>
          <article class="portal-class-stat portal-class-stat-violet">
            <span>Register days</span>
            <strong>${registerDays}</strong>
            <p>${escapeHtml(periodLabel)}</p>
          </article>
          <article class="portal-class-stat portal-class-stat-green">
            <span>Attendance rate</span>
            <strong>${rate === null ? "—" : `${rate}%`}</strong>
            <p>Present and late marks against recorded attendance.</p>
          </article>
          <article class="portal-class-stat portal-class-stat-rose">
            <span>Absent marks</span>
            <strong>${summary.counts.absent || 0}</strong>
            <p>Absences recorded in this period.</p>
          </article>
          <article class="portal-class-stat portal-class-stat-amber">
            <span>Late marks</span>
            <strong>${summary.counts.late || 0}</strong>
            <p>Late arrivals recorded in this period.</p>
          </article>
          <article class="portal-class-stat portal-class-stat-slate">
            <span>Excused marks</span>
            <strong>${summary.counts.excused || 0}</strong>
            <p>Excused attendance records in this period.</p>
          </article>
        `;

        const filteredRows = summary.rows.filter(({ student }) => {
          if (!state.search) {
            return true;
          }
          return [student.fullName, student.admissionNo, student.level]
            .filter(Boolean)
            .join(" ")
            .toLowerCase()
            .includes(state.search);
        });

        if (!filteredRows.length) {
          listTarget.innerHTML = `
            <article class="portal-class-empty">
              <strong>No student attendance rows match this report</strong>
              <p>Try another term, class, student, or search keyword.</p>
            </article>
          `;
        } else {
          const groupedRows = filteredRows.reduce((groups, row) => {
            const level = row.student.level || "Unassigned";
            if (!groups.has(level)) {
              groups.set(level, []);
            }
            groups.get(level).push(row);
            return groups;
          }, new Map());

          listTarget.innerHTML = Array.from(groupedRows.entries())
            .sort(([left], [right]) => left.localeCompare(right, undefined, { numeric: true }))
            .map(
              ([level, rows]) => `
                <section class="attendance-review-group">
                  <header class="attendance-review-group-head">
                    <strong>${escapeHtml(level)}</strong>
                    <span>${rows.length} student${rows.length === 1 ? "" : "s"}</span>
                  </header>
                  <div class="attendance-review-table">
                    ${rows
                      .map(({ student, counts, recordedDays, attendanceRate, lastEntry }) => {
                        const rateChipClass =
                          attendanceRate === null
                            ? "is-unmarked"
                            : attendanceRate >= 80
                              ? "is-present"
                              : attendanceRate >= 60
                                ? "is-late"
                                : "is-absent";
                        return `
                          <article class="attendance-review-row attendance-term-review-row">
                            <div class="attendance-review-student">
                              <strong>${escapeHtml(student.fullName)}</strong>
                              <span>${escapeHtml(student.admissionNo || "No admission no.")} • Last recorded ${escapeHtml(lastEntry?.date || "Not yet")}</span>
                            </div>
                            <div class="attendance-review-meta"><span>Recorded days</span><strong>${recordedDays}</strong></div>
                            <div class="attendance-review-meta"><span>Present</span><strong>${counts.present}</strong></div>
                            <div class="attendance-review-meta"><span>Late</span><strong>${counts.late}</strong></div>
                            <div class="attendance-review-meta"><span>Absent</span><strong>${counts.absent}</strong></div>
                            <div class="attendance-review-meta"><span>Excused</span><strong>${counts.excused}</strong></div>
                            <span class="attendance-chip ${rateChipClass}">${attendanceRate === null ? "—" : `${attendanceRate}%`}</span>
                          </article>
                        `;
                      })
                      .join("")}
                  </div>
                </section>
              `,
            )
            .join("");
        }
      } else {
        const summary = summarizeAttendanceForStudents(studentsInView, reportRecords);
        const rate = studentsInView.length
          ? Math.round(((summary.counts.present + summary.counts.late) / studentsInView.length) * 100)
          : null;
        const submittedClassIds = new Set(recordsForView.map((record) => record.classId));
        const classesWithStudents = classes.filter((classRecord) => getActiveStudentsForClass(classRecord).length > 0);
        const missingClasses = selectedStudent
          ? reportRecords.length
            ? 0
            : 1
          : selectedClass
            ? getActiveStudentsForClass(selectedClass).length && !submittedClassIds.has(selectedClass.id)
              ? 1
              : 0
            : classesWithStudents.filter((classRecord) => !submittedClassIds.has(classRecord.id)).length;

        summaryTarget.innerHTML = `
          <article class="portal-class-stat portal-class-stat-blue">
            <span>Students in view</span>
            <strong>${studentsInView.length}</strong>
            <p>${selectedStudent ? escapeHtml(selectedStudent.fullName) : selectedClass ? escapeHtml(getClassDisplayName(selectedClass)) : "Active students across all classes."}</p>
          </article>
          <article class="portal-class-stat portal-class-stat-green">
            <span>Attendance rate</span>
            <strong>${rate === null ? "—" : `${rate}%`}</strong>
            <p>Present and late marks against active enrolment.</p>
          </article>
          <article class="portal-class-stat portal-class-stat-rose">
            <span>Absent</span>
            <strong>${summary.counts.absent || 0}</strong>
            <p>Students marked absent on ${escapeHtml(state.date)}.</p>
          </article>
          <article class="portal-class-stat portal-class-stat-amber">
            <span>Late</span>
            <strong>${summary.counts.late || 0}</strong>
            <p>Students marked late by teachers.</p>
          </article>
          <article class="portal-class-stat portal-class-stat-slate">
            <span>Unmarked</span>
            <strong>${summary.counts.unmarked || 0}</strong>
            <p>Students without a saved mark.</p>
          </article>
          <article class="portal-class-stat portal-class-stat-violet">
            <span>Missing registers</span>
            <strong>${missingClasses}</strong>
            <p>Classes with enrolled students and no teacher submission.</p>
          </article>
        `;

        const filteredRows = summary.rows.filter(({ student, entry, status }) => {
          if (state.status !== "all" && status !== state.status) {
            return false;
          }

          if (!state.search) {
            return true;
          }

          return [
            student.fullName,
            student.admissionNo,
            student.level,
            status,
            entry?.submittedByName,
            entry?.submittedByEmail,
            entry?.note,
          ]
            .filter(Boolean)
            .join(" ")
            .toLowerCase()
            .includes(state.search);
        });

        if (!filteredRows.length) {
          listTarget.innerHTML = `
            <article class="portal-class-empty">
              <strong>No attendance rows match this view</strong>
              <p>Try another date, class, student, status, or search keyword.</p>
            </article>
          `;
        } else {
          const groupedRows = filteredRows.reduce((groups, row) => {
            const level = row.student.level || "Unassigned";
            if (!groups.has(level)) {
              groups.set(level, []);
            }
            groups.get(level).push(row);
            return groups;
          }, new Map());

          listTarget.innerHTML = Array.from(groupedRows.entries())
            .sort(([left], [right]) => left.localeCompare(right, undefined, { numeric: true }))
            .map(
              ([level, rows]) => `
                <section class="attendance-review-group">
                  <header class="attendance-review-group-head">
                    <strong>${escapeHtml(level)}</strong>
                    <span>${rows.length} student${rows.length === 1 ? "" : "s"}</span>
                  </header>
                  <div class="attendance-review-table">
                    ${rows
                      .map(({ student, entry, status }) => {
                        const chipClass = status === "unmarked" ? "is-unmarked" : getAttendanceStatusClass(status);
                        const label = status === "unmarked" ? "Unmarked" : getAttendanceStatusLabel(status);
                        return `
                          <article class="attendance-review-row">
                            <div class="attendance-review-student">
                              <strong>${escapeHtml(student.fullName)}</strong>
                              <span>${escapeHtml(student.admissionNo || "No admission no.")}</span>
                            </div>
                            <span class="attendance-chip ${chipClass}">${escapeHtml(label)}</span>
                            <div class="attendance-review-meta">
                              <span>Teacher</span>
                              <strong>${escapeHtml(entry?.submittedByName || entry?.submittedByEmail || "No submission")}</strong>
                            </div>
                            <div class="attendance-review-meta">
                              <span>Submitted</span>
                              <strong>${entry?.takenAt ? escapeHtml(formatTimestamp(entry.takenAt)) : "Not yet"}</strong>
                            </div>
                            <div class="attendance-review-note">
                              ${escapeHtml(entry?.note || "No note")}
                            </div>
                          </article>
                        `;
                      })
                      .join("")}
                  </div>
                </section>
              `,
            )
            .join("");
        }
      }

      const submissionRecords = reportRecords
        .slice()
        .sort((left, right) => {
          return new Date(right.takenAt || right.updatedAt).getTime() - new Date(left.takenAt || left.updatedAt).getTime();
        });

      submissionTarget.innerHTML = submissionRecords.length
        ? submissionRecords
            .map((record) => {
              const counts = (record.entries || []).reduce(
                (sum, entry) => {
                  const status = normalizeAttendanceStatus(entry.status);
                  sum[status] += 1;
                  return sum;
                },
                { present: 0, absent: 0, late: 0, excused: 0 },
              );

              return `
                <article class="attendance-submission-row">
                  <div>
                    <strong>${escapeHtml(record.className || record.level || "Class")}</strong>
                    <span>${escapeHtml(record.submittedByName || record.submittedByEmail || "Unknown teacher")} • ${escapeHtml(record.date || "Date not set")}</span>
                  </div>
                  <div class="attendance-submission-counts">
                    <span class="attendance-chip is-present">${counts.present}</span>
                    <span class="attendance-chip is-absent">${counts.absent}</span>
                    <span class="attendance-chip is-late">${counts.late}</span>
                    <span class="attendance-chip is-excused">${counts.excused}</span>
                  </div>
                  <small>${escapeHtml(formatTimestamp(record.takenAt || record.updatedAt))}</small>
                </article>
              `;
            })
            .join("")
        : `
          <article class="portal-class-empty">
            <strong>No teacher submissions yet</strong>
            <p>Submitted class registers will appear here immediately.</p>
          </article>
        `;

      setStatus(
        statusTarget,
        reportRecords.length ? "success" : "info",
        reportRecords.length
          ? `${reportRecords.length} register${reportRecords.length === 1 ? "" : "s"} included in ${
              state.view === "term" ? escapeHtml(periodLabel) : escapeHtml(state.date)
            }.`
          : `No attendance registers found for ${
              state.view === "term" ? escapeHtml(periodLabel) : escapeHtml(state.date)
            }.`,
      );
    };

    [viewSelect, dateInput, termSelect, classSelect, studentSelect, statusSelect, searchInput].forEach((control) => {
      if (!control) {
        return;
      }
      const eventName = control instanceof HTMLInputElement && control.type === "search" ? "input" : "change";
      control.addEventListener(eventName, render);
    });

    if (manager?.eventName) {
      window.addEventListener(manager.eventName, render);
    }
    if (classManager?.eventName) {
      window.addEventListener(classManager.eventName, render);
    }
    if (studentManager?.eventName) {
      window.addEventListener(studentManager.eventName, render);
    }
    if (academicCycleManager?.eventName) {
      window.addEventListener(academicCycleManager.eventName, render);
    }

    render();
  }

  function getStaffTodayName() {
    return ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"][
      new Date().getDay()
    ];
  }

  function getStaffActiveTermContext() {
    const cycleManager = getAcademicCycleManager();
    const cycleState =
      cycleManager && typeof cycleManager.getState === "function"
        ? cycleManager.getState()
        : { sessions: [], terms: [] };
    const openTerm = (cycleState.terms || []).find((term) => term.status === "open") || null;
    const openSession = openTerm
      ? (cycleState.sessions || []).find((session) => session.id === openTerm.sessionId) || null
      : (cycleState.sessions || []).find((session) => session.status === "open") || null;

    return { cycleState, openSession, openTerm };
  }

  function staffValueMatchesUser(value, user = {}) {
    const raw = String(value || "").trim();
    if (!raw) {
      return false;
    }

    const rawLower = raw.toLowerCase();
    const userId = String(user.id || "").trim().toLowerCase();
    const userEmail = normalizeEmail(user.email || "");
    const userName = String(user.displayName || user.email || "").trim().toLowerCase();

    return rawLower === userId || normalizeEmail(raw) === userEmail || rawLower === userName;
  }

  function getTeacherPortalTimetableEntries(user = {}, options = {}) {
    const manager = getTimetableManager();
    const summary = manager && typeof manager.summarize === "function" ? manager.summarize() : null;
    const { openTerm } = getStaffActiveTermContext();
    const activeTermOnly = options.activeTermOnly !== false;
    const dayOrder = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

    if (!summary) {
      return [];
    }

    return (summary.entries || [])
      .filter((entry) => {
        if (entry.status === "archived") {
          return false;
        }
        if (activeTermOnly && openTerm?.id && entry.termId && entry.termId !== openTerm.id) {
          return false;
        }
        return staffValueMatchesUser(entry.teacherId, user) || staffValueMatchesUser(entry.teacher, user);
      })
      .sort((left, right) => {
        const dayComparison = dayOrder.indexOf(left.day) - dayOrder.indexOf(right.day);
        if (dayComparison !== 0) {
          return dayComparison;
        }
        return String(left.startTime || "").localeCompare(String(right.startTime || ""));
      });
  }

  function getTeacherPortalAssignments(user = {}) {
    const assignedClasses = getTeacherAssignedClasses(user);
    const courseManager = getCourseManager();
    const courses =
      courseManager && typeof courseManager.getCourses === "function"
        ? courseManager.getCourses().filter((course) => course.status !== "archived")
        : [];
    const rows = [];
    const seen = new Set();
    const pushRow = (row = {}) => {
      const key = [row.classId, row.classLabel, row.subject, row.role].join(":").toLowerCase();
      if (seen.has(key)) {
        return;
      }
      seen.add(key);
      rows.push(row);
    };

    assignedClasses.forEach((classRecord) => {
      const classLabel = getClassDisplayName(classRecord);
      if (staffValueMatchesUser(classRecord.classTeacher, user)) {
        pushRow({
          classId: classRecord.id || "",
          classRecord,
          classLabel,
          subject: "Class register",
          subjectCode: "",
          role: "Class teacher",
        });
      }

      (classRecord.teacherAssignments || []).forEach((assignment) => {
        if (staffValueMatchesUser(assignment.teacher, user)) {
          pushRow({
            classId: classRecord.id || "",
            classRecord,
            classLabel,
            subject: assignment.subject || "Subject",
            subjectCode: "",
            role: "Subject teacher",
          });
        }
      });
    });

    courses.forEach((course) => {
      const hasTeacher = (course.teacherAssignments || []).some((teacher) =>
        staffValueMatchesUser(teacher, user),
      );
      if (!hasTeacher) {
        return;
      }

      const courseClassId = String(course.classId || course.classRecordId || "").trim();
      const matchedClasses =
        String(course.classScope || "").trim().toLowerCase() === "all-arms"
          ? assignedClasses.filter((classRecord) => courseAppliesToClassRecord(course, classRecord))
          : [
              assignedClasses.find((classRecord) => courseClassId && String(classRecord.id || "").trim() === courseClassId) ||
                assignedClasses.find(
                  (classRecord) =>
                    normalizeLevelToken(getClassDisplayName(classRecord)) === normalizeLevelToken(course.classLabel || course.level) ||
                    normalizeLevelToken(classRecord.level) === normalizeLevelToken(course.level),
                ) ||
                null,
            ];
      (matchedClasses.length ? matchedClasses : [null]).forEach((matchedClass) => {
        pushRow({
          classId: matchedClass?.id || "",
          classRecord: matchedClass || null,
          classLabel: matchedClass ? getClassDisplayName(matchedClass) : course.classLabel || course.level || "Assigned level",
          subject: course.name || course.code || "Course",
          subjectCode: course.code || "",
          role: course.creditUnit ? "Course lecturer" : "Subject teacher",
        });
      });
    });

    return rows;
  }

  function normalizeReportCardScore(value) {
    const score = Number.parseFloat(value);

    if (!Number.isFinite(score) || score < 0) {
      return 0;
    }

    return Math.min(100, Math.round(score * 100) / 100);
  }

  function getReportCardGradeInfo(value) {
    const score = normalizeReportCardScore(value);
    const configurationManager = getReportConfigurationManager();

    if (configurationManager && typeof configurationManager.gradeScore === "function") {
      return configurationManager.gradeScore(score);
    }

    if (score >= 70) return { grade: "A", remark: "Excellent" };
    if (score >= 60) return { grade: "B", remark: "Very Good" };
    if (score >= 50) return { grade: "C", remark: "Good" };
    if (score >= 45) return { grade: "D", remark: "Fair" };
    if (score >= 40) return { grade: "E", remark: "Pass" };
    return { grade: "F", remark: "Needs Improvement" };
  }

  function summarizeReportCardSubjects(subjects = []) {
    const manager = getReportCardManager();

    if (manager && typeof manager.summarizeSubjects === "function") {
      return manager.summarizeSubjects(subjects);
    }

    const normalizedSubjects = (Array.isArray(subjects) ? subjects : [])
      .map((subject) => {
        const caScore = normalizeReportCardScore(subject?.caScore);
        const examScore = normalizeReportCardScore(subject?.examScore);
        const totalScore = Math.min(100, Math.round((caScore + examScore) * 100) / 100);
        const grading = getReportCardGradeInfo(totalScore);
        return {
          ...subject,
          name: String(subject?.name || subject?.subject || "").trim(),
          caScore,
          examScore,
          totalScore,
          grade: grading.grade,
          remark: grading.remark,
        };
      })
      .filter((subject) => subject.name);
    const totalScore = normalizedSubjects.reduce((sum, subject) => sum + subject.totalScore, 0);
    const averageScore = normalizedSubjects.length
      ? Math.round((totalScore / normalizedSubjects.length) * 100) / 100
      : 0;
    const grading = getReportCardGradeInfo(averageScore);

    return {
      subjects: normalizedSubjects,
      subjectCount: normalizedSubjects.length,
      totalScore,
      averageScore,
      grade: grading.grade,
      remark: grading.remark,
    };
  }

  function formatReportSummaryList(items = []) {
    const values = (Array.isArray(items) ? items : [])
      .map((item) => String(item || "").trim())
      .filter(Boolean);

    if (values.length <= 1) {
      return values[0] || "";
    }

    if (values.length === 2) {
      return `${values[0]} and ${values[1]}`;
    }

    return `${values.slice(0, -1).join(", ")}, and ${values[values.length - 1]}`;
  }

  function getReportSummaryRecommendation(subjectNames = []) {
    const normalized = subjectNames.join(" ").toLowerCase();

    if (/\b(english|literature|comprehension|language|writing|reading)\b/.test(normalized)) {
      return "Regular reading practice and guided written exercises are recommended.";
    }

    if (/\b(math|mathematics|further mathematics|physics|chemistry|basic science|science)\b/.test(normalized)) {
      return "More guided practice with class examples and problem-solving exercises is recommended.";
    }

    return "Regular revision, class participation, and guided practice are recommended.";
  }

  function cleanReportSummaryClause(value = "") {
    return String(value || "")
      .replace(/\s+/g, " ")
      .replace(/[.!?]+$/g, "")
      .trim();
  }

  function getReportSummaryPeriodRank(record = {}, cycleState = {}) {
    const sessions = Array.isArray(cycleState.sessions) ? cycleState.sessions : [];
    const terms = Array.isArray(cycleState.terms) ? cycleState.terms : [];
    const sessionIndex = sessions.findIndex((session) => session.id === record.sessionId);
    const termIndex = terms.findIndex((term) => term.id === record.termId);

    if (sessionIndex >= 0 || termIndex >= 0) {
      return Math.max(0, sessionIndex) * 1000 + Math.max(0, termIndex);
    }

    const timestamp = new Date(record.releasedAt || record.updatedAt || record.createdAt || 0).getTime();
    return Number.isFinite(timestamp) ? timestamp / 1000000000 : 0;
  }

  function getReportSummaryPreviousCard(options = {}) {
    const allReportCards = Array.isArray(options.allReportCards) ? options.allReportCards : [];
    const cycleState = options.cycleState || {};
    const currentRank = getReportSummaryPeriodRank(
      { sessionId: options.session?.id || "", termId: options.term?.id || "", updatedAt: nowIso() },
      cycleState,
    );
    const previousCards = allReportCards
      .filter(
        (record) =>
          record.studentId === options.student?.id &&
          record.subjects?.length &&
          !(record.sessionId === options.session?.id && record.termId === options.term?.id),
      )
      .map((record) => ({
        record,
        summary: summarizeReportCardSubjects(record.subjects),
        rank: getReportSummaryPeriodRank(record, cycleState),
      }))
      .filter((entry) => entry.summary.subjectCount)
      .sort((left, right) => {
        const leftBeforeCurrent = left.rank < currentRank;
        const rightBeforeCurrent = right.rank < currentRank;

        if (leftBeforeCurrent !== rightBeforeCurrent) {
          return leftBeforeCurrent ? -1 : 1;
        }

        return right.rank - left.rank;
      });

    return previousCards.find((entry) => entry.rank < currentRank) || previousCards[0] || null;
  }

  function getReportSummaryClassAverage(options = {}) {
    const allReportCards = Array.isArray(options.allReportCards) ? options.allReportCards : [];
    const selectedClass = options.classRecord || {};
    const classLabel = selectedClass ? getClassDisplayName(selectedClass) : "";
    const classToken = normalizeLevelToken(classLabel);
    const averages = allReportCards
      .filter((record) => {
        const sameStudent = record.studentId === options.student?.id;
        const samePeriod = record.sessionId === options.session?.id && record.termId === options.term?.id;
        const sameClass =
          (selectedClass.id && record.classId === selectedClass.id) ||
          (classToken && normalizeLevelToken(record.classLevel) === classToken);

        return !sameStudent && samePeriod && sameClass && record.subjects?.length;
      })
      .map((record) => summarizeReportCardSubjects(record.subjects).averageScore)
      .filter((score) => Number.isFinite(score));

    if (!averages.length) {
      return null;
    }

    return Math.round((averages.reduce((sum, score) => sum + score, 0) / averages.length) * 100) / 100;
  }

  function getReportSummaryAttendanceInsight(options = {}) {
    const attendanceManager = getAttendanceManager();
    const selectedClass = options.classRecord || {};
    const selectedStudent = options.student || {};
    const selectedTerm = options.term || {};
    const selectedSession = options.session || {};
    const cycleState = options.cycleState || {};
    const records =
      attendanceManager && typeof attendanceManager.getRecords === "function"
        ? attendanceManager.getRecords()
        : [];
    const classLabel = selectedClass ? getClassDisplayName(selectedClass) : "";
    const classToken = normalizeLevelToken(classLabel);
    const classLevelToken = normalizeLevelToken(selectedClass.level || "");
    const relevantRecords = records.filter((record) => {
      const recordClassToken = normalizeLevelToken(record.className || record.level || "");
      const classMatches =
        (selectedClass.id && record.classId === selectedClass.id) ||
        (classToken && recordClassToken === classToken) ||
        (classLevelToken && normalizeLevelToken(record.level || "") === classLevelToken);
      const periodMatches =
        (selectedTerm.id && record.termId === selectedTerm.id) ||
        (!record.termId && selectedSession.id && record.sessionId === selectedSession.id) ||
        (selectedTerm.id && attendanceRecordMatchesAcademicTerm(record, selectedTerm, cycleState));

      return classMatches && periodMatches;
    });
    const attendance = summarizeAttendancePeriodForStudents([selectedStudent], relevantRecords).rows[0] || null;

    if (!attendance || !attendance.recordedDays) {
      return null;
    }

    return attendance;
  }

  function buildReportSummaryAssessmentInsight(subjects = [], scoreStructure = {}) {
    const caMaximum = Number.parseFloat(scoreStructure.caMaximum) || 40;
    const examMaximum = Number.parseFloat(scoreStructure.examMaximum) || 60;
    const subjectsWithDifference = subjects
      .map((subject) => {
        const caPercent = caMaximum ? (normalizeReportCardScore(subject.caScore) / caMaximum) * 100 : 0;
        const examPercent = examMaximum ? (normalizeReportCardScore(subject.examScore) / examMaximum) * 100 : 0;
        return {
          name: subject.name,
          difference: Math.round((examPercent - caPercent) * 100) / 100,
        };
      })
      .filter((subject) => subject.name);
    const examDrop = subjectsWithDifference
      .filter((subject) => subject.difference <= -20)
      .sort((left, right) => left.difference - right.difference)
      .slice(0, 2);
    const examLift = subjectsWithDifference
      .filter((subject) => subject.difference >= 20)
      .sort((left, right) => right.difference - left.difference)
      .slice(0, 2);

    if (examDrop.length) {
      return `Classwork was stronger than examination performance in ${formatReportSummaryList(
        examDrop.map((subject) => subject.name),
      )}, so exam-focused practice will help.`;
    }

    if (examLift.length) {
      return `Examination performance was especially strong in ${formatReportSummaryList(
        examLift.map((subject) => subject.name),
      )}.`;
    }

    return "";
  }

  function generateStaffResultSummary(studentName = "", subjects = [], options = {}) {
    const summary = summarizeReportCardSubjects(subjects);
    const normalizedSubjects = [...summary.subjects].sort((left, right) => right.totalScore - left.totalScore);

    if (!normalizedSubjects.length) {
      return "";
    }

    const firstName = String(studentName || "").trim().split(/\s+/).filter(Boolean)[0] || "The student";
    const average = formatReportCardScore(summary.averageScore);
    const strongSubjects = normalizedSubjects.filter((subject) => subject.totalScore >= 70).slice(0, 3);
    const improvementSubjects = [...summary.subjects]
      .filter((subject) => subject.totalScore < 50)
      .sort((left, right) => left.totalScore - right.totalScore)
      .slice(0, 3);
    const bestSubjects = strongSubjects.length ? strongSubjects : normalizedSubjects.slice(0, 2);
    const needsAttention = improvementSubjects.length ? improvementSubjects : [...normalizedSubjects].reverse().slice(0, 1);
    const bestSubjectNames = bestSubjects.map((subject) => subject.name);
    const attentionSubjectNames = needsAttention.map((subject) => subject.name);
    const previousCard = getReportSummaryPreviousCard(options);
    const classAverage = getReportSummaryClassAverage(options);
    const attendance = getReportSummaryAttendanceInsight(options);
    const assessmentInsight = cleanReportSummaryClause(
      buildReportSummaryAssessmentInsight(summary.subjects, options.scoreStructure),
    );
    const movement = previousCard
      ? Math.round((summary.averageScore - previousCard.summary.averageScore) * 100) / 100
      : null;
    const classDifference =
      Number.isFinite(classAverage) ? Math.round((summary.averageScore - classAverage) * 100) / 100 : null;
    const performanceLabel =
      summary.averageScore >= 75
        ? "an excellent"
        : summary.averageScore >= 60
          ? "a good"
          : summary.averageScore >= 50
            ? "a satisfactory"
            : summary.averageScore >= 40
              ? "a fair"
              : "a weak";
    const trendInsight =
      movement === null
        ? ""
        : Math.abs(movement) < 3
          ? `performance is steady compared with the previous report`
          : movement > 0
            ? `improved by ${formatReportCardScore(movement)} percentage points from the previous report`
            : `declined by ${formatReportCardScore(Math.abs(movement))} percentage points from the previous report`;
    const classInsight =
      classDifference === null
        ? ""
        : Math.abs(classDifference) < 3
          ? `close to the class average of ${formatReportCardScore(classAverage)}%`
          : classDifference > 0
            ? `${formatReportCardScore(classDifference)} percentage points above the class average`
            : `${formatReportCardScore(Math.abs(classDifference))} percentage points below the class average`;
    const attendanceInsight = attendance
      ? `attendance is ${formatReportCardScore(attendance.attendanceRate || 0)}% with ${attendance.counts.absent} absence${
          attendance.counts.absent === 1 ? "" : "s"
        } and ${attendance.counts.late} late mark${attendance.counts.late === 1 ? "" : "s"}`
      : "";
    const meaningfulTrend = movement !== null && Math.abs(movement) >= 3 ? trendInsight : "";
    const attendanceNeedsAttention = attendance && (attendance.counts.absent || attendance.counts.late) ? attendanceInsight : "";
    const optionalContext =
      meaningfulTrend ||
      classInsight ||
      attendanceNeedsAttention ||
      trendInsight ||
      assessmentInsight;
    const firstSentenceParts = [
      `${firstName} had ${performanceLabel} overall performance with an average of ${average}% and grade ${summary.grade}`,
      bestSubjectNames.length ? `performed well in ${formatReportSummaryList(bestSubjectNames)}` : "",
      optionalContext,
    ].filter(Boolean);
    const recommendation = cleanReportSummaryClause(getReportSummaryRecommendation(attentionSubjectNames));
    const secondSentence =
      attentionSubjectNames.length && (improvementSubjects.length || summary.averageScore < 70)
        ? `More attention is needed in ${formatReportSummaryList(attentionSubjectNames)}; ${recommendation}`
        : "The student should maintain steady study habits and keep participating actively in class";

    return [
      `${firstSentenceParts.join("; ")}.`,
      `${secondSentence}.`,
    ]
      .filter(Boolean)
      .join(" ");
  }

  function formatReportCardScore(value) {
    const score = Number.parseFloat(value);

    if (!Number.isFinite(score)) {
      return "0";
    }

    return Number.isInteger(score) ? String(score) : score.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
  }

  function getReportCardDisplayContext(record = {}) {
    const reportManager = getReportCardManager();
    const cycleManager = getAcademicCycleManager();
    const cycleState =
      cycleManager && typeof cycleManager.getState === "function"
        ? cycleManager.getState()
        : { sessions: [], terms: [] };
    const settingsManager = getSchoolSettingsManager();
    const settings =
      settingsManager && typeof settingsManager.getSettings === "function"
        ? settingsManager.getSettings()
        : getDefaultAdminSchoolSettings();
    const studentManager = getStudentManager();
    const student =
      studentManager && typeof studentManager.getStudents === "function"
        ? studentManager.getStudents().find((entry) => entry.id === record.studentId) || null
        : null;
    const summary = summarizeReportCardSubjects(record.subjects);
    const allRecords =
      reportManager && typeof reportManager.getRecords === "function" ? reportManager.getRecords() : [];
    const classToken = normalizeLevelToken(record.classLevel);
    const comparableRecords = allRecords
      .filter(
        (entry) =>
          entry.status === "released" &&
          entry.sessionId === record.sessionId &&
          entry.termId === record.termId &&
          (record.classId
            ? entry.classId === record.classId
            : normalizeLevelToken(entry.classLevel) === classToken),
      )
      .map((entry) => ({
        id: entry.id,
        averageScore: summarizeReportCardSubjects(entry.subjects).averageScore,
      }))
      .sort((left, right) => right.averageScore - left.averageScore);
    const positionIndex = comparableRecords.findIndex((entry) => entry.id === record.id);
    const reportConfiguration =
      getReportConfigurationManager()?.getConfiguration?.() || {
        scoreStructure: { caMaximum: 40, examMaximum: 60 },
        template: {
          title: "Term Report Card",
          showAttendance: true,
          showClassPosition: false,
          showTeacherComment: true,
          showSchoolComment: true,
        },
      };
    const attendanceEntries = (getAttendanceManager()?.getRecords?.() || []).flatMap((attendanceRecord) =>
      (attendanceRecord.entries || []).filter((entry) => String(entry.studentId || "") === String(record.studentId || "")),
    );
    const presentCount = attendanceEntries.filter((entry) => ["present", "late"].includes(entry.status)).length;

    return {
      ...record,
      settings,
      subjects: summary.subjects,
      subjectCount: summary.subjectCount,
      totalScore: summary.totalScore,
      averageScore: summary.averageScore,
      overallGrade: summary.grade,
      overallRemark: summary.remark,
      studentName: String(record.studentName || student?.fullName || "Student").trim(),
      admissionNo: String(record.admissionNo || student?.admissionNo || "Not set").trim(),
      classLevel: String(record.classLevel || student?.level || "Class").trim(),
      sessionName: String(
        record.sessionName || getSessionLabelFromCycle(cycleState, record.sessionId) || "Session",
      ).trim(),
      termName: String(record.termName || getTermLabelFromCycle(cycleState, record.termId) || "Term").trim(),
      position: positionIndex >= 0 ? `${positionIndex + 1} of ${comparableRecords.length}` : "Not ranked",
      reportTemplate: reportConfiguration.template || {},
      scoreStructure: reportConfiguration.scoreStructure || { caMaximum: 40, examMaximum: 60 },
      attendanceLabel: attendanceEntries.length ? `${presentCount} of ${attendanceEntries.length} present` : "No attendance recorded",
    };
  }

  function renderReportCardDocument(record = {}) {
    const card = getReportCardDisplayContext(record);
    const schoolName = card.settings.schoolName || "School";
    const schoolLocation = card.settings.address || card.settings.campusDetails || "";
    const schoolInitial = String(schoolName).trim().charAt(0).toUpperCase() || "S";
    const template = card.reportTemplate || {};
    const logoHtml = card.settings.logoUrl
      ? `<img src="${escapeHtml(String(card.settings.logoUrl))}" alt="${escapeHtml(String(schoolName))} logo" />`
      : escapeHtml(schoolInitial);
    const subjectRows = card.subjects
      .map(
        (subject, index) => `
          <tr>
            <td>${index + 1}</td>
            <td>
              <strong>${escapeHtml(String(subject.name || "Subject"))}</strong>
              ${subject.code ? `<span>${escapeHtml(String(subject.code))}</span>` : ""}
            </td>
            <td>${escapeHtml(formatReportCardScore(subject.caScore))}</td>
            <td>${escapeHtml(formatReportCardScore(subject.examScore))}</td>
            <td><strong>${escapeHtml(formatReportCardScore(subject.totalScore))}</strong></td>
            <td><strong>${escapeHtml(String(subject.grade || ""))}</strong></td>
            <td>${escapeHtml(String(subject.remark || ""))}</td>
          </tr>
        `,
      )
      .join("");

    return `
      <section class="portal-report-card-document">
        <header class="portal-report-card-head">
          <div class="portal-report-card-school">
            <span class="portal-report-card-mark ${card.settings.logoUrl ? "is-image" : ""}">${logoHtml}</span>
            <div>
              <span>${escapeHtml(String(template.title || "Term Report Card"))}</span>
              <h4>${escapeHtml(String(schoolName))}</h4>
              ${schoolLocation ? `<p>${escapeHtml(String(schoolLocation))}</p>` : ""}
            </div>
          </div>
          <aside>
            <span>Status</span>
            <strong>${card.status === "released" ? "Released" : "Draft"}</strong>
            <small>${escapeHtml(card.releasedAt ? formatTimestamp(card.releasedAt) : "Not released")}</small>
          </aside>
        </header>

        <div class="portal-report-card-meta">
          <article><span>Student</span><strong>${escapeHtml(card.studentName)}</strong></article>
          <article><span>Admission No.</span><strong>${escapeHtml(card.admissionNo)}</strong></article>
          <article><span>Class / Level</span><strong>${escapeHtml(card.classLevel)}</strong></article>
          <article><span>Academic Session</span><strong>${escapeHtml(card.sessionName)}</strong></article>
          <article><span>Term / Semester</span><strong>${escapeHtml(card.termName)}</strong></article>
          ${
            template.showClassPosition
              ? `<article><span>Position</span><strong>${escapeHtml(card.position)}</strong></article>`
              : ""
          }
          ${
            template.showAttendance !== false
              ? `<article><span>Attendance</span><strong>${escapeHtml(card.attendanceLabel)}</strong></article>`
              : ""
          }
        </div>

        <div class="portal-report-card-table-wrap">
          <table class="portal-report-card-table">
            <thead>
              <tr><th>#</th><th>Subject / Course</th><th>CA / ${escapeHtml(
                formatReportCardScore(card.scoreStructure?.caMaximum || 40),
              )}</th><th>Exam / ${escapeHtml(
                formatReportCardScore(card.scoreStructure?.examMaximum || 60),
              )}</th><th>Total</th><th>Grade</th><th>Remark</th></tr>
            </thead>
            <tbody>
              ${
                subjectRows ||
                `<tr><td colspan="7"><span>No subject scores recorded.</span></td></tr>`
              }
            </tbody>
          </table>
        </div>

        <div class="portal-report-card-summary">
          <article><span>Subjects</span><strong>${card.subjectCount}</strong></article>
          <article><span>Total Score</span><strong>${escapeHtml(formatReportCardScore(card.totalScore))}</strong></article>
          <article><span>Average</span><strong>${escapeHtml(formatReportCardScore(card.averageScore))}%</strong></article>
          <article><span>Overall Grade</span><strong>${escapeHtml(card.overallGrade)}</strong></article>
        </div>

        ${
          template.showTeacherComment !== false || template.showSchoolComment !== false
            ? `<div class="portal-report-card-comments">
                ${
                  template.showTeacherComment !== false
                    ? `<article>
                        <span>Teacher&apos;s Comment</span>
                        <p>${escapeHtml(String(card.teacherComment || "No comment recorded."))}</p>
                      </article>`
                    : ""
                }
                ${
                  template.showSchoolComment !== false
                    ? `<article>
                        <span>School Comment</span>
                        <p>${escapeHtml(String(card.schoolComment || card.overallRemark || "No comment recorded."))}</p>
                      </article>`
                    : ""
                }
              </div>`
            : ""
        }

        <footer class="portal-report-card-footer">
          <span>Released by ${escapeHtml(String(card.releasedByName || "School administration"))}</span>
          <strong>${escapeHtml(String(card.overallRemark))}</strong>
        </footer>
      </section>
    `;
  }

  function renderReportCardPrintDocument(record = {}) {
    const card = getReportCardDisplayContext(record);

    return `
      <!doctype html>
      <html>
        <head>
          <meta charset="utf-8" />
          <title>${escapeHtml(`${card.studentName} report card`)}</title>
          <style>
            * { box-sizing: border-box; }
            body { margin: 0; padding: 18mm; color: #17233a; font-family: Arial, sans-serif; background: #ffffff; }
            .portal-report-card-document { display: grid; gap: 18px; max-width: 900px; margin: 0 auto; }
            .portal-report-card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; padding-bottom: 16px; border-bottom: 2px solid #17233a; }
            .portal-report-card-school { display: flex; align-items: center; gap: 13px; }
            .portal-report-card-mark { display: inline-flex; align-items: center; justify-content: center; width: 52px; height: 52px; overflow: hidden; border-radius: 12px; background: #17233a; color: #ffffff; font-size: 24px; font-weight: 800; }
            .portal-report-card-mark img { width: 100%; height: 100%; object-fit: cover; }
            .portal-report-card-head span, .portal-report-card-meta span, .portal-report-card-summary span, .portal-report-card-comments span { color: #667188; font-size: 10px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
            .portal-report-card-head h4 { margin: 4px 0; font-size: 24px; }
            .portal-report-card-head p, .portal-report-card-head small { margin: 0; color: #56647a; font-size: 11px; }
            .portal-report-card-head aside { display: grid; gap: 4px; text-align: right; }
            .portal-report-card-head aside strong { color: #14804a; font-size: 18px; }
            .portal-report-card-meta { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 9px; }
            .portal-report-card-meta article, .portal-report-card-summary article { padding: 10px; border: 1px solid #dfe7f2; border-radius: 8px; }
            .portal-report-card-meta strong, .portal-report-card-summary strong { display: block; margin-top: 6px; font-size: 12px; overflow-wrap: anywhere; }
            table { width: 100%; border-collapse: collapse; table-layout: fixed; }
            th, td { padding: 9px 7px; border: 1px solid #d8e1ee; text-align: left; vertical-align: top; font-size: 11px; }
            th { background: #17233a; color: #ffffff; font-size: 9px; letter-spacing: .06em; text-transform: uppercase; }
            th:first-child, td:first-child { width: 32px; text-align: center; }
            th:nth-child(3), th:nth-child(4), th:nth-child(5), th:nth-child(6), td:nth-child(3), td:nth-child(4), td:nth-child(5), td:nth-child(6) { width: 58px; text-align: center; }
            td span { display: block; margin-top: 3px; color: #667188; font-size: 9px; }
            .portal-report-card-summary { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 9px; }
            .portal-report-card-comments { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; }
            .portal-report-card-comments article { min-height: 72px; padding: 11px; border: 1px solid #dfe7f2; border-radius: 8px; }
            .portal-report-card-comments p { margin: 7px 0 0; color: #34435a; font-size: 11px; line-height: 1.45; }
            .portal-report-card-footer { display: flex; justify-content: space-between; gap: 16px; padding-top: 12px; border-top: 1px solid #d8e1ee; color: #667188; font-size: 10px; }
            .portal-report-card-footer strong { color: #17233a; }
            @page { size: A4 portrait; margin: 12mm; }
            @media print { body { padding: 0; } }
          </style>
        </head>
        <body>
          ${renderReportCardDocument(card)}
          <script>
            window.addEventListener("load", function () {
              window.focus();
              window.print();
            });
          </script>
        </body>
      </html>
    `;
  }

  function showReportCardToast(type, message) {
    let toast = document.getElementById("portal-report-card-toast");

    if (!toast) {
      toast = document.createElement("div");
      toast.id = "portal-report-card-toast";
      toast.setAttribute("role", "status");
      toast.setAttribute("aria-live", "polite");
      document.body.appendChild(toast);
    }

    const safeType = ["success", "error", "info"].includes(type) ? type : "info";
    toast.className = `portal-toast portal-toast--${safeType} portal-toast--center`;
    toast.innerHTML = message;
    toast.hidden = false;
    window.clearTimeout(showReportCardToast.hideHandle);
    showReportCardToast.hideHandle = window.setTimeout(() => {
      toast.hidden = true;
    }, 4300);
  }

  function printReportCard(record = {}) {
    if (record.status !== "released") {
      showReportCardToast("info", "<strong>Report card is still a draft</strong><span>Release it before printing.</span>");
      return;
    }

    const printWindow = window.open("", "_blank", "width=980,height=820");

    if (!printWindow) {
      showReportCardToast("info", "<strong>Printing was blocked</strong><span>Allow popups, then try again.</span>");
      return;
    }

    printWindow.document.write(renderReportCardPrintDocument(record));
    printWindow.document.close();
  }

  let reportCardPdfLibraryPromise = null;

  function loadReportCardPdfLibrary() {
    if (window.jspdf?.jsPDF) {
      return Promise.resolve(window.jspdf.jsPDF);
    }

    if (reportCardPdfLibraryPromise) {
      return reportCardPdfLibraryPromise;
    }

    reportCardPdfLibraryPromise = new Promise((resolve, reject) => {
      const existing = document.querySelector('script[data-report-card-pdf-library="true"]');
      const script = existing || document.createElement("script");

      if (!existing) {
        script.src = "https://cdn.jsdelivr.net/npm/jspdf@4.2.1/dist/jspdf.umd.min.js";
        script.async = true;
        script.dataset.reportCardPdfLibrary = "true";
        document.head.appendChild(script);
      }

      script.addEventListener("load", () => {
        if (window.jspdf?.jsPDF) {
          resolve(window.jspdf.jsPDF);
          return;
        }
        reject(new Error("PDF library did not load."));
      });
      script.addEventListener("error", () => reject(new Error("PDF library could not be loaded.")));
    }).catch((error) => {
      reportCardPdfLibraryPromise = null;
      throw error;
    });

    return reportCardPdfLibraryPromise;
  }

  function getReportCardPdfFileName(record = {}) {
    const card = getReportCardDisplayContext(record);
    const base = `${card.studentName}-${card.termName}-${card.sessionName}-report-card`
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");
    return `${base || "report-card"}.pdf`;
  }

  async function downloadReportCardPdf(record = {}) {
    if (record.status !== "released") {
      showReportCardToast("info", "<strong>Report card is still a draft</strong><span>Release it before downloading.</span>");
      return;
    }

    const JsPdf = await loadReportCardPdfLibrary();
    const card = getReportCardDisplayContext(record);
    const doc = new JsPdf({ orientation: "portrait", unit: "mm", format: "a4" });
    const pageWidth = doc.internal.pageSize.getWidth();
    const pageHeight = doc.internal.pageSize.getHeight();
    const margin = 14;
    const contentWidth = pageWidth - margin * 2;
    const columns = [8, 64, 20, 20, 20, 16, 34];
    const headers = [
      "#",
      "Subject / Course",
      `CA / ${formatReportCardScore(card.scoreStructure?.caMaximum || 40)}`,
      `Exam / ${formatReportCardScore(card.scoreStructure?.examMaximum || 60)}`,
      "Total",
      "Grade",
      "Remark",
    ];
    let y = 15;

    const drawText = (text, x, textY, options = {}) => {
      doc.text(String(text || ""), x, textY, options);
    };
    const drawTableHeader = () => {
      let x = margin;
      doc.setFillColor(23, 35, 58);
      doc.rect(margin, y, contentWidth, 8, "F");
      doc.setTextColor(255, 255, 255);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(7);
      headers.forEach((header, index) => {
        drawText(header, x + (index === 1 ? 2 : columns[index] / 2), y + 5, {
          align: index === 1 ? "left" : "center",
        });
        x += columns[index];
      });
      y += 8;
      doc.setTextColor(23, 35, 58);
    };
    const ensurePageSpace = (height, includeTableHeader = false) => {
      if (y + height <= pageHeight - margin) {
        return;
      }
      doc.addPage();
      y = margin;
      if (includeTableHeader) {
        drawTableHeader();
      }
    };

    doc.setTextColor(23, 35, 58);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(18);
    drawText(card.settings.schoolName || "School", margin, y);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.setTextColor(92, 105, 124);
    y += 5;
    drawText(card.settings.address || card.settings.campusDetails || "Official report card", margin, y);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(20, 128, 74);
    drawText("RELEASED REPORT CARD", pageWidth - margin, 15, { align: "right" });
    doc.setFont("helvetica", "normal");
    doc.setTextColor(92, 105, 124);
    doc.setFontSize(7);
    drawText(card.releasedAt ? formatTimestamp(card.releasedAt) : "", pageWidth - margin, 20, { align: "right" });
    y += 7;
    doc.setDrawColor(23, 35, 58);
    doc.setLineWidth(0.6);
    doc.line(margin, y, pageWidth - margin, y);
    y += 8;

    const metadata = [
      ["Student", card.studentName],
      ["Admission No.", card.admissionNo],
      ["Class / Level", card.classLevel],
      ["Academic Session", card.sessionName],
      ["Term / Semester", card.termName],
      ["Position", card.position],
    ];
    metadata.forEach((item, index) => {
      const column = index % 3;
      const row = Math.floor(index / 3);
      const boxWidth = (contentWidth - 6) / 3;
      const x = margin + column * (boxWidth + 3);
      const boxY = y + row * 15;
      doc.setDrawColor(223, 231, 242);
      doc.setLineWidth(0.25);
      doc.rect(x, boxY, boxWidth, 12);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(6.5);
      doc.setTextColor(102, 113, 136);
      drawText(item[0].toUpperCase(), x + 2, boxY + 4);
      doc.setFontSize(8);
      doc.setTextColor(23, 35, 58);
      const lines = doc.splitTextToSize(String(item[1] || ""), boxWidth - 4);
      drawText(lines.slice(0, 2), x + 2, boxY + 8);
    });
    y += 34;

    drawTableHeader();
    card.subjects.forEach((subject, index) => {
      const subjectLines = doc.splitTextToSize(
        subject.code ? `${subject.name} (${subject.code})` : subject.name,
        columns[1] - 4,
      );
      const remarkLines = doc.splitTextToSize(subject.remark || "", columns[6] - 4);
      const rowHeight = Math.max(8, Math.max(subjectLines.length, remarkLines.length) * 3.6 + 3);
      ensurePageSpace(rowHeight, true);
      let x = margin;
      doc.setDrawColor(216, 225, 238);
      doc.setLineWidth(0.2);
      columns.forEach((width) => {
        doc.rect(x, y, width, rowHeight);
        x += width;
      });
      doc.setFont("helvetica", "normal");
      doc.setFontSize(7);
      doc.setTextColor(23, 35, 58);
      x = margin;
      const values = [
        String(index + 1),
        subjectLines,
        formatReportCardScore(subject.caScore),
        formatReportCardScore(subject.examScore),
        formatReportCardScore(subject.totalScore),
        subject.grade || "",
        remarkLines,
      ];
      values.forEach((value, valueIndex) => {
        const align = valueIndex === 1 || valueIndex === 6 ? "left" : "center";
        drawText(value, x + (align === "left" ? 2 : columns[valueIndex] / 2), y + 5, { align });
        x += columns[valueIndex];
      });
      y += rowHeight;
    });

    ensurePageSpace(32);
    y += 7;
    const summaryItems = [
      ["Subjects", card.subjectCount],
      ["Total Score", formatReportCardScore(card.totalScore)],
      ["Average", `${formatReportCardScore(card.averageScore)}%`],
      ["Overall Grade", card.overallGrade],
    ];
    summaryItems.forEach((item, index) => {
      const boxWidth = (contentWidth - 9) / 4;
      const x = margin + index * (boxWidth + 3);
      doc.setDrawColor(223, 231, 242);
      doc.rect(x, y, boxWidth, 13);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(6.5);
      doc.setTextColor(102, 113, 136);
      drawText(item[0].toUpperCase(), x + 2, y + 4);
      doc.setFontSize(10);
      doc.setTextColor(23, 35, 58);
      drawText(String(item[1]), x + 2, y + 10);
    });
    y += 20;

    const comments = [
      ["Teacher's Comment", card.teacherComment || "No comment recorded."],
      ["School Comment", card.schoolComment || card.overallRemark || "No comment recorded."],
    ];
    comments.forEach(([label, comment]) => {
      const lines = doc.splitTextToSize(String(comment), contentWidth - 4);
      const blockHeight = Math.max(14, lines.length * 4 + 8);
      ensurePageSpace(blockHeight + 4);
      doc.setDrawColor(223, 231, 242);
      doc.rect(margin, y, contentWidth, blockHeight);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(6.5);
      doc.setTextColor(102, 113, 136);
      drawText(label.toUpperCase(), margin + 2, y + 4);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(8);
      doc.setTextColor(23, 35, 58);
      drawText(lines, margin + 2, y + 9);
      y += blockHeight + 4;
    });

    ensurePageSpace(10);
    doc.setDrawColor(216, 225, 238);
    doc.line(margin, y, pageWidth - margin, y);
    y += 5;
    doc.setFont("helvetica", "normal");
    doc.setFontSize(7);
    doc.setTextColor(102, 113, 136);
    drawText(`Released by ${card.releasedByName || "School administration"}`, margin, y);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(23, 35, 58);
    drawText(card.overallRemark, pageWidth - margin, y, { align: "right" });

    doc.save(getReportCardPdfFileName(card));
  }

  let activeReportCardModalRecord = null;

  function ensureReportCardModal() {
    let overlay = document.getElementById("portal-report-card-overlay");

    if (overlay) {
      return overlay;
    }

    const wrapper = document.createElement("div");
    wrapper.innerHTML = `
      <div id="portal-report-card-overlay" class="portal-overlay" hidden>
        <button class="portal-overlay-backdrop" type="button" data-report-card-close aria-label="Close report card"></button>
        <section class="portal-overlay-panel portal-report-card-modal-panel" role="dialog" aria-modal="true" aria-labelledby="portal-report-card-modal-title">
          <header class="portal-overlay-head">
            <div>
              <span class="portal-overlay-kicker">Released report card</span>
              <h3 id="portal-report-card-modal-title">Report card</h3>
            </div>
            <button class="portal-overlay-close" type="button" data-report-card-close aria-label="Close report card">&times;</button>
          </header>
          <div id="portal-report-card-modal-body" class="portal-report-card-modal-body"></div>
          <footer class="portal-report-card-modal-actions">
            <button class="portal-class-button" type="button" data-report-card-print>Print</button>
            <button class="button button-primary" type="button" data-report-card-download>Download PDF</button>
          </footer>
        </section>
      </div>
    `;
    document.body.appendChild(wrapper.firstElementChild);
    overlay = document.getElementById("portal-report-card-overlay");

    overlay.addEventListener("click", async (event) => {
      if (event.target.closest("[data-report-card-close]")) {
        overlay.hidden = true;
        activeReportCardModalRecord = null;
        document.body.classList.toggle("portal-overlay-open", Boolean(document.querySelector(".portal-overlay:not([hidden])")));
        return;
      }

      if (event.target.closest("[data-report-card-print]") && activeReportCardModalRecord) {
        printReportCard(activeReportCardModalRecord);
        return;
      }

      const downloadButton = event.target.closest("[data-report-card-download]");
      if (downloadButton && activeReportCardModalRecord) {
        downloadButton.disabled = true;
        downloadButton.textContent = "Preparing PDF...";
        try {
          await downloadReportCardPdf(activeReportCardModalRecord);
          showReportCardToast("success", "<strong>PDF download ready</strong><span>The released report card has been downloaded.</span>");
        } catch {
          showReportCardToast("error", "<strong>Could not create PDF</strong><span>Check your network connection, then try again.</span>");
        } finally {
          downloadButton.disabled = false;
          downloadButton.textContent = "Download PDF";
        }
      }
    });

    overlay.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        overlay.querySelector("[data-report-card-close]")?.click();
      }
    });

    return overlay;
  }

  function openReportCardModal(record = {}) {
    if (record.status !== "released") {
      showReportCardToast("info", "<strong>Report card is still a draft</strong><span>Release it before opening the final document.</span>");
      return;
    }

    const overlay = ensureReportCardModal();
    const body = overlay.querySelector("#portal-report-card-modal-body");
    const title = overlay.querySelector("#portal-report-card-modal-title");
    const context = getReportCardDisplayContext(record);
    activeReportCardModalRecord = record;

    if (title) {
      title.textContent = `${context.studentName} report card`;
    }
    if (body) {
      body.innerHTML = renderReportCardDocument(record);
    }
    overlay.hidden = false;
    document.body.classList.add("portal-overlay-open");
    overlay.querySelector("[data-report-card-close]")?.focus();
  }

  function findReportCardRecordById(reportCardId) {
    const manager = getReportCardManager();
    const records = manager && typeof manager.getRecords === "function" ? manager.getRecords() : [];
    return records.find((record) => record.id === String(reportCardId || "").trim()) || null;
  }

  function wireReportCardDocumentActions(target) {
    if (!target || target.dataset.reportCardActionsWired === "true") {
      return;
    }

    target.dataset.reportCardActionsWired = "true";
    target.addEventListener("click", async (event) => {
      const action = event.target.closest("[data-report-card-action]");
      if (!action) {
        return;
      }

      const record = findReportCardRecordById(action.dataset.reportCardId);
      if (!record || record.status !== "released") {
        showReportCardToast("info", "<strong>Report card unavailable</strong><span>This report card has not been released.</span>");
        return;
      }

      const actionName = action.dataset.reportCardAction;
      if (actionName === "view") {
        openReportCardModal(record);
        return;
      }
      if (actionName === "print") {
        printReportCard(record);
        return;
      }
      if (actionName === "download") {
        action.disabled = true;
        const originalLabel = action.textContent;
        action.textContent = "Preparing...";
        try {
          await downloadReportCardPdf(record);
          showReportCardToast("success", "<strong>PDF download ready</strong><span>The released report card has been downloaded.</span>");
        } catch {
          showReportCardToast("error", "<strong>Could not create PDF</strong><span>Check your network connection, then try again.</span>");
        } finally {
          action.disabled = false;
          action.textContent = originalLabel;
        }
      }
    });
  }

  function getStudentPortalRecord(user = {}) {
    const manager = getStudentManager();

    if (!manager || typeof manager.getStudents !== "function") {
      return null;
    }

    const studentRecordId = String(user.studentRecordId || "").trim();
    const admissionNo = String(user.admissionNo || "").trim().toLowerCase();
    const userEmail = normalizeEmail(user.email || "");
    const students = manager.getStudents().filter((student) => student.status === "active");

    return (
      students.find((student) => studentRecordId && String(student.id || "") === studentRecordId) ||
      students.find((student) => admissionNo && String(student.admissionNo || "").trim().toLowerCase() === admissionNo) ||
      students.find((student) => userEmail && normalizeEmail(student.studentEmail || student.email || "") === userEmail) ||
      null
    );
  }

  function getStudentPortalClassRecords(student = null) {
    if (!student) {
      return [];
    }

    const classManager = getClassManager();
    const studentLevelToken = normalizeLevelToken(student.level);
    const studentClassId = String(student.classId || student.classRecordId || "").trim();

    if (!classManager || typeof classManager.getClasses !== "function" || (!studentLevelToken && !studentClassId)) {
      return [];
    }

    return classManager
      .getClasses()
      .filter((record) => record.status !== "archived")
      .filter((record) =>
        (studentClassId && String(record.id || "").trim() === studentClassId) ||
        [
          record.id,
          record.level,
          record.name,
          getClassDisplayName(record),
        ].some((value) => normalizeLevelToken(value) === studentLevelToken),
      )
      .sort((left, right) => getClassDisplayName(left).localeCompare(getClassDisplayName(right), undefined, { numeric: true }));
  }

  function getStudentPortalRoster(student = null) {
    const manager = getStudentManager();

    if (!student || !manager || typeof manager.getStudents !== "function") {
      return [];
    }

    const studentLevelToken = normalizeLevelToken(student.level);
    return manager
      .getStudents()
      .filter((record) => record.status === "active" && normalizeLevelToken(record.level) === studentLevelToken)
      .sort((left, right) => left.fullName.localeCompare(right.fullName, undefined, { numeric: true }));
  }

  function getStudentPortalTimetableEntries(student = null, options = {}) {
    if (!student) {
      return [];
    }

    const manager = getTimetableManager();
    const summary = manager && typeof manager.summarize === "function" ? manager.summarize() : null;
    const { openTerm } = getStaffActiveTermContext();
    const activeTermOnly = options.activeTermOnly !== false;
    const classRecords = getStudentPortalClassRecords(student);
    const classIds = new Set(classRecords.map((record) => String(record.id || "").trim()).filter(Boolean));
    const classTokens = new Set(
      [
        student.level,
        ...classRecords.flatMap((record) => [record.level, record.name, getClassDisplayName(record)]),
      ]
        .map((value) => normalizeLevelToken(value))
        .filter(Boolean),
    );
    const dayOrder = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

    if (!summary) {
      return [];
    }

    return (summary.entries || [])
      .filter((entry) => {
        if (entry.status === "archived") {
          return false;
        }
        if (activeTermOnly && openTerm?.id && entry.termId && entry.termId !== openTerm.id) {
          return false;
        }
        return (
          (entry.classId && classIds.has(String(entry.classId || "").trim())) ||
          classTokens.has(normalizeLevelToken(entry.classLevel))
        );
      })
      .sort((left, right) => {
        const dayComparison = dayOrder.indexOf(left.day) - dayOrder.indexOf(right.day);
        if (dayComparison !== 0) {
          return dayComparison;
        }
        return String(left.startTime || "").localeCompare(String(right.startTime || ""));
      });
  }

  function isStudentAnnouncementNotification(entry = {}) {
    const entityType = String(entry.entityType || "")
      .trim()
      .toLowerCase();
    return [
      "announcement",
      "school-announcement",
      "school-update",
      "class-announcement",
      "class-update",
      "notice",
      "calendar",
      "activity",
    ].includes(entityType);
  }

  function getStudentPortalAnnouncements(user = {}) {
    const session = getSession() || {};
    const workspaceId = normalizeWorkspaceId(user.workspaceId || session.workspaceId || getCurrentWorkspaceId());
    const studentSession = {
      ...session,
      role: "Student",
      userId: user.id || session.userId,
      email: user.email || session.email,
      workspaceId,
    };

    return filterNotificationsForSession(getNotifications(workspaceId), studentSession)
      .filter((entry) => isStudentAnnouncementNotification(entry))
      .slice(0, 6);
  }

  function getParentPortalAnnouncements(user = {}, student = null) {
    const session = getSession() || {};
    const workspaceId = normalizeWorkspaceId(user.workspaceId || session.workspaceId || getCurrentWorkspaceId());
    const studentId = String(student?.id || "").trim().toLowerCase();
    const studentLevel = normalizeLevelToken(student?.level);

    return filterNotificationsForSession(getNotifications(workspaceId), {
      ...session,
      role: "Parent",
      userId: user.id || session.userId,
      email: user.email || session.email,
      workspaceId,
    })
      .filter((entry) => {
        if (!isStudentAnnouncementNotification(entry)) {
          return false;
        }
        if (isWholeSchoolAnnouncement(entry)) {
          return true;
        }
        const entityId = String(entry.entityId || "").trim().toLowerCase();
        return entityId === studentId || normalizeLevelToken(entityId) === studentLevel;
      })
      .slice(0, 5);
  }

  function isWholeSchoolAnnouncement(entry = {}) {
    const entityId = String(entry.entityId || "")
      .trim()
      .toLowerCase();
    return !entityId || ["all", "everyone", "global", "school", "whole-school", "whole_school"].includes(entityId);
  }

  function isPortalAnnouncementToastEntry(entry = {}) {
    return ["announcement", "school-announcement", "class-announcement", "notice"].includes(
      String(entry.entityType || "").trim().toLowerCase(),
    );
  }

  function getAnnouncementToastSessionKey(session = {}, user = {}) {
    const workspaceId = normalizeWorkspaceId(user.workspaceId || session.workspaceId || getCurrentWorkspaceId());
    const identity =
      normalizeEmail(user.email || session.email || "") ||
      String(user.id || session.userId || "user").trim().toLowerCase();
    return `${ANNOUNCEMENT_TOAST_SESSION_PREFIX}:${workspaceId}:${identity}`;
  }

  function initPortalAnnouncementToasts(session = null, user = null) {
    const role = normalizeRoleLabel(session?.role || user?.role || DEFAULT_AUTH_ROLE);
    if (!session || !user || !["Teacher", "Parent", "Student"].includes(role)) {
      return;
    }

    const workspaceId = normalizeWorkspaceId(user.workspaceId || session.workspaceId || getCurrentWorkspaceId());
    const scopedSession = {
      ...session,
      role,
      userId: user.id || session.userId,
      email: user.email || session.email,
      workspaceId,
    };
    const sessionKey = getAnnouncementToastSessionKey(scopedSession, user);
    let savedIds = [];
    try {
      savedIds = parseJSON(localStorage.getItem(sessionKey), []);
    } catch {
      savedIds = [];
    }
    const shownIds = new Set(Array.isArray(savedIds) ? savedIds : []);
    const queue = [];
    let isShowing = false;

    const saveShownIds = () => {
      try {
        localStorage.setItem(sessionKey, JSON.stringify(Array.from(shownIds).slice(-80)));
      } catch {
        // The toast still works when persistent storage is unavailable.
      }
    };

    const ensureToast = () => {
      let toast = document.getElementById("portal-announcement-toast");
      if (toast) {
        return toast;
      }

      toast = document.createElement("aside");
      toast.id = "portal-announcement-toast";
      toast.className = "portal-announcement-toast";
      toast.setAttribute("role", "status");
      toast.setAttribute("aria-live", "polite");
      toast.hidden = true;
      toast.innerHTML = `
        <div class="portal-announcement-toast-icon" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">
            <path d="M3 11v2"></path>
            <path d="M6 9v6"></path>
            <path d="m9 8 9-4v16l-9-4Z"></path>
            <path d="M9 16l1.5 4H7.5L6 15"></path>
          </svg>
        </div>
        <div class="portal-announcement-toast-copy">
          <span>School announcement</span>
          <strong data-announcement-toast-title></strong>
          <p data-announcement-toast-message></p>
          <small data-announcement-toast-meta></small>
        </div>
        <button type="button" data-announcement-toast-close aria-label="Dismiss announcement">&times;</button>
        <i class="portal-announcement-toast-timer" aria-hidden="true"></i>
      `;
      document.body.appendChild(toast);
      return toast;
    };

    const showNext = () => {
      if (isShowing || !queue.length) {
        return;
      }

      const entry = queue.shift();
      const toast = ensureToast();
      const timer = toast.querySelector(".portal-announcement-toast-timer");
      let hideHandle = null;

      shownIds.add(entry.id);
      saveShownIds();
      isShowing = true;
      toast.querySelector("[data-announcement-toast-title]").textContent =
        entry.title || "School announcement";
      toast.querySelector("[data-announcement-toast-message]").textContent =
        entry.message || "A new school notice has been posted.";
      toast.querySelector("[data-announcement-toast-meta]").textContent = `${
        isWholeSchoolAnnouncement(entry) ? "Whole school" : "Your class"
      } • ${formatTimestamp(entry.createdAt || nowIso())}`;
      toast.hidden = false;
      toast.classList.remove("is-leaving");
      toast.classList.add("is-visible");
      if (timer) {
        timer.style.animation = "none";
        void timer.offsetWidth;
        timer.style.animation = "";
      }

      const dismiss = () => {
        window.clearTimeout(hideHandle);
        toast.classList.remove("is-visible");
        toast.classList.add("is-leaving");
        window.setTimeout(() => {
          toast.hidden = true;
          toast.classList.remove("is-leaving");
          isShowing = false;
          showNext();
        }, 260);
      };

      toast.querySelector("[data-announcement-toast-close]").onclick = dismiss;
      hideHandle = window.setTimeout(dismiss, 6500);
    };

    const refreshQueue = () => {
      const nextEntries = filterNotificationsForSession(getNotifications(workspaceId), scopedSession)
        .filter((entry) => isPortalAnnouncementToastEntry(entry))
        .filter((entry) => isNotificationUnreadForViewer(entry, user, role))
        .filter((entry) => !shownIds.has(entry.id))
        .filter((entry) => !queue.some((queued) => queued.id === entry.id))
        .sort((left, right) => String(left.createdAt || "").localeCompare(String(right.createdAt || "")));

      queue.push(...nextEntries);
      showNext();
    };

    refreshQueue();
    window.addEventListener(NOTIFICATION_EVENT_NAME, (event) => {
      const eventWorkspaceId = normalizeWorkspaceId(event?.detail?.workspaceId || workspaceId);
      if (eventWorkspaceId === workspaceId) {
        refreshQueue();
      }
    });
  }

  function renderStudentAnnouncementsPanel(user = {}) {
    const announcements = getStudentPortalAnnouncements(user);

    return `
      <section class="staff-portal-section admin-surface-card">
        <div class="admin-surface-head">
          <div>
            <h2>School Announcements</h2>
            <span>${announcements.length} notice${announcements.length === 1 ? "" : "s"} for your class or whole school</span>
          </div>
        </div>
        <div class="staff-portal-list">
          ${
            announcements.length
              ? announcements
                  .map(
                    (entry) => `
                      <article class="staff-portal-row staff-portal-row-wide">
                        <div>
                          <strong>${escapeHtml(entry.title || "School announcement")}</strong>
                          <span>${escapeHtml(entry.message || "No extra details.")}</span>
                        </div>
                        <small>${escapeHtml(isWholeSchoolAnnouncement(entry) ? "Whole school" : "Your class")} • ${escapeHtml(
                          formatTimestamp(entry.createdAt),
                        )}</small>
                      </article>
                    `,
                  )
                  .join("")
              : `
                <article class="portal-class-empty">
                  <strong>No announcements yet</strong>
                  <p>Whole-school and class notices will appear here when the school posts them.</p>
                </article>
              `
          }
        </div>
      </section>
    `;
  }

