  function getParentChatbotFeeContext(student = null, user = {}) {
    if (!student) {
      return null;
    }

    const workspaceId = normalizeWorkspaceId(user?.workspaceId || getCurrentWorkspaceId());
    const storedFeeRecord = readParentFeesState(workspaceId)[student.id] || null;
    const configuredFeeRecord = buildConfiguredParentFeeSnapshot(student);
    return storedFeeRecord?.invoiceNo || storedFeeRecord?.invoiceItems?.length
      ? storedFeeRecord
      : configuredFeeRecord || {
          studentId: student.id,
          studentName: student.fullName,
          classLevel: getStudentBaseClassLevel(student) || student.level || "",
          totalDue: 0,
          balance: 0,
          dueDate: "Not set",
          invoiceStatus: "not configured",
        };
  }

  function getParentChatbotTodayAttendance(student = null) {
    if (!student) {
      return null;
    }

    const today = getTodayDateValue();
    const attendanceManager = getAttendanceManager();
    const records =
      attendanceManager && typeof attendanceManager.getRecords === "function"
        ? attendanceManager.getRecords()
        : [];
    const matchingRecord = records
      .filter((record) => String(record.date || "") === today)
      .find((record) => (record.entries || []).some((entry) => String(entry.studentId || "") === String(student.id || "")));
    const entry = matchingRecord?.entries?.find((item) => String(item.studentId || "") === String(student.id || "")) || null;

    return {
      date: today,
      record: matchingRecord || null,
      entry,
      label: entry ? getAttendanceStatusLabel(entry.status) : "Not marked yet",
    };
  }

  function getParentChatbotNextExam() {
    const calendarManager = getAcademicCalendarManager();
    const today = getTodayDateValue();
    const events =
      calendarManager && typeof calendarManager.getEvents === "function"
        ? calendarManager.getEvents()
        : [];

    return events
      .filter((event) => event.status !== "archived")
      .filter((event) => normalizeCalendarType(event.type) === "exam")
      .filter((event) => String(event.endDate || "") >= today)
      .sort((left, right) => {
        const startComparison = String(left.startDate || "").localeCompare(String(right.startDate || ""));
        return startComparison || String(left.endDate || "").localeCompare(String(right.endDate || ""));
      })[0] || null;
  }

  function getParentChatbotLatestReport(student = null) {
    const reportManager = getReportCardManager();
    const records =
      reportManager && typeof reportManager.getRecords === "function"
        ? reportManager.getRecords()
        : [];

    return records
      .filter((record) => String(record.studentId || "") === String(student?.id || ""))
      .filter((record) => record.status === "released")
      .sort((left, right) =>
        String(right.releasedAt || right.updatedAt || right.createdAt || "").localeCompare(
          String(left.releasedAt || left.updatedAt || left.createdAt || ""),
        ),
      )[0] || null;
  }

  function getParentChatbotClassTimetableEntries(student = null) {
    const timetableManager = getTimetableManager();
    const entries =
      timetableManager && typeof timetableManager.getEntries === "function"
        ? timetableManager.getEntries()
        : [];
    const classRecord = findClassRecordForStudent(student || {});
    const classId = String(student?.classId || student?.classRecordId || classRecord?.id || "").trim();
    const tokens = [
      normalizeLevelToken(student?.level),
      normalizeLevelToken(student?.classLevel || student?.baseLevel),
      normalizeLevelToken(getStudentBaseClassLevel(student || {})),
      normalizeLevelToken(classRecord ? getClassDisplayName(classRecord) : ""),
    ].filter(Boolean);

    return entries
      .filter((entry) => entry.status !== "archived")
      .filter((entry) => {
        const entryClassId = String(entry.classId || "").trim();
        if (classId && entryClassId && entryClassId === classId) {
          return true;
        }
        return tokens.includes(normalizeLevelToken(entry.classLevel));
      })
      .sort((left, right) => {
        const dayComparison = String(left.day || "").localeCompare(String(right.day || ""));
        return dayComparison || String(left.startTime || "").localeCompare(String(right.startTime || ""));
      });
  }

  function getParentChatbotClosingTime(student = null) {
    const entries = getParentChatbotClassTimetableEntries(student);
    return entries
      .filter((entry) => String(entry.endTime || "").trim())
      .sort((left, right) => String(right.endTime || "").localeCompare(String(left.endTime || "")))[0] || null;
  }

  function getParentChatbotAnnouncements(user = {}, student = null) {
    return getParentPortalAnnouncements(user, student).slice(0, 3);
  }

  function buildParentChatbotAnswer(question = "", { student = null, children = [], user = {} } = {}) {
    const rawQuestion = String(question || "").trim();
    const normalized = rawQuestion.toLowerCase();
    const studentName = student?.fullName || "your child";

    if (!student) {
      return "I can only answer after a child is linked to this parent account. No linked child is available for this login yet.";
    }

    const asksFee =
      /\b(fee|fees|balance|owe|owing|outstanding|invoice|payment|pay)\b/.test(normalized);
    const asksExam = /\b(exam|exams|test|assessment|calendar)\b/.test(normalized);
    const asksAttendance = /\b(attendance|present|absent|late|marked|register|today)\b/.test(normalized);
    const asksReport = /\b(report|result|card|pdf|download|print|grade)\b/.test(normalized);
    const asksClosing = /\b(close|closing|dismiss|dismissal|school\s*time|end\s*time)\b/.test(normalized);
    const asksAnnouncement = /\b(announcement|notice|update|news|deadline|registration)\b/.test(normalized);
    const asksTeacher = /\b(teacher|teachers|lecturer|class\s*teacher)\b/.test(normalized);
    const asksCourse = /\b(subject|subjects|course|courses|classwork)\b/.test(normalized);
    const asksChild = /\b(child|children|student|class|level|admission)\b/.test(normalized);

    if (asksFee) {
      const fee = getParentChatbotFeeContext(student, user);
      const totalDue = Number(fee?.totalDue || 0);
      const balance = Number(fee?.balance || 0);
      const paid = Math.max(0, totalDue - balance);
      return [
        `${studentName}'s fee balance is ${formatCurrencyAmount(balance)}.`,
        `Total due: ${formatCurrencyAmount(totalDue)}.`,
        `Paid: ${formatCurrencyAmount(paid)}.`,
        fee?.invoiceNo ? `Invoice: ${fee.invoiceNo}.` : "",
        fee?.dueDate ? `Due date: ${fee.dueDate}.` : "",
      ]
        .filter(Boolean)
        .join("\n");
    }

    if (asksClosing) {
      const closingEntry = getParentChatbotClosingTime(student);
      if (!closingEntry) {
        const schoolSettings = getConfiguredSchoolSettings();
        return [
          "I could not find a closing time from this child's saved timetable.",
          schoolSettings.phone ? `You can contact the school office on ${schoolSettings.phone}.` : "",
        ]
          .filter(Boolean)
          .join("\n");
      }
      return `Based on ${studentName}'s timetable, the latest scheduled lesson ends at ${closingEntry.endTime}.`;
    }

    if (asksAttendance) {
      const attendance = getParentChatbotTodayAttendance(student);
      const termSummary = deriveParentAttendanceSummary(student);
      return [
        `Today's attendance for ${studentName}: ${attendance?.label || "Not marked yet"}.`,
        `Current period summary: ${termSummary.present} present, ${termSummary.absent} absent.`,
        attendance?.entry?.note ? `Note: ${attendance.entry.note}.` : "",
      ]
        .filter(Boolean)
        .join("\n");
    }

    if (asksExam) {
      const nextExam = getParentChatbotNextExam();
      if (!nextExam) {
        return "No upcoming exam period has been published on the school calendar yet.";
      }
      return [
        `The next exam event is ${nextExam.title}.`,
        `Date: ${formatCalendarRange(nextExam.startDate, nextExam.endDate)}.`,
        nextExam.notes ? `Note: ${nextExam.notes}.` : "",
      ]
        .filter(Boolean)
        .join("\n");
    }

    if (asksReport) {
      const report = getParentChatbotLatestReport(student);
      if (!report) {
        return `${studentName} does not have any released report card yet. Once the school releases one, it will appear under Reports.`;
      }
      const context = getReportCardDisplayContext(report);
      return [
        `${studentName}'s latest released report card is for ${context.termName}, ${context.sessionName}.`,
        `Average: ${formatReportCardScore(context.averageScore)}%. Grade: ${context.overallGrade}.`,
        "To download it, open Reports in the parent portal and click Download PDF beside the released report card.",
      ].join("\n");
    }

    if (asksAnnouncement) {
      const announcements = getParentChatbotAnnouncements(user, student);
      if (!announcements.length) {
        return `There are no current announcements for ${studentName}'s class or the whole school.`;
      }
      return [
        `Latest announcements for ${studentName}:`,
        ...announcements.map((entry, index) => `${index + 1}. ${entry.title || "Announcement"} - ${entry.message || "No extra details."}`),
      ].join("\n");
    }

    if (asksTeacher) {
      const groups = getParentTeacherGroups([student]);
      const classTeachers = groups.flatMap((group) => group.classTeachers || []);
      const subjectTeachers = groups.flatMap((group) => group.subjectTeachers || []);
      if (!classTeachers.length && !subjectTeachers.length) {
        return `No teacher assignments are saved yet for ${studentName}'s class.`;
      }
      return [
        `Teachers connected to ${studentName}:`,
        classTeachers.length ? `Class teacher: ${classTeachers.map((teacher) => teacher.name).join(", ")}.` : "",
        subjectTeachers.length
          ? `Subject/course teachers: ${subjectTeachers.map((teacher) => `${teacher.name} (${teacher.subject})`).join(", ")}.`
          : "",
      ]
        .filter(Boolean)
        .join("\n");
    }

    if (asksCourse) {
      const courses = getParentCoursesForStudent(student);
      if (!courses.length) {
        return `No subjects or courses are assigned yet for ${studentName}.`;
      }
      return `${studentName}'s assigned subjects/courses are: ${courses.map((course) => course.name).join(", ")}.`;
    }

    if (asksChild) {
      return [
        `${studentName} is linked to this parent account.`,
        `Class/level: ${getStudentLevelDisplayLabel(student.level || getStudentBaseClassLevel(student)) || "Not assigned"}.`,
        student.admissionNo ? `Admission number: ${student.admissionNo}.` : "",
        children.length > 1 ? `You have ${children.length} linked children. Use the child selector at the top to switch context.` : "",
      ]
        .filter(Boolean)
        .join("\n");
    }

    return [
      "I can answer questions from your child's school records only.",
      "Try asking about fee balance, today's attendance, next exam, report-card download, school closing time, announcements, teachers, or subjects.",
    ].join("\n");
  }

  function initParentFloatingChatbot(student, children, user) {
    const suggestions = [
      "What is my child's fee balance?",
      "What is today's attendance status?",
      "When is the next exam?",
      "How do I download the report card?",
      "What time does school close?",
    ];
    const existing = document.getElementById("parent-floating-chatbot");
    existing?.remove();

    if (!canAccessPermission("Parent", "parent_chatbot_view")) {
      return;
    }

    const wrapper = document.createElement("section");
    wrapper.id = "parent-floating-chatbot";
    wrapper.className = "parent-floating-chatbot";
    wrapper.innerHTML = `
      <button class="parent-floating-chatbot-toggle" type="button" data-parent-chatbot-toggle aria-expanded="false" aria-controls="parent-floating-chatbot-panel">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z"></path>
          <path d="M8 9h8"></path>
          <path d="M8 13h5"></path>
        </svg>
        <span>Ask AI</span>
      </button>
      <div id="parent-floating-chatbot-panel" class="parent-floating-chatbot-panel" data-parent-chatbot-panel hidden>
        <header class="parent-floating-chatbot-head">
          <div>
            <strong>AI Parent Chatbot</strong>
            <span>${student ? `Using ${escapeHtml(student.fullName)}'s school data` : "No linked child found"}</span>
          </div>
          <button type="button" data-parent-chatbot-close aria-label="Close parent chatbot">&times;</button>
        </header>
        <div class="parent-chatbot-thread" data-parent-chatbot-thread aria-live="polite">
          <article class="parent-chatbot-message is-bot">
            <span>Assistant</span>
            <p>${
              student
                ? `Ask me about ${escapeHtml(student.fullName)}'s fees, attendance, report cards, exams, announcements, teachers, or timetable.`
                : "I can answer after a child is linked to this parent account."
            }</p>
          </article>
        </div>
        <div class="parent-chatbot-suggestions" aria-label="Suggested questions">
            ${suggestions
              .map(
                (question) => `
                  <button class="parent-chatbot-chip" type="button" data-parent-chatbot-question="${escapeHtml(question)}">
                    ${escapeHtml(question)}
                  </button>
                `,
              )
              .join("")}
        </div>
        <form class="parent-chatbot-form" data-parent-chatbot-form novalidate>
          <label class="portal-field" for="parent-floating-chatbot-input">
            <span>Ask a question</span>
            <textarea id="parent-floating-chatbot-input" name="question" rows="2" placeholder="Ask about fees, attendance, reports, or school updates"></textarea>
          </label>
          <button class="button button-primary" type="submit">Ask</button>
        </form>
      </div>
    `;
    document.body.appendChild(wrapper);

    const toggle = wrapper.querySelector("[data-parent-chatbot-toggle]");
    const panel = wrapper.querySelector("[data-parent-chatbot-panel]");
    const closeButton = wrapper.querySelector("[data-parent-chatbot-close]");
    const thread = wrapper.querySelector("[data-parent-chatbot-thread]");
    const form = wrapper.querySelector("[data-parent-chatbot-form]");
    const input = form?.elements.question;
    const setOpen = (isOpen) => {
      if (!panel || !toggle) {
        return;
      }
      panel.hidden = !isOpen;
      wrapper.classList.toggle("is-open", isOpen);
      toggle.setAttribute("aria-expanded", String(isOpen));
      if (isOpen) {
        window.setTimeout(() => input?.focus(), 0);
      }
    };
    const appendMessage = (kind, label, message) => {
      if (!thread) {
        return;
      }
      thread.insertAdjacentHTML(
        "beforeend",
        `
          <article class="parent-chatbot-message ${kind === "user" ? "is-user" : "is-bot"}">
            <span>${escapeHtml(label)}</span>
            <p>${escapeHtml(message).replace(/\n/g, "<br>")}</p>
          </article>
        `,
      );
      thread.scrollTop = thread.scrollHeight;
    };
    const submitQuestion = (question) => {
      const value = String(question || "").trim();
      if (!value) {
        input?.focus();
        return;
      }
      appendMessage("user", "You", value);
      appendMessage("bot", "Assistant", buildParentChatbotAnswer(value, { student, children, user }));
      if (input) {
        input.value = "";
        input.focus();
      }
    };

    toggle?.addEventListener("click", () => {
      setOpen(panel?.hidden !== false);
    });
    closeButton?.addEventListener("click", () => {
      setOpen(false);
    });
    form?.addEventListener("submit", (event) => {
      event.preventDefault();
      submitQuestion(input?.value || "");
    });

    wrapper.querySelectorAll("[data-parent-chatbot-question]").forEach((button) => {
      button.addEventListener("click", () => {
        setOpen(true);
        submitQuestion(button.dataset.parentChatbotQuestion || button.textContent || "");
      });
    });
  }

  function renderParentPermissionRestrictedPage(target, page) {
    const label = PARENT_PAGE_LABELS[page] || "Parent section";
    target.innerHTML = `
      <article class="admin-surface-card">
        <div class="admin-surface-head">
          <div>
            <h2>${escapeHtml(label)} unavailable</h2>
            <span>Permission required</span>
          </div>
        </div>
        <p class="auth-helper-text">This section is currently hidden by parent role permissions.</p>
      </article>
    `;
  }

  function initParentPages() {
    const page = getPage();

    if (!isParentPage(page)) {
      return;
    }

    const accessContext = getAdminAccessContext();
    const { session, roleLabel } = accessContext;
    let { user } = accessContext;

    if (!session || !user) {
      window.location.assign("./login.html");
      return;
    }

    if (normalizeRoleLabel(roleLabel) !== "Parent") {
      window.location.assign(getRoleHomeRoute(roleLabel));
      return;
    }

    user = alignParentWorkspaceFromGuardianLink(user, session);
    syncStoredAttendanceAbsenceNotifications(user.workspaceId || session.workspaceId || getCurrentWorkspaceId());

    const brandMark = document.getElementById("admin-brand-mark");
    const brandName = document.getElementById("admin-brand-name");
    const brandSubtitle = document.getElementById("admin-brand-subtitle");
    const profileAvatar = document.getElementById("admin-profile-avatar");
    const profileName = document.getElementById("admin-profile-name");
    const profileRole = document.getElementById("admin-profile-role");
    const gate = document.getElementById("portal-gate");
    const lastUpdated = document.getElementById("portal-last-updated");
    const settingsManager = getSchoolSettingsManager();
    applyAdminBranding(brandMark, brandName, brandSubtitle, settingsManager);

    renderUserAvatar(profileAvatar, user, "Parent");
    if (profileName) {
      profileName.textContent = user.displayName || user.email;
    }
    if (profileRole) {
      profileRole.textContent = "Parent";
    }
    if (lastUpdated) {
      lastUpdated.textContent = `Updated ${formatTimestamp(nowIso())}`;
    }
    if (gate) {
      gate.innerHTML = `
        <a class="admin-signout-button" href="./parent-settings.html">My settings</a>
        <button class="admin-signout-button" type="button" data-signout>Log out</button>
      `;
      wireSignOutButton(gate);
    }

    const children = getParentLinkedStudents(user.email, getStudentManager());
    ensureParentOverdueFeeAlerts(user, children);
    const savedChildId = readParentSelectedChildId(user);
    const selectedChild = children.find((child) => child.id === savedChildId) || children[0] || null;

    if (selectedChild) {
      saveParentSelectedChildId(selectedChild.id, user);
    }

    const switcherHost = document.getElementById("parent-child-switcher");
    renderParentChildSelector(switcherHost, children, selectedChild?.id || "", user);
    let notificationButton = document.getElementById("admin-notification-button");
    const topbar = document.querySelector(".admin-dashboard-topbar");
    const toolsHost =
      switcherHost ||
      topbar?.querySelector(".admin-dashboard-tools") ||
      (() => {
        const host = document.createElement("div");
        host.className = "admin-dashboard-tools";
        topbar?.appendChild(host);
        return host;
      })();

    if (!notificationButton && toolsHost) {
      notificationButton = document.createElement("button");
      notificationButton.id = "admin-notification-button";
      notificationButton.className = "admin-notification-button";
      notificationButton.type = "button";
      notificationButton.setAttribute("aria-label", "Open notifications");
      notificationButton.setAttribute("aria-expanded", "false");
      notificationButton.innerHTML = `
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"></path>
          <path d="M10 21h4"></path>
        </svg>
        <span id="admin-notification-dot" class="admin-notification-dot" hidden></span>
      `;
      toolsHost.appendChild(notificationButton);
    }
    initPortalNotifications(notificationButton, session);
    initPortalAnnouncementToasts(
      { ...session, role: "Parent", workspaceId: user.workspaceId || session.workspaceId },
      user,
    );
    initParentFloatingChatbot(selectedChild, children, user);

    const contentHost = document.getElementById("parent-page-content");
    if (!contentHost) {
      return;
    }

    const permissionKey = PARENT_PAGE_PERMISSION_KEYS[page] || PAGE_PERMISSION_KEYS.portal;
    if (!canAccessPermission(roleLabel, permissionKey)) {
      renderParentPermissionRestrictedPage(contentHost, page);
      return;
    }

    if (page === "parent-portal") {
      renderParentPerformancePage(contentHost, selectedChild, children, user);
      return;
    }

    if (page === "parent-teachers") {
      renderParentTeachersPage(contentHost, selectedChild ? [selectedChild] : []);
      return;
    }

    if (page === "parent-courses") {
      renderParentCoursesPage(contentHost, selectedChild);
      return;
    }

    if (page === "parent-attendance") {
      renderParentAttendancePage(contentHost, selectedChild);
      return;
    }

    if (page === "parent-fees") {
      renderParentFeesPage(contentHost, selectedChild, user);
      return;
    }

    if (page === "parent-messages") {
      renderParentMessagesPage(contentHost, selectedChild, children, user);
      return;
    }

    if (page === "parent-reports") {
      renderParentReportsPage(contentHost, selectedChild);
      const reportCardManager = getReportCardManager();
      if (reportCardManager?.eventName) {
        window.addEventListener(reportCardManager.eventName, () => {
          renderParentReportsPage(contentHost, selectedChild);
        });
      }
    }
  }

  function initAdminShellPages() {
    if (
      !document.body.classList.contains("admin-dashboard-page") ||
      getPage() === "portal" ||
      STAFF_PORTAL_PAGE_CONFIG[getPage()] ||
      isParentPage()
    ) {
      return;
    }

    const brandMark = document.getElementById("admin-brand-mark");
    const brandName = document.getElementById("admin-brand-name");
    const brandSubtitle = document.getElementById("admin-brand-subtitle");
    const profileAvatar = document.getElementById("admin-profile-avatar");
    const profileName = document.getElementById("admin-profile-name");
    const profileRole = document.getElementById("admin-profile-role");
    const lastUpdated = document.getElementById("portal-last-updated");
    const gate = document.getElementById("portal-gate");
    const schoolSettingsManager = getSchoolSettingsManager();
    const settings = schoolSettingsManager
      ? schoolSettingsManager.getSettings()
      : getDefaultAdminSchoolSettings();
    const { session, user, roleLabel } = getAdminAccessContext();
    const normalizedRole = normalizeRoleLabel(roleLabel || DEFAULT_AUTH_ROLE);

    if (normalizedRole === "Parent" && !isParentPage()) {
      window.location.assign(getRoleHomeRoute(normalizedRole));
      return;
    }

    applyAdminBranding(brandMark, brandName, brandSubtitle, schoolSettingsManager);

    if (lastUpdated) {
      lastUpdated.textContent = session && user ? `Updated ${formatTimestamp(nowIso())}` : "Awaiting sign-in";
    }

    initAdminSectionQuickNav();

    if (!profileAvatar || !profileName || !profileRole || !gate) {
      return;
    }

    if (!session || !user) {
      profileAvatar.textContent = getInitials(settings.schoolName).charAt(0) || "S";
      profileName.textContent = settings.schoolName;
      profileRole.textContent = "Guest access";
      gate.innerHTML = `<a class="admin-signout-button" href="./login.html">Go to Login</a>`;
      return;
    }

    renderUserAvatar(profileAvatar, user, roleLabel);
    profileName.textContent = user.displayName || user.email;
    profileRole.textContent = roleLabel;
    gate.innerHTML = `
      <a class="admin-signout-button" href="${normalizedRole === "Teacher" ? "./staff-settings.html" : "./user-settings.html"}">My settings</a>
      <button class="admin-signout-button" type="button" data-signout>Log out</button>
    `;
    wireSignOutButton(gate);
  }

  function statusLabelForAdmission(value) {
    const status = normalizeAdmissionStatus(value);

    if (status === "review") {
      return "In Review";
    }
    if (status === "shortlisted") {
      return "Shortlisted";
    }
    if (status === "rejected") {
      return "Rejected";
    }
    if (status === "approved") {
      return "Approved";
    }
    return "Pending";
  }

  function sourceLabelForAdmission(value) {
    const source = String(value || "").trim().toLowerCase();

    if (source.includes("public") || source.includes("apply") || source.includes("link")) {
      return "Online";
    }

    return "";
  }

  function renderAdmissionsSummary(target, admissions = []) {
    if (!target) {
      return;
    }

    const counts = admissions.reduce(
      (sum, entry) => {
        const status = normalizeAdmissionStatus(entry.status);
        sum[status] += 1;
        return sum;
      },
      { pending: 0, review: 0, shortlisted: 0, rejected: 0, approved: 0 },
    );

    target.innerHTML = `
      <article class="portal-class-stat portal-class-stat-blue">
        <span>Total applications</span>
        <strong>${admissions.length}</strong>
        <p>${counts.pending} pending and ${counts.review} in review.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-green">
        <span>Shortlisted</span>
        <strong>${counts.shortlisted}</strong>
        <p>Applicants currently being considered.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-violet">
        <span>Approved</span>
        <strong>${counts.approved}</strong>
        <p>Accepted applicants are added to student records automatically.</p>
      </article>
      <article class="portal-class-stat portal-class-stat-rose">
        <span>Declined</span>
        <strong>${counts.rejected}</strong>
        <p>Applications not moving forward.</p>
      </article>
    `;
  }

  function renderAdmissionsList(target, admissions = [], isAdmin = false) {
    if (!target) {
      return;
    }

    if (!admissions.length) {
      target.innerHTML = `
        <article class="portal-class-empty">
          <strong>No applications yet</strong>
          <p>Share the application link so prospective students can apply.</p>
        </article>
      `;
      return;
    }

    target.innerHTML = `
      <div class="portal-admission-name-list">
        ${admissions
          .map((entry) => {
            const status = normalizeAdmissionStatus(entry.status);
            const level = entry.academicClassApplyingFor || entry.classApplyingFor || entry.level || "Class not set";
            const guardian = entry.guardianFullName || entry.guardianName || "Guardian not set";
            return `
              <article class="portal-admission-name-row">
                <button class="portal-admission-name-item" type="button" data-admission-open="${escapeHtml(entry.id)}">
                  <span class="portal-admission-name-copy">
                    <strong>${escapeHtml(entry.fullName)}</strong>
                    <small>${escapeHtml(level)} • ${escapeHtml(guardian)}</small>
                  </span>
                  <span class="portal-admission-name-meta">
                    <span class="portal-class-status is-${status === "approved" || status === "shortlisted" ? "active" : status === "rejected" ? "archived" : "pending"}">${escapeHtml(statusLabelForAdmission(status))}</span>
                    <small>${escapeHtml(formatTimestamp(entry.createdAt))}</small>
                  </span>
                </button>
                ${
                  isAdmin
                    ? `<button class="portal-admission-delete-button" type="button" data-admission-delete="${escapeHtml(
                        entry.id,
                      )}" data-admission-delete-scope="application" aria-label="Delete application for ${escapeHtml(
                        entry.fullName,
                      )}" title="Delete application">&times;</button>`
                    : ""
                }
              </article>
            `;
          })
          .join("")}
      </div>
    `;
  }

  function renderAdmissionsHistory(target, admissions = [], isAdmin = false) {
    if (!target) {
      return;
    }

    if (!admissions.length) {
      target.innerHTML = `
        <article class="portal-class-empty">
          <strong>No admission history yet</strong>
          <p>Applications will appear here after they are submitted or added on the platform.</p>
        </article>
      `;
      return;
    }

    target.innerHTML = `
      <div class="portal-admission-name-list">
        ${admissions
          .map((entry) => {
            const status = normalizeAdmissionStatus(entry.status);
            const level = entry.academicClassApplyingFor || entry.classApplyingFor || entry.level || "Class not set";
            const sourceLabel = sourceLabelForAdmission(entry.source);
            const decisionDate = entry.convertedAt || entry.reviewedAt || entry.updatedAt || entry.createdAt;
            return `
              <article class="portal-admission-name-row">
                <button class="portal-admission-name-item portal-admission-history-item" type="button" data-admission-open="${escapeHtml(entry.id)}">
                  <span class="portal-admission-name-copy">
                    <strong>${escapeHtml(entry.fullName)}</strong>
                    <small>${escapeHtml(level)}</small>
                    <small>Date: ${escapeHtml(formatTimestamp(entry.createdAt))}</small>
                  </span>
                  <span class="portal-admission-name-meta">
                    <span class="portal-class-status is-${status === "approved" || status === "shortlisted" ? "active" : status === "rejected" ? "archived" : "pending"}">${escapeHtml(statusLabelForAdmission(status))}</span>
                    ${sourceLabel ? `<span class="portal-admission-source-pill">${escapeHtml(sourceLabel)}</span>` : ""}
                    <small>Updated: ${escapeHtml(formatTimestamp(decisionDate))}</small>
                  </span>
                </button>
                ${
                  isAdmin
                    ? `<button class="portal-admission-delete-button" type="button" data-admission-delete="${escapeHtml(
                        entry.id,
                      )}" data-admission-delete-scope="history" aria-label="Delete admission history for ${escapeHtml(
                        entry.fullName,
                      )}" title="Delete history entry">&times;</button>`
                    : ""
                }
              </article>
            `;
          })
          .join("")}
      </div>
    `;
  }

  function initAdmissionsControls({ isAdmin, form, status, summaryTarget, listTarget, historyTarget, applyLinkTarget }) {
    if (!form || !status || !summaryTarget || !listTarget) {
      return;
    }

    const workspaceId = normalizeWorkspaceId(getCurrentWorkspaceId());
    const studentManager = getStudentManager();
    const admissionConfigManager = getAdmissionConfigManager();
    const levelSelect = form.elements.level || null;

    const refreshApplicationLevelOptions = () => {
      const admissionConfig =
        admissionConfigManager && typeof admissionConfigManager.summarize === "function"
          ? admissionConfigManager.summarize()
          : null;
      const activeClassNames = (admissionConfig?.activeClasses || [])
        .map((entry) => entry.name)
        .filter(Boolean);
      syncAdmissionClassFieldOptions(
        activeClassNames.length ? activeClassNames : getConfiguredStudentLevelOptions(),
        levelSelect,
        {
          placeholder: "Select level/class",
          emptyLabel: "Configure admission classes first",
        },
      );
    };

    const buildStudentPayloadFromAdmission = (entry) => {
      const classLevelSet = getActiveClassLevelTokenSet();
      const level = String(entry.academicClassApplyingFor || entry.classApplyingFor || entry.level || "").trim();
      const studentEmail = String(entry.studentEmail || entry.email || "").trim();
      const firstName = String(entry.firstName || "").trim() || String(entry.fullName || "").trim().split(/\s+/)[0] || "";
      const lastName =
        String(entry.lastName || "").trim() ||
        String(entry.fullName || "")
          .trim()
          .split(/\s+/)
          .slice(1)
          .join(" ") ||
        "Applicant";
      const fullName = [entry.firstName, entry.middleName, entry.lastName]
        .map((value) => String(value || "").trim())
        .filter(Boolean)
        .join(" ");
      const guardians = [
        {
          id: createId(),
          name: String(entry.guardianFullName || entry.guardianName || "").trim(),
          relationship: String(entry.guardianRelationship || "Guardian").trim() || "Guardian",
          phone: String(entry.guardianPhone || "").trim(),
          email: String(entry.guardianEmail || "").trim(),
        },
      ];

      if (!firstName || !lastName) {
        return { error: "Applicant name is incomplete; edit the application before converting." };
      }

      if (!level) {
        return { error: "Class applying for is missing. Update the application first." };
      }

      if (!isKnownClassLevel(level, classLevelSet)) {
        return { error: "Invalid class. Create this class in Class Management before converting." };
      }

      if (!guardians[0].name || !guardians[0].email) {
        return { error: "Guardian details are incomplete. A guardian email is required for parent login." };
      }

      if (!EMAIL_REGEX.test(guardians[0].email)) {
        return { error: "Guardian email format is invalid." };
      }

      if (guardians[0].phone && !isValidPhoneNumber(guardians[0].phone)) {
        return { error: "Guardian phone number format is invalid." };
      }

      if (studentEmail && !EMAIL_REGEX.test(studentEmail)) {
        return { error: "Student email format is invalid." };
      }

      const studentId = createId();
      const existingAdmissionNo = String(entry.admissionNo || entry.admissionNumber || "").trim();
      const admissionNumberTaken =
        existingAdmissionNo &&
        studentManager?.getStudents?.().some(
          (student) => String(student.admissionNo || "").toLowerCase() === existingAdmissionNo.toLowerCase(),
        );
      const admissionNo = !admissionNumberTaken && existingAdmissionNo
        ? existingAdmissionNo
        : generateAdmissionNumber({
            manager: studentManager,
            levelValue: level,
          });
      const selectedClassRecord = chooseStudentClassRecordForLevel(level);
      const classAssignment = buildStudentClassAssignment(level, selectedClassRecord);

      return {
        payload: {
          id: studentId,
          firstName,
          lastName,
          fullName: fullName || [firstName, lastName].join(" ").trim(),
          admissionNo,
          studentEmail,
          profilePhotoUrl: String(entry.passportPhotoFile?.dataUrl || "").trim(),
          profilePhotoName: String(entry.passportPhotoFile?.name || entry.passportPhotoName || "").trim(),
          profilePhotoMimeType: String(entry.passportPhotoFile?.type || "").trim(),
          profilePhotoSizeBytes: Number(entry.passportPhotoFile?.size || 0),
          profilePhotoRemoved: false,
          ...classAssignment,
          dateOfBirth: String(entry.dateOfBirth || "").trim(),
          gender: String(entry.gender || "").trim(),
          promotionDecision: "promote",
          examOutcome: "pass",
          guardians,
          status: "active",
        },
      };
    };

    const refresh = () => {
      const allAdmissions = getAdmissions(workspaceId);
      allAdmissions.forEach((admission) => {
        const photo = admission.passportPhotoFile;
        const convertedStudentId = String(admission.convertedStudentId || "").trim();
        if (!convertedStudentId || !photo?.dataUrl || !studentManager?.updateStudentProgression) {
          return;
        }
        const student = studentManager.getStudents?.().find((entry) => entry.id === convertedStudentId);
        if (!student || student.profilePhotoUrl || student.profilePhotoRemoved) {
          return;
        }
        studentManager.updateStudentProgression(convertedStudentId, (current) => ({
          ...current,
          profilePhotoUrl: photo.dataUrl,
          profilePhotoName: photo.name || admission.passportPhotoName || "",
          profilePhotoMimeType: photo.type || "",
          profilePhotoSizeBytes: Number(photo.size || 0),
          profilePhotoRemoved: false,
        }));
      });
      const admissions = allAdmissions.filter(
        (entry) => !String(entry.convertedAt || "").trim(),
      );
      renderAdmissionsSummary(summaryTarget, allAdmissions);
      renderAdmissionsList(listTarget, admissions, isAdmin);
      renderAdmissionsHistory(historyTarget, allAdmissions, isAdmin);
      const deleteApplicationsButton = document.querySelector('[data-admission-delete-all="applications"]');
      const deleteHistoryButton = document.querySelector('[data-admission-delete-all="history"]');
      if (deleteApplicationsButton) {
        deleteApplicationsButton.disabled = !isAdmin || admissions.length === 0;
      }
      if (deleteHistoryButton) {
        deleteHistoryButton.disabled = !isAdmin || allAdmissions.length === 0;
      }
      refreshApplicationLevelOptions();
    };

    let modalElement = null;
    let modalBody = null;
    let activeAdmissionId = "";
    let admissionToastTimer = null;
    let editingAdmissionId = "";
    const submitButton = document.getElementById("portal-admission-submit-button") || form.querySelector('button[type="submit"]');
    const cancelEditButton = document.getElementById("portal-admission-cancel-edit");
    const formOverlay = document.getElementById("portal-admission-form-overlay");
    const formTitle = document.getElementById("portal-admission-form-title");
    const formOpenButton = document.querySelector("[data-admission-form-open]");

    const setAdmissionFormOpen = (isOpen) => {
      if (!formOverlay) {
        return;
      }
      formOverlay.hidden = !isOpen;
      document.body.classList.toggle("portal-overlay-open", isOpen);
      if (isOpen) {
        window.setTimeout(() => form.elements.fullName?.focus?.(), 0);
      }
    };

    const clearAdmissionFileInputs = () => {
      ADMISSION_FILE_FIELDS.forEach((field) => {
        const input = form.elements[field.fieldName];
        if (input && input.type === "file") {
          input.value = "";
        }
      });
    };

    const setAdmissionFormMode = (mode = "create") => {
      const isEditing = mode === "edit";
      if (submitButton) {
        submitButton.textContent = isEditing ? "Save application" : "Add application";
      }
      if (formTitle) {
        formTitle.textContent = isEditing ? "Edit application" : "Add application";
      }
      if (cancelEditButton) {
        cancelEditButton.textContent = "Cancel";
      }
    };

    const stopAdmissionEdit = ({ reset = true } = {}) => {
      editingAdmissionId = "";
      if (reset) {
        form.reset();
        clearAdmissionFileInputs();
        refreshApplicationLevelOptions();
      }
      setAdmissionFormMode("create");
    };

    const startAdmissionEdit = (admissionId) => {
      const admission = getAdmissions(workspaceId).find((entry) => entry.id === admissionId);
      if (!admission) {
        setStatus(status, "error", "Application not found.");
        return;
      }

      editingAdmissionId = admission.id;
      const studentEmailInput = form.elements.studentEmail || form.elements.email || null;
      form.elements.fullName.value = admission.fullName || "";
      if (studentEmailInput) {
        studentEmailInput.value = admission.studentEmail || admission.email || "";
      }
      form.elements.phone.value = admission.phone || "";
      const selectedLevel = admission.level || admission.classApplyingFor || admission.academicClassApplyingFor || "";
      if (
        selectedLevel &&
        levelSelect &&
        !Array.from(levelSelect.options || []).some((option) => option.value === selectedLevel)
      ) {
        levelSelect.add(new Option(selectedLevel, selectedLevel));
      }
      form.elements.level.value = selectedLevel;
      form.elements.dateOfBirth.value = admission.dateOfBirth || "";
      form.elements.guardianName.value = admission.guardianFullName || admission.guardianName || "";
      form.elements.guardianEmail.value = admission.guardianEmail || "";
      form.elements.guardianPhone.value = admission.guardianPhone || "";
      form.elements.notes.value = admission.notes || admission.statusNote || "";
      clearAdmissionFileInputs();
      setAdmissionFormMode("edit");
      setModalOpen(false);
      setStatus(status, "info", `Editing application for <strong>${escapeHtml(admission.fullName)}</strong>. Upload new files only when replacing existing documents.`);
      setAdmissionFormOpen(true);
    };

    if (cancelEditButton) {
      cancelEditButton.addEventListener("click", () => {
        stopAdmissionEdit();
        setStatus(status, "", "");
        setAdmissionFormOpen(false);
      });
    }

    if (formOpenButton) {
      formOpenButton.disabled = !isAdmin;
      formOpenButton.addEventListener("click", () => {
        stopAdmissionEdit();
        setStatus(status, "", "");
        setAdmissionFormOpen(true);
      });
    }

    document.querySelectorAll("[data-admission-form-close]").forEach((button) => {
      button.addEventListener("click", () => {
        stopAdmissionEdit();
        setStatus(status, "", "");
        setAdmissionFormOpen(false);
      });
    });

    const showAdmissionApprovalToast = (message) => {
      if (!message) {
        return;
      }

      let toast = document.getElementById("portal-admission-approval-toast");
      if (!toast) {
        toast = document.createElement("div");
        toast.id = "portal-admission-approval-toast";
        toast.className = "portal-toast portal-toast--success portal-toast--center portal-admission-approval-toast";
        toast.setAttribute("role", "status");
        toast.setAttribute("aria-live", "polite");
        document.body.appendChild(toast);
      }

      toast.innerHTML = message;
      toast.hidden = false;
      window.clearTimeout(admissionToastTimer);
      admissionToastTimer = window.setTimeout(() => {
        toast.hidden = true;
      }, 3400);
    };

    const setModalOpen = (isOpen) => {
      if (!modalElement) return;
      modalElement.hidden = !isOpen;
      document.body.classList.toggle("portal-admission-modal-open", isOpen);
    };

    const ensureModal = () => {
      if (modalElement) {
        return modalElement;
      }

      const wrapper = document.createElement("div");
      wrapper.innerHTML = `
        <div id="portal-admission-modal" class="portal-admission-modal" hidden>
          <button class="portal-admission-modal-backdrop" type="button" data-admission-close aria-label="Close application details"></button>
          <section class="portal-admission-modal-panel" role="dialog" aria-modal="true" aria-labelledby="portal-admission-modal-title">
            <header class="portal-admission-modal-head">
              <h2 id="portal-admission-modal-title">Application details</h2>
              <button class="portal-admission-modal-close" type="button" data-admission-close aria-label="Close">&times;</button>
            </header>
            <div id="portal-admission-modal-body" class="portal-admission-modal-body"></div>
          </section>
        </div>
      `;
      document.body.appendChild(wrapper.firstElementChild);
      modalElement = document.getElementById("portal-admission-modal");
      modalBody = document.getElementById("portal-admission-modal-body");

      modalElement.addEventListener("click", async (event) => {
        const closeButton = event.target.closest("[data-admission-close]");
        if (closeButton) {
          setModalOpen(false);
          return;
        }

        const actionButton = event.target.closest("[data-admission-action]");
        if (!actionButton || !isAdmin) {
          return;
        }

        const action = String(actionButton.dataset.admissionAction || "").trim().toLowerCase();
        const admissionId = String(actionButton.dataset.admissionId || activeAdmissionId || "").trim();
        if (!admissionId || !action) {
          return;
        }
        await handleAdmissionAction(admissionId, action);
      });

      return modalElement;
    };

    const renderAdmissionDocumentList = (admission) => {
      const entries = getAdmissionDocumentEntries(admission);

      if (!entries.length) {
        return `<p class="portal-admission-doc-empty">No documents have been uploaded for this application yet.</p>`;
      }

      return `
        <div class="portal-admission-doc-list">
          ${entries
            .map((entry) => {
              const meta = [entry.type, entry.size ? formatFileSize(entry.size) : ""].filter(Boolean).join(" • ");
              const hasDownload = Boolean(entry.dataUrl);
              const availabilityCopy = hasDownload
                ? "Stored file is ready to download."
                : "Older record: only the filename was saved. Re-upload this document from Edit to enable download.";
              return `
                <div class="portal-admission-doc-row">
                  <div>
                    <strong>${escapeHtml(entry.label || "Document")}</strong>
                    <span>${escapeHtml(entry.name || "Uploaded file")}${meta ? ` • ${escapeHtml(meta)}` : ""}</span>
                    <small class="portal-admission-doc-note">${escapeHtml(availabilityCopy)}</small>
                  </div>
                  ${
                    hasDownload
                      ? `<a class="portal-admission-doc-link" href="${escapeHtml(entry.dataUrl)}" download="${escapeHtml(entry.name || "document")}">Download</a>`
                      : `<span class="portal-admission-doc-link is-disabled" title="${escapeHtml(availabilityCopy)}">Unavailable</span>`
                  }
                </div>
              `;
            })
            .join("")}
        </div>
      `;
    };

    const renderModalBody = (admission) => {
      if (!modalBody || !admission) return;

      const passportPhotoUrl = String(admission.passportPhotoFile?.dataUrl || "").trim();
      modalBody.innerHTML = `
        ${
          passportPhotoUrl
            ? `<figure class="portal-admission-passport-preview">
                <img src="${escapeHtml(passportPhotoUrl)}" alt="${escapeHtml(admission.fullName)} passport photograph" />
                <figcaption>Applicant photograph</figcaption>
              </figure>`
            : ""
        }
        <div class="portal-admission-modal-grid">
          <div class="portal-admission-modal-item"><span>Applicant</span><strong>${escapeHtml(admission.fullName)}</strong></div>
          <div class="portal-admission-modal-item"><span>Class Applying For</span><strong>${escapeHtml(admission.classApplyingFor || admission.academicClassApplyingFor || admission.level || "—")}</strong></div>
          <div class="portal-admission-modal-item"><span>Status</span><strong>${escapeHtml(statusLabelForAdmission(admission.status))}</strong></div>
          <div class="portal-admission-modal-item"><span>Stage</span><strong>${escapeHtml(admission.applicationStage || "Submitted")}</strong></div>
          <div class="portal-admission-modal-item"><span>Gender / DOB</span><strong>${escapeHtml(admission.gender || "—")} • ${escapeHtml(admission.dateOfBirth || "—")}</strong></div>
          <div class="portal-admission-modal-item"><span>Applied</span><strong>${escapeHtml(formatTimestamp(admission.createdAt))}</strong></div>
          <div class="portal-admission-modal-item"><span>Student Email</span><strong>${escapeHtml(admission.studentEmail || admission.email || "—")}</strong></div>
          <div class="portal-admission-modal-item"><span>Guardian</span><strong>${escapeHtml(admission.guardianFullName || admission.guardianName || "—")}</strong></div>
          <div class="portal-admission-modal-item"><span>Guardian Contact</span><strong>${escapeHtml(admission.guardianPhone || "—")} • ${escapeHtml(admission.guardianEmail || "—")}</strong></div>
          <div class="portal-admission-modal-item"><span>Guardian Relationship</span><strong>${escapeHtml(admission.guardianRelationship || "—")}</strong></div>
          <div class="portal-admission-modal-item"><span>Address</span><strong>${escapeHtml(admission.guardianAddress || "—")}</strong></div>
          <div class="portal-admission-modal-item"><span>Academic Background</span><strong>${escapeHtml(admission.lastClassAttended || "—")} → ${escapeHtml(admission.academicClassApplyingFor || "—")}</strong></div>
          <div class="portal-admission-modal-item"><span>Previous School</span><strong>${escapeHtml(admission.previousSchoolName || admission.previousSchool || "—")}</strong></div>
          <div class="portal-admission-modal-item"><span>Health</span><strong>${escapeHtml(admission.healthCondition || "—")}${admission.healthConditionDetails ? ` • ${escapeHtml(admission.healthConditionDetails)}` : ""}</strong></div>
          <div class="portal-admission-modal-item"><span>Allergies / Medication</span><strong>${escapeHtml(admission.healthAllergies || "—")} • ${escapeHtml(admission.healthMedications || "—")}</strong></div>
          <div class="portal-admission-modal-item portal-admission-modal-item-wide"><span>Documents</span>${renderAdmissionDocumentList(admission)}</div>
          <div class="portal-admission-modal-item portal-admission-modal-item-wide"><span>Notes</span><strong>${escapeHtml(admission.notes || admission.statusNote || "—")}</strong></div>
        </div>
        <div class="portal-admission-modal-actions">
          <button class="portal-class-button" type="button" data-admission-action="edit" data-admission-id="${escapeHtml(admission.id)}" ${isAdmin ? "" : "disabled"}>Edit</button>
          <button class="portal-class-button" type="button" data-admission-action="review" data-admission-id="${escapeHtml(admission.id)}" ${isAdmin ? "" : "disabled"}>Review</button>
          <button class="portal-class-button" type="button" data-admission-action="shortlisted" data-admission-id="${escapeHtml(admission.id)}" ${isAdmin ? "" : "disabled"}>Shortlist</button>
          <button class="portal-class-button is-archive" type="button" data-admission-action="rejected" data-admission-id="${escapeHtml(admission.id)}" ${isAdmin ? "" : "disabled"}>Decline</button>
          <button class="portal-class-button is-restore" type="button" data-admission-action="approved" data-admission-id="${escapeHtml(admission.id)}" ${isAdmin ? "" : "disabled"}>Accept</button>
          <button class="portal-class-button is-danger" type="button" data-admission-action="delete" data-admission-id="${escapeHtml(admission.id)}" ${isAdmin ? "" : "disabled"}>Delete</button>
        </div>
      `;
    };

    const openAdmissionModal = (admissionId) => {
      const admission = getAdmissions(workspaceId).find((entry) => entry.id === admissionId);
      if (!admission) {
        setStatus(status, "error", "Application not found.");
        return;
      }
      ensureModal();
      activeAdmissionId = admissionId;
      renderModalBody(admission);
      setModalOpen(true);
    };

    if (applyLinkTarget) {
      const linkValueInput = document.getElementById("portal-admission-link-value");
      const copyLinkButton = document.getElementById("portal-admission-copy-link");
      const qrImage = document.getElementById("portal-admission-qr-image");
      let currentApplyLink = "";

      const renderApplyLink = (institutionId = "") => {
        const linkUrl = new URL("./admissions-apply.html", window.location.href);
        linkUrl.searchParams.set("workspace", workspaceId);
        if (institutionId) {
          linkUrl.searchParams.set("institution", institutionId);
        }

        currentApplyLink = linkUrl.toString();
        applyLinkTarget.href = currentApplyLink;
        applyLinkTarget.textContent = "Open/Share Application Form";

        if (linkValueInput) {
          linkValueInput.value = currentApplyLink;
        }

        if (qrImage) {
          qrImage.src = `https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(
            currentApplyLink,
          )}`;
        }
      };

      renderApplyLink();

      if (isSupabaseConfigured()) {
        getSupabaseInstitutionContext().then((context) => {
          if (context?.institutionId) {
            renderApplyLink(context.institutionId);
          }
        }).catch(() => {
          // Keep workspace-only apply link when institution lookup fails.
        });
      }

      if (copyLinkButton) {
        copyLinkButton.addEventListener("click", async () => {
          try {
            await navigator.clipboard.writeText(currentApplyLink);
            setStatus(status, "success", "Application link copied.");
          } catch {
            setStatus(status, "info", "Copy failed on this browser. You can copy the link from the input.");
          }
        });
      }
    }

    form.addEventListener("input", () => {
      if (isAdmin) {
        setStatus(status, "", "");
      }
    });

    form.addEventListener("submit", async (event) => {
      event.preventDefault();

      if (!isAdmin) {
        setStatus(status, "info", "Only administrators can create admission records here.");
        return;
      }

      const existingAdmission = editingAdmissionId
        ? getAdmissions(workspaceId).find((entry) => entry.id === editingAdmissionId) || null
        : null;
      const isEditingAdmission = Boolean(existingAdmission);
      const selectedLevel = String(form.elements.level?.value || "").trim();
      const studentEmail = String(form.elements.studentEmail?.value || form.elements.email?.value || "").trim();
      const payload = {
        ...(existingAdmission || {}),
        fullName: String(form.elements.fullName?.value || "").trim(),
        email: studentEmail,
        studentEmail,
        phone: String(form.elements.phone?.value || "").trim(),
        level: selectedLevel,
        classApplyingFor: selectedLevel,
        academicClassApplyingFor: selectedLevel,
        dateOfBirth: String(form.elements.dateOfBirth?.value || "").trim(),
        guardianName: String(form.elements.guardianName?.value || "").trim(),
        guardianFullName: String(form.elements.guardianName?.value || "").trim(),
        guardianEmail: String(form.elements.guardianEmail?.value || "").trim(),
        guardianPhone: String(form.elements.guardianPhone?.value || "").trim(),
        notes: String(form.elements.notes?.value || "").trim(),
        status: existingAdmission?.status || "pending",
        source: existingAdmission?.source || "admin",
        updatedAt: nowIso(),
      };

      const admissionConfig =
        admissionConfigManager && typeof admissionConfigManager.summarize === "function"
          ? admissionConfigManager.summarize()
          : null;
      const openAdmissionSession = admissionConfig?.openSession || null;
      const firstActiveStage = (admissionConfig?.activeStages || [])[0] || null;
      payload.admissionSessionId = openAdmissionSession?.id || existingAdmission?.admissionSessionId || "";
      payload.admissionSessionName = openAdmissionSession?.name || existingAdmission?.admissionSessionName || "";
      payload.applicationStage = existingAdmission?.applicationStage || firstActiveStage?.name || "Submitted";

      if (!payload.fullName || !payload.level || !payload.guardianName || !payload.guardianEmail) {
        setStatus(status, "error", "Full name, level, guardian name, and guardian email are required.");
        return;
      }

      if (payload.studentEmail && !EMAIL_REGEX.test(payload.studentEmail)) {
        setStatus(status, "error", "Student email format is invalid.");
        return;
      }

      if (!EMAIL_REGEX.test(payload.guardianEmail)) {
        setStatus(status, "error", "Guardian email format is invalid.");
        return;
      }

      try {
        Object.assign(payload, await collectAdmissionFormFiles(form, ADMISSION_FILE_FIELDS));
      } catch (error) {
        setStatus(
          status,
          "error",
          String(error?.message || "") === "admission_file_too_large"
            ? getAdmissionFileSizeLimitMessage()
            : "Could not read one of the uploaded documents. Try selecting the file again.",
        );
        return;
      }

      const saved = upsertAdmission(payload, workspaceId)[0];
      recordAuditEvent({
        action: isEditingAdmission ? "updated" : "created",
        entityType: "admission-application",
        entityId: saved?.id || payload.fullName,
        summary: isEditingAdmission
          ? `Admission application updated for ${payload.fullName}`
          : `Admission application received for ${payload.fullName}`,
        details: `${payload.level} • ${payload.guardianName}`,
        workspaceId,
      });
      pushNotification(
        {
          title: isEditingAdmission ? `Admission updated: ${payload.fullName}` : `Admission application: ${payload.fullName}`,
          message: isEditingAdmission
            ? `${payload.level} applicant details were updated.`
            : `${payload.level} applicant submitted and awaiting review.`,
          entityType: "admission-application",
          entityId: saved?.id || "",
          action: isEditingAdmission ? "updated" : "submitted",
          visibleToRoles: ["Admin"],
        },
        workspaceId,
      );

      form.reset();
      clearFormDraftFor(form);
      stopAdmissionEdit({ reset: false });
      refreshApplicationLevelOptions();
      refresh();
      setAdmissionFormOpen(false);
      setStatus(
        status,
        "success",
        `Application for <strong>${escapeHtml(payload.fullName)}</strong> ${isEditingAdmission ? "updated" : "added"}.`,
      );
      showAdmissionApprovalToast(`
        <strong>${isEditingAdmission ? "Application updated" : "Application added"}</strong>
        <span>${escapeHtml(payload.fullName)} is now in the admission workflow.</span>
      `);
    });

    const convertAdmissionToStudent = async (admission) => {
        if (!studentManager || typeof studentManager.upsertStudent !== "function") {
          setStatus(status, "error", "Student manager is not available right now.");
          return null;
        }

        if (normalizeAdmissionStatus(admission.status) !== "approved") {
          setStatus(status, "error", "Only approved applications can be converted.");
          return null;
        }

        if (admission.convertedAt) {
          setStatus(status, "info", "This application has already been converted to a student.");
          return null;
        }

        const conversion = buildStudentPayloadFromAdmission(admission);
        if (conversion.error) {
          setStatus(status, "error", conversion.error);
          return null;
        }

        const studentPayload = conversion.payload;
        studentManager.upsertStudent(studentPayload);
        const persistedStudent =
          studentManager.getStudents?.().find(
            (record) =>
              String(record.id || "") === String(studentPayload.id || "") ||
              String(record.admissionNo || "").toLowerCase() === String(studentPayload.admissionNo || "").toLowerCase(),
          ) || studentPayload;
        const parentProvisioning = await provisionParentAccountsForStudent(persistedStudent);
        const studentProvisioning = await provisionStudentAccountForStudent(persistedStudent);
        upsertAdmission(
          {
            ...admission,
            convertedStudentId: persistedStudent.id,
            admissionNo: persistedStudent.admissionNo,
            convertedAt: nowIso(),
            status: "approved",
            statusNote: "Converted to student record",
          },
          workspaceId,
        );

        recordAuditEvent({
          action: "converted",
          entityType: "admission-application",
          entityId: admission.id,
          summary: `Converted approved applicant ${admission.fullName} to student`,
          details: `${persistedStudent.admissionNo} • ${persistedStudent.level}`,
          workspaceId,
        });

        pushNotification(
          {
            title: `Applicant converted: ${admission.fullName}`,
            message: `Student record created as ${persistedStudent.admissionNo}.`,
            entityType: "student",
            entityId: persistedStudent.admissionNo,
            action: "created",
            visibleToRoles: ["Admin"],
          },
          workspaceId,
        );

        const createdParentCopy = parentProvisioning.created.length
          ? ` Parent login created with default password <strong>${escapeHtml(DEFAULT_PARENT_PASSWORD)}</strong>.`
          : "";
        const googleParentCopy = parentProvisioning.existingGoogle.length
          ? ` ${parentProvisioning.existingGoogle.length} guardian account(s) already use Google sign-in.`
          : "";
        const failedParentCopy = parentProvisioning.failed?.length
          ? ` ${parentProvisioning.failed.length} guardian account(s) could not be provisioned.`
          : "";
        const studentLoginCopy =
          studentProvisioning.status === "created"
            ? ` Student login created with default password <strong>${escapeHtml(DEFAULT_STUDENT_PASSWORD)}</strong>.`
            : studentProvisioning.status === "updated"
              ? ` Student login updated for <strong>${escapeHtml(studentProvisioning.user.email)}</strong>.`
              : studentProvisioning.status === "existing_google"
                ? " Student account already uses Google sign-in."
                : studentProvisioning.status === "skipped"
                  ? ""
                  : studentProvisioning.message
                    ? ` ${escapeHtml(studentProvisioning.message)}`
                    : "";

        refresh();
        if (modalElement && !modalElement.hidden) {
          openAdmissionModal(admission.id);
        }
        setStatus(
          status,
          "success",
          `Accepted <strong>${escapeHtml(admission.fullName)}</strong> and added them as student <strong>${escapeHtml(
            persistedStudent.admissionNo,
          )}</strong> in <strong>${escapeHtml(persistedStudent.level)}</strong>.${createdParentCopy}${googleParentCopy}${failedParentCopy}${studentLoginCopy}`,
        );
        showAdmissionApprovalToast(`
          <strong>Application approved</strong>
          <span>${escapeHtml(admission.fullName)} has been added to Students.</span>
        `);
        return persistedStudent;
    };

    const deleteAdmissionRecords = async (admissionIds = [], scope = "application", forceBulk = false) => {
      if (!isAdmin) {
        return false;
      }

      const idSet = new Set(admissionIds.map((id) => String(id || "").trim()).filter(Boolean));
      const admissions = getAdmissions(workspaceId);
      const records = admissions.filter((entry) => idSet.has(entry.id));
      if (!records.length) {
        setStatus(status, "info", "No admission records were found to delete.");
        return false;
      }

      const isBulk = forceBulk || records.length > 1;
      const isHistory = scope === "history";
      const confirmed = await showAppConfirm({
        title: isBulk
          ? isHistory
            ? "Delete all admission history?"
            : "Delete all applications?"
          : isHistory
            ? "Delete admission history?"
            : "Delete application?",
        message: isBulk
          ? `Permanently delete ${records.length} admission record${records.length === 1 ? "" : "s"}?`
          : `Permanently delete ${records[0].fullName || "this admission record"}?`,
        details: isHistory
          ? "This removes the admission record and uploaded application documents. Student profiles already created from approved admissions will remain."
          : "This removes the application and its uploaded documents. This action cannot be undone.",
        confirmLabel: isBulk ? "Delete all" : "Delete",
        variant: "danger",
      });

      if (!confirmed) {
        return false;
      }

      saveAdmissions(
        admissions.filter((entry) => !idSet.has(entry.id)),
        workspaceId,
      );
      if (editingAdmissionId && idSet.has(editingAdmissionId)) {
        stopAdmissionEdit();
      }
      if (activeAdmissionId && idSet.has(activeAdmissionId)) {
        activeAdmissionId = "";
        setModalOpen(false);
      }
      recordAuditEvent({
        action: isBulk ? "bulk-deleted" : "deleted",
        entityType: "admission-application",
        entityId: isBulk ? scope : records[0].id,
        summary: isBulk
          ? `Deleted ${records.length} ${isHistory ? "admission history records" : "applications"}`
          : `Deleted admission record for ${records[0].fullName}`,
        details: isHistory ? "Admission history" : "Application",
        workspaceId,
      });
      refresh();
      const successMessage = isBulk
        ? `${records.length} ${isHistory ? "admission history record" : "application"}${records.length === 1 ? "" : "s"} deleted.`
        : `${isHistory ? "Admission history" : "Application"} for <strong>${escapeHtml(records[0].fullName)}</strong> deleted.`;
      setStatus(status, "success", successMessage);
      showAdmissionApprovalToast(`<strong>Deleted</strong><span>${successMessage}</span>`);
      return true;
    };

    const handleAdmissionAction = async (admissionId, action) => {
      if (action === "delete") {
        const admission = getAdmissions(workspaceId).find((entry) => entry.id === admissionId);
        await deleteAdmissionRecords([admissionId], admission?.convertedAt ? "history" : "application");
        return;
      }

      if (action === "convert") {
        const admission = getAdmissions(workspaceId).find((entry) => entry.id === admissionId);
        if (!admission) {
          setStatus(status, "error", "Application not found.");
          return;
        }
        await convertAdmissionToStudent(admission);
        return;
      }

      if (action === "edit") {
        startAdmissionEdit(admissionId);
        return;
      }

      const nextStatus = normalizeAdmissionStatus(action || "review");
      const admission = getAdmissions(workspaceId).find((entry) => entry.id === admissionId);

      if (!admission) {
        setStatus(status, "error", "Application not found.");
        return;
      }

      if (nextStatus === "approved") {
        if (!studentManager || typeof studentManager.upsertStudent !== "function") {
          setStatus(status, "error", "Student manager is not available right now.");
          return;
        }

        if (admission.convertedAt) {
          setStatus(status, "info", "This application has already been added to Students.");
          return;
        }

        const conversion = buildStudentPayloadFromAdmission(admission);
        if (conversion.error) {
          setStatus(status, "error", conversion.error);
          return;
        }
      }

      if (nextStatus === "approved" || nextStatus === "rejected") {
        const isApproval = nextStatus === "approved";
        const confirmed = await showAppConfirm({
          title: isApproval ? "Approve application?" : "Decline application?",
          message: isApproval
            ? `Approve ${admission.fullName || "this applicant"} and add them to Students?`
            : `Decline ${admission.fullName || "this applicant"}?`,
          details: isApproval
            ? "A student profile will be created automatically from this application."
            : "The application will stay in admission history for future reference.",
          confirmLabel: isApproval ? "Approve and add" : "Decline",
          variant: isApproval ? "success" : "danger",
        });

        if (!confirmed) {
          return;
        }
      }

      const updated = setAdmissionStatus(admissionId, nextStatus, {
        workspaceId,
        reviewedBy: getSession()?.email || "admin",
      });

      if (!updated) {
        setStatus(status, "error", "Could not update this application.");
        return;
      }

      recordAuditEvent({
        action: nextStatus,
        entityType: "admission-application",
        entityId: updated.id,
        summary: `${updated.fullName} marked as ${statusLabelForAdmission(nextStatus)}`,
        details: `${updated.level} • ${updated.guardianName}`,
        workspaceId,
      });
      pushNotification(
        {
          title: `${updated.fullName}: ${statusLabelForAdmission(nextStatus)}`,
          message: `Application status updated to ${statusLabelForAdmission(nextStatus)}.`,
          entityType: "admission-application",
          entityId: updated.id,
          action: nextStatus,
          visibleToRoles: ["Admin"],
        },
        workspaceId,
      );

      if (nextStatus === "approved") {
        await convertAdmissionToStudent(updated);
        return;
      }

      refresh();
      if (modalElement && !modalElement.hidden) {
        openAdmissionModal(updated.id);
      }
      setStatus(status, "success", `Application moved to <strong>${escapeHtml(statusLabelForAdmission(nextStatus))}</strong>.`);
    };

    const handleAdmissionOpenClick = (event) => {
      const deleteButton = event.target.closest("[data-admission-delete]");
      if (deleteButton) {
        const admissionId = String(deleteButton.dataset.admissionDelete || "").trim();
        const scope = String(deleteButton.dataset.admissionDeleteScope || "application").trim();
        if (admissionId) {
          deleteAdmissionRecords([admissionId], scope);
        }
        return;
      }

      const entryButton = event.target.closest("[data-admission-open]");
      if (!entryButton) {
        return;
      }
      const admissionId = String(entryButton.dataset.admissionOpen || "").trim();
      if (!admissionId) {
        return;
      }
      openAdmissionModal(admissionId);
    };

    listTarget.addEventListener("click", handleAdmissionOpenClick);
    if (historyTarget) {
      historyTarget.addEventListener("click", handleAdmissionOpenClick);
    }

    document.querySelectorAll("[data-admission-delete-all]").forEach((button) => {
      button.disabled = !isAdmin;
      button.addEventListener("click", async () => {
        const scope = String(button.dataset.admissionDeleteAll || "applications").trim();
        const admissions = getAdmissions(workspaceId);
        const records =
          scope === "history"
            ? admissions
            : admissions.filter((entry) => !String(entry.convertedAt || "").trim());
        if (!records.length) {
          setStatus(
            status,
            "info",
            scope === "history" ? "There is no admission history to delete." : "There are no applications to delete.",
          );
          return;
        }
        await deleteAdmissionRecords(
          records.map((entry) => entry.id),
          scope === "history" ? "history" : "application",
          true,
        );
      });
    });

    window.addEventListener(ADMISSIONS_EVENT_NAME, (event) => {
      const eventWorkspaceId = normalizeWorkspaceId(event?.detail?.workspaceId || workspaceId);
      if (eventWorkspaceId === workspaceId) {
        refresh();
      }
    });

    if (admissionConfigManager?.eventName) {
      window.addEventListener(admissionConfigManager.eventName, refreshApplicationLevelOptions);
    }

    refresh();
  }

