  function formatReportNumber(value) {
    const amount = Number(value || 0);
    return new Intl.NumberFormat("en-NG").format(Number.isFinite(amount) ? amount : 0);
  }

  function formatReportPercent(value) {
    const amount = Number(value);
    return Number.isFinite(amount) ? `${Math.round(amount)}%` : "Not enough data";
  }

  function clampReportScore(value) {
    const amount = Number(value);
    if (!Number.isFinite(amount)) {
      return 0;
    }
    return Math.max(0, Math.min(100, Math.round(amount)));
  }

  function getReportHealthLabel(score) {
    if (score >= 80) return "Healthy";
    if (score >= 55) return "Needs attention";
    return "At risk";
  }

  function getAdminParentMessagesForReports(workspaceId = null) {
    const targetWorkspaceId = normalizeWorkspaceId(workspaceId || getCurrentWorkspaceId());
    return getNotifications(targetWorkspaceId)
      .filter((entry) => ["parent-message", "parent-message-reply"].includes(String(entry.entityType || "").toLowerCase()))
      .filter((entry) => {
        const metadata = entry.metadata || {};
        const recipientRole = normalizeRoleLabel(metadata.recipientRole || "");
        const recipientScope = String(metadata.recipientScope || "").trim().toLowerCase();
        return recipientRole === "Admin" || recipientScope === "admin";
      })
      .sort((left, right) => String(left.createdAt || "").localeCompare(String(right.createdAt || "")));
  }

  function renderAdminReportParentMessages(target) {
    if (!target) {
      return;
    }

    const messages = getAdminParentMessagesForReports().slice(0, 20);

    if (!messages.length) {
      target.innerHTML = `
        <article class="portal-class-empty">
          <strong>No parent messages yet</strong>
          <p>Messages sent by parents to School Admin will appear here.</p>
        </article>
      `;
      return;
    }

    target.innerHTML = messages
      .map((entry) => {
        const metadata = entry.metadata || {};
        const isReply = String(entry.entityType || "").toLowerCase() === "parent-message-reply";
        const parentName = metadata.parentName || entry.actorName || "Parent";
        const studentName = metadata.studentName || "Student not linked";
        const classLevel = metadata.classLevel || "Class not set";
        return `
          <article class="admin-report-parent-message portal-message-bubble ${isReply ? "is-outgoing" : "is-incoming"}">
            <div class="portal-message-bubble-meta">
              <strong>${escapeHtml(isReply ? "You" : parentName)}</strong>
              <span>${escapeHtml(formatTimestamp(entry.createdAt || nowIso()))}</span>
            </div>
            <p>${escapeHtml(entry.message || "No message body.")}</p>
            <footer>
              <span>${escapeHtml(studentName)} - ${escapeHtml(classLevel)}</span>
              <span>${escapeHtml(isReply ? entry.title || "Reply sent" : entry.title || "Parent message")}</span>
            </footer>
            ${
              !isReply
                ? `
                  <form class="portal-message-inline-reply admin-report-parent-reply-form" data-admin-report-parent-reply-form data-message-id="${escapeHtml(entry.id)}" novalidate>
                    <label class="portal-field">
                      <span>Reply to parent</span>
                      <textarea name="reply" rows="2" placeholder="Type a reply to the parent."></textarea>
                    </label>
                    <div class="utility-actions">
                      <button class="portal-class-button" type="submit">Send reply</button>
                    </div>
                  </form>
                `
                : ""
            }
          </article>
        `;
      })
      .join("");
  }

  function wireAdminReportParentMessages(target) {
    if (!target || target.dataset.adminParentMessagesWired === "true") {
      return;
    }

    target.dataset.adminParentMessagesWired = "true";
    target.addEventListener("submit", (event) => {
      const form = event.target.closest("[data-admin-report-parent-reply-form]");
      if (!form) {
        return;
      }

      event.preventDefault();
      const session = getSession();
      const user = session?.userId ? getUsers().find((entry) => entry.id === session.userId) || null : null;
      const workspaceId = normalizeWorkspaceId(session?.workspaceId || user?.workspaceId || getCurrentWorkspaceId());
      const messageId = String(form.dataset.messageId || "").trim();
      const message = getNotifications(workspaceId).find((entry) => entry.id === messageId);
      const reply = String(form.elements.reply?.value || "").trim();

      if (!reply) {
        form.elements.reply?.focus();
        return;
      }

      if (!message) {
        return;
      }

      sendParentMessageReply(message, user || { role: "Admin", workspaceId }, reply);
      form.reset();
      const button = form.querySelector("button[type='submit']");
      if (button) {
        button.textContent = "Reply sent";
        button.disabled = true;
      }
      window.setTimeout(() => renderAdminReportParentMessages(target), 450);
    });
  }

  function getAdminMessageDirectory(workspaceId = null) {
    const targetWorkspaceId = normalizeWorkspaceId(workspaceId || getCurrentWorkspaceId());
    const contacts = new Map();
    const addContact = (contact = {}) => {
      const role = normalizeRoleLabel(contact.role || "");
      const email = normalizeEmail(contact.email || "");
      if (!email || !["Parent", "Teacher", "Student"].includes(role)) {
        return;
      }
      const key = `${role.toLowerCase()}:${email}`;
      const existing = contacts.get(key);
      const studentNames = Array.from(
        new Set([...(existing?.studentNames || []), ...(contact.studentNames || [])].filter(Boolean)),
      );
      const baseDisplayName =
        contact.baseDisplayName ||
        existing?.baseDisplayName ||
        contact.displayName ||
        existing?.displayName ||
        email;
      contacts.set(key, {
        id: contact.id || existing?.id || "",
        key,
        role,
        email,
        baseDisplayName,
        displayName:
          role === "Parent" && studentNames.length
            ? `${baseDisplayName} - ${studentNames.join(", ")}`
            : baseDisplayName,
        studentNames,
        studentId: contact.studentId || existing?.studentId || "",
        admissionNo: contact.admissionNo || existing?.admissionNo || "",
        classLevel: contact.classLevel || existing?.classLevel || "",
        phone: contact.phone || existing?.phone || "",
        detail:
          role === "Parent"
            ? studentNames.length
              ? `Parent of ${studentNames.join(", ")}`
              : "Parent account"
            : role === "Student"
              ? [contact.admissionNo, contact.classLevel].filter(Boolean).join(" - ") || "Student account"
              : "Teacher account",
        searchText: [
          contact.displayName,
          email,
          contact.id,
          contact.studentId,
          contact.admissionNo,
          contact.classLevel,
          studentNames.join(" "),
        ]
          .filter(Boolean)
          .join(" "),
      });
    };

    getUsers()
      .filter((user) => normalizeWorkspaceId(user.workspaceId || "") === targetWorkspaceId)
      .filter((user) => normalizeUserStatus(user.status) === "active")
      .forEach((user) => {
        const role = normalizeRoleLabel(user.role || DEFAULT_AUTH_ROLE);
        if (role === "Parent" || role === "Teacher" || role === "Student") {
          addContact({
            id: user.id,
            role,
            email: user.email,
            displayName: user.displayName || user.email,
            studentId: user.studentRecordId || "",
            admissionNo: user.admissionNo || "",
            phone: user.phone || "",
          });
        }
      });

    const studentManager = getStudentManager();
    const students =
      studentManager && typeof studentManager.getStudents === "function"
        ? studentManager.getStudents().filter((student) => student.status === "active")
        : [];
    students.forEach((student) => {
      (student.guardians || []).forEach((guardian) => {
        addContact({
          role: "Parent",
          email: guardian.email,
          displayName: guardian.name || guardian.email,
          phone: guardian.phone || "",
          studentNames: [student.fullName || student.admissionNo || "Student"],
          studentId: student.id,
          admissionNo: student.admissionNo,
          classLevel: student.level,
        });
      });

      const studentEmail = normalizeEmail(student.studentEmail || student.email || "");
      const studentUser = getUsers().find(
        (entry) =>
          normalizeWorkspaceId(entry.workspaceId || "") === targetWorkspaceId &&
          normalizeRoleLabel(entry.role || "") === "Student" &&
          (String(entry.studentRecordId || "") === String(student.id || "") ||
            String(entry.admissionNo || "").toLowerCase() === String(student.admissionNo || "").toLowerCase() ||
            normalizeEmail(entry.email || "") === studentEmail),
      );
      addContact({
        id: studentUser?.id || student.id,
        role: "Student",
        email: studentUser?.email || studentEmail,
        displayName: student.fullName || studentUser?.displayName || studentEmail,
        phone: getStudentWhatsAppPhone(student) || studentUser?.phone || "",
        studentId: student.id,
        admissionNo: student.admissionNo,
        classLevel: student.level,
      });
    });

    return Array.from(contacts.values()).sort((left, right) => {
      const roleComparison = left.role.localeCompare(right.role);
      return roleComparison || left.displayName.localeCompare(right.displayName);
    });
  }

  function buildAdminMessageThreads(user = {}) {
    const workspaceId = normalizeWorkspaceId(user.workspaceId || getCurrentWorkspaceId());
    const adminEmail = normalizeEmail(user.email || "");
    const threadMap = new Map();

    getAdminMessageDirectory(workspaceId).forEach((contact) => {
      threadMap.set(contact.key, {
        key: contact.key,
        name: contact.displayName,
        detail: contact.detail,
        emptyLabel: `Start a conversation with ${contact.displayName}.`,
        contact,
        messages: [],
        unreadIds: [],
        lastAt: "",
      });
    });

    getNotifications(workspaceId)
      .filter((entry) => isPortalMessageEntry(entry))
      .filter((entry) => !isNotificationHiddenForViewer(entry, user, "Admin"))
      .sort((left, right) => String(left.createdAt || "").localeCompare(String(right.createdAt || "")))
      .forEach((entry) => {
        const metadata = entry.metadata || {};
        const entityType = String(entry.entityType || "").trim().toLowerCase();
        let contact = null;

        if (entityType === "school-message") {
          const senderRole = normalizeRoleLabel(metadata.senderRole || "");
          const recipientRole = normalizeRoleLabel(metadata.recipientRole || "");
          const adminIsSender =
            senderRole === "Admin" &&
            (!normalizeEmail(metadata.senderEmail || "") ||
              !adminEmail ||
              normalizeEmail(metadata.senderEmail || "") === adminEmail);
          const adminIsRecipient =
            recipientRole === "Admin" &&
            (!normalizeEmail(metadata.recipientEmail || "") ||
              !adminEmail ||
              normalizeEmail(metadata.recipientEmail || "") === adminEmail);
          if (!adminIsSender && !adminIsRecipient) {
            return;
          }
          contact = {
            id: adminIsSender ? metadata.recipientId || "" : metadata.senderId || "",
            role: adminIsSender ? recipientRole : senderRole,
            email: normalizeEmail(adminIsSender ? metadata.recipientEmail : metadata.senderEmail),
            displayName:
              (adminIsSender ? metadata.recipientName : metadata.senderName) ||
              (adminIsSender ? metadata.recipientEmail : metadata.senderEmail) ||
              "School contact",
            detail: `${adminIsSender ? recipientRole : senderRole} account`,
          };
        } else {
          const recipientRole = normalizeRoleLabel(metadata.recipientRole || "");
          const recipientScope = String(metadata.recipientScope || "").trim().toLowerCase();
          if (recipientRole !== "Admin" && recipientScope !== "admin") {
            return;
          }
          contact = {
            role: "Parent",
            email: normalizeEmail(metadata.parentEmail || ""),
            displayName: metadata.parentName || entry.actorName || metadata.parentEmail || "Parent",
            detail: [metadata.studentName, metadata.classLevel].filter(Boolean).join(" - ") || "Parent account",
            studentNames: [metadata.studentName].filter(Boolean),
          };
        }

        if (!contact?.email || !["Parent", "Teacher", "Student"].includes(normalizeRoleLabel(contact.role))) {
          return;
        }

        contact.role = normalizeRoleLabel(contact.role);
        contact.key = `${contact.role.toLowerCase()}:${contact.email}`;
        if (!threadMap.has(contact.key)) {
          threadMap.set(contact.key, {
            key: contact.key,
            name: contact.displayName,
            detail: contact.detail,
            emptyLabel: `Start a conversation with ${contact.displayName}.`,
            contact,
            messages: [],
            unreadIds: [],
            lastAt: "",
          });
        }

        const thread = threadMap.get(contact.key);
        thread.messages.push(entry);
        thread.lastAt = entry.createdAt || thread.lastAt;
        if (isNotificationUnreadForViewer(entry, user, "Admin")) {
          thread.unreadIds.push(entry.id);
        }
      });

    return Array.from(threadMap.values()).sort((left, right) => {
      if (left.lastAt && right.lastAt) {
        return String(right.lastAt).localeCompare(String(left.lastAt));
      }
      if (left.lastAt) return -1;
      if (right.lastAt) return 1;
      const roleComparison = left.contact.role.localeCompare(right.contact.role);
      return roleComparison || left.name.localeCompare(right.name);
    });
  }

  function renderAdminMessageInbox(target, user) {
    const threads = buildAdminMessageThreads(user);
    const sendWhatsAppCopy = (thread, payload = {}) => {
      if (!payload.sendWhatsApp) {
        return;
      }
      const message = [payload.subject, payload.message].filter(Boolean).join("\n\n");
      openWhatsAppAlerts(getMessageContactWhatsAppRecipients(thread?.contact, user.workspaceId), message);
    };
    renderPortalMessageInbox(target, {
      threads,
      user,
      role: "Admin",
      heading: "Conversations",
      emptyMessage: "Parent and teacher contacts will appear here.",
      composerPlaceholder: "Type your message",
      enableWhatsAppToggle: true,
      onRefresh: () => renderAdminMessageInbox(target, user),
      onSend: (thread, payload) => {
        if (!thread?.contact) {
          return;
        }
        sendSchoolDirectMessage({
          sender: user,
          recipient: thread.contact,
          message: payload.message,
          workspaceId: user.workspaceId,
          metadata: {
            conversationId: getSchoolMessageConversationId(thread.contact.role, thread.contact.email),
            studentName: thread.contact.studentNames?.[0] || "",
          },
        });
        sendWhatsAppCopy(thread, payload);
      },
    });
  }

  function buildAdminReportSnapshot() {
    const workspaceId = normalizeWorkspaceId(getCurrentWorkspaceId());
    const users = getUsers().filter((user) => normalizeWorkspaceId(user.workspaceId) === workspaceId);
    const studentManager = getStudentManager();
    const classManager = getClassManager();
    const feeManager = getFeeItemManager();
    const attendanceManager = getAttendanceManager();
    const timetableManager = getTimetableManager();
    const students = studentManager && typeof studentManager.getStudents === "function" ? studentManager.getStudents() : [];
    const activeStudents = students.filter((student) => student.status === "active");
    const classes = classManager && typeof classManager.getClasses === "function" ? classManager.getClasses() : [];
    const activeClasses = classes.filter((item) => item.status !== "archived");
    const teachers = users.filter(
      (user) => normalizeRoleLabel(user.role || DEFAULT_AUTH_ROLE) === "Teacher" && normalizeUserStatus(user.status) === "active",
    );
    const admissions = getAdmissions(workspaceId);
    const admissionCounts = admissions.reduce(
      (counts, entry) => {
        const status = normalizeAdmissionStatus(entry.status);
        counts[status] = (counts[status] || 0) + 1;
        return counts;
      },
      { pending: 0, review: 0, shortlisted: 0, rejected: 0, approved: 0 },
    );
    const attendanceSummary =
      attendanceManager && typeof attendanceManager.summarize === "function"
        ? attendanceManager.summarize({ date: getTodayDateValue() })
        : {
            activeStudentCount: activeStudents.length,
            markedCount: 0,
            attendanceRate: null,
            counts: { present: 0, absent: 0, late: 0, excused: 0, unmarked: activeStudents.length },
          };
    const feeSummary =
      feeManager && typeof feeManager.summarize === "function"
        ? feeManager.summarize()
        : { activeCount: 0, classCount: 0, activeAmount: 0, archivedCount: 0 };
    const timetableSummary =
      timetableManager && typeof timetableManager.summarize === "function"
        ? timetableManager.summarize()
        : { entries: [], publishedCount: 0, draftCount: 0, classCount: 0, teacherCount: 0, activePeriods: [] };
    const invoices = Object.values(readParentFeesState(workspaceId) || {}).filter((invoice) => invoice && invoice.invoiceNo);
    const invoiceTotalDue = invoices.reduce((sum, invoice) => sum + Number(invoice.totalDue || 0), 0);
    const invoiceBalance = invoices.reduce((sum, invoice) => sum + Number(invoice.balance || 0), 0);
    const classTeacherCount = activeClasses.filter((item) => String(item.classTeacher || "").trim()).length;
    const attendanceMarkedScore = attendanceSummary.activeStudentCount
      ? (Number(attendanceSummary.markedCount || 0) / Number(attendanceSummary.activeStudentCount || 1)) * 100
      : 0;
    const classTeacherScore = activeClasses.length ? (classTeacherCount / activeClasses.length) * 100 : 0;
    const feeCoverageScore = activeClasses.length ? (Number(feeSummary.classCount || 0) / activeClasses.length) * 100 : 0;
    const timetableCoverageScore = activeClasses.length ? (Number(timetableSummary.classCount || 0) / activeClasses.length) * 100 : 0;
    const healthScores = [
      { key: "attendance", label: "Attendance marked today", score: clampReportScore(attendanceMarkedScore) },
      { key: "class-teachers", label: "Classes with class teachers", score: clampReportScore(classTeacherScore) },
      { key: "fee-coverage", label: "Classes with fees configured", score: clampReportScore(feeCoverageScore) },
      { key: "timetable", label: "Classes with timetable lessons", score: clampReportScore(timetableCoverageScore) },
    ];
    const overallScore = healthScores.length
      ? clampReportScore(healthScores.reduce((sum, item) => sum + item.score, 0) / healthScores.length)
      : 0;

    return {
      workspaceId,
      activeStudents,
      activeClasses,
      teachers,
      admissions,
      admissionCounts,
      attendanceSummary,
      feeSummary,
      timetableSummary,
      invoices,
      invoiceTotalDue,
      invoiceBalance,
      classTeacherCount,
      healthScores,
      overallScore,
    };
  }

  function setReportSelectOptions(select, options = [], selectedValue = "") {
    if (!(select instanceof HTMLSelectElement)) {
      return "";
    }
    const values = options.map((option) => String(option.value || ""));
    const nextValue = values.includes(String(selectedValue || ""))
      ? String(selectedValue || "")
      : values[0] || "";
    select.innerHTML = options
      .map(
        (option) =>
          `<option value="${escapeHtml(String(option.value || ""))}" ${
            String(option.value || "") === nextValue ? "selected" : ""
          }>${escapeHtml(String(option.label || option.value || ""))}</option>`,
      )
      .join("");
    return nextValue;
  }

  function studentMatchesReportSession(student, session) {
    if (!session) {
      return true;
    }
    const createdAt = String(student.createdAt || "").slice(0, 10);
    if (!createdAt) {
      return true;
    }
    if (session.startDate && createdAt < session.startDate) {
      return false;
    }
    if (session.endDate && createdAt > session.endDate) {
      return false;
    }
    return true;
  }

  function renderEnrollmentReport(report) {
    const target = document.getElementById("admin-report-enrollment");
    const sessionSelect = document.getElementById("admin-report-enrollment-session");
    const classSelect = document.getElementById("admin-report-enrollment-class");
    const genderSelect = document.getElementById("admin-report-enrollment-gender");
    if (!target || !sessionSelect || !classSelect || !genderSelect) {
      return;
    }

    const cycleState = getAcademicCycleManager()?.getState?.() || { sessions: [] };
    const sessions = Array.isArray(cycleState.sessions) ? cycleState.sessions : [];
    const selectedSession = setReportSelectOptions(
      sessionSelect,
      [{ value: "all", label: "All sessions" }, ...sessions.map((session) => ({ value: session.id, label: session.name }))],
      sessionSelect.value,
    );
    const classLabels = Array.from(
      new Set(report.activeStudents.map((student) => getStudentLevelDisplayLabel(student.level)).filter(Boolean)),
    ).sort((left, right) => left.localeCompare(right, undefined, { numeric: true }));
    const selectedClass = setReportSelectOptions(
      classSelect,
      [{ value: "all", label: "All classes" }, ...classLabels.map((label) => ({ value: label, label }))],
      classSelect.value,
    );
    const selectedGender = genderSelect.value || "all";
    const session = sessions.find((entry) => entry.id === selectedSession) || null;
    const students = report.activeStudents.filter((student) => {
      const classLabel = getStudentLevelDisplayLabel(student.level);
      const gender = String(student.gender || "Other").trim() || "Other";
      return (
        studentMatchesReportSession(student, session) &&
        (selectedClass === "all" || classLabel === selectedClass) &&
        (selectedGender === "all" || (selectedGender === "Other" ? !["Male", "Female"].includes(gender) : gender === selectedGender))
      );
    });
    const classRows = Array.from(
      students.reduce((map, student) => {
        const label = getStudentLevelDisplayLabel(student.level) || "Unassigned";
        map.set(label, (map.get(label) || 0) + 1);
        return map;
      }, new Map()),
    )
      .map(([label, value]) => ({ label, value }))
      .sort((left, right) => left.label.localeCompare(right.label, undefined, { numeric: true }));
    const genderRows = ["Male", "Female", "Other"].map((label) => ({
      label,
      value: students.filter((student) => {
        const gender = String(student.gender || "").trim();
        return label === "Other" ? !["Male", "Female"].includes(gender) : gender === label;
      }).length,
    }));
    const classMax = Math.max(...classRows.map((row) => row.value), 1);
    const genderMax = Math.max(...genderRows.map((row) => row.value), 1);

    target.innerHTML = `
      <article class="admin-report-analysis-card">
        <header><span>Enrollment</span><strong>${formatReportNumber(students.length)}</strong></header>
        <div class="admin-report-horizontal-bars">
          ${
            classRows.length
              ? classRows
                  .map(
                    (row) => `<div><span>${escapeHtml(row.label)}</span><strong>${row.value}</strong><i><em style="width:${
                      (row.value / classMax) * 100
                    }%"></em></i></div>`,
                  )
                  .join("")
              : `<p class="admin-report-empty-copy">No students match this enrollment filter.</p>`
          }
        </div>
      </article>
      <article class="admin-report-analysis-card">
        <header><span>Gender distribution</span><strong>${formatReportNumber(students.length)}</strong></header>
        <div class="admin-report-horizontal-bars is-gender">
          ${genderRows
            .map(
              (row) => `<div><span>${escapeHtml(row.label)}</span><strong>${row.value}</strong><i><em style="width:${
                (row.value / genderMax) * 100
              }%"></em></i></div>`,
            )
            .join("")}
        </div>
      </article>
    `;
  }

  function renderAcademicPerformanceReport() {
    const target = document.getElementById("admin-report-performance");
    const sessionSelect = document.getElementById("admin-report-performance-session");
    const classSelect = document.getElementById("admin-report-performance-class");
    const subjectSelect = document.getElementById("admin-report-performance-subject");
    if (!target || !sessionSelect || !classSelect || !subjectSelect) {
      return;
    }

    const records = getReportCardManager()?.getRecords?.() || [];
    const sessions = Array.from(
      records.reduce((map, record) => {
        if (record.sessionId) map.set(record.sessionId, record.sessionName || record.sessionId);
        return map;
      }, new Map()),
    );
    const selectedSession = setReportSelectOptions(
      sessionSelect,
      [{ value: "all", label: "All sessions" }, ...sessions.map(([value, label]) => ({ value, label }))],
      sessionSelect.value,
    );
    const sessionRecords = records.filter((record) => selectedSession === "all" || record.sessionId === selectedSession);
    const classes = Array.from(new Set(sessionRecords.map((record) => record.classLevel).filter(Boolean))).sort((a, b) =>
      a.localeCompare(b, undefined, { numeric: true }),
    );
    const selectedClass = setReportSelectOptions(
      classSelect,
      [{ value: "all", label: "All classes" }, ...classes.map((label) => ({ value: label, label }))],
      classSelect.value,
    );
    const classRecords = sessionRecords.filter((record) => selectedClass === "all" || record.classLevel === selectedClass);
    const subjects = Array.from(
      new Set(classRecords.flatMap((record) => (record.subjects || []).map((subject) => subject.name)).filter(Boolean)),
    ).sort((a, b) => a.localeCompare(b));
    const selectedSubject = setReportSelectOptions(
      subjectSelect,
      [{ value: "all", label: "All subjects" }, ...subjects.map((label) => ({ value: label, label }))],
      subjectSelect.value,
    );
    const subjectMap = new Map();
    classRecords.forEach((record) => {
      (record.subjects || []).forEach((subject) => {
        if (selectedSubject !== "all" && subject.name !== selectedSubject) {
          return;
        }
        const current = subjectMap.get(subject.name) || { label: subject.name, total: 0, count: 0, pass: 0 };
        const score = Number(subject.totalScore || 0);
        current.total += score;
        current.count += 1;
        if (score >= 40) current.pass += 1;
        subjectMap.set(subject.name, current);
      });
    });
    const rows = Array.from(subjectMap.values())
      .map((row) => ({
        ...row,
        average: row.count ? Math.round((row.total / row.count) * 10) / 10 : 0,
        passRate: row.count ? Math.round((row.pass / row.count) * 100) : 0,
      }))
      .sort((left, right) => right.average - left.average);
    const overallAverage = rows.length
      ? Math.round((rows.reduce((sum, row) => sum + row.average, 0) / rows.length) * 10) / 10
      : 0;

    target.innerHTML = `
      <article class="admin-report-analysis-card">
        <header><span>Average score</span><strong>${formatReportPercent(overallAverage)}</strong></header>
        <div class="admin-report-horizontal-bars">
          ${
            rows.length
              ? rows
                  .map(
                    (row) => `<div><span>${escapeHtml(row.label)}</span><strong>${row.average}%</strong><i><em style="width:${
                      row.average
                    }%"></em></i></div>`,
                  )
                  .join("")
              : `<p class="admin-report-empty-copy">No result records match this performance filter.</p>`
          }
        </div>
      </article>
      <article class="admin-report-analysis-card">
        <header><span>Pass rate</span><strong>${formatReportNumber(classRecords.length)} reports</strong></header>
        <div class="admin-report-horizontal-bars is-performance">
          ${
            rows.length
              ? rows
                  .map(
                    (row) => `<div><span>${escapeHtml(row.label)}</span><strong>${row.passRate}%</strong><i><em style="width:${
                      row.passRate
                    }%"></em></i></div>`,
                  )
                  .join("")
              : `<p class="admin-report-empty-copy">Released and draft report-card scores will appear here.</p>`
          }
        </div>
      </article>
    `;
  }

  function getAdminAnnouncementClassOptions() {
    const classManager = getClassManager();
    const classes =
      classManager && typeof classManager.getClasses === "function"
        ? classManager.getClasses().filter((item) => item.status !== "archived")
        : [];
    const mapped = new Map();

    classes.forEach((item) => {
      const rawLabel = getClassDisplayName(item) || item.level || item.name || "";
      const label = getStudentLevelDisplayLabel(rawLabel) || String(rawLabel || "").trim();
      const token = normalizeLevelToken(label);
      if (!token || mapped.has(token)) {
        return;
      }
      mapped.set(token, label);
    });

    return Array.from(mapped.entries())
      .map(([value, label]) => ({ value, label }))
      .sort((left, right) => left.label.localeCompare(right.label, undefined, { numeric: true }));
  }

  function getAdminAnnouncementNotifications(workspaceId = null) {
    const resolvedWorkspaceId = normalizeWorkspaceId(workspaceId || getCurrentWorkspaceId());
    return getNotifications(resolvedWorkspaceId)
      .filter((entry) => isStudentAnnouncementNotification(entry))
      .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")));
  }

  function renderAdminAnnouncementSection({ isAdmin = false, user = null } = {}) {
    const form = document.getElementById("admin-announcement-form");
    const status = document.getElementById("admin-announcement-status");
    const classWrap = document.querySelector("[data-announcement-class-wrap]");
    const classOptionsTarget = document.getElementById("admin-announcement-class-options");
    const listTarget = document.getElementById("admin-announcement-list");

    if (!form || !status || !classOptionsTarget || !listTarget) {
      return;
    }

    const selectedClassValues = new Set(
      Array.from(form.querySelectorAll('input[name="classTargets"]:checked'))
        .map((input) => normalizeLevelToken(input.value))
        .filter(Boolean),
    );
    const scope = String(form.elements.scope?.value || "school").trim().toLowerCase();
    const classOptions = getAdminAnnouncementClassOptions();
    const announcements = getAdminAnnouncementNotifications(user?.workspaceId || getCurrentWorkspaceId()).slice(0, 12);

    if (classWrap instanceof HTMLElement) {
      classWrap.hidden = scope !== "class";
    }

    classOptionsTarget.innerHTML = classOptions.length
      ? classOptions
          .map(
            (option) => `
              <label class="admin-announcement-class-option">
                <input
                  type="checkbox"
                  name="classTargets"
                  value="${escapeHtml(option.label)}"
                  ${selectedClassValues.has(option.value) ? "checked" : ""}
                  ${isAdmin ? "" : "disabled"}
                />
                <span>${escapeHtml(option.label)}</span>
              </label>
            `,
          )
          .join("")
      : `
          <article class="portal-class-empty">
            <strong>No classes available yet</strong>
            <p>Create classes first to target announcements to selected classes.</p>
          </article>
        `;

    listTarget.innerHTML = announcements.length
      ? announcements
          .map((entry) => {
            const audienceRoles = normalizeNotificationRoles(entry.visibleToRoles, [])
              .filter((role) => role !== "Admin")
              .join(", ");
            const targetLabel = isWholeSchoolAnnouncement(entry)
              ? "Whole school"
              : entry.metadata?.targetClassLabel || getStudentLevelDisplayLabel(entry.entityId) || entry.entityId || "Selected class";
            const audienceLabel = audienceRoles || "All portals";
            return `
              <article class="admin-announcement-item">
                <div class="admin-announcement-item-head">
                  <div>
                    <strong>${escapeHtml(entry.title || "Announcement")}</strong>
                    <p>${escapeHtml(entry.message || "No additional details.")}</p>
                  </div>
                  <small>${escapeHtml(formatTimestamp(entry.createdAt))}</small>
                </div>
                <div class="admin-announcement-item-meta">
                  <span>${escapeHtml(targetLabel)}</span>
                  <span>${escapeHtml(audienceLabel)}</span>
                  <span>${escapeHtml(entry.actorName || "Admin")}</span>
                </div>
              </article>
            `;
          })
          .join("")
      : `
          <article class="portal-class-empty">
            <strong>No announcements yet</strong>
            <p>New announcements posted here will appear in recent notifications and relevant portals.</p>
          </article>
        `;

    Array.from(form.elements).forEach((field) => {
      if (field instanceof HTMLElement) {
        field.disabled = !isAdmin;
      }
    });
  }

  function getStudentAcademicHistory(record = {}) {
    const reportManager = getReportCardManager();
    const cycleManager = getAcademicCycleManager();
    const cycleState =
      cycleManager && typeof cycleManager.getState === "function"
        ? cycleManager.getState()
        : { sessions: [], terms: [] };
    const admissionNo = String(record.admissionNo || "").trim().toLowerCase();
    const studentEmail = normalizeEmail(record.studentEmail || record.email || "");
    const records =
      reportManager && typeof reportManager.getRecords === "function"
        ? reportManager.getRecords()
        : [];

    const reportRows = records
      .filter((entry) => {
        const sameStudentId = String(entry.studentId || "").trim() === String(record.id || "").trim();
        const sameAdmissionNo =
          admissionNo && String(entry.admissionNo || "").trim().toLowerCase() === admissionNo;
        const sameEmail = studentEmail && normalizeEmail(entry.studentEmail || "") === studentEmail;
        return sameStudentId || sameAdmissionNo || sameEmail;
      })
      .map((entry) => {
        const summary = summarizeReportCardSubjects(entry.subjects || []);
        return {
          id: entry.id,
          sessionName: String(entry.sessionName || getSessionLabelFromCycle(cycleState, entry.sessionId) || "Session").trim(),
          termName: String(entry.termName || getTermLabelFromCycle(cycleState, entry.termId) || "Term").trim(),
          classLevel: getStudentLevelDisplayLabel(entry.classLevel || record.level) || entry.classLevel || record.level || "Class",
          averageScore: summary.averageScore,
          grade: summary.grade,
          subjectCount: summary.subjectCount,
          status: String(entry.status || "draft").trim().toLowerCase(),
          updatedAt: entry.releasedAt || entry.updatedAt || entry.createdAt || nowIso(),
        };
      })
      .sort((left, right) => String(right.updatedAt || "").localeCompare(String(left.updatedAt || "")));

    const progressionRows = (Array.isArray(record.progressionHistory) ? record.progressionHistory : [])
      .slice()
      .sort((left, right) => String(right.timestamp || "").localeCompare(String(left.timestamp || "")));

    return {
      reportRows,
      progressionRows,
      sessionCount: new Set(reportRows.map((row) => row.sessionName).filter(Boolean)).size,
      termCount: reportRows.length,
      releasedCount: reportRows.filter((row) => row.status === "released").length,
      latestAverage: reportRows.length ? reportRows[0].averageScore : null,
    };
  }

  function csvCell(value) {
    const text = String(value ?? "");
    return `"${text.replace(/"/g, '""')}"`;
  }

  function downloadReportDataset(type, report) {
    let headers = [];
    let rows = [];
    if (type === "students") {
      headers = ["Student", "Admission Number", "Email", "Class", "Gender", "Status"];
      rows = (getStudentManager()?.getStudents?.() || []).map((student) => [
        student.fullName,
        student.admissionNo,
        student.studentEmail,
        getStudentLevelDisplayLabel(student.level),
        student.gender,
        student.status,
      ]);
    } else if (type === "finance") {
      headers = ["Invoice", "Student", "Class", "Total Due", "Paid", "Balance", "Status"];
      rows = report.invoices.map((invoice) => [
        invoice.invoiceNo,
        invoice.studentName,
        invoice.classLevel,
        invoice.totalDue,
        Number(invoice.totalDue || 0) - Number(invoice.balance || 0),
        invoice.balance,
        invoice.status,
      ]);
    } else if (type === "attendance") {
      headers = ["Date", "Class", "Student", "Status", "Submitted By"];
      rows = (getAttendanceManager()?.getRecords?.() || []).flatMap((record) =>
        (record.entries || []).map((entry) => [
          record.date,
          record.className || record.level,
          entry.studentName,
          entry.status,
          record.submittedByName,
        ]),
      );
    } else {
      headers = ["Session", "Term", "Class", "Student", "Admission Number", "Subject", "CA", "Exam", "Total", "Grade", "Status"];
      rows = (getReportCardManager()?.getRecords?.() || []).flatMap((record) =>
        (record.subjects || []).map((subject) => [
          record.sessionName,
          record.termName,
          record.classLevel,
          record.studentName,
          record.admissionNo,
          subject.name,
          subject.caScore,
          subject.examScore,
          subject.totalScore,
          subject.grade,
          record.status,
        ]),
      );
    }
    const content = [headers, ...rows].map((row) => row.map(csvCell).join(",")).join("\n");
    downloadTextFile(`school-${type}-data.csv`, content, "text/csv;charset=utf-8");
  }

  function renderAdminReportsDashboard() {
    if (getPage() !== "admin-reports") {
      return;
    }

    const kpiTarget = document.getElementById("admin-report-kpis");
    const insightsTarget = document.getElementById("admin-report-insights");
    const healthTarget = document.getElementById("admin-report-health");
    const areasTarget = document.getElementById("admin-report-areas");
    const checklistTarget = document.getElementById("admin-report-checklist");

    if (!kpiTarget || !insightsTarget || !healthTarget || !areasTarget || !checklistTarget) {
      return;
    }

    const report = buildAdminReportSnapshot();
    renderEnrollmentReport(report);
    renderAcademicPerformanceReport();
    const attendanceCounts = report.attendanceSummary.counts || {};
    const unmarkedCount = Number(attendanceCounts.unmarked || 0);
    const attendanceRateLabel = formatReportPercent(report.attendanceSummary.attendanceRate);
    const outstandingRate = report.invoiceTotalDue ? (report.invoiceBalance / report.invoiceTotalDue) * 100 : 0;
    const approvedAdmissions = Number(report.admissionCounts.approved || 0);
    const activePipeline =
      Number(report.admissionCounts.pending || 0) +
      Number(report.admissionCounts.review || 0) +
      Number(report.admissionCounts.shortlisted || 0);
    const attendanceRateValue = Number.isFinite(Number(report.attendanceSummary.attendanceRate))
      ? clampReportScore(report.attendanceSummary.attendanceRate)
      : 0;
    const markedRate = report.attendanceSummary.activeStudentCount
      ? clampReportScore((Number(report.attendanceSummary.markedCount || 0) / Number(report.attendanceSummary.activeStudentCount || 1)) * 100)
      : 0;
    const paidAmount = Math.max(0, report.invoiceTotalDue - report.invoiceBalance);
    const collectionRate = report.invoiceTotalDue ? clampReportScore((paidAmount / report.invoiceTotalDue) * 100) : 0;
    const classTeacherRate = report.activeClasses.length
      ? clampReportScore((report.classTeacherCount / report.activeClasses.length) * 100)
      : 0;
    const feeCoverageRate = report.activeClasses.length
      ? clampReportScore((Number(report.feeSummary.classCount || 0) / report.activeClasses.length) * 100)
      : 0;
    const timetableCoverageRate = report.activeClasses.length
      ? clampReportScore((Number(report.timetableSummary.classCount || 0) / report.activeClasses.length) * 100)
      : 0;
    const admissionsTotal = activePipeline + approvedAdmissions + Number(report.admissionCounts.rejected || 0);
    const admissionsApprovalRate = admissionsTotal ? clampReportScore((approvedAdmissions / admissionsTotal) * 100) : 0;
    const admissionsStageRows = [
      { label: "Pending", value: Number(report.admissionCounts.pending || 0) },
      { label: "Review", value: Number(report.admissionCounts.review || 0) },
      { label: "Shortlisted", value: Number(report.admissionCounts.shortlisted || 0) },
      { label: "Approved", value: approvedAdmissions },
    ];
    const admissionsStageMax = Math.max(...admissionsStageRows.map((stage) => stage.value), 1);

    kpiTarget.innerHTML = `
      <article class="admin-report-kpi">
        <span>Active students</span>
        <strong>${formatReportNumber(report.activeStudents.length)}</strong>
        <p>${formatReportNumber(report.activeClasses.length)} active class group${report.activeClasses.length === 1 ? "" : "s"}</p>
      </article>
      <article class="admin-report-kpi">
        <span>Attendance today</span>
        <strong>${escapeHtml(attendanceRateLabel)}</strong>
        <p>${formatReportNumber(report.attendanceSummary.markedCount || 0)} of ${formatReportNumber(report.attendanceSummary.activeStudentCount || 0)} students marked</p>
      </article>
      <article class="admin-report-kpi">
        <span>Fees configured</span>
        <strong>${formatReportNumber(report.feeSummary.activeCount || 0)}</strong>
        <p>${formatCurrencyAmount(report.feeSummary.activeAmount || 0)} active billing value</p>
      </article>
      <article class="admin-report-kpi">
        <span>Outstanding balance</span>
        <strong>${formatCurrencyAmount(report.invoiceBalance)}</strong>
        <p>${formatReportNumber(report.invoices.length)} generated invoice${report.invoices.length === 1 ? "" : "s"}</p>
      </article>
      <article class="admin-report-kpi">
        <span>Timetable coverage</span>
        <strong>${formatReportNumber(report.timetableSummary.classCount || 0)}</strong>
        <p>${formatReportNumber(report.timetableSummary.publishedCount || 0)} published lesson${Number(report.timetableSummary.publishedCount || 0) === 1 ? "" : "s"}</p>
      </article>
      <article class="admin-report-kpi">
        <span>Admissions pipeline</span>
        <strong>${formatReportNumber(activePipeline)}</strong>
        <p>${formatReportNumber(approvedAdmissions)} approved applicant${approvedAdmissions === 1 ? "" : "s"}</p>
      </article>
    `;

    insightsTarget.innerHTML = `
      <div class="admin-report-chart-grid">
        <article class="admin-report-chart-card">
          <header><span>Attendance</span><strong>${escapeHtml(attendanceRateLabel)}</strong></header>
          <div class="admin-report-donut" style="--score:${attendanceRateValue}"><span>${escapeHtml(attendanceRateLabel)}</span></div>
          <div class="admin-report-mini-legend">
            <span><i class="is-good"></i>Present ${formatReportNumber(attendanceCounts.present || 0)}</span>
            <span><i class="is-warn"></i>Late ${formatReportNumber(attendanceCounts.late || 0)}</span>
            <span><i class="is-bad"></i>Absent ${formatReportNumber(attendanceCounts.absent || 0)}</span>
          </div>
        </article>

        <article class="admin-report-chart-card">
          <header><span>Fee collection</span><strong>${formatReportPercent(collectionRate)}</strong></header>
          <div class="admin-report-stacked-bar" aria-hidden="true">
            <i style="width:${collectionRate}%"></i>
          </div>
          <div class="admin-report-split-metric">
            <span>Paid <strong>${escapeHtml(formatCurrencyAmount(paidAmount))}</strong></span>
            <span>Due <strong>${escapeHtml(formatCurrencyAmount(report.invoiceBalance))}</strong></span>
          </div>
        </article>

        <article class="admin-report-chart-card">
          <header><span>Operations</span><strong>${formatReportPercent(report.overallScore)}</strong></header>
          <div class="admin-report-mini-bars">
            <div><span>Attendance marked</span><b>${formatReportPercent(markedRate)}</b><i><em style="width:${markedRate}%"></em></i></div>
            <div><span>Class teachers</span><b>${formatReportPercent(classTeacherRate)}</b><i><em style="width:${classTeacherRate}%"></em></i></div>
            <div><span>Fees coverage</span><b>${formatReportPercent(feeCoverageRate)}</b><i><em style="width:${feeCoverageRate}%"></em></i></div>
            <div><span>Timetable</span><b>${formatReportPercent(timetableCoverageRate)}</b><i><em style="width:${timetableCoverageRate}%"></em></i></div>
          </div>
        </article>

        <article class="admin-report-chart-card">
          <header><span>Admissions</span><strong>${formatReportNumber(activePipeline)}</strong></header>
          <div class="admin-report-admission-bars">
            ${admissionsStageRows
              .map(
                (stage) => `
                  <div>
                    <span>${escapeHtml(stage.label)}</span>
                    <strong>${formatReportNumber(stage.value)}</strong>
                    <i><em style="width:${clampReportScore((stage.value / admissionsStageMax) * 100)}%"></em></i>
                  </div>
                `,
              )
              .join("")}
          </div>
        </article>
      </div>
    `;

    healthTarget.innerHTML = `
      <div class="admin-report-health-score" style="--score:${report.overallScore}">
        <strong>${formatReportPercent(report.overallScore)}</strong>
        <span>${escapeHtml(getReportHealthLabel(report.overallScore))}</span>
      </div>
      <div class="admin-report-health-bars">
        ${report.healthScores
          .map(
            (item) => `
              <div class="admin-report-health-row">
                <div>
                  <strong>${escapeHtml(item.label)}</strong>
                  <span>${formatReportPercent(item.score)}</span>
                </div>
                <div class="admin-report-progress" aria-hidden="true"><i style="width:${item.score}%"></i></div>
              </div>
            `,
          )
          .join("")}
      </div>
    `;

    const reportAreas = [
      {
        title: "Students and Guardians",
        metric: `${formatReportNumber(report.activeStudents.length)} active students`,
        score: report.activeStudents.length ? 100 : 0,
        status: report.activeStudents.length ? "Active register" : "No register",
        href: "./admin-students.html",
        action: "Open students",
      },
      {
        title: "Attendance",
        metric: attendanceRateLabel,
        score: attendanceRateValue,
        status: unmarkedCount ? `${formatReportNumber(unmarkedCount)} unmarked` : "Complete today",
        href: "./admin-attendance.html",
        action: "Open attendance",
      },
      {
        title: "Fees and Invoices",
        metric: formatCurrencyAmount(report.invoiceBalance || report.feeSummary.activeAmount || 0),
        score: report.invoices.length ? collectionRate : feeCoverageRate,
        status: report.invoices.length ? `${formatReportPercent(outstandingRate)} outstanding` : "Invoice pending",
        href: "./admin-fees.html",
        action: "Open fees",
      },
      {
        title: "Classes and Teachers",
        metric: `${formatReportNumber(report.classTeacherCount)}/${formatReportNumber(report.activeClasses.length)} assigned`,
        score: classTeacherRate,
        status: report.classTeacherCount < report.activeClasses.length ? "Needs assignment" : "Assigned",
        href: "./admin-classes.html",
        action: "Open classes",
      },
      {
        title: "Timetable",
        metric: `${formatReportNumber(report.timetableSummary.classCount || 0)} classes covered`,
        score: timetableCoverageRate,
        status: Number(report.timetableSummary.draftCount || 0) ? "Draft lessons" : "Published ready",
        href: "./admin-schedule.html",
        action: "Open timetable",
      },
      {
        title: "Admissions",
        metric: `${formatReportNumber(activePipeline)} in progress`,
        score: admissionsApprovalRate,
        status: activePipeline ? "Pipeline active" : "No queue",
        href: "./admin-admissions.html",
        action: "Open admissions",
      },
    ];

    areasTarget.innerHTML = reportAreas
      .map(
        (area) => `
          <article class="admin-report-area">
            <div>
              <span>${escapeHtml(area.title)}</span>
              <strong>${escapeHtml(area.metric)}</strong>
            </div>
            <div class="admin-report-area-chart"><i style="width:${area.score}%"></i></div>
            <footer>
              <small>${escapeHtml(area.status)}</small>
              <a href="${escapeHtml(area.href)}">${escapeHtml(area.action)}</a>
            </footer>
          </article>
        `,
      )
      .join("");

    const checklist = [
      {
        label: "Students are entered",
        detail: report.activeStudents.length ? "Student register has active records." : "No active students are available for reports.",
        ready: report.activeStudents.length > 0,
      },
      {
        label: "Attendance is complete",
        detail: unmarkedCount ? `${formatReportNumber(unmarkedCount)} students are unmarked today.` : "Attendance has no unmarked students today.",
        ready: unmarkedCount === 0 && report.attendanceSummary.activeStudentCount > 0,
      },
      {
        label: "Class ownership is clear",
        detail:
          report.activeClasses.length && report.classTeacherCount < report.activeClasses.length
            ? `${formatReportNumber(report.activeClasses.length - report.classTeacherCount)} classes need class teachers.`
            : "Classes have assigned ownership.",
        ready: report.activeClasses.length > 0 && report.classTeacherCount >= report.activeClasses.length,
      },
      {
        label: "Fees are visible to guardians",
        detail: report.feeSummary.activeCount ? "Fee items are configured by class." : "No active fee items have been configured.",
        ready: Number(report.feeSummary.activeCount || 0) > 0,
      },
      {
        label: "Timetable is usable",
        detail: report.timetableSummary.classCount ? "Timetable lessons exist for class review." : "No class timetables have been recorded yet.",
        ready: Number(report.timetableSummary.classCount || 0) > 0,
      },
    ];

    checklistTarget.innerHTML = checklist
      .map(
        (item) => `
          <div class="admin-report-check">
            <span class="${item.ready ? "is-ready" : "is-pending"}">${item.ready ? "Ready" : "Needs work"}</span>
            <div>
              <strong>${escapeHtml(item.label)}</strong>
              <p>${escapeHtml(item.detail)}</p>
            </div>
          </div>
        `,
      )
      .join("");
  }

  function initAdminAnnouncementComposer({ isAdmin = false, user = null } = {}) {
    const announcementForm = document.getElementById("admin-announcement-form");
    const announcementStatus = document.getElementById("admin-announcement-status");

    if (!announcementForm || !announcementStatus) {
      return;
    }

    const refreshAnnouncements = () => renderAdminAnnouncementSection({ isAdmin, user });
    refreshAnnouncements();

    if (announcementForm.dataset.bound !== "true") {
      announcementForm.addEventListener("change", (event) => {
        if (event.target === announcementForm.elements.scope) {
          refreshAnnouncements();
        }
      });

      announcementForm.addEventListener("reset", () => {
        window.setTimeout(() => {
          refreshAnnouncements();
          setStatus(announcementStatus, "", "");
        }, 0);
      });

      announcementForm.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!isAdmin) {
          setStatus(announcementStatus, "info", "Only administrators can post announcements.");
          return;
        }

        const scope = String(announcementForm.elements.scope?.value || "school").trim().toLowerCase();
        const title = String(announcementForm.elements.title?.value || "").trim();
        const message = String(announcementForm.elements.message?.value || "").trim();
        const alertType = String(announcementForm.elements.alertType?.value || "general").trim().toLowerCase();
        const sendWhatsApp = Boolean(announcementForm.elements.sendWhatsApp?.checked);
        const selectedRoles = Array.from(
          announcementForm.querySelectorAll('input[name="roleTargets"]:checked'),
        )
          .map((input) => normalizeRoleLabel(input.value))
          .filter(Boolean);
        const selectedClasses = Array.from(
          announcementForm.querySelectorAll('input[name="classTargets"]:checked'),
        )
          .map((input) => String(input.value || "").trim())
          .filter(Boolean);

        if (!title) {
          setStatus(announcementStatus, "error", "Enter an announcement title.");
          return;
        }

        if (!message) {
          setStatus(announcementStatus, "error", "Enter the announcement message.");
          return;
        }

        if (!selectedRoles.length) {
          setStatus(announcementStatus, "error", "Select at least one target role.");
          return;
        }

        if (scope === "class" && !selectedClasses.length) {
          setStatus(announcementStatus, "error", "Select at least one class for this announcement.");
          return;
        }

        const workspaceId = normalizeWorkspaceId(user?.workspaceId || getCurrentWorkspaceId());
        const actorName = user?.displayName || user?.email || "Admin";

        if (scope === "class") {
          selectedClasses.forEach((classLabel) => {
            pushNotification(
              {
                title,
                message,
                entityType: "class-announcement",
                entityId: classLabel,
                action: "posted",
                actorName,
                visibleToRoles: selectedRoles,
                metadata: {
                  announcementScope: "class",
                  alertType,
                  targetClassLabel: classLabel,
                  targetRoles: selectedRoles,
                },
              },
              workspaceId,
            );
          });
        } else {
          pushNotification(
            {
              title,
              message,
              entityType: "school-announcement",
              entityId: "all",
              action: "posted",
              actorName,
              visibleToRoles: selectedRoles,
              metadata: {
                announcementScope: "school",
                alertType,
                targetRoles: selectedRoles,
              },
            },
            workspaceId,
          );
        }

        recordAuditEvent({
          action: "created",
          entityType: scope === "class" ? "class-announcement" : "school-announcement",
          entityId: scope === "class" ? selectedClasses.join(", ") : "all",
          summary: `Posted ${scope === "class" ? "class" : "school-wide"} announcement: ${title}`,
          details:
            scope === "class"
              ? `${selectedClasses.length} class target(s) • ${selectedRoles.join(", ")}`
              : `Whole school • ${selectedRoles.join(", ")}`,
          workspaceId,
        });

        if (sendWhatsApp) {
          openAnnouncementWhatsAppAlerts({
            workspaceId,
            scope,
            selectedRoles,
            selectedClasses,
            title: alertType === "registration-deadline" ? `Registration deadline: ${title}` : title,
            message,
          });
        }

        announcementForm.reset();
        setStatus(
          announcementStatus,
          "success",
          scope === "class"
            ? `Announcement sent to <strong>${selectedClasses.length}</strong> selected class${selectedClasses.length === 1 ? "" : "es"}.`
            : "School-wide announcement sent successfully.",
        );
        refreshAnnouncements();
      });

      announcementForm.dataset.bound = "true";
    }

    [getClassManager()?.eventName, getStudentManager()?.eventName, NOTIFICATION_EVENT_NAME]
      .filter(Boolean)
      .forEach((eventName) => {
        window.addEventListener(eventName, refreshAnnouncements);
      });
  }

